import { createScope } from '@tinker/core';
import type { Scope } from '@tinker/core';
import { expect } from 'vitest';
import {
  discardMoveEdit,
  Errors,
  isError,
  moves,
  moveStock,
  openMoveEdit,
} from '../src/index.ts';

/** A fresh scope for one test. */
export const openScope = (): Scope.Handle => createScope();

/** The exact failure one call raised, narrowed to the expected kind. */
export const failureOf = <N extends Errors.Name>(
  call: () => void,
  kind: N,
): Errors.Of<N> => {
  let thrown: unknown;
  try {
    call();
  } catch (error) {
    thrown = error;
  }
  if (!isError(thrown, kind)) expect.unreachable(`expected ${kind}`);
  return thrown;
};

/** Run a move and answer with the saved move. */
export const saveMove = (
  scope: Scope.Handle,
  item: string,
  from: string,
  to: string,
  quantity: number,
) => scope.run(moveStock, { input: { item, from, to, quantity } });

/** Open a move for editing and answer with the draft. */
export const openEdit = (scope: Scope.Handle, id: string) =>
  scope.run(openMoveEdit, { input: { id } });

/** Close a draft. */
export const discardEdit = (scope: Scope.Handle, id: string): void => {
  scope.run(discardMoveEdit, { input: { id } });
};

/** The saved move list. */
export const savedMoves = (scope: Scope.Handle) => scope.resolve(moves);

import { describe, expect, it } from "vitest";
import {
  bookings,
  bookBooking,
  cancelBooking,
  discardEdit,
  editDraft,
  editDraft as draftCell,
  isError,
  openEdit,
  saveEdit,
} from "../src/index.ts";
import { createScope } from "@tinker/core";

/** Run one operation and catch the failure as an unknown value. */
function caught(run: () => unknown): unknown {
  try {
    run();
  } catch (error) {
    return error;
  }
  return undefined;
}

describe("book and cancel (round 1)", () => {
  it("books a slot and lists it", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    expect(saved.title).toBe("Standup");
    expect(saved.room).toBe("Cedar");
    expect(saved.start).toBe(540);
    expect(saved.end).toBe(600);
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("starts empty and two scopes share nothing", () => {
    const a = createScope();
    const b = createScope();
    expect(a.resolve(bookings)).toEqual([]);
    expect(b.resolve(bookings)).toEqual([]);
    a.run(bookBooking, { input: { title: "A", room: "Cedar", start: 0, end: 60 } });
    expect(b.resolve(bookings)).toEqual([]);
 expect(a.resolve(bookings).length).toBe(1);
  });

  it("rejects the same slot in one room but allows the other room and back-to-back", () => {
    const scope = createScope();
    const first = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const clash = caught(() =>
      scope.run(bookBooking, { input: { title: "Again", room: "Cedar", start: 540, end: 600 } }),
    );
    expect(isError(clash, "Clash")).toBe(true);
    expect(scope.resolve(bookings)).toEqual([first]);
    const maple = scope.run(bookBooking, {
      input: { title: "Maple standup", room: "Maple", start: 540, end: 600 },
    });
    expect(maple.room).toBe("Maple");
    const later = scope.run(bookBooking, {
      input: { title: "Follow-up", room: "Cedar", start: 600, end: 660 },
    });
    expect(later.start).toBe(600);
    expect(scope.resolve(bookings)).toEqual([first, maple, later]);
  });

  it("rejects a blank title, unknown room, bad times, and an empty slot", () => {
    const scope = createScope();
    const blank = caught(() =>
      scope.run(bookBooking, { input: { title: "   ", room: "Cedar", start: 0, end: 60 } }),
    );
    expect(isError(blank, "BlankTitle")).toBe(true);
    const room = caught(() =>
      scope.run(bookBooking, { input: { title: "X", room: "Oak", start: 0, end: 60 } }),
    );
    expect(isError(room, "UnknownRoom")).toBe(true);
    const low = caught(() =>
      scope.run(bookBooking, { input: { title: "X", room: "Cedar", start: -1, end: 60 } }),
    );
    expect(isError(low, "BadTime")).toBe(true);
    const high = caught(() =>
      scope.run(bookBooking, { input: { title: "X", room: "Cedar", start: 0, end: 1440 } }),
    );
    expect(isError(high, "BadTime")).toBe(true);
    const fraction = caught(() =>
      scope.run(bookBooking, { input: { title: "X", room: "Cedar", start: 0.5, end: 60 } }),
    );
    expect(isError(fraction, "BadTime")).toBe(true);
    const empty = caught(() =>
      scope.run(bookBooking, { input: { title: "X", room: "Cedar", start: 600, end: 600 } }),
    );
    expect(isError(empty, "EmptySlot")).toBe(true);
    const backwards = caught(() =>
      scope.run(bookBooking, { input: { title: "X", room: "Cedar", start: 700, end: 600 } }),
    );
    expect(isError(backwards, "EmptySlot")).toBe(true);
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("trims the title", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "  Standup  ", room: "Cedar", start: 540, end: 600 },
    });
    expect(saved.title).toBe("Standup");
  });

  it("orders by start time, then creation order", () => {
    const scope = createScope();
    const a = scope.run(bookBooking, { input: { title: "A", room: "Cedar", start: 600, end: 660 } });
    const b = scope.run(bookBooking, { input: { title: "B", room: "Cedar", start: 540, end: 600 } });
    const c = scope.run(bookBooking, { input: { title: "C", room: "Maple", start: 600, end: 660 } });
    expect(scope.resolve(bookings).map((booked) => booked.id)).toEqual([b.id, a.id, c.id]);
  });

  it("cancels by id; a second cancel reports not found", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(cancelBooking, { input: { id: saved.id } });
    expect(scope.resolve(bookings)).toEqual([]);
    const again = caught(() => scope.run(cancelBooking, { input: { id: saved.id } }));
    expect(isError(again, "NotFound")).toBe(true);
    if (!isError(again, "NotFound")) throw new Error("unreachable");
    expect(again.payload.id).toBe(saved.id);
  });

  it("frees a slot after cancel", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(cancelBooking, { input: { id: saved.id } });
    const again = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    expect(again.id).not.toBe(saved.id);
  });

  it("two calls for one empty slot create exactly one booking", () => {
