    scope.run(bookBooking, { input: { title: "First", room: "Cedar", start: 540, end: 600 } });
    const second = caught(() =>
      scope.run(bookBooking, { input: { title: "Second", room: "Cedar", start: 540, end: 600 } }),
    );
