    expect(scope.resolve(bookings).length).toBe(1);
  });
});

describe("edit a booking (round 2)", () => {
  it("openEdit returns a copy; writing to it never changes the saved list", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const draft = scope.run(openEdit, { input: { id: saved.id } });
    expect(draft).toEqual(saved);
    expect(draft).not.toBe(saved);
    const leaked = draft as { title: string };
    leaked.title = "Changed";
    expect(scope.resolve(bookings)[0]?.title).toBe("Standup");
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("a discard leaves the saved booking unchanged and closes the draft", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    scope.run(discardEdit, { input: { id: saved.id } });
    expect(scope.resolve(bookings)).toEqual([saved]);
    expect(scope.resolve(editDraft)).toBeUndefined();
  });

  it("save replaces the booking with checked values", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const updated = scope.run(saveEdit, {
      input: { id: saved.id, title: "  Planning  ", room: "Maple", start: 660, end: 720 },
    });
    expect(updated.title).toBe("Planning");
    expect(updated.room).toBe("Maple");
    expect(updated.start).toBe(660);
    expect(updated.end).toBe(720);
    expect(updated.id).toBe(saved.id);
    expect(scope.resolve(bookings)).toEqual([updated]);
    expect(scope.resolve(editDraft)).toBeUndefined();
  });

  it("a clash on save reports Clash and keeps the booking and draft", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(bookBooking, { input: { title: "Other", room: "Cedar", start: 660, end: 720 } });
    scope.run(openEdit, { input: { id: saved.id } });
    const clash = caught(() =>
      scope.run(saveEdit, { input: { id: saved.id, title: "Moved", room: "Cedar", start: 660, end: 720 } }),
    );
    expect(isError(clash, "Clash")).toBe(true);
    expect(scope.resolve(bookings)[0]?.title).toBe("Standup");
    expect(scope.resolve(editDraft)?.id).toBe(saved.id);
  });

  it("saving the draft back to its own slot passes: the clash check skips the edited booking", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const kept = scope.run(saveEdit, {
      input: { id: saved.id, title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    expect(kept.id).toBe(saved.id);
  });

  it("a failed save keeps the saved booking and the draft open for another try", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const blank = caught(() =>
      scope.run(saveEdit, { input: { id: saved.id, title: " ", room: "Cedar", start: 540, end: 600 } }),
    );
    expect(isError(blank, "BlankTitle")).toBe(true);
    expect(scope.resolve(editDraft)?.title).toBe("Standup");
    const updated = scope.run(saveEdit, {
      input: { id: saved.id, title: "Planning", room: "Cedar", start: 540, end: 600 },
    });
    expect(updated.title).toBe("Planning");
  });

  it("a draft blocks nothing until save: another booking can take a slot while the draft is open", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const taker = scope.run(bookBooking, {
      input: { title: "Taker", room: "Cedar", start: 660, end: 720 },
    });
    expect(taker.title).toBe("Taker");
    const clash = caught(() =>
      scope.run(saveEdit, { input: { id: saved.id, title: "Planning", room: "Cedar", start: 660, end: 720 } }),
    );
    expect(isError(clash, "Clash")).toBe(true);
    expect(scope.resolve(editDraft)?.id).toBe(saved.id);
    expect(scope.resolve(bookings).map((booked) => booked.id)).toContain(taker.id);
    expect(scope.resolve(bookings)[0]?.title).toBe("Standup");
  });

  it("openEdit of an unknown id reports NotFound", () => {
    const scope = createScope();
    const missing = caught(() => scope.run(openEdit, { input: { id: "nope" } }));
    expect(isError(missing, "NotFound")).toBe(true);
  });

  it("discardEdit of an unknown id reports NotFound", () => {
    const scope = createScope();
    const missing = caught(() => scope.run(discardEdit, { input: { id: "nope" } }));
    expect(isError(missing, "NotFound")).toBe(true);
  });

  it("save or discard for a closed or missing draft reports NotFound with that id", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const closedSave = caught(() =>
      scope.run(saveEdit, { input: { id: saved.id, title: "X", room: "Cedar", start: 540, end: 600 } }),
    );
    expect(isError(closedSave, "NotFound")).toBe(true);
    const closedDiscard = caught(() => scope.run(discardEdit, { input: { id: saved.id } }));
    expect(isError(closedDiscard, "NotFound")).toBe(true);
    scope.run(openEdit, { input: { id: saved.id } });
    scope.run(discardEdit, { input: { id: saved.id } });
    const afterClose = caught(() =>
      scope.run(saveEdit, { input: { id: saved.id, title: "X", room: "Cedar", start: 540, end: 600 } }),
    );
    expect(isError(afterClose, "NotFound")).toBe(true);
  });

  it("canceling the drafted booking closes its draft too", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    scope.run(cancelBooking, { input: { id: saved.id } });
    expect(scope.resolve(bookings)).toEqual([]);
    expect(scope.resolve(editDraft)).toBeUndefined();
    const afterCancel = caught(() =>
      scope.run(saveEdit, { input: { id: saved.id, title: "X", room: "Cedar", start: 540, end: 600 } }),
    );
    expect(isError(afterCancel, "NotFound")).toBe(true);
  });

  it("only one draft is open at a time; opening a second closes the first", () => {
    const scope = createScope();
    const a = scope.run(bookBooking, { input: { title: "A", room: "Cedar", start: 540, end: 600 } });
    const b = scope.run(bookBooking, { input: { title: "B", room: "Cedar", start: 660, end: 720 } });
    scope.run(openEdit, { input: { id: a.id } });
    scope.run(openEdit, { input: { id: b.id } });
    expect(scope.resolve(editDraft)?.id).toBe(b.id);
    const lostA = caught(() =>
      scope.run(saveEdit, { input: { id: a.id, title: "A2", room: "Cedar", start: 540, end: 600 } }),
    );
    expect(isError(lostA, "NotFound")).toBe(true);
    expect(scope.resolve(bookings)[0]?.title).toBe("A");
  });

  it("unsaved text never changes the list", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const draft = scope.run(openEdit, { input: { id: saved.id } });
    expect(draft.title).toBe("Standup");
    expect(scope.resolve(bookings)).toEqual([saved]);
  });
});

import {
  bookSeries,
  cancelSeries,
} from "../src/index.ts";

describe("dates and a weekly series (round 3)", () => {
  it("an omitted date books the default day 2026-10-01", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    expect(saved.date).toBe("2026-10-01");
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("an explicit date is kept and old calls still work beside it", () => {
    const scope = createScope();
    const onSecond = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-02", start: 540, end: 600 },
    });
    expect(onSecond.date).toBe("2026-10-02");
    const onDefault = scope.run(bookBooking, {
      input: { title: "Later", room: "Cedar", start: 600, end: 660 },
    });
    expect(onDefault.date).toBe("2026-10-01");
    expect(scope.resolve(bookings).map((booked) => booked.date)).toEqual([
      "2026-10-01",
      "2026-10-02",
    ]);
  });

  it("rejects a date that is not a real YYYY-MM-DD day with BadDate", () => {
    const scope = createScope();
    for (const bad of ["2026-02-30", "2026-13-01", "not-a-date", "2026-10-1", 123, null]) {
      const error = caught(() =>
        scope.run(bookBooking, {
          input: { title: "X", room: "Cedar", date: bad as never, start: 0, end: 60 },
        }),
      );
      expect(isError(error, "BadDate")).toBe(true);
      if (!isError(error, "BadDate")) throw new Error("unreachable");
      expect(error.payload.date).toEqual(bad);
    }
    // a leap day that exists is accepted
    const leap = scope.run(bookBooking, {
      input: { title: "Leap", room: "Cedar", date: "2028-02-29", start: 0, end: 60 },
    });
    expect(leap.date).toBe("2028-02-29");
  });

  it("the same slot on two dates never clashes; one room on one date still does", () => {
    const scope = createScope();
    scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-01", start: 540, end: 600 },
    });
    const otherDay = scope.run(bookBooking, {
      input: { title: "Same slot, other day", room: "Cedar", date: "2026-10-02", start: 540, end: 600 },
    });
    expect(otherDay.date).toBe("2026-10-02");
    const clash = caught(() =>
      scope.run(bookBooking, {
        input: { title: "Same slot, same day", room: "Cedar", date: "2026-10-01", start: 540, end: 600 },
      }),
    );
    expect(isError(clash, "Clash")).toBe(true);
  });

  it("orders by date, then start time, then creation order", () => {
    const scope = createScope();
    const late = scope.run(bookBooking, {
      input: { title: "Late", room: "Cedar", date: "2026-10-02", start: 540, end: 600 },
    });
    const lateSameSlot = scope.run(bookBooking, {
      input: { title: "Late too", room: "Maple", date: "2026-10-02", start: 540, end: 600 },
    });
    const early = scope.run(bookBooking, {
      input: { title: "Early", room: "Cedar", date: "2026-10-01", start: 900, end: 960 },
    });
    expect(scope.resolve(bookings).map((booked) => booked.id)).toEqual([
      early.id,
      late.id,
      lateSameSlot.id,
    ]);
  });

  it("bookSeries books weeks dates seven days apart sharing one seriesId", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 3 },
    });
    expect(made.map((booked) => booked.date)).toEqual(["2026-10-06", "2026-10-13", "2026-10-20"]);
    expect(new Set(made.map((booked) => booked.seriesId)).size).toBe(1);
    expect(made[0]?.seriesId).toBeDefined();
    expect(scope.resolve(bookings)).toEqual(made);
  });

  it("one series date being taken books nothing and reports Clash", () => {
    const scope = createScope();
    scope.run(bookBooking, {
      input: { title: "Blocker", room: "Cedar", date: "2026-10-13", start: 540, end: 600 },
    });
    const failed = caught(() =>
      scope.run(bookSeries, {
        input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 3 },
      }),
    );
    expect(isError(failed, "Clash")).toBe(true);
    expect(scope.resolve(bookings).map((booked) => booked.title)).toEqual(["Blocker"]);
  });

  it("rejects a weeks count outside 1..12 or not an integer with BadCount", () => {
    const scope = createScope();
    for (const weeks of [0, 13, 1.5, -1, "3"]) {
      const error = caught(() =>
        scope.run(bookSeries, {
          input: { title: "X", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: weeks as never },
        }),
      );
      expect(isError(error, "BadCount")).toBe(true);
      if (!isError(error, "BadCount")) throw new Error("unreachable");
      expect(error.payload.weeks).toEqual(weeks);
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("canceling one occurrence frees one day and leaves the rest of its series", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 3 },
    });
    const middle = made[1];
    if (middle === undefined) throw new Error("unreachable");
    scope.run(cancelBooking, { input: { id: middle.id } });
    const rest = scope.resolve(bookings);
    expect(rest.map((booked) => booked.date)).toEqual(["2026-10-06", "2026-10-20"]);
    const refill = scope.run(bookBooking, {
      input: { title: "Freed", room: "Cedar", date: "2026-10-13", start: 540, end: 600 },
    });
    expect(refill.date).toBe("2026-10-13");
  });

  it("cancelSeries removes every occurrence; an unknown seriesId reports NotFound", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 3 },
    });
    const seriesId = made[0]?.seriesId;
    if (seriesId === undefined) throw new Error("unreachable");
    scope.run(cancelSeries, { input: { seriesId } });
    expect(scope.resolve(bookings)).toEqual([]);
    const again = caught(() => scope.run(cancelSeries, { input: { seriesId } }));
    expect(isError(again, "NotFound")).toBe(true);
    if (!isError(again, "NotFound")) throw new Error("unreachable");
    expect(again.payload.id).toBe(seriesId);
  });

  it("cancelSeries of a one-off-only list reports NotFound and removes nothing", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "One-off", room: "Cedar", start: 540, end: 600 },
    });
    const missing = caught(() => scope.run(cancelSeries, { input: { seriesId: saved.id } }));
    expect(isError(missing, "NotFound")).toBe(true);
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("canceling the series closes the draft of its drafted occurrence", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 2 },
    });
    const first = made[0];
    if (first === undefined) throw new Error("unreachable");
    scope.run(openEdit, { input: { id: first.id } });
    scope.run(cancelSeries, { input: { seriesId: first.seriesId ?? "" } });
    expect(scope.resolve(bookings)).toEqual([]);
    expect(scope.resolve(editDraft)).toBeUndefined();
  });

  it("saveEdit accepts a date and clash-checks only that room on that date", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-01", start: 540, end: 600 },
    });
    scope.run(bookBooking, {
      input: { title: "Other", room: "Cedar", date: "2026-10-02", start: 600, end: 660 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const moved = scope.run(saveEdit, {
      input: { id: saved.id, title: "Moved", room: "Maple", date: "2026-10-02", start: 600, end: 660 },
    });
    expect(moved.date).toBe("2026-10-02");
    // the same room and slot on the target date still clashes
    scope.run(openEdit, { input: { id: saved.id } });
    const clash = caught(() =>
      scope.run(saveEdit, {
        input: { id: saved.id, title: "Moved", room: "Cedar", date: "2026-10-02", start: 600, end: 660 },
      }),
    );
    expect(isError(clash, "Clash")).toBe(true);
    expect(scope.resolve(editDraft)?.id).toBe(saved.id);
  });

  it("a failed date save keeps the saved booking; a BadDate save reports BadDate", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const bad = caught(() =>
      scope.run(saveEdit, {
        input: { id: saved.id, title: "X", room: "Cedar", date: "2026-02-30", start: 540, end: 600 },
      }),
    );
    expect(isError(bad, "BadDate")).toBe(true);
    expect(scope.resolve(bookings)).toEqual([saved]);
    expect(scope.resolve(editDraft)?.id).toBe(saved.id);
  });

  it("saving a series occurrence keeps its seriesId; editing skips only the edited booking", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 2 },
    });
    const first = made[0];
    if (first === undefined) throw new Error("unreachable");
    scope.run(openEdit, { input: { id: first.id } });
    const renamed = scope.run(saveEdit, {
      input: { id: first.id, title: "Renamed", room: "Cedar", date: "2026-10-06", start: 540, end: 600 },
    });
    expect(renamed.seriesId).toBe(first.seriesId);
    expect(scope.resolve(bookings).map((booked) => booked.title)).toEqual(["Renamed", "Standup"]);
  });

  it("a draft on one date blocks nothing on another date until save", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-01", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const taker = scope.run(bookBooking, {
      input: { title: "Taker", room: "Cedar", date: "2026-10-02", start: 540, end: 600 },
    });
    expect(taker.title).toBe("Taker");
    expect(scope.resolve(editDraft)?.id).toBe(saved.id);
  });
});

import {
  bookBooking as bookOp,
  bookSeries as seriesOp,
  cancelBooking as cancelOp,
  cancelSeries as cancelSeriesOp,
  openEdit as openOp,
  saveEdit as saveOp,
  undoChange,
} from "../src/index.ts";

describe("undo the last change (round 4)", () => {
  it("undo removes the last booking, then the first, then reports EmptyUndo", () => {
    const scope = createScope();
    scope.run(bookOp, { input: { title: "A", room: "Cedar", date: "2026-10-01", start: 540, end: 600 } });
    const b = scope.run(bookOp, {
      input: { title: "B", room: "Cedar", date: "2026-10-01", start: 660, end: 720 },
    });
    scope.run(undoChange, {});
    expect(scope.resolve(bookings).map((booked) => booked.id)).not.toContain(b.id);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([]);
    const empty = caught(() => scope.run(undoChange, {}));
    expect(isError(empty, "EmptyUndo")).toBe(true);
    if (!isError(empty, "EmptyUndo")) throw new Error("unreachable");
    expect(empty.payload).toEqual({});
  });

  it("undo reverses a cancel and a series cancel restores every occurrence", () => {
    const scope = createScope();
    const made = scope.run(seriesOp, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 2 },
    });
    scope.run(cancelSeriesOp, { input: { seriesId: made[0]?.seriesId ?? "" } });
    expect(scope.resolve(bookings)).toEqual([]);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual(made);
   });

  it("a series book is one step: undo removes all three days at once", () => {
    const scope = createScope();
    scope.run(bookOp, { input: { title: "Solo", room: "Maple", start: 0, end: 30 } });
    const made = scope.run(seriesOp, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 3 },
    });
    scope.run(undoChange, {});
    const rest = scope.resolve(bookings);
    expect(rest.map((booked) => booked.title)).toEqual(["Solo"]);
    expect(rest.some((booked) => booked.seriesId === made[0]?.seriesId)).toBe(false);
  });

  it("undo of a cancel restores the booking and frees nothing extra", () => {
    const scope = createScope();
    const saved = scope.run(bookOp, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-01", start: 540, end: 600 },
    });
    scope.run(cancelOp, { input: { id: saved.id } });
    expect(scope.resolve(bookings)).toEqual([]);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("undo of an edit save restores the prior values under the same id", () => {
    const scope = createScope();
    const saved = scope.run(bookOp, {
      input: { title: "A", room: "Cedar", date: "2026-10-01", start: 540, end: 600 },
    });
    scope.run(openOp, { input: { id: saved.id } });
    scope.run(saveOp, {
      input: { id: saved.id, title: "A2", room: "Maple", date: "2026-10-02", start: 660, end: 720 },
    });
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("a failed action adds no undo step; undo still reverses the last passing change", () => {
    const scope = createScope();
    scope.run(bookOp, { input: { title: "A", room: "Cedar", date: "2026-10-01", start: 540, end: 600 } });
    const failed = caught(() =>
      scope.run(bookOp, { input: { title: "B", room: "Cedar", date: "2026-10-01", start: 540, end: 600 } }),
    );
    expect(isError(failed, "Clash")).toBe(true);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([]);
    const empty = caught(() => scope.run(undoChange, {}));
    expect(isError(empty, "EmptyUndo")).toBe(true);
  });

  it("an undo of an undo pops one step each time and adds no entry", () => {
    const scope = createScope();
    scope.run(bookOp, { input: { title: "A", room: "Cedar", start: 540, end: 600 } });
    scope.run(undoChange, {});
    scope.run(bookOp, { input: { title: "B", room: "Cedar", start: 540, end: 600 } });
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([]);
    expect(caught(() => scope.run(undoChange, {}))).not.toBeUndefined();
  });

  it("undo leaves an open draft untouched", () => {
    const scope = createScope();
    const saved = scope.run(bookOp, {
      input: { title: "A", room: "Cedar", date: "2026-10-01", start: 540, end: 600 },
    });
    scope.run(openOp, { input: { id: saved.id } });
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([]);
    expect(scope.resolve(editDraft)?.id).toBe(saved.id);
  });

  it("undo never fails with Clash: restoring a prior snapshot always passes", () => {
    const scope = createScope();
    const saved = scope.run(bookOp, {
      input: { title: "A", room: "Cedar", date: "2026-10-01", start: 540, end: 600 },
    });
    scope.run(cancelOp, { input: { id: saved.id } });
    scope.run(bookOp, {
      input: { title: "B", room: "Cedar", date: "2026-10-01", start: 540, end: 600 },
    });
    // the last change was booking B: undo removes it without a Clash,
    // and a second undo restores A's cancel
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([]);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([saved]);
  });
});

/**
 * The one error registry for the booking app. Every failure is raised from here,
 * so callers narrow with `isError(error, "Kind")` instead of matching strings.
 */

/** Payload carried by each booking error kind. */
export type Payloads = {
  BlankTitle: { title: string };
  UnknownRoom: { room: string };
  BadTime: { value: unknown };
  EmptySlot: { start: number; end: number };
  Clash: { room: string; start: number; end: number };
  NotFound: { id: string };
  BadDate: { date: unknown };
  BadCount: { weeks: unknown };
  EmptyUndo: {};
};

export namespace Errors {
  /** Every booking error kind. */
  export type Name = keyof Payloads;
  /** The typed payload carried by one error kind. */
  export type Payload<N extends Name> = Payloads[N];
  /** A booking error: identified by `kind`, carrying a typed `payload`. */
  export type Of<N extends Name = Name> = Error & {
    readonly kind: N;
    readonly payload: Payload<N>;
  };
}

/** The concrete error instance behind every factory below. */
class RegistryError<N extends Errors.Name> extends Error implements Errors.Of<N> {
  readonly kind: N;
  readonly payload: Errors.Payload<N>;

  constructor(kind: N, payload: Errors.Payload<N>) {
    super(kind);
    this.name = "BookingError";
    this.kind = kind;
    this.payload = payload;
  }
}

/** Build one registry error. Callers should prefer the named factories. */
export function makeError<N extends Errors.Name>(
  kind: N,
  payload: Errors.Payload<N>,
): Errors.Of<N> {
  return new RegistryError(kind, payload);
}

/** Narrow an unknown value to one registry entry. */
export function isError<N extends Errors.Name>(
  value: unknown,
  kind: N,
): value is Errors.Of<N> {
  return (
    typeof value === "object" &&
    value !== null &&
    "kind" in value &&
    value.kind === kind
  );
}

export const blankTitle = (title: string): Errors.Of<"BlankTitle"> =>
  makeError("BlankTitle", { title });

export const unknownRoom = (room: string): Errors.Of<"UnknownRoom"> =>
  makeError("UnknownRoom", { room });

export const badTime = (value: unknown): Errors.Of<"BadTime"> =>
  makeError("BadTime", { value });

export const emptySlot = (start: number, end: number): Errors.Of<"EmptySlot"> =>
  makeError("EmptySlot", { start, end });

export const clash = (
  room: string,
  start: number,
  end: number,
): Errors.Of<"Clash"> => makeError("Clash", { room, start, end });

export const notFound = (id: string): Errors.Of<"NotFound"> =>
  makeError("NotFound", { id });

export const badDate = (date: unknown): Errors.Of<"BadDate"> =>
  makeError("BadDate", { date });

export const badCount = (weeks: unknown): Errors.Of<"BadCount"> =>
  makeError("BadCount", { weeks });

export const emptyUndo = (): Errors.Of<"EmptyUndo"> =>
  makeError("EmptyUndo", {});

import { type Data, data } from "@tinker/core";
import { appError } from "./errors.ts";

export type Room = "Cedar" | "Maple";

export const rooms: readonly Room[] = ["Cedar", "Maple"];

/** The default calendar day: the fixed day earlier rounds booked. */
export const defaultDate = "2026-10-01";

export type Booking = {
  readonly id: string;
  readonly title: string;
  readonly room: Room;
  readonly date: string;
  readonly start: number;
  readonly end: number;
  readonly seriesId?: string;
};

export type BookInput = {
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

export type SeriesInput = {
  readonly title: string;
  readonly room: string;
  readonly date: string;
  readonly start: number;
  readonly end: number;
  readonly weeks: number;
};

export type EditInput = {
  readonly id: string;
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

/** Every saved booking across the days, sorted by date, then start time, then creation order. */
export const bookings: Data.Cell<readonly Booking[]> = data<readonly Booking[]>({
  label: "bookings",
  initial: [],
});

/** The one open edit draft: a copy of a saved booking, or empty when closed. */
export const editDraft: Data.Cell<Booking | undefined> = data<Booking | undefined>({
  label: "editDraft",
  initial: undefined,
});

/** Every id ever issued, in creation order: ids stay unique and fix the tiebreak. */
export const issuedIds: Data.Cell<readonly string[]> = data<readonly string[]>({
  label: "issuedIds",
  initial: [],
});

/** Undo history: the saved booking lists before each passing change, oldest first. */
export const undoHistory: Data.Cell<readonly (readonly Booking[])[]> = data<
  readonly (readonly Booking[])[]
>({
  label: "undoHistory",
  initial: [],
});

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

/** One raw field of a record, or `undefined` when the shape carries no such key. */
export function field(raw: unknown, key: string): unknown {
  return isRecord(raw) && key in raw ? raw[key] : undefined;
}

export function isRoom(value: string): value is Room {
  return rooms.some((room) => room === value);
}

/** Trusted booking fields after the boundary checks: `title` is trimmed and never blank. */
export type Fields = {
  readonly title: string;
  readonly room: Room;
  readonly date: string;
  readonly start: number;
  readonly end: number;
};

function requireMinute(value: unknown): number {
  if (
    typeof value !== "number" ||
    !Number.isInteger(value) ||
    value < 0 ||
    value > 1439
  ) {
    throw appError("BadTime", { value });
  }
  return value;
}

/** True when a string names a real calendar day as `YYYY-MM-DD`. */
function isRealDay(date: string): boolean {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(date);
  if (!match) return false;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const time = new Date(0);
  time.setUTCFullYear(year, month - 1, day);
  time.setUTCHours(0, 0, 0, 0);
  return (
    time.getUTCFullYear() === year &&
    time.getUTCMonth() === month - 1 &&
    time.getUTCDate() === day
  );
}

/** Validate one title: trimmed and never blank; blank text reports BlankTitle with the original text. */
export function requireTitle(value: unknown): string {
  const safe = typeof value === "string" ? value : "";
  if (safe.trim() === "") {
    throw appError("BlankTitle", { title: safe });
  }
  return safe.trim();
}

/** Validate one date: an absent date reads as the default day; anything else must be real. */
export function requireDate(value: unknown): string {
  if (value === undefined) {
    return defaultDate;
  }
  if (typeof value !== "string" || !isRealDay(value)) {
    throw appError("BadDate", { date: value });
  }
  return value;
}

/** The calendar day `days` after a date, in UTC. */
function addDays(date: string, days: number): string {
  const parts = date.split("-").map(Number);
  const time = new Date(0);
  time.setUTCFullYear(parts[0], parts[1] - 1, parts[2] + days);
  time.setUTCHours(0, 0, 0, 0);
  const year = time.getUTCFullYear().toString().padStart(4, "0");
  const month = (time.getUTCMonth() + 1).toString().padStart(2, "0");
  const day = time.getUTCDate().toString().padStart(2, "0");
  return `${year}-${month}-${day}`;
}

/** The `weeks` dates of a weekly series: seven days apart, starting from `date`. */
export function occurrenceDates(date: string, weeks: number): readonly string[] {
  const dates: string[] = [];
  for (let index = 0; index < weeks; index += 1) {
    dates.push(addDays(date, index * 7));
  }
  return dates;
}

/** Validate the repeat count on raw input: an integer of weeks from 1 to 12. */
export function weekCount(raw: unknown): number {
  return requireWeeks(field(raw, "weeks"));
}

/** Validate the repeat count: an integer of weeks from 1 to 12. */
export function requireWeeks(value: unknown): number {
  if (
    typeof value !== "number" ||
    !Number.isInteger(value) ||
    value < 1 ||
    value > 12
  ) {
    throw appError("BadCount", { weeks: value });
  }
  return value;
}

/** Validate raw booking fields in order: title, room, date, time, then the slot. */
export function validateFields(raw: unknown): Fields {
  const title = requireTitle(field(raw, "title"));
  const room = field(raw, "room");
  const safeRoom = typeof room === "string" ? room : "";
  if (!isRoom(safeRoom)) {
    throw appError("UnknownRoom", { room: safeRoom });
  }
  const date = requireDate(field(raw, "date"));
  const start = requireMinute(field(raw, "start"));
  const end = requireMinute(field(raw, "end"));
  if (end <= start) {
    throw appError("EmptySlot", { start, end });
  }
  return { title, room: safeRoom, date, start, end };
}

/** Read a value as text; anything that is not a string reads as blank. */
export function text(value: unknown): string {
  return typeof value === "string" ? value : "";
}

function minute(value: unknown): number {
  return typeof value === "number" ? value : Number.NaN;
}

/** Shape raw input into its declared type without judging it; the checks raise in the body. */
export function shapeBooking(raw: unknown): BookInput {
  const date = field(raw, "date");
  return {
    title: text(field(raw, "title")),
    room: text(field(raw, "room")),
    date: typeof date === "string" ? date : undefined,
    start: minute(field(raw, "start")),
    end: minute(field(raw, "end")),
  };
}

/** Shape raw series input into its declared type without judging it. */
export function shapeSeries(raw: unknown): SeriesInput {
  const booking = shapeBooking(raw);
  const weeks = field(raw, "weeks");
  return {
    ...booking,
    date: booking.date ?? defaultDate,
    weeks: typeof weeks === "number" ? weeks : Number.NaN,
  };
}

/** Shape raw series-title input into its declared type without judging it. */
export function shapeSeriesRename(raw: unknown): {
  seriesId: string;
  title: string;
} {
  return { seriesId: requireSeriesId(raw), title: text(field(raw, "title")) };
}

/** Shape raw edit input into its declared type; the checks raise in the body. */
export function shapeEdit(raw: unknown): EditInput {
  return { id: requireId(raw), ...shapeBooking(raw) };
}

/** Normalize an id at the boundary; a non-string id reads as absent. */
export function requireId(raw: unknown): string {
  const id = field(raw, "id");
  return typeof id === "string" ? id : "";
}

/** Normalize a series id at the boundary; a non-string id reads as absent. */
export function requireSeriesId(raw: unknown): string {
  const id = field(raw, "seriesId");
  return typeof id === "string" ? id : "";
}

/** True when one room's slot on one date overlaps a saved booking (back-to-back is not one). */
export function clashesWith(
  list: readonly Booking[],
  room: Room,
  date: string,
  start: number,
  end: number,
  skipId?: string,
): boolean {
  return list.some(
    (booking) =>
      booking.id !== skipId &&
      booking.room === room &&
      booking.date === date &&
      booking.start < end &&
      start < booking.end,
  );
}

/** The bookings of one series, in saved list order. */
export function seriesRows(
  list: readonly Booking[],
  seriesId: string,
): readonly Booking[] {
  return list.filter((booking) => booking.seriesId === seriesId);
}

/** The list with one series retitled: only its occurrences change, order kept. */
export function retitledSeries(
  list: readonly Booking[],
  seriesId: string,
  title: string,
): readonly Booking[] {
  return list.map((booking) =>
    booking.seriesId === seriesId ? { ...booking, title } : booking,
  );
}

/** Keep the list ordered by date, then start time, then creation order. */
export function sortedBookings(
  list: readonly Booking[],
  issued: readonly string[],
): readonly Booking[] {
  return [...list].sort(
    (a, b) =>
      a.date.localeCompare(b.date) ||
      a.start - b.start ||
      issued.indexOf(a.id) - issued.indexOf(b.id),
  );
}

import { describe, expect, it } from "vitest";
import {
  bookings,
  bookBooking,
  cancelBooking,
  discardEdit,
  editDraft,
  editDraft as draftCell,
  isError,
  openEdit,
  saveEdit,
} from "../src/index.ts";
import { createScope } from "@tinker/core";

/** Run one operation and catch the failure as an unknown value. */
function caught(run: () => unknown): unknown {
  try {
    run();
  } catch (error) {
    return error;
  }
  return undefined;
}

describe("book and cancel (round 1)", () => {
  it("books a slot and lists it", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    expect(saved.title).toBe("Standup");
    expect(saved.room).toBe("Cedar");
    expect(saved.start).toBe(540);
    expect(saved.end).toBe(600);
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("starts empty and two scopes share nothing", () => {
    const a = createScope();
    const b = createScope();
    expect(a.resolve(bookings)).toEqual([]);
    expect(b.resolve(bookings)).toEqual([]);
    a.run(bookBooking, { input: { title: "A", room: "Cedar", start: 0, end: 60 } });
    expect(b.resolve(bookings)).toEqual([]);
 expect(a.resolve(bookings).length).toBe(1);
  });

  it("rejects the same slot in one room but allows the other room and back-to-back", () => {
    const scope = createScope();
    const first = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const clash = caught(() =>
      scope.run(bookBooking, { input: { title: "Again", room: "Cedar", start: 540, end: 600 } }),
    );
    if (!isError(clash, "Clash")) throw new Error("unreachable");
    expect(scope.resolve(bookings)).toEqual([first]);
    const maple = scope.run(bookBooking, {
      input: { title: "Maple standup", room: "Maple", start: 540, end: 600 },
    });
    expect(maple.room).toBe("Maple");
    const later = scope.run(bookBooking, {
      input: { title: "Follow-up", room: "Cedar", start: 600, end: 660 },
    });
    expect(later.start).toBe(600);
    expect(scope.resolve(bookings)).toEqual([first, maple, later]);
  });

  it("rejects a blank title, unknown room, bad times, and an empty slot", () => {
    const scope = createScope();
    const blank = caught(() =>
      scope.run(bookBooking, { input: { title: "   ", room: "Cedar", start: 0, end: 60 } }),
    );
    if (!isError(blank, "BlankTitle")) throw new Error("unreachable");
    const room = caught(() =>
      scope.run(bookBooking, { input: { title: "X", room: "Oak", start: 0, end: 60 } }),
    );
    if (!isError(room, "UnknownRoom")) throw new Error("unreachable");
    const low = caught(() =>
      scope.run(bookBooking, { input: { title: "X", room: "Cedar", start: -1, end: 60 } }),
    );
    if (!isError(low, "BadTime")) throw new Error("unreachable");
    const high = caught(() =>
      scope.run(bookBooking, { input: { title: "X", room: "Cedar", start: 0, end: 1440 } }),
    );
    if (!isError(high, "BadTime")) throw new Error("unreachable");
    const fraction = caught(() =>
      scope.run(bookBooking, { input: { title: "X", room: "Cedar", start: 0.5, end: 60 } }),
    );
    if (!isError(fraction, "BadTime")) throw new Error("unreachable");
    const empty = caught(() =>
      scope.run(bookBooking, { input: { title: "X", room: "Cedar", start: 600, end: 600 } }),
    );
    if (!isError(empty, "EmptySlot")) throw new Error("unreachable");
    const backwards = caught(() =>
      scope.run(bookBooking, { input: { title: "X", room: "Cedar", start: 700, end: 600 } }),
    );
    if (!isError(backwards, "EmptySlot")) throw new Error("unreachable");
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("trims the title", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "  Standup  ", room: "Cedar", start: 540, end: 600 },
    });
    expect(saved.title).toBe("Standup");
  });

  it("orders by start time, then creation order", () => {
    const scope = createScope();
    const a = scope.run(bookBooking, { input: { title: "A", room: "Cedar", start: 600, end: 660 } });
    const b = scope.run(bookBooking, { input: { title: "B", room: "Cedar", start: 540, end: 600 } });
    const c = scope.run(bookBooking, { input: { title: "C", room: "Maple", start: 600, end: 660 } });
    expect(scope.resolve(bookings).map((booked) => booked.id)).toEqual([b.id, a.id, c.id]);
  });

  it("cancels by id; a second cancel reports not found", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(cancelBooking, { input: { id: saved.id } });
    expect(scope.resolve(bookings)).toEqual([]);
    const again = caught(() => scope.run(cancelBooking, { input: { id: saved.id } }));
    if (!isError(again, "NotFound")) throw new Error("unreachable");
    expect(again.payload.id).toBe(saved.id);
  });

  it("frees a slot after cancel", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(cancelBooking, { input: { id: saved.id } });
    const again = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    expect(again.id).not.toBe(saved.id);
  });

  it("two calls for one empty slot create exactly one booking", () => {
    const scope = createScope();
    scope.run(bookBooking, { input: { title: "First", room: "Cedar", start: 540, end: 600 } });
    const second = caught(() =>
      scope.run(bookBooking, { input: { title: "Second", room: "Cedar", start: 540, end: 600 } }),
    );
    if (!isError(second, "Clash")) throw new Error("unreachable");
    expect(scope.resolve(bookings).length).toBe(1);
  });
});

describe("edit a booking (round 2)", () => {
  it("openEdit returns a copy; writing to it never changes the saved list", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const draft = scope.run(openEdit, { input: { id: saved.id } });
    expect(draft).toEqual(saved);
    expect(draft).not.toBe(saved);
    const leaked = draft as { title: string };
    leaked.title = "Changed";
    expect(scope.resolve(bookings)[0]?.title).toBe("Standup");
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("a discard leaves the saved booking unchanged and closes the draft", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    scope.run(discardEdit, { input: { id: saved.id } });
    expect(scope.resolve(bookings)).toEqual([saved]);
    expect(scope.resolve(editDraft)).toBeUndefined();
  });

  it("save replaces the booking with checked values", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const updated = scope.run(saveEdit, {
      input: { id: saved.id, title: "  Planning  ", room: "Maple", start: 660, end: 720 },
    });
    expect(updated.title).toBe("Planning");
    expect(updated.room).toBe("Maple");
    expect(updated.start).toBe(660);
    expect(updated.end).toBe(720);
    expect(updated.id).toBe(saved.id);
    expect(scope.resolve(bookings)).toEqual([updated]);
    expect(scope.resolve(editDraft)).toBeUndefined();
  });

  it("a clash on save reports Clash and keeps the booking and draft", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(bookBooking, { input: { title: "Other", room: "Cedar", start: 660, end: 720 } });
    scope.run(openEdit, { input: { id: saved.id } });
    const clash = caught(() =>
      scope.run(saveEdit, { input: { id: saved.id, title: "Moved", room: "Cedar", start: 660, end: 720 } }),
    );
    if (!isError(clash, "Clash")) throw new Error("unreachable");
    expect(scope.resolve(bookings)[0]?.title).toBe("Standup");
    expect(scope.resolve(editDraft)?.id).toBe(saved.id);
  });

  it("saving the draft back to its own slot passes: the clash check skips the edited booking", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const kept = scope.run(saveEdit, {
      input: { id: saved.id, title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    expect(kept.id).toBe(saved.id);
  });

  it("a failed save keeps the saved booking and the draft open for another try", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const blank = caught(() =>
      scope.run(saveEdit, { input: { id: saved.id, title: " ", room: "Cedar", start: 540, end: 600 } }),
    );
    if (!isError(blank, "BlankTitle")) throw new Error("unreachable");
    expect(scope.resolve(editDraft)?.title).toBe("Standup");
    const updated = scope.run(saveEdit, {
      input: { id: saved.id, title: "Planning", room: "Cedar", start: 540, end: 600 },
    });
    expect(updated.title).toBe("Planning");
  });

  it("a draft blocks nothing until save: another booking can take a slot while the draft is open", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const taker = scope.run(bookBooking, {
      input: { title: "Taker", room: "Cedar", start: 660, end: 720 },
    });
    expect(taker.title).toBe("Taker");
    const clash = caught(() =>
      scope.run(saveEdit, { input: { id: saved.id, title: "Planning", room: "Cedar", start: 660, end: 720 } }),
    );
    if (!isError(clash, "Clash")) throw new Error("unreachable");
    expect(scope.resolve(editDraft)?.id).toBe(saved.id);
    expect(scope.resolve(bookings).map((booked) => booked.id)).toContain(taker.id);
    expect(scope.resolve(bookings)[0]?.title).toBe("Standup");
  });

  it("openEdit of an unknown id reports NotFound", () => {
    const scope = createScope();
    const missing = caught(() => scope.run(openEdit, { input: { id: "nope" } }));
    if (!isError(missing, "NotFound")) throw new Error("unreachable");
  });

  it("discardEdit of an unknown id reports NotFound", () => {
    const scope = createScope();
    const missing = caught(() => scope.run(discardEdit, { input: { id: "nope" } }));
    if (!isError(missing, "NotFound")) throw new Error("unreachable");
  });

  it("save or discard for a closed or missing draft reports NotFound with that id", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const closedSave = caught(() =>
      scope.run(saveEdit, { input: { id: saved.id, title: "X", room: "Cedar", start: 540, end: 600 } }),
    );
    if (!isError(closedSave, "NotFound")) throw new Error("unreachable");
    const closedDiscard = caught(() => scope.run(discardEdit, { input: { id: saved.id } }));
    if (!isError(closedDiscard, "NotFound")) throw new Error("unreachable");
    scope.run(openEdit, { input: { id: saved.id } });
    scope.run(discardEdit, { input: { id: saved.id } });
    const afterClose = caught(() =>
      scope.run(saveEdit, { input: { id: saved.id, title: "X", room: "Cedar", start: 540, end: 600 } }),
    );
    if (!isError(afterClose, "NotFound")) throw new Error("unreachable");
  });

  it("canceling the drafted booking closes its draft too", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    scope.run(cancelBooking, { input: { id: saved.id } });
    expect(scope.resolve(bookings)).toEqual([]);
    expect(scope.resolve(editDraft)).toBeUndefined();
    const afterCancel = caught(() =>
      scope.run(saveEdit, { input: { id: saved.id, title: "X", room: "Cedar", start: 540, end: 600 } }),
    );
    if (!isError(afterCancel, "NotFound")) throw new Error("unreachable");
  });

  it("only one draft is open at a time; opening a second closes the first", () => {
    const scope = createScope();
    const a = scope.run(bookBooking, { input: { title: "A", room: "Cedar", start: 540, end: 600 } });
    const b = scope.run(bookBooking, { input: { title: "B", room: "Cedar", start: 660, end: 720 } });
    scope.run(openEdit, { input: { id: a.id } });
    scope.run(openEdit, { input: { id: b.id } });
    expect(scope.resolve(editDraft)?.id).toBe(b.id);
    const lostA = caught(() =>
      scope.run(saveEdit, { input: { id: a.id, title: "A2", room: "Cedar", start: 540, end: 600 } }),
    );
    if (!isError(lostA, "NotFound")) throw new Error("unreachable");
    expect(scope.resolve(bookings)[0]?.title).toBe("A");
  });

  it("unsaved text never changes the list", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const draft = scope.run(openEdit, { input: { id: saved.id } });
