    expect(scope.resolve(bookings)).toEqual([saved]);
  });
});

import {
  bookSeries,
  cancelSeries,
} from "../src/index.ts";

describe("dates and a weekly series (round 3)", () => {
  it("an omitted date books the default day 2026-10-01", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    expect(saved.date).toBe("2026-10-01");
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("an explicit date is kept and old calls still work beside it", () => {
    const scope = createScope();
    const onSecond = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-02", start: 540, end: 600 },
    });
    expect(onSecond.date).toBe("2026-10-02");
    const onDefault = scope.run(bookBooking, {
      input: { title: "Later", room: "Cedar", start: 600, end: 660 },
    });
    expect(onDefault.date).toBe("2026-10-01");
    expect(scope.resolve(bookings).map((booked) => booked.date)).toEqual([
      "2026-10-01",
      "2026-10-02",
    ]);
  });

  it("rejects a date that is not a real YYYY-MM-DD day with BadDate", () => {
    const scope = createScope();
    for (const bad of ["2026-02-30", "2026-13-01", "not-a-date", "2026-10-1", 123, null]) {
      const error = caught(() =>
        scope.run(bookBooking, {
          input: { title: "X", room: "Cedar", date: bad as never, start: 0, end: 60 },
        }),
      );
      if (!isError(error, "BadDate")) throw new Error("unreachable");
      expect(error.payload.date).toEqual(bad);
    }
    // a leap day that exists is accepted
    const leap = scope.run(bookBooking, {
      input: { title: "Leap", room: "Cedar", date: "2028-02-29", start: 0, end: 60 },
    });
    expect(leap.date).toBe("2028-02-29");
  });

  it("the same slot on two dates never clashes; one room on one date still does", () => {
    const scope = createScope();
    scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-01", start: 540, end: 600 },
    });
    const otherDay = scope.run(bookBooking, {
      input: { title: "Same slot, other day", room: "Cedar", date: "2026-10-02", start: 540, end: 600 },
    });
    expect(otherDay.date).toBe("2026-10-02");
    const clash = caught(() =>
      scope.run(bookBooking, {
        input: { title: "Same slot, same day", room: "Cedar", date: "2026-10-01", start: 540, end: 600 },
      }),
    );
    if (!isError(clash, "Clash")) throw new Error("unreachable");
  });

  it("orders by date, then start time, then creation order", () => {
    const scope = createScope();
    const late = scope.run(bookBooking, {
      input: { title: "Late", room: "Cedar", date: "2026-10-02", start: 540, end: 600 },
    });
    const lateSameSlot = scope.run(bookBooking, {
      input: { title: "Late too", room: "Maple", date: "2026-10-02", start: 540, end: 600 },
    });
    const early = scope.run(bookBooking, {
      input: { title: "Early", room: "Cedar", date: "2026-10-01", start: 900, end: 960 },
    });
    expect(scope.resolve(bookings).map((booked) => booked.id)).toEqual([
      early.id,
      late.id,
      lateSameSlot.id,
    ]);
  });

  it("bookSeries books weeks dates seven days apart sharing one seriesId", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 3 },
    });
    expect(made.map((booked) => booked.date)).toEqual(["2026-10-06", "2026-10-13", "2026-10-20"]);
    expect(new Set(made.map((booked) => booked.seriesId)).size).toBe(1);
    expect(made[0]?.seriesId).toBeDefined();
    expect(scope.resolve(bookings)).toEqual(made);
  });

  it("one series date being taken books nothing and reports Clash", () => {
    const scope = createScope();
    scope.run(bookBooking, {
      input: { title: "Blocker", room: "Cedar", date: "2026-10-13", start: 540, end: 600 },
    });
    const failed = caught(() =>
      scope.run(bookSeries, {
        input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 3 },
      }),
    );
    if (!isError(failed, "Clash")) throw new Error("unreachable");
    expect(scope.resolve(bookings).map((booked) => booked.title)).toEqual(["Blocker"]);
  });

  it("rejects a weeks count outside 1..12 or not an integer with BadCount", () => {
    const scope = createScope();
    for (const weeks of [0, 13, 1.5, -1, "3"]) {
      const error = caught(() =>
        scope.run(bookSeries, {
          input: { title: "X", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: weeks as never },
        }),
      );
      if (!isError(error, "BadCount")) throw new Error("unreachable");
      expect(error.payload.weeks).toEqual(weeks);
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("canceling one occurrence frees one day and leaves the rest of its series", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 3 },
    });
    const middle = made[1];
    if (middle === undefined) throw new Error("unreachable");
    scope.run(cancelBooking, { input: { id: middle.id } });
    const rest = scope.resolve(bookings);
    expect(rest.map((booked) => booked.date)).toEqual(["2026-10-06", "2026-10-20"]);
    const refill = scope.run(bookBooking, {
      input: { title: "Freed", room: "Cedar", date: "2026-10-13", start: 540, end: 600 },
    });
    expect(refill.date).toBe("2026-10-13");
  });

  it("cancelSeries removes every occurrence; an unknown seriesId reports NotFound", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 3 },
    });
    const seriesId = made[0]?.seriesId;
    if (seriesId === undefined) throw new Error("unreachable");
    scope.run(cancelSeries, { input: { seriesId } });
    expect(scope.resolve(bookings)).toEqual([]);
    const again = caught(() => scope.run(cancelSeries, { input: { seriesId } }));
    if (!isError(again, "NotFound")) throw new Error("unreachable");
    expect(again.payload.id).toBe(seriesId);
  });

  it("cancelSeries of a one-off-only list reports NotFound and removes nothing", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "One-off", room: "Cedar", start: 540, end: 600 },
    });
    const missing = caught(() => scope.run(cancelSeries, { input: { seriesId: saved.id } }));
    if (!isError(missing, "NotFound")) throw new Error("unreachable");
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("canceling the series closes the draft of its drafted occurrence", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 2 },
    });
    const first = made[0];
    if (first === undefined) throw new Error("unreachable");
    scope.run(openEdit, { input: { id: first.id } });
    scope.run(cancelSeries, { input: { seriesId: first.seriesId ?? "" } });
    expect(scope.resolve(bookings)).toEqual([]);
    expect(scope.resolve(editDraft)).toBeUndefined();
  });

  it("saveEdit accepts a date and clash-checks only that room on that date", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-01", start: 540, end: 600 },
    });
    scope.run(bookBooking, {
      input: { title: "Other", room: "Cedar", date: "2026-10-02", start: 600, end: 660 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const moved = scope.run(saveEdit, {
      input: { id: saved.id, title: "Moved", room: "Maple", date: "2026-10-02", start: 600, end: 660 },
    });
    expect(moved.date).toBe("2026-10-02");
    // the same room and slot on the target date still clashes
    scope.run(openEdit, { input: { id: saved.id } });
    const clash = caught(() =>
      scope.run(saveEdit, {
        input: { id: saved.id, title: "Moved", room: "Cedar", date: "2026-10-02", start: 600, end: 660 },
      }),
    );
    if (!isError(clash, "Clash")) throw new Error("unreachable");
    expect(scope.resolve(editDraft)?.id).toBe(saved.id);
  });

  it("a failed date save keeps the saved booking; a BadDate save reports BadDate", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const bad = caught(() =>
      scope.run(saveEdit, {
        input: { id: saved.id, title: "X", room: "Cedar", date: "2026-02-30", start: 540, end: 600 },
      }),
    );
    if (!isError(bad, "BadDate")) throw new Error("unreachable");
    expect(scope.resolve(bookings)).toEqual([saved]);
    expect(scope.resolve(editDraft)?.id).toBe(saved.id);
  });

  it("saving a series occurrence keeps its seriesId; editing skips only the edited booking", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 2 },
    });
    const first = made[0];
    if (first === undefined) throw new Error("unreachable");
    scope.run(openEdit, { input: { id: first.id } });
    const renamed = scope.run(saveEdit, {
      input: { id: first.id, title: "Renamed", room: "Cedar", date: "2026-10-06", start: 540, end: 600 },
    });
    expect(renamed.seriesId).toBe(first.seriesId);
    expect(scope.resolve(bookings).map((booked) => booked.title)).toEqual(["Renamed", "Standup"]);
  });

  it("a draft on one date blocks nothing on another date until save", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-01", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const taker = scope.run(bookBooking, {
      input: { title: "Taker", room: "Cedar", date: "2026-10-02", start: 540, end: 600 },
    });
    expect(taker.title).toBe("Taker");
    expect(scope.resolve(editDraft)?.id).toBe(saved.id);
  });
});

