    const renamed = scope.run(renameSeries, {
      input: { seriesId: made[0]?.seriesId ?? "", title: "  Weekly sync  " },
    });
    expect(renamed.map((booked) => booked.title)).toEqual(["Weekly sync", "Weekly sync", "Weekly sync"]);
    expect(renamed.map((booked) => booked.id)).toEqual(before.map((booked) => booked.id));
    expect(renamed.map((booked) => booked.date)).toEqual(["2026-10-06", "2026-10-13", "2026-10-20"]);
    expect(new Set(renamed.map((booked) => booked.seriesId)).size).toBe(1);
    expect(scope.resolve(bookings)).toEqual(renamed);
