  it("returns the renamed bookings in saved list order and renames only that series", () => {
    const scope = createScope();
    const made = scope.run(seriesOp, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 2 },
    });
    const other = scope.run(seriesOp, {
      input: { title: "Other", room: "Maple", date: "2026-10-01", start: 540, end: 600, weeks: 2 },
    });
    const oneOff = scope.run(bookOp, {
      input: { title: "One-off", room: "Cedar", date: "2026-10-07", start: 0, end: 30 },
    });
    const renamed = scope.run(renameSeries, {
      input: { seriesId: made[0]?.seriesId ?? "", title: "Renamed" },
    });
    // saved list order by date: the 10-01 occurrence, the renamed 10-06
    // occurrences, the 10-07 one-off, then the 10-08 and 10-13 occurrences
    expect(scope.resolve(bookings).map((booked) => booked.title)).toEqual([
      "Other",
      "Renamed",
      "One-off",
      "Other",
      "Renamed",
    ]);
    expect(renamed.every((booked) => booked.seriesId === made[0]?.seriesId)).toBe(true);
    expect(scope.resolve(bookings).filter((booked) => booked.title === "Other").map((booked) => booked.id))
      .toEqual(other.map((booked) => booked.id));
    expect(scope.resolve(bookings).find((booked) => booked.id === oneOff.id)?.title).toBe("One-off");
  });

  it("renames only the remaining occurrences after one was canceled", () => {
    const scope = createScope();
    const made = scope.run(seriesOp, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 3 },
    });
    const middle = made[1];
    if (middle === undefined) throw new Error("unreachable");
    scope.run(cancelOp, { input: { id: middle.id } });
    const renamed = scope.run(renameSeries, {
      input: { seriesId: made[0]?.seriesId ?? "", title: "Renamed" },
    });
    expect(renamed.map((booked) => booked.id)).toEqual([made[0]?.id, made[2]?.id]);
    expect(scope.resolve(bookings).map((booked) => booked.title)).toEqual(["Renamed", "Renamed"]);
  });

  it("a blank title reports BlankTitle with the original text and changes nothing", () => {
    const scope = createScope();
    const made = scope.run(seriesOp, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 2 },
    });
    const blank = caught(() =>
      scope.run(renameSeries, { input: { seriesId: made[0]?.seriesId ?? "", title: "   " } }),
    );
    if (!isError(blank, "BlankTitle")) throw new Error("unreachable");
    expect(blank.payload.title).toBe("   ");
    expect(scope.resolve(bookings).every((booked) => booked.title === "Standup")).toBe(true);
  });

  it("an unknown series reports NotFound with the seriesId and changes nothing", () => {
    const scope = createScope();
    const saved = scope.run(bookOp, {
      input: { title: "One-off", room: "Cedar", start: 540, end: 600 },
    });
    const missing = caught(() =>
      scope.run(renameSeries, { input: { seriesId: "nope", title: "Renamed" } }),
    );
    if (!isError(missing, "NotFound")) throw new Error("unreachable");
    expect(missing.payload.id).toBe("nope");
    // a one-off booking's id is not a series id either
    const oneOff = caught(() =>
      scope.run(renameSeries, { input: { seriesId: saved.id, title: "Renamed" } }),
    );
    if (!isError(oneOff, "NotFound")) throw new Error("unreachable");
    expect(scope.resolve(bookings)[0]?.title).toBe("One-off");
  });

  it("a failed rename adds no undo step", () => {
    const scope = createScope();
    scope.run(bookOp, { input: { title: "A", room: "Cedar", start: 540, end: 600 } });
    const failed = caught(() =>
      scope.run(renameSeries, { input: { seriesId: "nope", title: "Renamed" } }),
    );
    if (!isError(failed, "NotFound")) throw new Error("unreachable");
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([]);
    const empty = caught(() => scope.run(undoChange, {}));
    if (!isError(empty, "EmptyUndo")) throw new Error("unreachable");
  });

  it("a passing rename is one undo step that restores the exact prior list", () => {
    const scope = createScope();
    const made = scope.run(seriesOp, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 3 },
    });
    scope.run(renameSeries, {
      input: { seriesId: made[0]?.seriesId ?? "", title: "Renamed" },
    });
    expect(scope.resolve(bookings).every((booked) => booked.title === "Renamed")).toBe(true);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual(made);
    expect(scope.resolve(bookings).map((booked) => booked.title)).toEqual([
      "Standup",
      "Standup",
      "Standup",
    ]);
  });

  it("a rename leaves an open booking draft alone, even on the renamed series", () => {
    const scope = createScope();
    const made = scope.run(seriesOp, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 2 },
    });
    const first = made[0];
    if (first === undefined) throw new Error("unreachable");
    scope.run(openOp, { input: { id: first.id } });
    scope.run(renameSeries, {
      input: { seriesId: first.seriesId ?? "", title: "Renamed" },
    });
    expect(scope.resolve(editDraft)).toEqual(first);
    expect(scope.resolve(editDraft)?.id).toBe(first.id);
  });

  it("two scopes share nothing: a rename in one leaves the other alone", () => {
    const a = createScope();
    const b = createScope();
    const madeA = a.run(seriesOp, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 2 },
    });
    const madeB = b.run(seriesOp, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 2 },
    });
    a.run(renameSeries, { input: { seriesId: madeA[0]?.seriesId ?? "", title: "Only A" } });
    expect(b.resolve(bookings).every((booked) => booked.title === "Standup")).toBe(true);
    expect(a.resolve(bookings).every((booked) => booked.title === "Only A")).toBe(true);
    expect(madeB[0]?.seriesId).not.toBe(madeA[0]?.seriesId);
  });
});

/**
 * The one error registry for the booking app. Every failure is raised from here,
 * so callers narrow with `isError(error, "Kind")` instead of matching strings.
 */

/** Payload carried by each booking error kind. */
export type Payloads = {
  BlankTitle: { title: string };
  UnknownRoom: { room: string };
  BadTime: { value: unknown };
  EmptySlot: { start: number; end: number };
  Clash: { room: string; start: number; end: number };
  NotFound: { id: string };
  BadDate: { date: unknown };
  BadCount: { weeks: unknown };
  EmptyUndo: {};
};

export namespace Errors {
  /** Every booking error kind. */
  export type Name = keyof Payloads;
  /** The typed payload carried by one error kind. */
  export type Payload<N extends Name> = Payloads[N];
  /** A booking error: identified by `kind`, carrying a typed `payload`. */
  export type Of<N extends Name = Name> = Error & {
    readonly kind: N;
    readonly payload: Payload<N>;
  };
}

/** The concrete error instance behind every factory below. */
class RegistryError<N extends Errors.Name> extends Error implements Errors.Of<N> {
  readonly kind: N;
  readonly payload: Errors.Payload<N>;

  constructor(kind: N, payload: Errors.Payload<N>) {
    super(kind);
    this.name = "BookingError";
    this.kind = kind;
    this.payload = payload;
  }
}

/** Build one registry error. Callers should prefer the named factories. */
export function makeError<N extends Errors.Name>(
  kind: N,
  payload: Errors.Payload<N>,
): Errors.Of<N> {
  return new RegistryError(kind, payload);
}

/** Narrow an unknown value to one registry entry. */
export function isError<N extends Errors.Name>(
  value: unknown,
  kind: N,
): value is Errors.Of<N> {
  return (
    typeof value === "object" &&
    value !== null &&
    "kind" in value &&
    value.kind === kind
  );
}

/** Every registry kind, so a value can be narrowed against the whole registry at once. */
const NAMES: readonly Errors.Name[] = [
  "BlankTitle",
  "UnknownRoom",
  "BadTime",
  "EmptySlot",
  "Clash",
  "NotFound",
  "BadDate",
  "BadCount",
  "EmptyUndo",
];

/** Narrow an unknown value to any entry of this registry. */
export function isRegistryError(value: unknown): value is Errors.Of {
  return NAMES.some((kind) => isError(value, kind));
}

/** The kind of a registry error. Rethrows any value that is not one of ours. */
export function errorKind(value: unknown): Errors.Name {
  if (!isRegistryError(value)) {
    throw value;
  }
  return value.kind;
}

export const blankTitle = (title: string): Errors.Of<"BlankTitle"> =>
  makeError("BlankTitle", { title });

export const unknownRoom = (room: string): Errors.Of<"UnknownRoom"> =>
  makeError("UnknownRoom", { room });

export const badTime = (value: unknown): Errors.Of<"BadTime"> =>
  makeError("BadTime", { value });

export const emptySlot = (start: number, end: number): Errors.Of<"EmptySlot"> =>
  makeError("EmptySlot", { start, end });

export const clash = (
  room: string,
  start: number,
  end: number,
): Errors.Of<"Clash"> => makeError("Clash", { room, start, end });

export const notFound = (id: string): Errors.Of<"NotFound"> =>
  makeError("NotFound", { id });

export const badDate = (date: unknown): Errors.Of<"BadDate"> =>
  makeError("BadDate", { date });

export const badCount = (weeks: unknown): Errors.Of<"BadCount"> =>
  makeError("BadCount", { weeks });

export const emptyUndo = (): Errors.Of<"EmptyUndo"> =>
  makeError("EmptyUndo", {});

import { expect } from "vitest";
import type { Scope } from "@tinker/core";
import { editDraft, moves, stock } from "../src/index.ts";

/** The observable desk state of one scope. */
export function state(scope: Scope.Handle) {
  return { stock: scope.resolve(stock), moves: scope.resolve(moves), draft: scope.resolve(editDraft) };
}

/** The failure one call throws; unreachable when the call passes. */
export function failure(call: () => unknown): unknown {
  try {
    call();
  } catch (error) {
    return error;
  }
  return expect.unreachable("expected the call to fail");
}

