import { operation, type Operation, type Scope } from "@tinker/core";
import { asId, asItem, asPlace, asQuantity, applyMove, readFields, reverseMove, withField, type EditMoveInput, type FormText, type Move, type MoveInput } from "./model.ts";
import { asManaged, fail, type Errors } from "./errors.ts";
import { editDraft, editForm, filter, moves, newForm, nextId, notice, stock, undoStack, type MoveFilter } from "./state.ts";

/** Record a managed failure on the notice block, then rethrow it; anything else is rethrown untouched. */
function recorded(noticeSlot: Scope.DataController<Errors.Of | undefined>, error: unknown): never {
  const managed = asManaged(error);
  if (managed !== undefined) noticeSlot.set(managed);
  throw error;
}

/**
 * Move stock between two places: validates the raw submission, then subtracts
 * the source and adds the target, appends one saved move with a fresh
 * scope-unique id, and records one undo step. A failed move changes no stock,
 * moves, draft, or undo history.
 */
export const moveStock: Operation.Handle<Move, MoveInput> = operation({
  label: "moveStock",
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    undo: undoStack.controller,
    nextId: nextId.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    try {
      const fields = readFields(ctx.rawInput);
      const item = asItem(fields.item);
      const from = asPlace(fields.from);
      const to = asPlace(fields.to);
      if (from === to) fail("SamePlace", { place: from });
      const quantity = asQuantity(fields.quantity);
      const stockBefore = deps.stock.get();
      const movesBefore = deps.moves.get();
      const moved = applyMove(stockBefore, item, from, to, quantity);
      const record: Move = { id: `move-${deps.nextId.get()}`, item, from, to, quantity };
      deps.nextId.update((n) => n + 1);
      deps.undo.update((history) => [...history, { stock: stockBefore, moves: movesBefore }]);
      deps.stock.set(moved);
      deps.moves.set([...movesBefore, record]);
      deps.notice.set(undefined);
      return record;
    } catch (error) {
      throw recorded(deps.notice, error);
    }
  },
});

/**
 * Copy one saved move into the open draft and seed the editor text with it.
 * Opening a second move drops the first draft and its unsaved text, and adds no
 * undo step. Unknown ids report `NotFound`.
 */
export const openMoveEdit: Operation.Handle<Move, { id: string }> = operation({
  label: "openMoveEdit",
  depends: {
    draft: editDraft.controller,
    moves: moves.controller,
    text: editForm.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    try {
      const id = asId(readFields(ctx.rawInput).id);
      const found = deps.moves.get().find((move) => move.id === id);
      if (found === undefined) fail("NotFound", { id });
      const copy: Move = { ...found };
      deps.draft.set(copy);
      deps.text.set({ item: copy.item, from: copy.from, to: copy.to, quantity: String(copy.quantity) });
      deps.notice.set(undefined);
      return copy;
    } catch (error) {
      throw recorded(deps.notice, error);
    }
  },
});

/**
 * Replace the open draft's saved move in place, keeping its id and list
 * position: first reverse the old move against current stock, then apply the
 * replacement against the restored stock, checking both before writing. One
 * undo step covers the whole save; a failed save writes nothing and keeps the
 * editor open with its typed values.
 */
export const saveMoveEdit: Operation.Handle<Move, EditMoveInput> = operation({
  label: "saveMoveEdit",
  depends: {
    draft: editDraft.controller,
    stock: stock.controller,
    moves: moves.controller,
    undo: undoStack.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    try {
      const fields = readFields(ctx.rawInput);
      const id = asId(fields.id);
      const saved = deps.moves.get();
      const index = saved.findIndex((move) => move.id === id);
      const open = deps.draft.get();
      if (open?.id !== id || index < 0) fail("NotFound", { id });
      const old = saved[index];
      const item = asItem(fields.item);
      const from = asPlace(fields.from);
      const to = asPlace(fields.to);
      if (from === to) fail("SamePlace", { place: from });
      const quantity = asQuantity(fields.quantity);
      const stockBefore = deps.stock.get();
      const restored = reverseMove(stockBefore, old);
      const moved = applyMove(restored, item, from, to, quantity);
      const replaced: Move = { id, item, from, to, quantity };
      deps.undo.update((history) => [...history, { stock: stockBefore, moves: saved }]);
      deps.stock.set(moved);
      deps.moves.set(saved.map((move, at) => (at === index ? replaced : move)));
      deps.draft.set(undefined);
      deps.notice.set(undefined);
      return replaced;
    } catch (error) {
      throw recorded(deps.notice, error);
    }
  },
});

/**
 * Close the open draft without changing stock, moves, or undo history. A closed
 * or different draft reports `NotFound`.
 */
export const discardMoveEdit: Operation.Handle<void, { id: string }> = operation({
  label: "discardMoveEdit",
  depends: {
    draft: editDraft.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    try {
      const id = asId(readFields(ctx.rawInput).id);
      const open = deps.draft.get();
      if (open?.id !== id) fail("NotFound", { id });
      deps.draft.set(undefined);
      deps.notice.set(undefined);
    } catch (error) {
      throw recorded(deps.notice, error);
    }
  },
});

/**
 * Restore the exact stock and move list before the last passing change, without
 * adding a step and without touching the draft, form text, or filter. Empty
 * history reports `EmptyUndo`; issued ids are never rewound.
 */
export const undoMove: Operation.Handle<void, void> = operation({
  label: "undoMove",
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    undo: undoStack.controller,
    notice: notice.controller,
  },
  run: (deps) => {
    try {
      const history = deps.undo.get();
      if (history.length === 0) fail("EmptyUndo", {});
      const before = history[history.length - 1];
      deps.undo.set(history.slice(0, -1));
      deps.stock.set(before.stock);
      deps.moves.set(before.moves);
      deps.notice.set(undefined);
    } catch (error) {
      throw recorded(deps.notice, error);
    }
  },
});

/** One form field retyped from the screen. */
type FieldInput = {
  field: keyof FormText;
  value: string;
};

/** Type into one new-move form field; the notice block resets like any passing action. */
export const typeNew: Operation.Handle<void, FieldInput> = operation({
  label: "typeNew",
  depends: {
    form: newForm.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    const { field, value } = ctx.input;
    deps.form.update((text) => withField(text, field, value));
    deps.notice.set(undefined);
  },
});

/** Type into one editor field; saved moves, stock, and undo history are untouched. */
export const typeEdit: Operation.Handle<void, FieldInput> = operation({
  label: "typeEdit",
  depends: {
    form: editForm.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    const { field, value } = ctx.input;
    deps.form.update((text) => withField(text, field, value));
    deps.notice.set(undefined);
  },
});

/** Choose which move rows the desk shows; saved moves and stock are untouched. */
export const chooseFilter: Operation.Handle<void, { filter: MoveFilter }> = operation({
  label: "chooseFilter",
  depends: {
    filter: filter.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    deps.filter.set(ctx.input.filter);
    deps.notice.set(undefined);
  },
});

import { useId, type ReactNode } from "react";
import { createScope } from "@tinker/core";
import { ScopeProvider, useData, useRun } from "@tinker/react";
import {
  addPrerequisite,
  chooseCourse,
  chooseFilter,
  choosePrerequisite,
  completeCourse,
  courseChoice,
  courses,
  filterMode,
  noticeCell,
  prerequisiteChoice,
  removePrerequisite,
  reopenCourse,
  submitCourse,
  titleDraft,
  typeTitle,
  undoPlan,
  type Course,
  type FilterMode,
} from "./plan.ts";

type Choice = { readonly value: string; readonly label: string };

function isReady(course: Course, all: readonly Course[]): boolean {
  return course.prerequisiteIds.every(
    (id) => all.find((other) => other.id === id)?.done ?? false,
  );
}

function statusText(course: Course, all: readonly Course[]): string {
  if (course.done) return "Done";
  return isReady(course, all) ? "Ready" : "Blocked";
}

function requiresText(course: Course, all: readonly Course[]): string {
  if (course.prerequisiteIds.length === 0) return "None";
  return course.prerequisiteIds
    .map((id) => all.find((other) => other.id === id)?.title ?? id)
    .join(", ");
}

function visibleCourses(all: readonly Course[], mode: FilterMode): readonly Course[] {
  if (mode === "All") return all;
  if (mode === "Done") return all.filter((course) => course.done);
  return all.filter((course) => !course.done && isReady(course, all));
}

function selectChoices(all: readonly Course[], selected: string): readonly Choice[] {
  const choices: Choice[] = [
    { value: "", label: "Choose course" },
    ...all.map((course) => ({ value: course.id, label: course.title })),
  ];
  if (selected !== "" && !all.some((course) => course.id === selected)) {
    choices.push({ value: selected, label: "Removed course" });
  }
  return choices;
}

/** The learning plan app: a fresh scope per mounted root. */
export function PlanApp(): ReactNode {
  return (
    <ScopeProvider create={() => createScope()}>
      <PlanScreen />
    </ScopeProvider>
  );
}

function PlanScreen(): ReactNode {
  const undo = useRun(undoPlan);
  return (
    <main>
      <Notice />
      <CreateForm />
      <CourseFilters />
      <CoursesTable />
      <LinkForm />
      <button type="button" onClick={() => undo.run({})}>
        Undo
      </button>
    </main>
  );
}

function Notice(): ReactNode {
  const kind = useData(noticeCell);
  return <div role="alert">{kind === null ? "" : kind}</div>;
}

function CreateForm(): ReactNode {
  const text = useData(titleDraft);
  const typing = useRun(typeTitle);
  const saving = useRun(submitCourse);
  const titleId = useId();
  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        saving.run({});
      }}
    >
      <label htmlFor={titleId}>Title</label>
      <input
        id={titleId}
        value={text}
        onChange={(event) => typing.run({ input: { text: event.currentTarget.value } })}
      />
      <button type="submit">Add course</button>
    </form>
  );
}

function CourseFilters(): ReactNode {
  const mode = useData(filterMode);
  const choose = useRun(chooseFilter);
  const modes: readonly FilterMode[] = ["All", "Ready", "Done"];
  return (
    <div>
      {modes.map((filter) => (
        <button
          key={filter}
          type="button"
          aria-pressed={mode === filter}
          onClick={() => choose.run({ input: { filter } })}
        >
          {filter}
        </button>
      ))}
    </div>
  );
}

function CoursesTable(): ReactNode {
  const all = useData(courses);
  const mode = useData(filterMode);
  const complete = useRun(completeCourse);
  const reopen = useRun(reopenCourse);
  return (
    <table aria-label="Courses">
      <caption>Courses</caption>
      <thead>
        <tr>
          <th>Title</th>
          <th>Status</th>
          <th>Requires</th>
        </tr>
      </thead>
      <tbody>
        {visibleCourses(all, mode).map((course) => (
          <tr key={course.id}>
            <td>{course.title}</td>
            <td>{statusText(course, all)}</td>
            <td>{requiresText(course, all)}</td>
            <td>
              {course.done ? (
                <button
                  type="button"
                  onClick={() => reopen.run({ input: { id: course.id } })}
                >{`Reopen ${course.title}`}</button>
              ) : (
                <button
                  type="button"
                  onClick={() => complete.run({ input: { id: course.id } })}
                >{`Complete ${course.title}`}</button>
              )}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function LinkForm(): ReactNode {
  const all = useData(courses);
  const courseId = useData(courseChoice);
  const prerequisiteId = useData(prerequisiteChoice);
  const choosingCourse = useRun(chooseCourse);
  const choosingPrerequisite = useRun(choosePrerequisite);
  const adding = useRun(addPrerequisite);
  const removing = useRun(removePrerequisite);
  const courseSelectId = useId();
  const prerequisiteSelectId = useId();
  const courseChoices = selectChoices(all, courseId);
  const prerequisiteChoices = selectChoices(all, prerequisiteId);
  return (
    <form>
      <label htmlFor={courseSelectId}>Course</label>
      <select
        id={courseSelectId}
        value={courseId}
        onChange={(event) => choosingCourse.run({ input: { id: event.currentTarget.value } })}
      >
        {courseChoices.map((choice) => (
          <option key={choice.value} value={choice.value}>
            {choice.label}
          </option>
        ))}
      </select>
      <label htmlFor={prerequisiteSelectId}>Prerequisite</label>
      <select
        id={prerequisiteSelectId}
        value={prerequisiteId}
        onChange={(event) =>
          choosingPrerequisite.run({ input: { id: event.currentTarget.value } })
        }
      >
        {prerequisiteChoices.map((choice) => (
          <option key={choice.value} value={choice.value}>
            {choice.label}
          </option>
        ))}
      </select>
      <button
        type="button"
        onClick={() => adding.run({ input: { courseId, prerequisiteId } })}
      >
        Add requirement
      </button>
      <button
        type="button"
        onClick={() => removing.run({ input: { courseId, prerequisiteId } })}
      >
        Remove requirement
      </button>
    </form>
  );
}

