import { chromium } from "playwright";
import type { Browser, Page } from "playwright";
import { createServer } from "vite";
import type { ViteDevServer } from "vite";
import { afterAll, afterEach, beforeAll, expect, it } from "vitest";
import { fileURLToPath } from "node:url";

let server: ViteDevServer;
let browser: Browser;
let page: Page;

beforeAll(async () => {
  server = await createServer({
    root: fileURLToPath(new URL("..", import.meta.url)),
    cacheDir: fileURLToPath(new URL("../.vite-cache", import.meta.url)),
    logLevel: "error",
    server: { host: "127.0.0.1", port: 0 },
  });
  await server.listen();
  const url = server.resolvedUrls?.local?.[0] ?? "";
  browser = await chromium.launch({ args: ["--no-sandbox"] });
  page = await browser.newPage();
  await page.goto(url);
});

afterEach(async () => {
  await page.reload();
});

afterAll(async () => {
  await browser?.close();
  await server?.close();
});

async function createCourse(title: string) {
  await page.getByLabel("Title").fill(title);
  await page.getByRole("button", { name: "Add course" }).click();
}

async function link(course: string, prerequisite: string) {
  await page.getByLabel("Course", { exact: true }).selectOption({ label: course });
  await page.getByLabel("Prerequisite", { exact: true }).selectOption({ label: prerequisite });
  await page.getByRole("button", { name: "Add requirement" }).click();
}

function row(title: string) {
  return page.getByRole("row", { name: new RegExp(`^${title}`) });
}

async function rowText(title: string) {
  return row(title).innerText();
}

async function expectRow(title: string, text: string) {
  await expect.poll(async () => rowText(title), { timeout: 5000 }).toContain(text);
}

async function expectNoRow(title: string) {
  await expect.poll(async () => row(title).count(), { timeout: 5000 }).toBe(0);
}

async function expectAlert(kind: string | null) {
  await expect
    .poll(async () => {
      const alert = page.getByRole("alert");
      return (await alert.count()) === 0 ? null : alert.innerText();
    }, { timeout: 5000 })
    .toBe(kind);
}

async function inputValue(locator: ReturnType<Page["getByLabel"]>) {
  return locator.inputValue();
}

