/**
 * Pure booking rules over plain values: rooms, times, real calendar days, clashes, and
 * list order. Nothing here reads or writes a cell; the operations own every state change.
 */

import {
  badCount,
  badDate,
  badTime,
  blankTitle,
  emptySlot,
  unknownRoom,
} from "./errors.ts";

/** The two fixed rooms. */
export type Room = "Cedar" | "Maple";

/** The two fixed rooms, in display order. */
export const rooms: readonly Room[] = ["Cedar", "Maple"];

/** The default calendar day, used when a call omits `date`. */
export const DEFAULT_DATE = "2026-10-01";

/** One saved booking. `id` is opaque to callers; `seriesId` ties a weekly series. */
export type Booking = {
  readonly id: string;
  readonly title: string;
  readonly room: Room;
  readonly date: string;
  readonly start: number;
  readonly end: number;
  readonly seriesId?: string;
};

/** The input `bookBooking` takes; `room` is a plain string, `date` defaults. */
export type BookInput = {
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

/** The input `saveEdit` takes: an existing id plus the edited fields. */
export type EditInput = {
  readonly id: string;
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

/** The input `bookSeries` takes: one booking repeated weekly. */
export type SeriesInput = {
  readonly title: string;
  readonly room: string;
  readonly date: string;
  readonly start: number;
  readonly end: number;
  readonly weeks: number;
};

/** One validated booking, before it gains an id. */
export type ValidFields = {
  readonly title: string;
  readonly room: Room;
  readonly date: string;
  readonly start: number;
  readonly end: number;
};

const MINUTES_PER_HOUR = 60;
const LAST_MINUTE = 1439;
const MIN_WEEKS = 1;
const MAX_WEEKS = 12;
const DAYS_PER_WEEK = 7;
const MONTHS_PER_YEAR = 12;
const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;
const TIME_PATTERN = /^(\d{1,2}):(\d{2})$/;
const DAYS_IN_MONTH: readonly number[] = [
  31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31,
];

/** Format minutes since midnight as 24-hour `HH:MM`. */
export function formatTime(minutes: number): string {
  const hours = Math.floor(minutes / MINUTES_PER_HOUR);
  const mins = minutes % MINUTES_PER_HOUR;
  return `${String(hours).padStart(2, "0")}:${String(mins).padStart(2, "0")}`;
}

/** Parse 24-hour `HH:MM` into minutes since midnight, or undefined when malformed. */
export function parseTime(raw: string): number | undefined {
  const match = TIME_PATTERN.exec(raw.trim());
  if (match === null) {
    return undefined;
  }
  const hours = Number(match[1]);
  const mins = Number(match[2]);
  if (hours > 23 || mins > 59) {
    return undefined;
  }
  return hours * MINUTES_PER_HOUR + mins;
}

/** True when a four-digit year is a Gregorian leap year, year 0 included. */
function isLeapYear(year: number): boolean {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

/** How many days a month of that year really has. */
function daysInMonth(year: number, month: number): number {
  const length = DAYS_IN_MONTH[month - 1];
  if (length === undefined) {
    return 0;
  }
  return month === 2 && isLeapYear(year) ? 29 : length;
}

/** Check one real `YYYY-MM-DD` day; a four-digit year below 100 is still real. */
export function checkDate(value: unknown): string {
  if (typeof value !== "string") {
    throw badDate(value);
  }
  const match = DATE_PATTERN.exec(value);
  if (match === null) {
    throw badDate(value);
  }
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (month < 1 || month > MONTHS_PER_YEAR) {
    throw badDate(value);
  }
  if (day < 1 || day > daysInMonth(year, month)) {
    throw badDate(value);
  }
  return value;
}

/** Check one time value against the 0..1439 integer rule. */
export function checkTime(value: number): number {
  if (!Number.isInteger(value) || value < 0 || value > LAST_MINUTE) {
    throw badTime(value);
  }
  return value;
}

/** Check the weekly repeat count against the 1..12 integer rule. */
export function checkWeeks(value: number): number {
  if (!Number.isInteger(value) || value < MIN_WEEKS || value > MAX_WEEKS) {
    throw badCount(value);
  }
  return value;
}

/** Move a real `YYYY-MM-DD` day forward by whole days, keeping the same format. */
export function addDays(date: string, days: number): string {
  const match = DATE_PATTERN.exec(date);
  if (match === null) {
    throw badDate(date);
  }
  let year = Number(match[1]);
  let month = Number(match[2]);
  let day = Number(match[3]) + days;
  let limit = daysInMonth(year, month);
  while (day > limit) {
    day -= limit;
    month += 1;
    if (month > MONTHS_PER_YEAR) {
      month = 1;
      year += 1;
    }
    limit = daysInMonth(year, month);
  }
  const textYear = String(year).padStart(4, "0");
  const textMonth = String(month).padStart(2, "0");
  const textDay = String(day).padStart(2, "0");
  return `${textYear}-${textMonth}-${textDay}`;
}

/** Resolve a raw room string to a known room without a cast. */
export function toRoom(value: string): Room | undefined {
  return rooms.find((candidate) => candidate === value);
}

/** Title, room, date, and time rules shared by booking, editing, and series. */
export function checkFields(input: {
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
}): ValidFields {
  const title = input.title.trim();
  if (title.length === 0) {
    throw blankTitle(title);
  }
  const room = toRoom(input.room);
  if (room === undefined) {
    throw unknownRoom(input.room);
  }
  const date = input.date === undefined ? DEFAULT_DATE : checkDate(input.date);
  const start = checkTime(input.start);
  const end = checkTime(input.end);
  if (end <= start) {
    throw emptySlot(start, end);
  }
  return { title, room, date, start, end };
}

/** True when two half-open time ranges share a minute. */
function overlaps(
  aStart: number,
  aEnd: number,
  bStart: number,
  bEnd: number,
): boolean {
  return aStart < bEnd && bStart < aEnd;
}

/** True when an existing booking in the same room and date overlaps the slot. */
export function hasConflict(
  list: readonly Booking[],
  room: Room,
  date: string,
  start: number,
  end: number,
  skipId?: string,
): boolean {
  return list.some(
    (booking) =>
      booking.id !== skipId &&
      booking.room === room &&
      booking.date === date &&
      overlaps(start, end, booking.start, booking.end),
  );
}

/** The creation position of an id, after every id actually in the list. */
function creationIndex(order: readonly string[], id: string): number {
  const index = order.indexOf(id);
  return index < 0 ? Number.MAX_SAFE_INTEGER : index;
}

/** Order by date, then start time, then creation order from `order`. */
export function sortBookings(
  list: readonly Booking[],
  order: readonly string[],
): Booking[] {
  return [...list].sort((a, b) => {
    if (a.date !== b.date) {
      return a.date < b.date ? -1 : 1;
    }
    if (a.start !== b.start) {
      return a.start - b.start;
    }
    return creationIndex(order, a.id) - creationIndex(order, b.id);
  });
}

/** A copy of one booking that shares no field with the original. */
export function copyBooking(booking: Booking): Booking {
  const copy: Booking = {
    id: booking.id,
    title: booking.title,
    room: booking.room,
    date: booking.date,
    start: booking.start,
    end: booking.end,
  };
  if (booking.seriesId === undefined) {
    return copy;
  }
  return { ...copy, seriesId: booking.seriesId };
}

/** The dates of a weekly series, one week apart, starting from `date`. */
export function seriesDates(date: string, weeks: number): readonly string[] {
  const dates: string[] = [];
  for (let week = 0; week < weeks; week += 1) {
    dates.push(addDays(date, week * DAYS_PER_WEEK));
  }
  return dates;
}

/** Trim a new series title; a blank one reports BlankTitle with the text as given. */
export function checkRenameTitle(value: string): string {
  const title = value.trim();
  if (title.length === 0) {
    throw blankTitle(value);
  }
  return title;
}

/** Retitle every occurrence of one series, keeping its other fields and the list order. */
export function retitleSeries(
  list: readonly Booking[],
  seriesId: string,
  title: string,
): Booking[] {
  return list
    .filter((booking) => booking.seriesId === seriesId)
    .map((booking) => ({ ...booking, title }));
}

import { describe, expect, it } from 'vitest';
import {
  editDraft,
  moves,
  saveMoveEdit,
  stock,
  undoMove,
} from '../src/index.ts';
import {
  discardEdit,
  failureOf,
  openEdit,
  openScope,
  savedMoves,
  saveMove,
} from './helpers.ts';

describe('undoMove', () => {
  it('restores the stock and move list from before the last move', () => {
    const scope = openScope();
    saveMove(scope, 'Cable', 'East', 'West', 3);
    scope.run(undoMove, {});
    expect(scope.resolve(stock)).toEqual([
      { item: 'Cable', place: 'East', quantity: 8 },
      { item: 'Cable', place: 'West', quantity: 2 },
      { item: 'Stand', place: 'East', quantity: 3 },
      { item: 'Stand', place: 'West', quantity: 1 },
    ]);
    expect(scope.resolve(moves)).toEqual([]);
  });

  it('treats a whole edit save as one step', () => {
    const scope = openScope();
    const saved = saveMove(scope, 'Cable', 'East', 'West', 3);
    openEdit(scope, saved.id);
    scope.run(saveMoveEdit, {
      input: { id: saved.id, item: 'Cable', from: 'East', to: 'West', quantity: 5 },
    });
    scope.run(undoMove, {});
    expect(scope.resolve(stock)).toEqual([
      { item: 'Cable', place: 'East', quantity: 5 },
      { item: 'Cable', place: 'West', quantity: 5 },
      { item: 'Stand', place: 'East', quantity: 3 },
      { item: 'Stand', place: 'West', quantity: 1 },
    ]);
    expect(savedMoves(scope)).toEqual([saved]);
  });

  it('reports EmptyUndo and keeps undoing unavailable when history is empty', () => {
    const scope = openScope();
    const failure = failureOf(() => scope.run(undoMove, {}), 'EmptyUndo');
    expect(failure.payload).toEqual({});
  });

  it('has no redo, so a second undo reports EmptyUndo', () => {
    const scope = openScope();
    saveMove(scope, 'Cable', 'East', 'West', 3);
    scope.run(undoMove, {});
    failureOf(() => scope.run(undoMove, {}), 'EmptyUndo');
  });

  it('ignores openings and discards when choosing the last step', () => {
    const scope = openScope();
    const saved = saveMove(scope, 'Cable', 'East', 'West', 3);
    openEdit(scope, saved.id);
    discardEdit(scope, saved.id);
    scope.run(undoMove, {});
    expect(savedMoves(scope)).toEqual([]);
  });

  it('leaves the draft open', () => {
    const scope = openScope();
    const saved = saveMove(scope, 'Cable', 'East', 'West', 3);
    openEdit(scope, saved.id);
    scope.run(undoMove, {});
    expect(scope.resolve(editDraft)).toEqual(saved);
  });

  it('never reissues an id used before the undo', () => {
    const scope = openScope();
    const first = saveMove(scope, 'Cable', 'East', 'West', 1);
    scope.run(undoMove, {});
    const second = saveMove(scope, 'Cable', 'East', 'West', 1);
    expect(second.id).not.toBe(first.id);
    expect(savedMoves(scope)).toEqual([second]);
  });
});

import { type Operation, type Scope, operation } from "@tinker/core";
import { appError } from "./errors.ts";
import {
  type BookInput,
  type Booking,
  type EditInput,
  type Fields,
  type SeriesInput,
  bookings,
  clashesWith,
  editDraft,
  issuedIds,
  occurrenceDates,
  requireId,
  requireSeriesId,
  shapeBooking,
  shapeEdit,
  shapeSeries,
  sortedBookings,
  undoHistory,
  validateFields,
  weekCount,
} from "./model.ts";

function parseBookInput(raw: unknown): BookInput {
  return shapeBooking(raw);
}

function parseSeriesInput(raw: unknown): SeriesInput {
  return shapeSeries(raw);
}

function parseIdInput(raw: unknown): { id: string } {
  return { id: requireId(raw) };
}

function parseSeriesIdInput(raw: unknown): { seriesId: string } {
  return { seriesId: requireSeriesId(raw) };
}

function parseEditInput(raw: unknown): EditInput {
  return shapeEdit(raw);
}

/** The value the caller actually passed, on either call shape. */
function source(ctx: {
  readonly rawInput: unknown;
  readonly input: unknown;
}): unknown {
  return ctx.rawInput !== undefined ? ctx.rawInput : ctx.input;
}

function savedBooking(
  fields: Fields,
  id: string,
  seriesId: string | undefined,
): Booking {
  const booking: Booking = {
    id,
    title: fields.title.trim(),
    room: fields.room,
    date: fields.date,
    start: fields.start,
    end: fields.end,
  };
  return seriesId === undefined ? booking : { ...booking, seriesId };
}

function clash(fields: Fields): Error {
  return appError("Clash", {
    room: fields.room,
    start: fields.start,
    end: fields.end,
  });
}

type ChangeDeps = {
  readonly list: Scope.DataController<readonly Booking[]>;
  readonly history: Scope.DataController<readonly (readonly Booking[])[]>;
};

/** Save one undo step, then the new list: one passing change per call. */
function applyChange(deps: ChangeDeps, next: readonly Booking[]): void {
  deps.history.set([...deps.history.get(), deps.list.get()]);
  deps.list.set(next);
}

/** Book a slot: one more saved booking unless the room's slot on that date is taken. */
export const bookBooking: Operation.Handle<Booking, BookInput> = operation({
  label: "bookBooking",
  input: parseBookInput,
  depends: {
    list: bookings.controller,
    issued: issuedIds.controller,
    history: undoHistory.controller,
  },
  run(deps, ctx): Booking {
    const fields = validateFields(source(ctx));
    const list = deps.list.get();
    if (clashesWith(list, fields.room, fields.date, fields.start, fields.end)) {
      throw clash(fields);
    }
    const issued = deps.issued.get();
    const id = `booking-${issued.length}`;
    const booking = savedBooking(fields, id, undefined);
    deps.issued.set([...issued, id]);
    applyChange(deps, sortedBookings([...list, booking], [...issued, id]));
    return booking;
  },
});

/** Book a weekly series: all occurrences land together, or none when one date fails. */
export const bookSeries: Operation.Handle<readonly Booking[], SeriesInput> =
  operation({
    label: "bookSeries",
    input: parseSeriesInput,
    depends: {
      list: bookings.controller,
      issued: issuedIds.controller,
      history: undoHistory.controller,
    },
    run(deps, ctx): readonly Booking[] {
      const fields = validateFields(source(ctx));
      const weeks = weekCount(source(ctx));
      const list = deps.list.get();
      const dates = occurrenceDates(fields.date, weeks);
      for (const date of dates) {
        if (clashesWith(list, fields.room, date, fields.start, fields.end)) {
          throw clash(fields);
        }
      }
      const seriesId = `series-${deps.issued.get().length}`;
      let issued = deps.issued.get();
      const made: Booking[] = [];
      const added: string[] = [];
      for (const date of dates) {
        const id = `booking-${issued.length + added.length}`;
        made.push(savedBooking({ ...fields, date }, id, seriesId));
        added.push(id);
      }
      issued = [...issued, ...added];
      deps.issued.set(issued);
      applyChange(deps, sortedBookings([...list, ...made], issued));
      return made;
    },
  });

/** Cancel one booking by id; a second cancel of the id reports NotFound. */
export const cancelBooking: Operation.Handle<void, { id: string }> = operation({
  label: "cancelBooking",
  input: parseIdInput,
  depends: {
    list: bookings.controller,
    draft: editDraft.controller,
    history: undoHistory.controller,
  },
  run(deps, ctx): void {
    const id = requireId(source(ctx));
    const list = deps.list.get();
    if (!list.some((booking) => booking.id === id)) {
      throw appError("NotFound", { id });
    }
    applyChange(deps, list.filter((booking) => booking.id !== id));
    const draft = deps.draft.get();
    if (draft?.id === id) {
      deps.draft.set(undefined);
    }
  },
});

/** Cancel every occurrence of one series by its series id. */
export const cancelSeries: Operation.Handle<void, { seriesId: string }> =
  operation({
    label: "cancelSeries",
    input: parseSeriesIdInput,
    depends: {
      list: bookings.controller,
      draft: editDraft.controller,
      history: undoHistory.controller,
    },
    run(deps, ctx): void {
      const seriesId = requireSeriesId(source(ctx));
      const list = deps.list.get();
      const gone = list.filter((booking) => booking.seriesId === seriesId);
      if (gone.length === 0) {
        throw appError("NotFound", { id: seriesId });
      }
      applyChange(
        deps,
        list.filter((booking) => booking.seriesId !== seriesId),
      );
      const draft = deps.draft.get();
      if (draft && gone.some((booking) => booking.id === draft.id)) {
        deps.draft.set(undefined);
      }
    },
  });

/** Open an edit draft: a copy of the saved booking, never the saved row itself. */
export const openEdit: Operation.Handle<Booking, { id: string }> = operation({
  label: "openEdit",
  input: parseIdInput,
  depends: { list: bookings.controller, draft: editDraft.controller },
  run(deps, ctx): Booking {
    const id = requireId(source(ctx));
    const saved = deps.list.get().find((booking) => booking.id === id);
    if (!saved) {
      throw appError("NotFound", { id });
    }
    const draft: Booking = { ...saved };
    deps.draft.set(draft);
    return draft;
  },
});

/** Save the open draft: it replaces the booking and closes the draft. */
export const saveEdit: Operation.Handle<Booking, EditInput> = operation({
  label: "saveEdit",
  input: parseEditInput,
  depends: {
    list: bookings.controller,
    draft: editDraft.controller,
    issued: issuedIds.controller,
    history: undoHistory.controller,
  },
  run(deps, ctx): Booking {
    const fields = validateFields(source(ctx));
    const id = requireId(source(ctx));
    const draft = deps.draft.get();
    if (!draft || draft.id !== id) {
      throw appError("NotFound", { id });
    }
    const list = deps.list.get();
    const saved = list.find((booking) => booking.id === id);
    if (!saved) {
      throw appError("NotFound", { id });
    }
    if (
      clashesWith(list, fields.room, fields.date, fields.start, fields.end, id)
    ) {
      throw clash(fields);
    }
    const updated = savedBooking(fields, id, saved.seriesId);
    applyChange(
      deps,
      sortedBookings(
        list.map((booking) => (booking.id === id ? updated : booking)),
        deps.issued.get(),
      ),
    );
    deps.draft.set(undefined);
    return updated;
  },
});

/** Drop the open draft untouched; the saved booking stays as it was. */
export const discardEdit: Operation.Handle<void, { id: string }> = operation({
  label: "discardEdit",
  input: parseIdInput,
  depends: { draft: editDraft.controller },
  run(deps, ctx): void {
    const id = requireId(source(ctx));
    const draft = deps.draft.get();
    if (!draft || draft.id !== id) {
      throw appError("NotFound", { id });
    }
    deps.draft.set(undefined);
  },
});

/** Reverse the last passing booking change; with no step left it reports EmptyUndo. */
export const undoChange: Operation.Handle<void, void> = operation({
  label: "undoChange",
  depends: { list: bookings.controller, history: undoHistory.controller },
  run(deps): void {
    const history = deps.history.get();
    const before = history.at(-1);
    if (before === undefined) {
      throw appError("EmptyUndo", {});
    }
    deps.history.set(history.slice(0, history.length - 1));
    deps.list.set(before);
  },
});

import { createScope } from "@tinker/core";
import { ScopeProvider, useData, useScope } from "@tinker/react";
import { type ReactElement, useId, useState } from "react";
import { errorKind } from "./errors.ts";
import {
  type Booking,
  type Room,
  bookings,
  defaultDate,
  editDraft,
} from "./model.ts";
import {
  bookBooking,
  bookSeries,
  cancelBooking,
  cancelSeries,
  discardEdit,
