export type EditInput = {
  readonly id: string;
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

/** Every saved booking across the days, sorted by date, then start time, then creation order. */
export const bookings: Data.Cell<readonly Booking[]> = data<readonly Booking[]>({
  label: "bookings",
  initial: [],
});

/** The one open edit draft: a copy of a saved booking, or empty when closed. */
