} from "../src/index.ts";

function capture(action: () => unknown): unknown {
  try {
    action();
    return undefined;
  } catch (error) {
    return error;
  }
}

describe("bookSeries", () => {
  it("books weeks dates, seven days apart, under one series id", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    expect(made.map((booking) => booking.date)).toEqual([
      "2026-10-06",
      "2026-10-13",
      "2026-10-20",
    ]);
    const seriesId = made[0]?.seriesId;
    expect(seriesId).toBeTypeOf("string");
    for (const booking of made) {
      expect(booking.seriesId).toBe(seriesId);
    }
    expect(scope.resolve(bookings)).toEqual(made);
  });

  it("carries no series id on a one-off booking", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Solo", room: "Cedar", start: 540, end: 600 },
    });
    expect(saved.seriesId).toBeUndefined();
  });

  it("crosses a month boundary seven days at a time", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Review",
        room: "Maple",
        date: "2026-10-27",
        start: 600,
        end: 660,
        weeks: 3,
      },
    });
    expect(made.map((booking) => booking.date)).toEqual([
      "2026-10-27",
      "2026-11-03",
      "2026-11-10",
    ]);
  });

  it("rejects weeks outside 1 to 12 or not an integer", () => {
    const scope = createScope();
    for (const weeks of [0, -1, 13, 1.5, Number.NaN]) {
      const error = capture(() =>
        scope.run(bookSeries, {
          input: {
            title: "Standup",
            room: "Cedar",
            date: "2026-10-06",
            start: 540,
            end: 600,
            weeks,
          },
        }),
      );
      expect(isError(error, "BadCount"), String(weeks)).toBe(true);
      if (isError(error, "BadCount")) {
        expect(error.payload.weeks).toBe(weeks);
      }
    }
    const notNumber = capture(() =>
      scope.run(bookSeries, {
        rawInput: {
          title: "Standup",
          room: "Cedar",
          date: "2026-10-06",
          start: 540,
          end: 600,
          weeks: "3",
        },
      }),
    );
    expect(isError(notNumber, "BadCount")).toBe(true);
    if (isError(notNumber, "BadCount")) {
      expect(notNumber.payload.weeks).toBe("3");
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("accepts weeks = 1 and weeks = 12 as the bounds", () => {
    const scope = createScope();
    const one = scope.run(bookSeries, {
      input: {
        title: "One",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 1,
      },
    });
    expect(one).toHaveLength(1);
    const twelve = scope.run(bookSeries, {
      input: {
        title: "Twelve",
        room: "Maple",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 12,
      },
    });
    expect(twelve).toHaveLength(12);
    expect(twelve[11]?.date).toBe("2026-12-22");
  });

  it("books none and reports Clash when one date is taken", () => {
    const scope = createScope();
    scope.run(bookBooking, {
      input: {
        title: "Busy",
        room: "Cedar",
        date: "2026-10-13",
        start: 550,
        end: 590,
      },
    });
    const error = capture(() =>
      scope.run(bookSeries, {
        input: {
          title: "Standup",
          room: "Cedar",
          date: "2026-10-06",
          start: 540,
          end: 600,
          weeks: 3,
        },
      }),
    );
    expect(isError(error, "Clash")).toBe(true);
    expect(scope.resolve(bookings)).toHaveLength(1);
  });

  it("leaves saved bookings unchanged when the title is blank", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Kept", room: "Maple", start: 540, end: 600 },
    });
    const error = capture(() =>
      scope.run(bookSeries, {
        input: {
          title: "   ",
          room: "Cedar",
          date: "2026-10-06",
          start: 540,
          end: 600,
          weeks: 2,
        },
      }),
    );
    expect(isError(error, "BlankTitle")).toBe(true);
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("rejects a bad date before booking anything", () => {
    const scope = createScope();
    const error = capture(() =>
      scope.run(bookSeries, {
        input: {
          title: "Standup",
          room: "Cedar",
          date: "2026-02-30",
          start: 540,
          end: 600,
          weeks: 2,
        },
      }),
    );
    expect(isError(error, "BadDate")).toBe(true);
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("overlaps in another room or on another date never clash", () => {
    const scope = createScope();
    scope.run(bookSeries, {
      input: {
        title: "Cedar run",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    const maple = scope.run(bookSeries, {
      input: {
        title: "Maple run",
        room: "Maple",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    expect(maple).toHaveLength(3);
    const otherDates = scope.run(bookSeries, {
      input: {
        title: "Cedar later",
        room: "Cedar",
        date: "2026-10-07",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    expect(otherDates).toHaveLength(3);
    expect(scope.resolve(bookings)).toHaveLength(9);
  });
});

describe("cancelSeries", () => {
  it("frees every occurrence of the series", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    const seriesId = made[0]?.seriesId ?? "";
    scope.run(cancelSeries, { input: { seriesId } });
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("canceling one id leaves the rest of its series", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    const middle = made[1];
    if (!middle) throw new Error("missing occurrence");
    scope.run(cancelBooking, { input: { id: middle.id } });
    const list = scope.resolve(bookings);
    expect(list).toHaveLength(2);
    expect(list.map((booking) => booking.date)).toEqual([
      "2026-10-06",
      "2026-10-20",
    ]);
    for (const booking of list) {
      expect(booking.seriesId).toBe(made[0]?.seriesId);
    }
  });

  it("reports NotFound for an unknown series id, with that id", () => {
    const scope = createScope();
    const error = capture(() =>
      scope.run(cancelSeries, { input: { seriesId: "nope" } }),
    );
    expect(isError(error, "NotFound")).toBe(true);
    if (isError(error, "NotFound")) {
      expect(error.payload.id).toBe("nope");
    }
  });

  it("reports NotFound on a second cancel of one series id", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 2,
      },
    });
    const seriesId = made[0]?.seriesId ?? "";
    scope.run(cancelSeries, { input: { seriesId } });
    const error = capture(() =>
      scope.run(cancelSeries, { input: { seriesId } }),
    );
    expect(isError(error, "NotFound")).toBe(true);
  });

  it("cancelSeries closes the draft of an occurrence it removes", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 2,
      },
    });
    const first = made[0];
    if (!first || first.seriesId === undefined) {
      throw new Error("missing occurrence");
    }
    scope.run(openEdit, { input: { id: first.id } });
    scope.run(cancelSeries, { input: { seriesId: first.seriesId } });
    expect(scope.resolve(editDraft)).toBeUndefined();
    const saveError = capture(() =>
      scope.run(saveEdit, {
        input: {
          id: first.id,
          title: "Renamed",
          room: "Cedar",
          start: 540,
          end: 600,
        },
      }),
    );
    expect(isError(saveError, "NotFound")).toBe(true);
  });

  it("keeps the series tie when one occurrence is edited", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 2,
      },
    });
    const first = made[0];
    if (!first || first.seriesId === undefined) {
      throw new Error("missing occurrence");
    }
    scope.run(openEdit, { input: { id: first.id } });
    const updated = scope.run(saveEdit, {
      input: {
        id: first.id,
        title: "Renamed",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
      },
    });
    expect(updated.seriesId).toBe(first.seriesId);
    const closed = capture(() =>
      scope.run(discardEdit, { input: { id: first.id } }),
    );
    expect(isError(closed, "NotFound")).toBe(true);
  });

  it("books another room while a draft is open: the draft blocks nothing", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 1,
      },
    });
    const first = made[0];
    if (!first) throw new Error("missing occurrence");
    scope.run(openEdit, { input: { id: first.id } });
    const other = scope.run(bookBooking, {
      input: {
        title: "Planning",
        room: "Maple",
        date: "2026-10-06",
        start: 540,
        end: 600,
      },
    });
    expect(other.title).toBe("Planning");
    expect(scope.resolve(bookings)).toHaveLength(2);
  });
});

import { createScope } from "@tinker/core";
import { describe, expect, it } from "vitest";
import {
  type BookInput,
  bookBooking,
  bookings,
  cancelBooking,
  isError,
} from "../src/index.ts";

function capture(action: () => unknown): unknown {
  try {
    action();
    return undefined;
  } catch (error) {
    return error;
  }
}

function book(input: BookInput): BookInput {
  return input;
}

describe("bookBooking", () => {
  it("rejects a second booking of the same room and slot", () => {
    const scope = createScope();
    const standup = scope.run(bookBooking, {
      input: book({ title: "Standup", room: "Cedar", start: 540, end: 600 }),
    });
    expect(standup).toEqual({
      id: standup.id,
      title: "Standup",
      room: "Cedar",
      date: "2026-10-01",
      start: 540,
      end: 600,
    });
    const clash = capture(() =>
      scope.run(bookBooking, {
        input: { title: "Again", room: "Cedar", start: 540, end: 600 },
      }),
    );
    expect(isError(clash, "Clash")).toBe(true);
    expect(scope.resolve(bookings)).toEqual([standup]);
  });

  it("allows the same slot in another room and a start when another ends", () => {
    const scope = createScope();
    const standup = scope.run(bookBooking, {
      input: book({ title: "Standup", room: "Cedar", start: 540, end: 600 }),
    });
    const maple = scope.run(bookBooking, {
      input: { title: "Maple copy", room: "Maple", start: 540, end: 600 },
    });
    const later = scope.run(bookBooking, {
      input: { title: "Planning", room: "Cedar", start: 600, end: 660 },
    });
    expect(scope.resolve(bookings)).toEqual([standup, maple, later]);
  });

  it("trims the saved title", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "  Standup  ", room: "Cedar", start: 60, end: 120 },
    });
    expect(saved.title).toBe("Standup");
  });

  it("rejects a blank title", () => {
    const scope = createScope();
    for (const title of ["", "   ", "\t\n"]) {
      const error = capture(() =>
        scope.run(bookBooking, {
          input: { title, room: "Cedar", start: 60, end: 120 },
        }),
      );
      expect(isError(error, "BlankTitle"), title).toBe(true);
      if (isError(error, "BlankTitle")) {
        expect(error.payload.title).toBe(title);
      }
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects an unknown room", () => {
    const scope = createScope();
    const error = capture(() =>
      scope.run(bookBooking, {
        input: { title: "Standup", room: "Attic", start: 60, end: 120 },
      }),
    );
    expect(isError(error, "UnknownRoom")).toBe(true);
    if (isError(error, "UnknownRoom")) {
      expect(error.payload.room).toBe("Attic");
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects a time outside 0..1439 or not an integer", () => {
    const scope = createScope();
    const badStarts = [-1, 1440, 25.5, Number.NaN, Number.POSITIVE_INFINITY];
    for (const start of badStarts) {
      const error = capture(() =>
        scope.run(bookBooking, {
          input: { title: "Standup", room: "Cedar", start, end: 120 },
        }),
      );
      expect(isError(error, "BadTime"), String(start)).toBe(true);
      if (isError(error, "BadTime")) {
        expect(error.payload.value).toBe(start);
      }
    }
    const badEnd = capture(() =>
      scope.run(bookBooking, {
        input: { title: "Standup", room: "Cedar", start: 120, end: 2000 },
      }),
    );
    expect(isError(badEnd, "BadTime")).toBe(true);
    if (isError(badEnd, "BadTime")) {
      expect(badEnd.payload.value).toBe(2000);
    }
    const notNumbers = capture(() =>
      scope.run(bookBooking, {
        rawInput: { title: "Standup", room: "Cedar", start: "9am", end: 120 },
      }),
    );
    expect(isError(notNumbers, "BadTime")).toBe(true);
    if (isError(notNumbers, "BadTime")) {
      expect(notNumbers.payload.value).toBe("9am");
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects an end at or before the start", () => {
    const scope = createScope();
    for (const [start, end] of [
      [600, 600],
      [600, 540],
    ] as const) {
      const error = capture(() =>
        scope.run(bookBooking, {
          input: { title: "Standup", room: "Cedar", start, end },
        }),
      );
      expect(isError(error, "EmptySlot"), `${start}-${end}`).toBe(true);
      if (isError(error, "EmptySlot")) {
        expect(error.payload).toEqual({ start, end });
      }
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects any overlap in one room and allows overlap across rooms", () => {
    const scope = createScope();
    scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const inside = capture(() =>
      scope.run(bookBooking, {
        input: { title: "Inside", room: "Cedar", start: 550, end: 590 },
      }),
    );
    expect(isError(inside, "Clash")).toBe(true);
    if (isError(inside, "Clash")) {
      expect(inside.payload).toEqual({ room: "Cedar", start: 550, end: 590 });
    }
    const across = scope.run(bookBooking, {
      input: { title: "Across", room: "Maple", start: 550, end: 590 },
    });
    expect(across.room).toBe("Maple");
  });

  it("allows back-to-back bookings: one starts exactly when another ends", () => {
    const scope = createScope();
    const early = scope.run(bookBooking, {
      input: { title: "Early", room: "Cedar", start: 540, end: 600 },
    });
    const late = scope.run(bookBooking, {
      input: { title: "Late", room: "Cedar", start: 600, end: 660 },
    });
    const tail = scope.run(bookBooking, {
      input: { title: "Tail", room: "Cedar", start: 480, end: 540 },
    });
    expect(scope.resolve(bookings)).toEqual([tail, early, late]);
  });

  it("lists bookings by start time, then creation order", () => {
    const scope = createScope();
    const b = scope.run(bookBooking, {
      input: { title: "B", room: "Cedar", start: 600, end: 660 },
    });
    const a2 = scope.run(bookBooking, {
      input: { title: "A2", room: "Cedar", start: 540, end: 600 },
    });
    const a1 = scope.run(bookBooking, {
      input: { title: "A1", room: "Maple", start: 540, end: 600 },
    });
    expect(scope.resolve(bookings)).toEqual([a2, a1, b]);
  });

  it("leaves saved bookings unchanged on a failed action", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    capture(() =>
      scope.run(bookBooking, {
        input: { title: "Bad", room: "", start: 1, end: 0 },
      }),
    );
    capture(() =>
      scope.run(bookBooking, {
        input: { title: "Clash", room: "Cedar", start: 550, end: 590 },
      }),
    );
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("creates exactly one booking for two calls on an empty slot", () => {
    const scope = createScope();
    const first = capture(() =>
      scope.run(bookBooking, {
        input: { title: "First", room: "Cedar", start: 540, end: 600 },
      }),
    );
    expect(isError(first, "Clash")).toBe(false);
    const second = capture(() =>
      scope.run(bookBooking, {
        input: { title: "Second", room: "Cedar", start: 545, end: 595 },
      }),
    );
    expect(isError(second, "Clash")).toBe(true);
    const list = scope.resolve(bookings);
    expect(list).toHaveLength(1);
    expect(list[0]?.title).toBe("First");
  });
});

describe("cancelBooking", () => {
  it("cancel removes the booking so its slot can be booked again", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(cancelBooking, { input: { id: saved.id } });
    expect(scope.resolve(bookings)).toEqual([]);
    const again = scope.run(bookBooking, {
      input: { title: "New", room: "Cedar", start: 540, end: 600 },
    });
    expect(again.title).toBe("New");
  });

  it("reports NotFound on a second cancel of one id", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(cancelBooking, { input: { id: saved.id } });
    const error = capture(() =>
      scope.run(cancelBooking, { input: { id: saved.id } }),
    );
    expect(isError(error, "NotFound")).toBe(true);
    if (isError(error, "NotFound")) {
      expect(error.payload.id).toBe(saved.id);
    }
  });

  it("reports NotFound for an unknown id", () => {
    const scope = createScope();
    const error = capture(() =>
      scope.run(cancelBooking, { input: { id: "nope" } }),
    );
    expect(isError(error, "NotFound")).toBe(true);
    if (isError(error, "NotFound")) {
      expect(error.payload.id).toBe("nope");
    }
  });
});

import { fileURLToPath } from 'node:url';
import { chromium } from 'playwright';
import type { Browser, Page } from 'playwright';
import { afterAll, afterEach, beforeAll, describe, expect, it } from 'vitest';
import { createServer } from 'vite';
import type { ViteDevServer } from 'vite';

const root = fileURLToPath(new URL('..', import.meta.url));

let server: ViteDevServer;
let browser: Browser;
let base = '';
const openPages: Page[] = [];

beforeAll(async () => {
  server = await createServer({
    root,
    logLevel: 'error',
    cacheDir: `${root}.vite`,
    server: { port: 4317, strictPort: false },
  });
  await server.listen();
  base = server.resolvedUrls?.local[0] ?? '';
  browser = await chromium.launch();
}, 120_000);

afterEach(async () => {
  while (openPages.length > 0) await openPages.pop()?.close();
});

afterAll(async () => {
  await browser?.close();
  await server?.close();
});

/** Open one real page and wait for the stock table. */
const openPage = async (path: string, rootSelector: string): Promise<Page> => {
  const page = await browser.newPage();
  openPages.push(page);
  await page.goto(`${base}${path}`);
  await page.waitForSelector(`${rootSelector} table[aria-label="Stock"]`);
  return page;
};

/** The page root, or one mounted app inside it. */
const scoped = (page: Page, scope = '') => page.locator(scope === '' ? 'body' : scope);

/** All cells of a named table, row by row. */
const grid = async (page: Page, table: string, scope = ''): Promise<string[][]> => {
  const rows = scoped(page, scope).locator(`table[aria-label="${table}"] tbody tr`);
  const out: string[][] = [];
  for (let index = 0; index < (await rows.count()); index += 1) {
    out.push(await rows.nth(index).locator('td').allInnerTexts());
  }
  return out;
};

/** The four saved columns of each move row. */
const moveGrid = async (page: Page, scope = ''): Promise<string[][]> =>
  (await grid(page, 'Moves', scope)).map(cells => cells.slice(0, 4));

/** One labeled text input. */
const field = (page: Page, label: string, scope = '') =>
  scoped(page, scope).getByLabel(label, { exact: true });

/** Click a button by its text. */
const click = (page: Page, name: string, scope = '') =>
  scoped(page, scope).getByRole('button', { name, exact: true }).click();

