import { describe, expect, it } from 'vitest';
import { editDraft, moves, saveMoveEdit, stock, undoMove } from '../src/index.ts';
import {
  discardEdit,
  failureOf,
  openEdit,
  openScope,
  savedMoves,
  saveMove,
} from './helpers.ts';

describe('openMoveEdit', () => {
  it('copies the named saved move into the draft and returns it', () => {
    const scope = openScope();
    const saved = saveMove(scope, 'Cable', 'East', 'West', 3);
    const draft = openEdit(scope, saved.id);
    expect(draft).toEqual(saved);
    expect(scope.resolve(editDraft)).toEqual(saved);
  });

  it('reports NotFound for an unknown id and opens nothing', () => {
    const scope = openScope();
    saveMove(scope, 'Cable', 'East', 'West', 3);
    const failure = failureOf(() => openEdit(scope, 'move-404'), 'NotFound');
    expect(failure.payload).toEqual({ id: 'move-404' });
    expect(scope.resolve(editDraft)).toBeUndefined();
  });

  it('drops the first draft when a second move opens', () => {
    const scope = openScope();
    const first = saveMove(scope, 'Cable', 'East', 'West', 3);
    const second = saveMove(scope, 'Stand', 'East', 'West', 1);
    openEdit(scope, first.id);
    openEdit(scope, second.id);
    expect(scope.resolve(editDraft)).toEqual(second);
  });

  it('adds no undo step', () => {
    const scope = openScope();
    const saved = saveMove(scope, 'Cable', 'East', 'West', 3);
    openEdit(scope, saved.id);
    scope.run(undoMove, {});
    expect(savedMoves(scope)).toEqual([]);
  });
});

describe('saveMoveEdit', () => {
  it('replaces the move in place with the reversal first', () => {
    const scope = openScope();
    const saved = saveMove(scope, 'Cable', 'East', 'West', 3);
    openEdit(scope, saved.id);
    const replaced = scope.run(saveMoveEdit, {
      input: { id: saved.id, item: 'Cable', from: 'East', to: 'West', quantity: 5 },
    });
    expect(replaced).toEqual({ ...saved, quantity: 5 });
    expect(scope.resolve(stock)).toEqual([
      { item: 'Cable', place: 'East', quantity: 3 },
      { item: 'Cable', place: 'West', quantity: 7 },
      { item: 'Stand', place: 'East', quantity: 3 },
      { item: 'Stand', place: 'West', quantity: 1 },
    ]);
    expect(savedMoves(scope)).toEqual([replaced]);
  });

  it('reports ShortStock for the old target when the reversal cannot run', () => {
    const scope = openScope();
    const first = saveMove(scope, 'Cable', 'East', 'West', 3);
    const second = saveMove(scope, 'Cable', 'West', 'East', 4);
    openEdit(scope, first.id);
    const failure = failureOf(
      () =>
        scope.run(saveMoveEdit, {
          input: { id: first.id, item: 'Cable', from: 'East', to: 'West', quantity: 5 },
        }),
      'ShortStock',
    );
    expect(failure.payload).toEqual({
      item: 'Cable',
      place: 'West',
      available: 1,
      requested: 3,
    });
    expect(scope.resolve(stock)).toEqual([
      { item: 'Cable', place: 'East', quantity: 9 },
      { item: 'Cable', place: 'West', quantity: 1 },
      { item: 'Stand', place: 'East', quantity: 3 },
      { item: 'Stand', place: 'West', quantity: 1 },
    ]);
    expect(savedMoves(scope)).toEqual([first, second]);
  });

  it('keeps the editor open with its typed values when the save fails', () => {
    const scope = openScope();
    const first = saveMove(scope, 'Cable', 'East', 'West', 3);
    openEdit(scope, first.id);
    failureOf(
      () =>
        scope.run(saveMoveEdit, {
          rawInput: { id: first.id, item: 'Cable', from: 'East', to: 'West', quantity: '' },
        }),
      'BadQuantity',
    );
    expect(scope.resolve(editDraft)).toEqual(first);
    expect(savedMoves(scope)).toEqual([first]);
  });

  it('reports NotFound when no draft is open for the id', () => {
    const scope = openScope();
    const saved = saveMove(scope, 'Cable', 'East', 'West', 3);
    const failure = failureOf(
      () =>
        scope.run(saveMoveEdit, {
          input: { id: saved.id, item: 'Cable', from: 'East', to: 'West', quantity: 5 },
        }),
      'NotFound',
    );
    expect(failure.payload).toEqual({ id: saved.id });
  });

  it('reports NotFound when the open draft is a different move', () => {
    const scope = openScope();
    const first = saveMove(scope, 'Cable', 'East', 'West', 3);
    const second = saveMove(scope, 'Stand', 'East', 'West', 1);
    openEdit(scope, first.id);
    const failure = failureOf(
      () =>
        scope.run(saveMoveEdit, {
          input: { id: second.id, item: 'Stand', from: 'East', to: 'West', quantity: 1 },
        }),
      'NotFound',
    );
    expect(failure.payload).toEqual({ id: second.id });
    expect(savedMoves(scope)).toEqual([first, second]);
    expect(scope.resolve(editDraft)).toEqual(first);
  });

  it('adds no undo step when the save fails', () => {
