const startingStock = [
  ['Cable', 'East', '8'],
  ['Cable', 'West', '2'],
  ['Stand', 'East', '3'],
  ['Stand', 'West', '1'],
];

type Area = Page | Locator;

function savedRows(area: Area, name: string): Locator {
  return area.getByRole('table', { name }).locator('tbody tr');
}

async function rows(area: Area, name: string): Promise<string[][]> {
  const found = await area.getByRole('table', { name }).locator('tbody tr').all();
  return Promise.all(
    found.map(async (row) => (await row.locator('td').allTextContents()).slice(0, 4)),
  );
}

function expectStock(area: Area, cells: string[][]): Promise<void> {
  return expect.poll(() => rows(area, 'Stock'), { timeout: 5000 }).toEqual(cells);
}

function expectMoves(area: Area, cells: string[][]): Promise<void> {
  return expect.poll(() => rows(area, 'Moves'), { timeout: 5000 }).toEqual(cells);
}

async function alertText(): Promise<string> {
  return (await page.getByRole('alert').textContent()) ?? '';
}

async function inputValue(label: string): Promise<string> {
  return page.getByLabel(label).inputValue();
}

