import { execFileSync } from 'node:child_process';
import { createServer, type Server } from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join } from 'node:path';
import { build } from 'vite';
declare module 'vitest' {
  interface ProvidedContext {
    baseUrl: string;
  }
}

type Provide = <K extends keyof import('vitest').ProvidedContext & string>(
  key: K,
  value: import('vitest').ProvidedContext[K],
) => void;

const root = new URL('..', import.meta.url).pathname;
const dist = join(root, 'dist');

const types: Record<string, string> = {
  '.html': 'text/html',
  '.js': 'text/javascript',
  '.css': 'text/css',
  '.svg': 'image/svg+xml',
  '.map': 'application/json',
};

let server: Server | undefined;

export default async function setup({ provide }: { provide: Provide }): Promise<() => void> {
  // Two entries: the app page, and a page with two mounted apps for the
  // isolation test. A programmatic build with no config file keeps the
  // read-only node_modules untouched.
  await build({
    root,
    configFile: false,
    cacheDir: join(root, '.vite'),
    logLevel: 'warn',
    build: {
      outDir: dist,
      emptyOutDir: true,
      rollupOptions: {
        input: {
          main: join(root, 'index.html'),
          two: join(root, 'tests', 'browser', 'two-apps.html'),
        },
      },
    },
  });
  server = createServer(async (request, response) => {
    const url = new URL(request.url ?? '/', 'http://localhost');
    const file = url.pathname === '/' ? 'index.html' : url.pathname.slice(1).split('?')[0];
    try {
      const body = await readFile(join(dist, file));
      response.writeHead(200, { 'content-type': types[extname(file)] ?? 'application/octet-stream' });
      response.end(body);
    } catch {
      response.writeHead(404);
      response.end('not found');
    }
  });
  const port = await new Promise<number>((resolvePort, rejectPort) => {
    server?.listen(0, '127.0.0.1', () => {
      const address = server?.address();
      if (address !== null && typeof address === 'object') resolvePort(address.port);
      else rejectPort(new Error('no server address'));
    });
  });
  provide('baseUrl', `http://127.0.0.1:${port}/`);
  return () => {
    server?.close();
  };
}

import { expect, test } from "vitest";
