test("empty undo history reports EmptyUndo with an empty payload", () => {
  const scope = createScope();
  const error = failure(() => scope.run(undoMove, {}));
  if (!isError(error, "EmptyUndo")) throw error;
  expect(error.payload).toEqual({});
});

test("undo restores the exact stock and move list before the last passing change", () => {
  const scope = createScope();
  scope.run(moveStock, { input: { item: "Cable", from: "East", to: "West", quantity: 3 } });
  const afterFirst = state(scope);
  scope.run(moveStock, { input: { item: "Stand", from: "East", to: "West", quantity: 1 } });
  scope.run(undoMove, {});
  expect(state(scope)).toEqual(afterFirst);
});

test("undo adds no new step", () => {
  const scope = createScope();
  scope.run(moveStock, { input: { item: "Cable", from: "East", to: "West", quantity: 3 } });
  scope.run(undoMove, {});
  expect(state(scope).stock[0]).toEqual({ item: "Cable", place: "East", quantity: 8 });
  const error = failure(() => scope.run(undoMove, {}));
  if (!isError(error, "EmptyUndo")) throw error;
  expect(error.payload).toEqual({});
});

test("undo leaves an open draft untouched even when its move is gone", () => {
  const scope = createScope();
  scope.run(moveStock, { input: { item: "Cable", from: "East", to: "West", quantity: 1 } });
  const second = scope.run(moveStock, { input: { item: "Stand", from: "East", to: "West", quantity: 1 } });
  const opened = scope.run(openMoveEdit, { input: { id: second.id } });
  scope.run(undoMove, {});
  expect(state(scope).draft).toEqual(opened);
});

test("a move after undo never reuses an issued id", () => {
  const scope = createScope();
  const first = scope.run(moveStock, { input: { item: "Cable", from: "East", to: "West", quantity: 1 } });
  scope.run(undoMove, {});
  const second = scope.run(moveStock, { input: { item: "Cable", from: "East", to: "West", quantity: 1 } });
  expect(second.id).not.toBe(first.id);
  expect(state(scope).moves).toEqual([second]);
});

