/**
 * The one error registry for the stock desk: every app failure is one of
 * these managed kinds, carrying its typed payload.
 */
import type { Item, Place } from './domain';

/** The managed error kinds and payload types of the stock desk. */
export namespace Errors {
  /** Every managed error kind. */
  export type Name =
    | 'UnknownItem'
    | 'UnknownPlace'
    | 'SamePlace'
    | 'BadQuantity'
    | 'ShortStock'
    | 'NotFound'
    | 'EmptyUndo';

  type PayloadMap = {
    UnknownItem: { item: unknown };
    UnknownPlace: { place: unknown };
    SamePlace: { place: string };
    BadQuantity: { quantity: unknown };
    ShortStock: { item: Item; place: Place; available: number; requested: number };
    NotFound: { id: string };
    EmptyUndo: {};
  };

  /** The typed payload carried by one kind. */
  export type Payload<N extends Name = Name> = PayloadMap[N];

  /** A managed error: identified by `kind`, carrying a typed `payload`. */
  export type Of<N extends Name = Name> = Error & {
    readonly kind: N;
    readonly payload: Payload<N>;
  };
}

const kinds: readonly Errors.Name[] = [
  'UnknownItem',
  'UnknownPlace',
  'SamePlace',
  'BadQuantity',
  'ShortStock',
  'NotFound',
  'EmptyUndo',
];

class ManagedError<N extends Errors.Name> extends Error {
  readonly kind: N;
  readonly payload: Errors.Payload<N>;

  constructor(kind: N, payload: Errors.Payload<N>) {
    super(kind);
    this.name = kind;
    this.kind = kind;
    this.payload = payload;
  }
}

/** Build one managed error to throw from an operation. */
export function appError<N extends Errors.Name>(kind: N, payload: Errors.Payload<N>): Errors.Of<N> {
  return new ManagedError(kind, payload);
}

/** Narrow an unknown thrown value to one managed kind; rethrow anything else. */
export function isError<N extends Errors.Name>(value: unknown, kind: N): value is Errors.Of<N> {
  return value instanceof ManagedError && value.kind === kind;
}

/** The managed kind of an unknown thrown value, or undefined when it is not one of ours. */
export function errorKind(value: unknown): Errors.Name | undefined {
  for (const kind of kinds) {
    if (isError(value, kind)) return kind;
  }
  return undefined;
}

/** Payload type for each app error. The registry is the only place the app throws. */
type Payloads = {
  BlankTitle: { title: string };
  UnknownRoom: { room: string };
  BadTime: { value: unknown };
  EmptySlot: { start: number; end: number };
  Clash: { room: string; start: number; end: number };
  NotFound: { id: string };
  EmptyUndo: Record<string, never>;
  BadDate: { date: unknown };
  BadCount: { weeks: unknown };
};

export declare namespace Errors {
  /** Every app error name. */
  type Name = keyof Payloads;
  /** The typed payload carried by one error name. */
  type Payload<N extends Name> = Payloads[N];
  /** An app error: identified by `kind`, carrying a typed `payload`. */
  type Of<N extends Name = Name> = Error & {
    readonly kind: N;
    readonly payload: Payload<N>;
  };
}

/** Narrow an unknown error to one registry entry; callers rethrow on mismatch. */
export function isError<N extends Errors.Name>(
  value: unknown,
  kind: N,
): value is Errors.Of<N> {
  return (
    value instanceof Error &&
    "kind" in value &&
    value.kind === kind &&
    "payload" in value
  );
}

/** Build one registry error: an `Error` carrying its `kind` and typed `payload`. */
export function appError<N extends Errors.Name>(
  kind: N,
  payload: Errors.Payload<N>,
): Errors.Of<N> {
  return Object.assign(new Error(kind), { kind, payload });
}

import { describe, expect, it } from "vitest";
import { createScope } from "@tinker/core";
import {
  addPrerequisite,
  completeCourse,
  courses,
  createCourse,
  isError,
  removePrerequisite,
  undoPlan,
} from "../src/index.ts";
import { reported } from "./support/report.ts";

describe("addPrerequisite", () => {
  it("appends the link and returns the changed course only", () => {
    const scope = createScope();
    const basics = scope.run(createCourse, { input: { title: "Basics" } });
    const practice = scope.run(createCourse, { input: { title: "Practice" } });
    const changed = scope.run(addPrerequisite, {
      input: { courseId: practice.id, prerequisiteId: basics.id },
    });
    expect(changed.id).toBe(practice.id);
    expect(changed.title).toBe("Practice");
    expect(changed.done).toBe(false);
    expect(changed.prerequisiteIds).toEqual([basics.id]);
    const list = scope.resolve(courses);
    expect(list.map((course) => course.title)).toEqual(["Basics", "Practice"]);
    expect(list[0]).toEqual(basics);
  });

  it("keeps the prerequisite ids in link order", () => {
    const scope = createScope();
    const basics = scope.run(createCourse, { input: { title: "Basics" } });
    const reading = scope.run(createCourse, { input: { title: "Reading" } });
    const practice = scope.run(createCourse, { input: { title: "Practice" } });
    scope.run(addPrerequisite, {
      input: { courseId: practice.id, prerequisiteId: reading.id },
    });
    const changed = scope.run(addPrerequisite, {
      input: { courseId: practice.id, prerequisiteId: basics.id },
    });
    expect(changed.prerequisiteIds).toEqual([reading.id, basics.id]);
  });

  it("accepts a completed prerequisite", () => {
    const scope = createScope();
    const basics = scope.run(createCourse, { input: { title: "Basics" } });
    const practice = scope.run(createCourse, { input: { title: "Practice" } });
    scope.run(completeCourse, { input: { id: basics.id } });
    const changed = scope.run(addPrerequisite, {
      input: { courseId: practice.id, prerequisiteId: basics.id },
    });
    expect(changed.prerequisiteIds).toEqual([basics.id]);
  });

  it("reports NotFound for an unknown course id", () => {
    const scope = createScope();
    const basics = scope.run(createCourse, { input: { title: "Basics" } });
    const error = reported(() =>
      scope.run(addPrerequisite, {
        input: { courseId: "ghost", prerequisiteId: basics.id },
      }),
    );
    if (!isError(error, "NotFound")) throw error;
    expect(error.payload).toEqual({ id: "ghost" });
    expect(scope.resolve(courses)).toEqual([basics]);
  });

  it("reports NotFound for an unknown prerequisite id", () => {
    const scope = createScope();
    const basics = scope.run(createCourse, { input: { title: "Basics" } });
    const error = reported(() =>
      scope.run(addPrerequisite, {
        input: { courseId: basics.id, prerequisiteId: "ghost" },
      }),
    );
    if (!isError(error, "NotFound")) throw error;
    expect(error.payload).toEqual({ id: "ghost" });
  });

  it("reports SelfRequirement with the courseId", () => {
    const scope = createScope();
    const basics = scope.run(createCourse, { input: { title: "Basics" } });
    const error = reported(() =>
      scope.run(addPrerequisite, {
        input: { courseId: basics.id, prerequisiteId: basics.id },
      }),
    );
    if (!isError(error, "SelfRequirement")) throw error;
    expect(error.payload).toEqual({ id: basics.id });
    expect(scope.resolve(courses)).toEqual([basics]);
  });

  it("reports Cycle for a direct two-course loop and keeps the plan", () => {
    const scope = createScope();
    const basics = scope.run(createCourse, { input: { title: "Basics" } });
    const reading = scope.run(createCourse, { input: { title: "Reading" } });
    scope.run(addPrerequisite, {
      input: { courseId: reading.id, prerequisiteId: basics.id },
    });
    const error = reported(() =>
      scope.run(addPrerequisite, {
        input: { courseId: basics.id, prerequisiteId: reading.id },
      }),
    );
    if (!isError(error, "Cycle")) throw error;
    expect(error.payload).toEqual({ courseId: basics.id, prerequisiteId: reading.id });
    const list = scope.resolve(courses);
    expect(list[0].prerequisiteIds).toEqual([]);
    expect(list[1].prerequisiteIds).toEqual([basics.id]);
  });

  it("reports Cycle for a loop through several courses", () => {
    const scope = createScope();
    const basics = scope.run(createCourse, { input: { title: "Basics" } });
    const reading = scope.run(createCourse, { input: { title: "Reading" } });
    const practice = scope.run(createCourse, { input: { title: "Practice" } });
    scope.run(addPrerequisite, {
      input: { courseId: reading.id, prerequisiteId: basics.id },
    });
    scope.run(addPrerequisite, {
      input: { courseId: practice.id, prerequisiteId: reading.id },
    });
    const error = reported(() =>
      scope.run(addPrerequisite, {
        input: { courseId: basics.id, prerequisiteId: practice.id },
      }),
    );
    if (!isError(error, "Cycle")) throw error;
    expect(error.payload).toEqual({ courseId: basics.id, prerequisiteId: practice.id });
  });

  it("reports CourseDone when the course is completed", () => {
    const scope = createScope();
    const basics = scope.run(createCourse, { input: { title: "Basics" } });
    const reading = scope.run(createCourse, { input: { title: "Reading" } });
    const practice = scope.run(createCourse, { input: { title: "Practice" } });
    scope.run(completeCourse, { input: { id: basics.id } });
    const before = scope.resolve(courses);
    const error = reported(() =>
      scope.run(addPrerequisite, {
        input: { courseId: basics.id, prerequisiteId: practice.id },
      }),
    );
    if (!isError(error, "CourseDone")) throw error;
    expect(error.payload).toEqual({ id: basics.id });
    expect(scope.resolve(courses)).toEqual(before);
  });

  it("adds a present link as a passing no-change action without an undo step", () => {
    const scope = createScope();
    const basics = scope.run(createCourse, { input: { title: "Basics" } });
    const practice = scope.run(createCourse, { input: { title: "Practice" } });
    const linked = scope.run(addPrerequisite, {
      input: { courseId: practice.id, prerequisiteId: basics.id },
    });
    const again = scope.run(addPrerequisite, {
      input: { courseId: practice.id, prerequisiteId: basics.id },
    });
    expect(again).toEqual(linked);
    scope.run(undoPlan, {});
    const list = scope.resolve(courses);
    expect(list[1].prerequisiteIds).toEqual([]);
  });
});

describe("removePrerequisite", () => {
