} from "./model.ts";
import { isError, type Errors } from "./errors.ts";

const KINDS: readonly Errors.Name[] = [
  "BlankTitle",
  "UnknownRoom",
  "BadTime",
  "EmptySlot",
  "Clash",
  "NotFound",
  "BadDate",
  "BadCount",
  "EmptyUndo",
];

/** The registry kind of a thrown failure; foreign errors are rethrown. */
function errorKind(thrown: unknown): string {
  for (const kind of KINDS) {
    if (isError(thrown, kind)) {
      return kind;
    }
  }
  throw thrown;
}

/** `HH:MM` (24-hour) to minutes since midnight; anything else is not a time. */
function toMinutes(text: string): number {
  const match = /^([0-9]{2}):([0-9]{2})$/.exec(text.trim());
  if (match === null) {
    return Number.NaN;
  }
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (hours > 23 || minutes > 59) {
    return Number.NaN;
  }
  return hours * 60 + minutes;
}

/** Minutes since midnight back to `HH:MM`. */
function formatTime(minutes: number): string {
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  return `${String(hours).padStart(2, "0")}:${String(rest).padStart(2, "0")}`;
}

type EditFormProps = {
  readonly draft: Booking;
  readonly onSuccess: () => void;
  readonly onFailure: (thrown: unknown) => void;
};

/** The one open draft: its own local text, saved or discarded through the scope. */
function EditForm({ draft, onSuccess, onFailure }: EditFormProps): ReactElement {
  const scope = useScope();
  const [title, setTitle] = useState(draft.title);
  const [room, setRoom] = useState<string>(draft.room);
  const [date, setDate] = useState(draft.date);
  const [start, setStart] = useState(formatTime(draft.start));
  const [end, setEnd] = useState(formatTime(draft.end));

  function handleSave(event: FormEvent): void {
    event.preventDefault();
    try {
      scope.run(saveEdit, {
        input: { id: draft.id, title, room, date, start: toMinutes(start), end: toMinutes(end) },
      });
      onSuccess();
    } catch (thrown) {
      onFailure(thrown);
    }
  }

  function handleDiscard(): void {
    try {
      scope.run(discardEdit, { input: { id: draft.id } });
      onSuccess();
    } catch (thrown) {
      onFailure(thrown);
    }
  }

  return (
    <form className="edit-form" onSubmit={handleSave}>
      <label htmlFor="edit-title">Edit title</label>
      <input
        id="edit-title"
        name="Edit title"
        value={title}
        onChange={(event) => setTitle(event.target.value)}
      />
      <label htmlFor="edit-room">Edit room</label>
      <input
        id="edit-room"
        name="Edit room"
        value={room}
        onChange={(event) => setRoom(event.target.value)}
      />
      <label htmlFor="edit-date">Edit date</label>
      <input
        id="edit-date"
        name="Edit date"
        value={date}
        onChange={(event) => setDate(event.target.value)}
      />
      <label htmlFor="edit-start">Edit start time</label>
      <input
        id="edit-start"
        name="Edit start time"
        value={start}
        onChange={(event) => setStart(event.target.value)}
      />
      <label htmlFor="edit-end">Edit end time</label>
      <input
        id="edit-end"
        name="Edit end time"
        value={end}
        onChange={(event) => setEnd(event.target.value)}
      />
      <button type="submit">Save</button>
      <button type="button" onClick={handleDiscard}>
        Discard
      </button>
    </form>
  );
}

