/** A fresh desk on its own scope, with the default stock and no history. */
function desk(): Scope.Handle {
  return createScope();
}

/** Run `call` and hand back the value it threw, or nothing when it passed. */
function capture(call: () => unknown): unknown {
  try {
    call();
    return undefined;
  } catch (error) {
    return error;
  }
}

/** A desk holding two Cable moves (3 East to West, then 4 West to East) for edit cases. */
function twoMoveDesk(): Scope.Handle {
  const scope = desk();
  scope.run(moveStock, { input: { item: "Cable", from: "East", to: "West", quantity: 3 } });
  scope.run(moveStock, { input: { item: "Cable", from: "West", to: "East", quantity: 4 } });
  return scope;
}

const defaultStock = [
  { item: "Cable", place: "East", quantity: 8 },
  { item: "Cable", place: "West", quantity: 2 },
  { item: "Stand", place: "East", quantity: 3 },
  { item: "Stand", place: "West", quantity: 1 },
];

