  | "title"
  | "room"
  | "date"
  | "start"
  | "end"
  | "weeks";

/** Which edit-form field one keystroke changes. */
export type EditField = "title" | "room" | "date" | "start" | "end";

/** The room filter: one room, or every room. */
export type Filter = Room | "All";

/** The live booking form, held as the text the user typed. */
export type BookingForm = {
  title: string;
  room: string;
  date: string;
  start: string;
  end: string;
  weeks: string;
};

/** The live edit form, held as the text the user typed. */
export type EditForm = {
  title: string;
  room: string;
  date: string;
  start: string;
  end: string;
};

/** The one open series-title editor: the chosen series and its unsaved title text. */
export type SeriesTitleEditor = {
  seriesId: string;
  title: string;
};

const EMPTY_EDIT_FORM: EditForm = {
  title: "",
  room: "",
  date: DEFAULT_DATE,
  start: "",
  end: "",
};

/** The saved bookings of this scope, ordered by date, then start, then creation. */
export const bookings: Data.Cell<readonly Booking[]> = data<readonly Booking[]>({
  label: "bookings",
