/** The single open series-title editor, or `undefined` when no editor is open. */
export const seriesTitleEditor: Data.Cell<SeriesTitleEditor | undefined> = data<
  SeriesTitleEditor | undefined
>({
  label: "seriesTitleEditor",
  initial: undefined,
});

/** The active room filter. */
export const roomFilter: Data.Cell<Filter> = data<Filter>({
  label: "roomFilter",
  initial: "All",
});

/** The kind of the last failed screen action, shown beside the form. */
export const notice: Data.Cell<Errors.Name | undefined> = data<
  Errors.Name | undefined
>({
  label: "notice",
  initial: undefined,
});

/** Creation order of every id this scope has ever saved, oldest first. */
const createdOrder: Data.Cell<readonly string[]> = data<readonly string[]>({
  label: "createdOrder",
  initial: [],
});

/**
 * One snapshot of the saved bookings per passing change, newest last. Kept in a core
 * cell: it is app state, so it lives nowhere else. `undoChange` pops one entry.
 */
const history: Data.Cell<readonly (readonly Booking[])[]> = data<
  readonly (readonly Booking[])[]
>({
  label: "history",
  initial: [],
});

/** Record one undo step for the list as it was before a change. */
function pushHistory(
  store: Scope.DataController<readonly Booking[]>,
  historyStore: Scope.DataController<readonly (readonly Booking[])[]>,
): void {
  historyStore.set([...historyStore.get(), store.get()]);
}

/** A unique opaque id. Uses the platform UUID source so nothing lives outside cells. */
function nextId(): string {
  return globalThis.crypto.randomUUID();
}

/** The minutes a time input holds, or `BadTime` when it cannot be read. */
function minutesFromText(text: string): number {
  const minutes = parseTime(text);
  if (minutes === undefined) {
    throw badTime(text);
  }
  return minutes;
}

/** The whole-number weeks a text input holds, or `BadCount` when it cannot be read. */
function weeksFromText(text: string): number {
  if (!/^-?\d+$/.test(text.trim())) {
    throw badCount(text);
  }
  return Number(text.trim());
}

/** Create a booking when every rule passes; otherwise throw and change nothing. */
export const bookBooking: Operation.Handle<Booking, BookInput> = operation({
  label: "bookBooking",
  depends: {
    bookings: bookings.controller,
    history: history.controller,
    createdOrder: createdOrder.controller,
  },
  run: ({ bookings: store, history: historyStore, createdOrder: order }, ctx) => {
    const fields = checkFields(ctx.input);
    const existing = store.get();
    if (hasConflict(existing, fields.room, fields.date, fields.start, fields.end)) {
      throw clash(fields.room, fields.start, fields.end);
    }
    const booking: Booking = { id: nextId(), ...fields };
    const orderNext = [...order.get(), booking.id];
    pushHistory(store, historyStore);
    order.set(orderNext);
    store.set(sortBookings([...existing, booking], orderNext));
    return booking;
  },
});

/** Cancel a booking by id; also closes its draft when it owns one. */
export const cancelBooking: Operation.Handle<void, { id: string }> = operation({
  label: "cancelBooking",
  depends: {
    bookings: bookings.controller,
    editDraft: editDraft.controller,
    history: history.controller,
  },
  run: ({ bookings: store, editDraft: draft, history: historyStore }, ctx) => {
    const { id } = ctx.input;
    const existing = store.get();
    if (!existing.some((booking) => booking.id === id)) {
      throw notFound(id);
    }
    pushHistory(store, historyStore);
    store.set(existing.filter((booking) => booking.id !== id));
    if (draft.get()?.id === id) {
      draft.set(undefined);
    }
  },
});

/** Open a copy of a saved booking as the one draft; unknown id reports NotFound. */
export const openEdit: Operation.Handle<Booking, { id: string }> = operation({
  label: "openEdit",
  depends: {
    bookings: bookings.controller,
    editDraft: editDraft.controller,
  },
  run: ({ bookings: store, editDraft: draft }, ctx) => {
    const found = store.get().find((booking) => booking.id === ctx.input.id);
    if (found === undefined) {
      throw notFound(ctx.input.id);
    }
    const copy = copyBooking(found);
    draft.set(copy);
    return copy;
  },
});

/** Open the title editor for the clicked occurrence; unknown id reports NotFound. */
export const openRename: Operation.Handle<SeriesTitleEditor, { id: string }> =
  operation({
    label: "openRename",
    depends: {
      bookings: bookings.controller,
      seriesTitleEditor: seriesTitleEditor.controller,
    },
    run: ({ bookings: store, seriesTitleEditor: editor }, ctx) => {
      const { id } = ctx.input;
      const found = store.get().find((booking) => booking.id === id);
      const seriesId = found?.seriesId;
      if (found === undefined || seriesId === undefined) {
        throw notFound(id);
      }
      const open: SeriesTitleEditor = { seriesId, title: found.title };
      editor.set(open);
      return open;
    },
  });

/** Save the open draft over its booking when every rule passes. */
export const saveEdit: Operation.Handle<Booking, EditInput> = operation({
  label: "saveEdit",
  depends: {
    bookings: bookings.controller,
    editDraft: editDraft.controller,
    createdOrder: createdOrder.controller,
    history: history.controller,
  },
  run: (
    {
      bookings: store,
      editDraft: draft,
      createdOrder: order,
      history: historyStore,
    },
    ctx,
  ) => {
    const { id } = ctx.input;
    const open = draft.get();
    if (open === undefined || open.id !== id) {
      throw notFound(id);
    }
    const existing = store.get();
    const index = existing.findIndex((booking) => booking.id === id);
    if (index < 0) {
      throw notFound(id);
    }
    const fields = checkFields(ctx.input);
    if (
      hasConflict(existing, fields.room, fields.date, fields.start, fields.end, id)
    ) {
      throw clash(fields.room, fields.start, fields.end);
    }
    const updated: Booking =
      open.seriesId === undefined
        ? { id, ...fields }
        : { id, ...fields, seriesId: open.seriesId };
    pushHistory(store, historyStore);
    store.set(
      sortBookings(
        existing.map((booking, at) => (at === index ? updated : booking)),
        order.get(),
      ),
    );
    draft.set(undefined);
    return updated;
  },
});

/** Drop the open draft without touching the saved booking. */
export const discardEdit: Operation.Handle<void, { id: string }> = operation({
  label: "discardEdit",
  depends: { editDraft: editDraft.controller },
  run: ({ editDraft: draft }, ctx) => {
    const { id } = ctx.input;
    if (draft.get()?.id !== id) {
      throw notFound(id);
    }
    draft.set(undefined);
  },
});

/** Book one weekly series, or book none and report the first failure. */
export const bookSeries: Operation.Handle<readonly Booking[], SeriesInput> =
  operation({
    label: "bookSeries",
    depends: {
      bookings: bookings.controller,
      history: history.controller,
      createdOrder: createdOrder.controller,
    },
    run: (
      { bookings: store, history: historyStore, createdOrder: order },
      ctx,
    ) => {
      const weeks = checkWeeks(ctx.input.weeks);
      const fields = checkFields(ctx.input);
      const dates = seriesDates(fields.date, weeks);
      const existing = store.get();
      for (const date of dates) {
        if (hasConflict(existing, fields.room, date, fields.start, fields.end)) {
          throw clash(fields.room, fields.start, fields.end);
        }
      }
      const seriesId = nextId();
      const created: Booking[] = dates.map((date) => ({
        id: nextId(),
        title: fields.title,
        room: fields.room,
        date,
        start: fields.start,
        end: fields.end,
        seriesId,
      }));
      const orderNext = [...order.get(), ...created.map((booking) => booking.id)];
      pushHistory(store, historyStore);
      order.set(orderNext);
      store.set(sortBookings([...existing, ...created], orderNext));
      return created;
    },
  });

/** Cancel every occurrence of one series; unknown series id reports NotFound. */
export const cancelSeries: Operation.Handle<void, { seriesId: string }> =
  operation({
    label: "cancelSeries",
    depends: {
      bookings: bookings.controller,
      editDraft: editDraft.controller,
      history: history.controller,
    },
    run: ({ bookings: store, editDraft: draft, history: historyStore }, ctx) => {
      const { seriesId } = ctx.input;
      const existing = store.get();
      const removed = existing.filter((booking) => booking.seriesId === seriesId);
      if (removed.length === 0) {
        throw notFound(seriesId);
      }
      pushHistory(store, historyStore);
      store.set(existing.filter((booking) => booking.seriesId !== seriesId));
      const open = draft.get();
      if (open !== undefined && removed.some((booking) => booking.id === open.id)) {
        draft.set(undefined);
      }
    },
  });

/** Rename every remaining occurrence of one series in one step; unknown id reports NotFound. */
export const renameSeries: Operation.Handle<
  readonly Booking[],
  { seriesId: string; title: string }
> = operation({
    label: "renameSeries",
    depends: {
      bookings: bookings.controller,
      history: history.controller,
    },
    run: ({ bookings: store, history: historyStore }, ctx) => {
      const title = checkRenameTitle(ctx.input.title);
      const { seriesId } = ctx.input;
      const existing = store.get();
      const renamed = retitleSeries(existing, seriesId, title);
      if (renamed.length === 0) {
        throw notFound(seriesId);
      }
      const byId = new Map(renamed.map((booking) => [booking.id, booking]));
      pushHistory(store, historyStore);
      store.set(existing.map((booking) => byId.get(booking.id) ?? booking));
      return renamed;
    },
  });

/**
 * Reverse the last passing booking change in one step, restoring the exact prior list.
 * Restores booking data only: drafts, form text, and filters are never touched.
 */
export const undoChange: Operation.Handle<void, void> = operation({
  label: "undoChange",
  depends: {
    bookings: bookings.controller,
    history: history.controller,
  },
  run: ({ bookings: store, history: historyStore }) => {
    const steps = historyStore.get();
    if (steps.length === 0) {
      throw emptyUndo();
    }
    const restored = steps[steps.length - 1];
    if (restored === undefined) {
      throw emptyUndo();
    }
    store.set(restored);
    historyStore.set(steps.slice(0, -1));
  },
});

