import { expect } from "vitest";

/** Run an action that must report a managed error, and hand back the thrown value. */
export function reported(action: () => unknown): unknown {
  try {
    action();
  } catch (error) {
    return error;
  }
  return expect.fail("the action should report a managed error");
}

import { describe, expect, it } from "vitest";
import { createScope } from "@tinker/core";
import {
  bookBooking,
  bookings,
  cancelBooking,
  discardEdit,
  editDraft,
  isError,
  openEdit,
  saveEdit,
} from "../src/index.ts";
import type { Booking } from "../src/index.ts";

function book(scope: ReturnType<typeof createScope>, input: {
  title: string;
  room: string;
  start: number;
  end: number;
}): Booking {
  return scope.run(bookBooking, { input });
}

describe("bookBooking", () => {
  it("saves a booking with the trimmed title", () => {
    const scope = createScope();
    const saved = book(scope, {
      title: "  Standup  ",
      room: "Cedar",
      start: 540,
      end: 600,
    });
    expect(saved.id).toBeTypeOf("string");
    expect(saved.title).toBe("Standup");
    expect(saved.room).toBe("Cedar");
    expect(saved.start).toBe(540);
    expect(saved.end).toBe(600);
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("starts with an empty list", () => {
    const scope = createScope();
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects a blank title", () => {
    const scope = createScope();
    try {
      book(scope, { title: "   ", room: "Cedar", start: 0, end: 30 });
      throw new Error("expected a throw");
    } catch (error) {
      if (!isError(error, "BlankTitle")) {
        throw error;
      }
        expect(error.payload.title).toBe("");
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects an unknown room", () => {
    const scope = createScope();
    try {
      book(scope, { title: "Standup", room: "Garage", start: 0, end: 30 });
      throw new Error("expected a throw");
    } catch (error) {
      if (!isError(error, "UnknownRoom")) {
        throw error;
      }
        expect(error.payload.room).toBe("Garage");
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects non-integer and out-of-range times", () => {
    const scope = createScope();
    for (const value of [1.5, -1, 1440, Number.NaN]) {
      try {
        book(scope, { title: "Standup", room: "Cedar", start: 540, end: value });
        throw new Error("expected a throw");
      } catch (error) {
        if (!isError(error, "BadTime")) {
          throw error;
        }
      }
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects an end at or before the start", () => {
    const scope = createScope();
    for (const [start, end] of [
      [600, 600],
      [600, 540],
    ]) {
      try {
        book(scope, { title: "Standup", room: "Cedar", start, end });
        throw new Error("expected a throw");
      } catch (error) {
        if (!isError(error, "EmptySlot")) {
          throw error;
        }
          expect(error.payload).toEqual({ start, end });
      }
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("clashes on overlap within one room", () => {
    const scope = createScope();
    book(scope, { title: "Standup", room: "Cedar", start: 540, end: 600 });
    try {
      book(scope, { title: "Other", room: "Cedar", start: 570, end: 630 });
      throw new Error("expected a throw");
    } catch (error) {
      if (!isError(error, "Clash")) {
        throw error;
      }
        expect(error.payload).toEqual({
          room: "Cedar",
          start: 570,
          end: 630,
        });
    }
    expect(scope.resolve(bookings)).toHaveLength(1);
  });

  it("allows the same slot in another room", () => {
    const scope = createScope();
    book(scope, { title: "Standup", room: "Cedar", start: 540, end: 600 });
    const maple = book(scope, {
      title: "Standup",
      room: "Maple",
      start: 540,
      end: 600,
    });
    expect(scope.resolve(bookings)).toHaveLength(2);
