  });

  it("allows back-to-back bookings in one room", () => {
    const scope = createScope();
    book(scope, { title: "Standup", room: "Cedar", start: 540, end: 600 });
    book(scope, { title: "Review", room: "Cedar", start: 600, end: 660 });
