  });

  it("creates exactly one booking for a contended slot", () => {
    const scope = createScope();
    book(scope, { title: "Standup", room: "Cedar", start: 540, end: 600 });
    expect(() =>
      book(scope, { title: "Other", room: "Cedar", start: 540, end: 600 }),
    ).toThrow();
    expect(scope.resolve(bookings)).toHaveLength(1);
  });
});

describe("cancelBooking", () => {
