describe("openEdit", () => {
  it("returns a copy that does not alias the saved booking", () => {
    const scope = createScope();
    const saved = book(scope, {
      title: "Standup",
      room: "Cedar",
      start: 540,
      end: 600,
    });
    const draft = scope.run(openEdit, { input: { id: saved.id } });
    expect(draft).toEqual(saved);
    expect(draft).not.toBe(saved);
    Object.assign(draft, { title: "Renamed" });
    expect(scope.resolve(bookings)[0]?.title).toBe("Standup");
    expect(scope.resolve(editDraft)?.title).toBe("Renamed");
  });

  it("reports NotFound for an unknown id", () => {
    const scope = createScope();
    expect(() => scope.run(openEdit, { input: { id: "nope" } })).toThrow();
    try {
      scope.run(openEdit, { input: { id: "nope" } });
    } catch (error) {
      if (!isError(error, "NotFound")) {
        throw error;
      }
    }
  });

  it("keeps only one draft open at a time", () => {
    const scope = createScope();
    const first = book(scope, {
      title: "First",
      room: "Cedar",
      start: 540,
      end: 600,
    });
    const second = book(scope, {
      title: "Second",
      room: "Cedar",
      start: 600,
      end: 660,
    });
    scope.run(openEdit, { input: { id: first.id } });
    scope.run(openEdit, { input: { id: second.id } });
    expect(scope.resolve(editDraft)?.id).toBe(second.id);
    expect(scope.resolve(bookings).map((b) => b.title)).toEqual([
      "First",
      "Second",
    ]);
  });

  it("blocks nothing until save", () => {
    const scope = createScope();
    const saved = book(scope, {
      title: "Standup",
      room: "Cedar",
      start: 540,
      end: 600,
    });
    const draft = scope.run(openEdit, { input: { id: saved.id } });
    // The draft now asks for a later slot; the saved list must not reserve it.
    Object.assign(draft, { start: 600, end: 660 });
    const other = book(scope, {
      title: "Overlap",
      room: "Cedar",
      start: 600,
      end: 660,
    });
    expect(other.start).toBe(600);
    expect(scope.resolve(bookings)).toHaveLength(2);
  });
});

describe("saveEdit", () => {
  it("replaces the booking and closes the draft", () => {
    const scope = createScope();
    const saved = book(scope, {
      title: "Standup",
      room: "Cedar",
      start: 540,
      end: 600,
    });
    scope.run(openEdit, { input: { id: saved.id } });
