        room: "Cedar",
        start: 540,
        end: 600,
      },
    });
    expect(updated.title).toBe("Planning");
    expect(scope.resolve(bookings)).toEqual([updated]);
    expect(scope.resolve(editDraft)).toBeUndefined();
  });

  it("allows keeping the booking's own slot", () => {
    const scope = createScope();
    const saved = book(scope, {
      title: "Standup",
      room: "Cedar",
      start: 540,
      end: 600,
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const updated = scope.run(saveEdit, {
      input: {
        id: saved.id,
        title: "Renamed",
        room: "Cedar",
        start: 540,
        end: 600,
      },
    });
    expect(updated.id).toBe(saved.id);
    expect(scope.resolve(bookings)).toHaveLength(1);
  });

  it("reports Clash against another booking and keeps the draft open", () => {
    const scope = createScope();
    const first = book(scope, {
      title: "First",
      room: "Cedar",
      start: 540,
      end: 600,
    });
    const second = book(scope, {
      title: "Second",
      room: "Cedar",
      start: 600,
      end: 660,
    });
    scope.run(openEdit, { input: { id: second.id } });
    try {
      scope.run(saveEdit, {
        input: {
          id: second.id,
          title: "Second",
          room: "Cedar",
          start: 570,
          end: 630,
        },
      });
      throw new Error("expected a throw");
    } catch (error) {
      if (!isError(error, "Clash")) {
        throw error;
      }
    }
    expect(scope.resolve(bookings)).toEqual([first, second]);
    expect(scope.resolve(editDraft)?.id).toBe(second.id);
  });

  it("uses the same title and time rules as booking", () => {
    const scope = createScope();
    const saved = book(scope, {
      title: "Standup",
      room: "Cedar",
      start: 540,
      end: 600,
    });
    scope.run(openEdit, { input: { id: saved.id } });
    expect(() =>
      scope.run(saveEdit, {
        input: {
          id: saved.id,
          title: "  ",
          room: "Cedar",
          start: 540,
          end: 600,
        },
      }),
    ).toThrow();
    expect(scope.resolve(bookings)[0]?.title).toBe("Standup");
    expect(scope.resolve(editDraft)?.id).toBe(saved.id);

    expect(() =>
      scope.run(saveEdit, {
        input: {
          id: saved.id,
          title: "Standup",
          room: "Garage",
          start: 540,
          end: 600,
        },
      }),
    ).toThrow();
    expect(() =>
      scope.run(saveEdit, {
        input: {
          id: saved.id,
          title: "Standup",
          room: "Cedar",
          start: 600,
          end: 600,
        },
      }),
    ).toThrow();
  });

  it("reports NotFound when the draft is closed", () => {
    const scope = createScope();
    const saved = book(scope, {
      title: "Standup",
      room: "Cedar",
      start: 540,
      end: 600,
    });
    scope.run(openEdit, { input: { id: saved.id } });
    scope.run(discardEdit, { input: { id: saved.id } });
    try {
      scope.run(saveEdit, {
        input: {
          id: saved.id,
          title: "Planning",
          room: "Cedar",
          start: 540,
          end: 600,
        },
      });
      throw new Error("expected a throw");
    } catch (error) {
      if (!isError(error, "NotFound")) {
        throw error;
      }
    }
    expect(scope.resolve(bookings)[0]?.title).toBe("Standup");
  });
});

