import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { build, preview } from "vite";
import type { PreviewServer } from "vite";
import { chromium } from "playwright";
import type { Browser, Locator, Page } from "playwright";

let server: PreviewServer;
let browser: Browser;
let page: Page;
let baseUrl: string;

beforeAll(async () => {
  await build({ root: process.cwd(), logLevel: "silent" });
  server = await preview({
    root: process.cwd(),
    logLevel: "silent",
    preview: { host: "127.0.0.1", port: 5199, strictPort: false },
  });
  const url = server.resolvedUrls?.local[0];
  if (url === undefined) {
    throw new Error("preview server did not report a url");
  }
  baseUrl = url;
  browser = await chromium.launch({ args: ["--no-sandbox"] });
  page = await browser.newPage();
  await page.goto(baseUrl);
}, 60000);

afterAll(async () => {
  await browser?.close();
  await server?.close();
});

const TIMEOUT = { timeout: 5000 };

function rows(): Locator {
  return page.locator("tbody tr");
}

async function expectRows(count: number): Promise<void> {
  await expect.poll(() => rows().count(), TIMEOUT).toBe(count);
}

async function expectRowContains(index: number, text: string): Promise<void> {
  await expect.poll(() => rows().nth(index).textContent(), TIMEOUT).toContain(
    text,
  );
}

async function expectAlert(text: string): Promise<void> {
  await expect
    .poll(async () => {
      const alert = page.getByRole("alert");
      return (await alert.count()) === 0 ? null : alert.first().textContent();
    }, TIMEOUT)
    .toBe(text);
}

async function expectNoAlert(): Promise<void> {
  await expect.poll(() => page.getByRole("alert").count(), TIMEOUT).toBe(0);
}

async function expectInput(label: string, value: string): Promise<void> {
  await expect
    .poll(() => page.getByLabel(label, { exact: true }).inputValue(), TIMEOUT)
    .toBe(value);
}

async function expectGone(label: string): Promise<void> {
  await expect
    .poll(() => page.getByLabel(label, { exact: true }).count(), TIMEOUT)
    .toBe(0);
}

async function reload(): Promise<void> {
  await page.goto(baseUrl);
}

async function book(values: {
  title: string;
  room: string;
  start: string;
  end: string;
}): Promise<void> {
  await page.getByLabel("Title", { exact: true }).fill(values.title);
  await page.getByLabel("Room", { exact: true }).fill(values.room);
  await page.getByLabel("Start time", { exact: true }).fill(values.start);
  await page.getByLabel("End time", { exact: true }).fill(values.end);
  await page.getByRole("button", { name: "Book", exact: true }).click();
}

describe("booking screen", () => {
  it(
    "books a row, clears the title, and keeps the form",
    async () => {
      await reload();
      await expectRows(0);
      await book({
        title: "Standup",
        room: "Cedar",
        start: "09:00",
        end: "10:00",
      });
      await expectRows(1);
      await expectRowContains(0, "Standup");
      await expectRowContains(0, "Cedar");
      await expectRowContains(0, "09:00-10:00");
      await expectInput("Title", "");
      await expectInput("Start time", "09:00");
      await expectNoAlert();
    },
    30000,
  );

  it(
    "shows Clash beside the form and keeps the form values",
    async () => {
      await reload();
      await book({
        title: "Standup",
        room: "Cedar",
        start: "09:00",
        end: "10:00",
      });
      await book({
        title: "Standup",
        room: "Cedar",
        start: "09:00",
        end: "10:00",
      });
      await expectAlert("Clash");
      await expectRows(1);
      await expectInput("Title", "Standup");
      await expectInput("Room", "Cedar");
    },
    30000,
  );

  it(
    "allows the same slot in another room and back-to-back times",
    async () => {
      await reload();
      await book({
        title: "Standup",
        room: "Cedar",
        start: "09:00",
        end: "10:00",
      });
      await book({
        title: "Standup",
        room: "Maple",
        start: "09:00",
        end: "10:00",
      });
      await expectRows(2);
      await book({
        title: "Review",
        room: "Cedar",
        start: "10:00",
        end: "11:00",
      });
      await expectRows(3);
    },
    30000,
  );

  it(
    "filters rows without deleting them",
    async () => {
      await reload();
      await book({
        title: "Standup",
        room: "Cedar",
        start: "09:00",
        end: "10:00",
      });
      await book({
        title: "Maple chat",
        room: "Maple",
        start: "09:00",
        end: "10:00",
      });
      await page.getByRole("button", { name: "Cedar", exact: true }).click();
      await expectRows(1);
      await expectRowContains(0, "Standup");
      await page.getByRole("button", { name: "All", exact: true }).click();
      await expectRows(2);
      await page.getByRole("button", { name: "Maple", exact: true }).click();
      await expectRows(1);
      await expectRowContains(0, "Maple chat");
    },
    30000,
  );

  it(
    "cancels a row and frees its slot",
    async () => {
      await reload();
      await book({
        title: "Standup",
        room: "Cedar",
        start: "09:00",
        end: "10:00",
      });
      await page
        .getByRole("button", { name: "Cancel Standup", exact: true })
        .click();
      await expectRows(0);
      await book({
        title: "Again",
        room: "Cedar",
        start: "09:00",
        end: "10:00",
      });
      await expectRows(1);
      await expectRowContains(0, "Again");
    },
    30000,
  );

  it(
    "discards an edit, then saves one",
    async () => {
      await reload();
      await book({
        title: "Standup",
        room: "Cedar",
        start: "09:00",
        end: "10:00",
      });
      await page
        .getByRole("button", { name: "Edit Standup", exact: true })
        .click();
      await page.getByLabel("Edit title", { exact: true }).fill("Planning");
      await page.getByRole("button", { name: "Discard", exact: true }).click();
      await expectRows(1);
      await expectRowContains(0, "Standup");

      await page
        .getByRole("button", { name: "Edit Standup", exact: true })
        .click();
      await page.getByLabel("Edit title", { exact: true }).fill("Planning");
      await page.getByRole("button", { name: "Save", exact: true }).click();
      await expectRows(1);
      await expectRowContains(0, "Planning");
      await expectGone("Edit title");
    },
    30000,
  );

  it(
    "keeps the draft open on a clashing save",
    async () => {
      await reload();
      await book({
        title: "First",
        room: "Cedar",
        start: "09:00",
        end: "10:00",
      });
      await book({
        title: "Second",
        room: "Cedar",
        start: "10:00",
        end: "11:00",
      });
      await page
        .getByRole("button", { name: "Edit Second", exact: true })
        .click();
      await page.getByLabel("Edit start time", { exact: true }).fill("09:30");
      await page.getByLabel("Edit end time", { exact: true }).fill("10:30");
      await page.getByRole("button", { name: "Save", exact: true }).click();
      await expectAlert("Clash");
      await expectInput("Edit title", "Second");
      await expectRows(2);
    },
    30000,
  );

  it(
    "starts fresh after a reload",
    async () => {
      await reload();
      await book({
        title: "Standup",
        room: "Cedar",
        start: "09:00",
        end: "10:00",
      });
      await expectRows(1);
      await reload();
      await expectRows(0);
    },
    30000,
  );
});

import { createScope } from "@tinker/core";
import { describe, expect, it } from "vitest";
import {
  bookBooking,
  bookings,
  cancelBooking,
  discardEdit,
  editDraft,
  isError,
  openEdit,
  saveEdit,
} from "../src/index.ts";

function capture(action: () => unknown): unknown {
  try {
    action();
    return undefined;
  } catch (error) {
    return error;
  }
}

describe("dates on one booking", () => {
  it("books 2026-10-01 when the input carries no date", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    expect(saved.date).toBe("2026-10-01");
  });

  it("stores the passed date on the saved booking", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-02",
        start: 540,
        end: 600,
      },
    });
    expect(saved.date).toBe("2026-10-02");
  });

  it("rejects a date that is not a real YYYY-MM-DD day", () => {
    const scope = createScope();
    const bad = [
      "2026-02-30",
      "2026-13-01",
      "2026-00-10",
      "2026-10-1",
      "not-a-day",
      "",
    ];
    for (const date of bad) {
      const error = capture(() =>
        scope.run(bookBooking, {
          input: { title: "Standup", room: "Cedar", date, start: 540, end: 600 },
        }),
      );
      expect(isError(error, "BadDate"), date).toBe(true);
      if (isError(error, "BadDate")) {
        expect(error.payload.date).toBe(date);
      }
    }
    const notText = capture(() =>
      scope.run(bookBooking, {
        rawInput: {
          title: "Standup",
          room: "Cedar",
          date: 20261001,
          start: 540,
          end: 600,
        },
      }),
    );
    expect(isError(notText, "BadDate")).toBe(true);
    if (isError(notText, "BadDate")) {
      expect(notText.payload.date).toBe(20261001);
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("clashes only in one room on one date", () => {
    const scope = createScope();
    scope.run(bookBooking, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-02",
        start: 540,
        end: 600,
      },
    });
    const clash = capture(() =>
      scope.run(bookBooking, {
        input: {
          title: "Clash",
          room: "Cedar",
          date: "2026-10-02",
          start: 550,
          end: 590,
        },
      }),
    );
    expect(isError(clash, "Clash")).toBe(true);
    const otherDate = scope.run(bookBooking, {
      input: {
        title: "Next day",
        room: "Cedar",
        date: "2026-10-03",
        start: 540,
        end: 600,
      },
    });
    const otherRoom = scope.run(bookBooking, {
      input: {
        title: "Maple",
        room: "Maple",
        date: "2026-10-02",
        start: 540,
        end: 600,
      },
    });
    const list = scope.resolve(bookings);
    expect(list).toHaveLength(3);
    expect(list.map((booking) => booking.id)).toContain(otherDate.id);
    expect(list.map((booking) => booking.id)).toContain(otherRoom.id);
  });

  it("sorts by date, then start time, then creation order", () => {
    const scope = createScope();
    const lateDay = scope.run(bookBooking, {
      input: {
        title: "Late day",
        room: "Cedar",
        date: "2026-10-02",
        start: 480,
        end: 540,
      },
    });
    const later = scope.run(bookBooking, {
      input: {
        title: "Later",
        room: "Maple",
        date: "2026-10-01",
        start: 600,
        end: 660,
      },
    });
    const a2 = scope.run(bookBooking, {
      input: {
        title: "A2",
        room: "Cedar",
        date: "2026-10-01",
        start: 540,
        end: 600,
      },
    });
    const a1 = scope.run(bookBooking, {
      input: {
        title: "A1",
        room: "Maple",
        date: "2026-10-01",
        start: 540,
        end: 600,
      },
    });
    expect(scope.resolve(bookings)).toEqual([a2, a1, later, lateDay]);
  });

  it("cancels by id and frees only that day", () => {
    const scope = createScope();
    scope.run(bookBooking, {
      input: {
        title: "One",
        room: "Cedar",
        date: "2026-10-02",
        start: 540,
