describe("dates on edit", () => {
  it("openEdit copies the saved date while the list keeps its own", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-05",
        start: 540,
        end: 600,
      },
    });
    const draft = scope.run(openEdit, { input: { id: saved.id } });
    expect(draft.date).toBe("2026-10-05");
    Object.assign(draft, { date: "2026-10-06" });
    expect(scope.resolve(bookings)[0]?.date).toBe("2026-10-05");
    scope.run(discardEdit, { input: { id: saved.id } });
  });

  it("saves onto a new date and clashes on that date only", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-05",
