        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
      },
    });
    expect(moved.date).toBe("2026-10-06");
    expect(scope.resolve(editDraft)).toBeUndefined();
  });

  it("saveEdit on the booking's own slot and date never reports Clash", () => {
