    const updated = scope.run(saveEdit, {
      input: {
        id: saved.id,
        title: "Renamed",
        room: "Cedar",
        date: "2026-10-05",
        start: 540,
        end: 600,
      },
    });
    expect(updated.title).toBe("Renamed");
    expect(scope.resolve(bookings)).toEqual([updated]);
  });

  it("rejects a bad date on save and keeps the draft open", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const error = capture(() =>
      scope.run(saveEdit, {
        input: {
          id: saved.id,
          title: "Renamed",
          room: "Cedar",
          date: "2026-02-30",
          start: 540,
          end: 600,
        },
