/** The two fixed rooms. */
export type Room = "Cedar" | "Maple";
export const rooms: readonly Room[] = ["Cedar", "Maple"];

/** The default calendar day, used when a call omits `date`. */
export const DEFAULT_DATE = "2026-10-01";

/** One saved booking. `id` is opaque to callers; `seriesId` ties a weekly series. */
export type Booking = {
  readonly id: string;
  readonly title: string;
  readonly room: Room;
  readonly date: string;
  readonly start: number;
  readonly end: number;
  readonly seriesId?: string;
};

/** The input `bookBooking` takes; `room` is a plain string, `date` defaults. */
export type BookInput = {
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

/** The input `saveEdit` takes: an existing id plus the edited fields. */
export type EditInput = {
  readonly id: string;
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

/** The input `bookSeries` takes: one booking repeated weekly. */
export type SeriesInput = {
  readonly title: string;
  readonly room: string;
  readonly date: string;
  readonly start: number;
  readonly end: number;
  readonly weeks: number;
};

/** The saved bookings of this scope, ordered by date, then start, then creation. */
export const bookings: Data.Cell<readonly Booking[]> = data<readonly Booking[]>({
  label: "bookings",
  initial: [],
});

/** The single open edit draft, or `undefined` when nothing is being edited. */
export const editDraft: Data.Cell<Booking | undefined> = data<Booking | undefined>({
  label: "editDraft",
  initial: undefined,
});

/**
 * One snapshot of the saved bookings per passing change, newest last. Kept in a core
 * cell: it is app state, so it lives nowhere else. `undoChange` pops one entry.
 */
const history: Data.Cell<readonly (readonly Booking[])[]> = data<
  readonly (readonly Booking[])[]
>({
  label: "history",
  initial: [],
});

/** Record one undo step for the list as it was before a change. */
function pushHistory(
  store: Scope.DataController<readonly Booking[]>,
  historyStore: Scope.DataController<readonly (readonly Booking[])[]>,
): void {
  historyStore.set([...historyStore.get(), store.get()]);
}

/** A unique opaque id. Uses the platform UUID source so nothing lives outside cells. */
function nextId(): string {
  return globalThis.crypto.randomUUID();
}

/** Resolve a raw room string to a known room without a cast. */
function toRoom(value: string): Room | undefined {
  for (const candidate of rooms) {
    if (candidate === value) {
      return candidate;
    }
  }
  return undefined;
}

/** Check one time value against the 0..1439 integer rule. */
function checkTime(value: number): number {
  if (!Number.isInteger(value) || value < 0 || value > 1439) {
    throw badTime(value);
  }
  return value;
}

const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;

/** Check one calendar day against the real `YYYY-MM-DD` rule. */
function checkDate(value: unknown): string {
  if (typeof value !== "string") {
    throw badDate(value);
  }
  const match = DATE_PATTERN.exec(value);
  if (match === null) {
    throw badDate(value);
  }
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const probe = new Date(Date.UTC(year, month - 1, day));
  if (
    probe.getUTCFullYear() !== year ||
    probe.getUTCMonth() !== month - 1 ||
    probe.getUTCDate() !== day
  ) {
    throw badDate(value);
  }
  return value;
}

/** Move a valid `YYYY-MM-DD` day forward by whole days, keeping the same format. */
function addDays(date: string, days: number): string {
  const parts = date.split("-");
  const year = Number(parts[0]);
  const month = Number(parts[1]);
  const day = Number(parts[2]);
  const moved = new Date(Date.UTC(year, month - 1, day + days));
  const movedYear = String(moved.getUTCFullYear()).padStart(4, "0");
  const movedMonth = String(moved.getUTCMonth() + 1).padStart(2, "0");
  const movedDay = String(moved.getUTCDate()).padStart(2, "0");
  return `${movedYear}-${movedMonth}-${movedDay}`;
}

type ValidFields = {
  readonly title: string;
  readonly room: Room;
  readonly date: string;
  readonly start: number;
  readonly end: number;
};

/** Title, room, date, and time rules shared by booking, editing, and series. */
function validateFields(input: {
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
}): ValidFields {
  const title = typeof input.title === "string" ? input.title.trim() : "";
  if (title.length === 0) {
    throw blankTitle(title);
  }
  const room = toRoom(input.room);
  if (room === undefined) {
    throw unknownRoom(input.room);
  }
  const date = input.date === undefined ? DEFAULT_DATE : checkDate(input.date);
  const start = checkTime(input.start);
  const end = checkTime(input.end);
  if (end <= start) {
    throw emptySlot(start, end);
  }
  return { title, room, date, start, end };
}

function overlaps(
  aStart: number,
  aEnd: number,
  bStart: number,
  bEnd: number,
): boolean {
  return aStart < bEnd && bStart < aEnd;
}

/** True when an existing booking in the same room and date overlaps the slot. */
function hasConflict(
  list: readonly Booking[],
  room: Room,
  date: string,
  start: number,
  end: number,
  skipId?: string,
): boolean {
  return list.some(
    (booking) =>
      booking.id !== skipId &&
      booking.room === room &&
      booking.date === date &&
      overlaps(start, end, booking.start, booking.end),
  );
}

/** Stable sort by date, then start time; equal keys keep creation order. */
function sortBookings(list: readonly Booking[]): Booking[] {
  return [...list].sort((a, b) => {
    if (a.date !== b.date) {
      return a.date < b.date ? -1 : 1;
    }
    return a.start - b.start;
  });
}

function copyBooking(booking: Booking): Booking {
  const copy: Booking = {
    id: booking.id,
    title: booking.title,
    room: booking.room,
    date: booking.date,
    start: booking.start,
    end: booking.end,
  };
  if (booking.seriesId === undefined) {
    return copy;
  }
  return { ...copy, seriesId: booking.seriesId };
}

/** Create a booking when every rule passes; otherwise throw and change nothing. */
export const bookBooking: Operation.Handle<Booking, BookInput> = operation({
  label: "bookBooking",
  depends: { bookings: bookings.controller, history: history.controller },
  run: ({ bookings: store, history: historyStore }, ctx) => {
    const fields = validateFields(ctx.input);
    const existing = store.get();
    if (hasConflict(existing, fields.room, fields.date, fields.start, fields.end)) {
      throw clash(fields.room, fields.start, fields.end);
    }
    const booking: Booking = { id: nextId(), ...fields };
    pushHistory(store, historyStore);
    store.set(sortBookings([...existing, booking]));
    return booking;
  },
});

/** Cancel a booking by id; also closes its draft when it owns one. */
export const cancelBooking: Operation.Handle<void, { id: string }> = operation({
  label: "cancelBooking",
  depends: {
    bookings: bookings.controller,
    editDraft: editDraft.controller,
    history: history.controller,
  },
  run: ({ bookings: store, editDraft: draft, history: historyStore }, ctx) => {
    const { id } = ctx.input;
    const existing = store.get();
    if (!existing.some((booking) => booking.id === id)) {
      throw notFound(id);
    }
    pushHistory(store, historyStore);
    store.set(existing.filter((booking) => booking.id !== id));
    if (draft.get()?.id === id) {
      draft.set(undefined);
    }
  },
});

/** Open a copy of a saved booking as the one draft; unknown id reports NotFound. */
export const openEdit: Operation.Handle<Booking, { id: string }> = operation({
  label: "openEdit",
  depends: {
    bookings: bookings.controller,
    editDraft: editDraft.controller,
  },
  run: ({ bookings: store, editDraft: draft }, ctx) => {
    const found = store.get().find((booking) => booking.id === ctx.input.id);
    if (found === undefined) {
      throw notFound(ctx.input.id);
    }
    const copy = copyBooking(found);
    draft.set(copy);
    return copy;
  },
});

/** Save the open draft over its booking when every rule passes. */
export const saveEdit: Operation.Handle<Booking, EditInput> = operation({
  label: "saveEdit",
  depends: {
    bookings: bookings.controller,
    editDraft: editDraft.controller,
    history: history.controller,
  },
  run: ({ bookings: store, editDraft: draft, history: historyStore }, ctx) => {
    const { id } = ctx.input;
    const open = draft.get();
    if (open === undefined || open.id !== id) {
      throw notFound(id);
    }
    const existing = store.get();
    const index = existing.findIndex((booking) => booking.id === id);
    if (index < 0) {
      throw notFound(id);
    }
    const fields = validateFields(ctx.input);
    if (
      hasConflict(existing, fields.room, fields.date, fields.start, fields.end, id)
    ) {
      throw clash(fields.room, fields.start, fields.end);
    }
    const updated: Booking =
      open.seriesId === undefined
        ? { id, ...fields }
        : { id, ...fields, seriesId: open.seriesId };
    pushHistory(store, historyStore);
    store.set(
      sortBookings(
        existing.map((booking, at) => (at === index ? updated : booking)),
      ),
    );
    draft.set(undefined);
    return updated;
  },
});

/** Drop the open draft without touching the saved booking. */
export const discardEdit: Operation.Handle<void, { id: string }> = operation({
  label: "discardEdit",
  depends: { editDraft: editDraft.controller },
  run: ({ editDraft: draft }, ctx) => {
    const { id } = ctx.input;
    if (draft.get()?.id !== id) {
      throw notFound(id);
    }
    draft.set(undefined);
  },
});

/** Book one weekly series, or book none and report the first failure. */
export const bookSeries: Operation.Handle<readonly Booking[], SeriesInput> = operation({
  label: "bookSeries",
  depends: { bookings: bookings.controller, history: history.controller },
  run: ({ bookings: store, history: historyStore }, ctx) => {
    const input = ctx.input;
    if (!Number.isInteger(input.weeks) || input.weeks < 1 || input.weeks > 12) {
      throw badCount(input.weeks);
    }
    const fields = validateFields(input);
    const dates: string[] = [];
    for (let week = 0; week < input.weeks; week += 1) {
      dates.push(addDays(fields.date, week * 7));
    }
    const existing = store.get();
    for (const date of dates) {
      if (hasConflict(existing, fields.room, date, fields.start, fields.end)) {
        throw clash(fields.room, fields.start, fields.end);
      }
    }
    const seriesId = nextId();
    const created: Booking[] = dates.map((date) => ({
      id: nextId(),
      title: fields.title,
      room: fields.room,
      date,
      start: fields.start,
      end: fields.end,
      seriesId,
    }));
    pushHistory(store, historyStore);
    store.set(sortBookings([...existing, ...created]));
    return created;
  },
});

/** Cancel every occurrence of one series; unknown series id reports NotFound. */
export const cancelSeries: Operation.Handle<void, { seriesId: string }> = operation({
  label: "cancelSeries",
  depends: {
    bookings: bookings.controller,
    editDraft: editDraft.controller,
    history: history.controller,
  },
  run: ({ bookings: store, editDraft: draft, history: historyStore }, ctx) => {
    const { seriesId } = ctx.input;
    const existing = store.get();
    const removed = existing.filter((booking) => booking.seriesId === seriesId);
    if (removed.length === 0) {
      throw notFound(seriesId);
    }
    pushHistory(store, historyStore);
    store.set(existing.filter((booking) => booking.seriesId !== seriesId));
    const open = draft.get();
    if (open !== undefined && removed.some((booking) => booking.id === open.id)) {
      draft.set(undefined);
    }
  },
});

/**
 * Reverse the last passing booking change in one step, restoring the exact prior list.
 * Restores booking data only: drafts, form text, and filters are never touched.
 */
export const undoChange: Operation.Handle<void, void> = operation({
  label: "undoChange",
  depends: {
    bookings: bookings.controller,
    history: history.controller,
  },
  run: ({ bookings: store, history: historyStore }) => {
    const steps = historyStore.get();
    if (steps.length === 0) {
      throw emptyUndo();
    }
    const restored = steps[steps.length - 1];
    store.set(restored);
    historyStore.set(steps.slice(0, -1));
  },
});

