/** Format minutes since midnight as the 24-hour `HH:MM` the inputs show. */
export function formatClock(minute: number): string {
  const hour = Math.floor(minute / 60)
    .toString()
    .padStart(2, "0");
  const rest = (minute % 60).toString().padStart(2, "0");
  return `${hour}:${rest}`;
}

/** Parse one `HH:MM` field into minutes; any other text reports `BadTime` carrying it. */
function requireClock(value: string): number {
  const match = /^(\d{1,2}):(\d{2})$/.exec(value.trim());
  if (!match) {
    throw appError("BadTime", { value });
  }
  const hour = Number(match[1]);
  const minute = Number(match[2]);
  if (hour > 23 || minute > 59) {
    throw appError("BadTime", { value });
  }
  return hour * 60 + minute;
}

/** Parse the repeat count field; text that is no number reports `BadCount` carrying it. */
function requireCount(value: string): number {
  const count = Number(value);
  if (value.trim() === "" || Number.isNaN(count)) {
    throw appError("BadCount", { weeks: value });
  }
  return count;
}

/** Apply one keystroke to a form's texts; a field name the form does not know is dropped. */
function withBookText(previous: BookText, write: TextWrite): BookText {
  return Object.hasOwn(previous, write.field)
    ? { ...previous, [write.field]: write.value }
    : previous;
}

/** Apply one keystroke to the draft's texts; a field name the form does not know is dropped. */
function withEditText(previous: EditText, write: TextWrite): EditText {
  return Object.hasOwn(previous, write.field)
    ? { ...previous, [write.field]: write.value }
    : previous;
}

/** The draft's texts as the open draft shows them: times formatted, the rest as saved. */
function editTextOf(booking: Booking): EditText {
  return {
    id: booking.id,
    title: booking.title,
    room: booking.room,
    date: booking.date,
    start: formatClock(booking.start),
    end: formatClock(booking.end),
  };
}

/** Shape one keystroke at the boundary into its field name and text. */
function shapeWrite(raw: unknown): TextWrite {
  return { field: text(field(raw, "field")), value: text(field(raw, "value")) };
}

/** Shape one filter click at the boundary into its filter name. */
function shapeFilter(raw: unknown): { value: string } {
  return { value: text(field(raw, "value")) };
}

/** Shape one id call at the boundary; a non-string id reads as absent. */
function shapeId(raw: unknown): { id: string } {
  return { id: requireId(raw) };
}

/** Shape one series id call at the boundary; a non-string id reads as absent. */
function shapeSeriesId(raw: unknown): { seriesId: string } {
  return { seriesId: requireSeriesId(raw) };
}

/** Shape one series-title keystroke at the boundary into its text. */
function shapeTitleValue(raw: unknown): { value: string } {
  return { value: text(field(raw, "value")) };
}

/** The registry kind of a failed series rename: `BlankTitle` or `NotFound`, or `undefined` to rethrow. */
function renameFailure(caught: unknown): Errors.Name | undefined {
  if (isError(caught, "BlankTitle")) return caught.kind;
  if (isError(caught, "NotFound")) return caught.kind;
  return undefined;
}

/** The registry kind of a failed book check, or `undefined` for a value the screen rethrows. */
function bookingFailure(caught: unknown): Errors.Name | undefined {
  if (isError(caught, "BlankTitle")) return caught.kind;
  if (isError(caught, "UnknownRoom")) return caught.kind;
  if (isError(caught, "BadTime")) return caught.kind;
  if (isError(caught, "BadDate")) return caught.kind;
  if (isError(caught, "EmptySlot")) return caught.kind;
  if (isError(caught, "Clash")) return caught.kind;
  return undefined;
}

/** The registry kind of a failed series book: book failures plus `BadCount`. */
function seriesFailure(caught: unknown): Errors.Name | undefined {
  const kind = bookingFailure(caught);
  return kind ?? (isError(caught, "BadCount") ? caught.kind : undefined);
}

/** The registry kind of a failed save: book failures plus `NotFound`. */
function saveFailure(caught: unknown): Errors.Name | undefined {
  const kind = bookingFailure(caught);
  return kind ?? (isError(caught, "NotFound") ? caught.kind : undefined);
}

/** The registry kind of a missing draft or id: `NotFound`, or `undefined` to rethrow. */
function goneFailure(caught: unknown): Errors.Name | undefined {
  return isError(caught, "NotFound") ? caught.kind : undefined;
}

/** The registry kind of an exhausted undo: `EmptyUndo`, or `undefined` to rethrow. */
function undoFailure(caught: unknown): Errors.Name | undefined {
  return isError(caught, "EmptyUndo") ? caught.kind : undefined;
}

