/** Save the open draft: on success it clears the draft and shows the saved row. */
export const submitSave: Operation.Handle<void, { id: string }> = operation({
  label: "submitSave",
  input: shapeId,
  depends: {
    text: editText.controller,
    notice: notice.controller,
    save: saveEdit,
  },
  run(deps, ctx): void {
    try {
      const form = deps.text.get();
      if (form === undefined || form.id !== ctx.input.id) {
        throw appError("NotFound", { id: ctx.input.id });
      }
      deps.save.run({
        input: {
          id: form.id,
          title: form.title,
          room: form.room,
          date: form.date,
          start: requireClock(form.start),
          end: requireClock(form.end),
        },
      });
      deps.text.set(undefined);
      deps.notice.set(undefined);
    } catch (caught) {
      const kind = saveFailure(caught);
      if (kind === undefined) throw caught;
      deps.notice.set(kind);
    }
  },
});

