/** Cancel one row and free its slot, closing its draft when the row carried one. */
export const submitCancel: Operation.Handle<void, { id: string }> = operation({
  label: "submitCancel",
  input: shapeId,
  depends: {
    list: bookings.controller,
    text: editText.controller,
    notice: notice.controller,
    cancel: cancelBooking,
  },
  run(deps, ctx): void {
    try {
      deps.cancel.run({ input: { id: ctx.input.id } });
      const form = deps.text.get();
      const stillSaved = deps.list
        .get()
        .some((booking) => booking.id === form?.id);
      if (form !== undefined && !stillSaved) {
        deps.text.set(undefined);
      }
      deps.notice.set(undefined);
    } catch (caught) {
      const kind = goneFailure(caught);
      if (kind === undefined) throw caught;
      deps.notice.set(kind);
    }
  },
});

