import { createScope } from "@tinker/core";
import { describe, expect, it } from "vitest";
import {
  bookBooking,
  bookings,
  cancelBooking,
  discardEdit,
  editDraft,
  isError,
  openEdit,
  saveEdit,
} from "../src/index.ts";

function capture(action: () => unknown): unknown {
  try {
    action();
    return undefined;
  } catch (error) {
    return error;
  }
}

describe("openEdit", () => {
  it("returns a copy: editing it never changes the saved booking", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const draft = scope.run(openEdit, { input: { id: saved.id } });
    expect(draft).toEqual(saved);
    expect(draft).not.toBe(saved);
    Object.assign(draft, { title: "Planning" });
    const list = scope.resolve(bookings);
    expect(list[0]?.title).toBe("Standup");
  });

  it("reports NotFound for an unknown id", () => {
    const scope = createScope();
    const error = capture(() =>
      scope.run(openEdit, { input: { id: "nope" } }),
    );
    expect(isError(error, "NotFound")).toBe(true);
    if (isError(error, "NotFound")) {
      expect(error.payload.id).toBe("nope");
    }
  });

  it("keeps only one draft: opening a second id closes the first", () => {
    const scope = createScope();
    const first = scope.run(bookBooking, {
      input: { title: "First", room: "Cedar", start: 540, end: 600 },
    });
    const second = scope.run(bookBooking, {
      input: { title: "Second", room: "Maple", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: first.id } });
    scope.run(openEdit, { input: { id: second.id } });
    expect(scope.resolve(editDraft)?.id).toBe(second.id);
    const error = capture(() =>
      scope.run(discardEdit, { input: { id: first.id } }),
    );
    expect(isError(error, "NotFound")).toBe(true);
    scope.run(discardEdit, { input: { id: second.id } });
  });
});

describe("discardEdit", () => {
  it("drops the draft and leaves the booking unchanged", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    scope.run(discardEdit, { input: { id: saved.id } });
    expect(scope.resolve(editDraft)).toBeUndefined();
    expect(scope.resolve(bookings)).toEqual([saved]);
    const closed = capture(() =>
      scope.run(discardEdit, { input: { id: saved.id } }),
    );
    expect(isError(closed, "NotFound")).toBe(true);
    if (isError(closed, "NotFound")) {
      expect(closed.payload.id).toBe(saved.id);
    }
  });

  it("reports NotFound for an unknown id", () => {
    const scope = createScope();
    const error = capture(() =>
      scope.run(discardEdit, { input: { id: "nope" } }),
    );
    expect(isError(error, "NotFound")).toBe(true);
    if (isError(error, "NotFound")) {
      expect(error.payload.id).toBe("nope");
    }
  });
});

describe("saveEdit", () => {
  it("replaces the booking and closes the draft", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const updated = scope.run(saveEdit, {
      input: {
        id: saved.id,
        title: "  Planning  ",
        room: "Maple",
        start: 600,
        end: 660,
      },
    });
    expect(updated).toEqual({
      id: saved.id,
      title: "Planning",
      room: "Maple",
      date: "2026-10-01",
      start: 600,
      end: 660,
    });
    expect(scope.resolve(bookings)).toEqual([updated]);
    expect(scope.resolve(editDraft)).toBeUndefined();
  });

  it("passes a save that keeps the edited booking's own slot", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const updated = scope.run(saveEdit, {
      input: {
        id: saved.id,
        title: "Standup",
        room: "Cedar",
        start: 540,
        end: 600,
      },
    });
    expect(scope.resolve(bookings)).toEqual([updated]);
  });

  it("re-sorts the list after a save moves a booking", () => {
    const scope = createScope();
    const early = scope.run(bookBooking, {
      input: { title: "Early", room: "Cedar", start: 540, end: 600 },
    });
    const late = scope.run(bookBooking, {
      input: { title: "Late", room: "Cedar", start: 600, end: 660 },
    });
    scope.run(openEdit, { input: { id: late.id } });
    const moved = scope.run(saveEdit, {
      input: { id: late.id, title: "Late", room: "Cedar", start: 480, end: 540 },
    });
    expect(scope.resolve(bookings)).toEqual([moved, early]);
  });

  it("reports Clash and keeps the saved booking and the draft", () => {
    const scope = createScope();
    const holder = scope.run(bookBooking, {
      input: { title: "Holder", room: "Cedar", start: 540, end: 600 },
    });
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Maple", start: 600, end: 660 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const error = capture(() =>
      scope.run(saveEdit, {
        input: {
          id: saved.id,
          title: "Standup",
          room: "Cedar",
          start: 550,
          end: 590,
        },
      }),
    );
    expect(isError(error, "Clash")).toBe(true);
    if (isError(error, "Clash")) {
      expect(error.payload).toEqual({ room: "Cedar", start: 550, end: 590 });
    }
    expect(scope.resolve(bookings)).toEqual([holder, saved]);
    expect(scope.resolve(editDraft)?.id).toBe(saved.id);
    const retry = scope.run(saveEdit, {
      input: {
        id: saved.id,
        title: "Renamed",
        room: "Maple",
        start: 600,
        end: 660,
      },
    });
    expect(retry.title).toBe("Renamed");
  });

  it("keeps the draft open on a validation failure", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const blank = capture(() =>
      scope.run(saveEdit, {
        input: { id: saved.id, title: "  ", room: "Cedar", start: 540, end: 600 },
      }),
    );
    expect(isError(blank, "BlankTitle")).toBe(true);
    const badRoom = capture(() =>
      scope.run(saveEdit, {
        input: { id: saved.id, title: "X", room: "Attic", start: 540, end: 600 },
      }),
    );
    expect(isError(badRoom, "UnknownRoom")).toBe(true);
    const badTime = capture(() =>
      scope.run(saveEdit, {
        input: { id: saved.id, title: "X", room: "Cedar", start: 99.5, end: 600 },
      }),
    );
    expect(isError(badTime, "BadTime")).toBe(true);
    const empty = capture(() =>
      scope.run(saveEdit, {
        input: { id: saved.id, title: "X", room: "Cedar", start: 600, end: 540 },
      }),
    );
    expect(isError(empty, "EmptySlot")).toBe(true);
    expect(scope.resolve(bookings)).toEqual([saved]);
    expect(scope.resolve(editDraft)?.id).toBe(saved.id);
  });

  it("reports NotFound for a closed or missing draft", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const closed = capture(() =>
      scope.run(saveEdit, {
        input: { id: saved.id, title: "X", room: "Cedar", start: 540, end: 600 },
      }),
    );
    expect(isError(closed, "NotFound")).toBe(true);
    if (isError(closed, "NotFound")) {
      expect(closed.payload.id).toBe(saved.id);
    }
    const missing = capture(() =>
      scope.run(saveEdit, {
        input: { id: "nope", title: "X", room: "Cedar", start: 540, end: 600 },
      }),
    );
    expect(isError(missing, "NotFound")).toBe(true);
    if (isError(missing, "NotFound")) {
      expect(missing.payload.id).toBe("nope");
    }
  });

  it("reports NotFound after canceling the drafted booking", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    scope.run(cancelBooking, { input: { id: saved.id } });
    expect(scope.resolve(editDraft)).toBeUndefined();
    const error = capture(() =>
      scope.run(saveEdit, {
        input: { id: saved.id, title: "X", room: "Cedar", start: 540, end: 600 },
      }),
    );
    expect(isError(error, "NotFound")).toBe(true);
    const gone = capture(() =>
      scope.run(discardEdit, { input: { id: saved.id } }),
    );
    expect(isError(gone, "NotFound")).toBe(true);
  });
});

describe("drafts never block or leak", () => {
  it("blocks nothing while a draft is open: other bookings still book", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const other = scope.run(bookBooking, {
      input: { title: "Other", room: "Cedar", start: 600, end: 660 },
    });
    const moved = scope.run(bookBooking, {
      input: { title: "Moved", room: "Maple", start: 540, end: 600 },
    });
    expect(scope.resolve(bookings)).toEqual([saved, other, moved].sort(
      (a, b) => a.start - b.start,
    ));
  });

  it("never changes the list from unsaved draft text", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const draft = scope.run(openEdit, { input: { id: saved.id } });
    Object.assign(draft, { title: "Planning", start: 1, end: 2 });
    expect(scope.resolve(bookings)).toEqual([saved]);
  });
});

import { fileURLToPath } from "node:url";
import { afterAll, assert, beforeAll, beforeEach, expect, it } from "vitest";
import { chromium, type Browser, type Locator, type Page } from "playwright";
import { createServer, type ViteDevServer } from "vite";

const root = fileURLToPath(new URL("..", import.meta.url));

let server: ViteDevServer;
let browser: Browser;
let page: Page;
let base: string;

/** Every locator the tests reach for on one mounted desk. */
function view(at: Page | Locator) {
  return {
    stock: at.getByRole("table", { name: "Stock" }),
    moves: at.getByRole("table", { name: "Moves" }),
    item: at.getByLabel("Item", { exact: true }),
    from: at.getByLabel("From", { exact: true }),
    to: at.getByLabel("To", { exact: true }),
    quantity: at.getByLabel("Quantity", { exact: true }),
    editItem: at.getByLabel("Edit item", { exact: true }),
    editFrom: at.getByLabel("Edit from", { exact: true }),
    editTo: at.getByLabel("Edit to", { exact: true }),
    editQuantity: at.getByLabel("Edit quantity", { exact: true }),
    move: at.getByRole("button", { name: "Move stock", exact: true }),
    save: at.getByRole("button", { name: "Save move", exact: true }),
    discard: at.getByRole("button", { name: "Discard move", exact: true }),
    undo: at.getByRole("button", { name: "Undo", exact: true }),
    all: at.getByRole("button", { name: "All", exact: true }),
    cable: at.getByRole("button", { name: "Cable", exact: true }),
    stand: at.getByRole("button", { name: "Stand", exact: true }),
    editButtons: at.getByRole("button", { name: "Edit move", exact: true }),
    alert: at.getByRole("alert"),
  };
}

function stockRow(at: Page | Locator, name: string): Locator {
  return view(at).stock.getByRole("row", { name, exact: true });
}

function moveRow(at: Page | Locator, name: string): Locator {
  return view(at).moves.getByRole("row", { name, exact: true });
}

/** Read the shared alert once it is on screen; the kind is all it ever shows. */
async function alertText(at: Page | Locator): Promise<string> {
  const alert = view(at).alert;
  await alert.waitFor();
  return (await alert.textContent()) ?? "";
}

/** Fill and submit the new-move form: repeated setup for the cases that need a saved move. */
async function submitMove(at: Page | Locator, item: string, quantity: string): Promise<void> {
  const desk = view(at);
  await desk.item.fill(item);
  await desk.quantity.fill(quantity);
  await desk.move.click();
}

beforeAll(async () => {
  server = await createServer({
    root,
    cacheDir: `${root}.vite`,
    logLevel: "silent",
    server: { host: "127.0.0.1", port: 0 },
