import { useState } from "react";
import type { FormEvent, ReactElement } from "react";
import { createScope } from "@tinker/core";
import { ScopeProvider, useData, useRun } from "@tinker/react";
import {
  bookBooking,
  bookSeries,
  bookings,
  cancelBooking,
  cancelSeries,
  discardEdit,
  editDraft,
  openEdit,
  saveEdit,
  undoChange,
} from "./bookings.ts";
import type { Booking, Room } from "./bookings.ts";
import { errorKind } from "./errors.ts";

type Filter = "All" | Room;

const filters: readonly Filter[] = ["All", "Cedar", "Maple"];

const defaultDate = "2026-10-01";

/** Parse a 24-hour `HH:MM` string into minutes since midnight. */
function toMinute(raw: string): number | undefined {
  const match = /^(\d{1,2}):(\d{2})$/.exec(raw.trim());
  if (match === null) return undefined;
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (hours > 23 || minutes > 59) return undefined;
  return hours * 60 + minutes;
}

/** Render minutes since midnight as `HH:MM`. */
function timeLabel(minute: number): string {
  const hours = String(Math.floor(minute / 60)).padStart(2, "0");
  const minutes = String(minute % 60).padStart(2, "0");
  return `${hours}:${minutes}`;
}

function visible(list: readonly Booking[], filter: Filter): readonly Booking[] {
  if (filter === "All") return list;
  return list.filter((booked) => booked.room === filter);
}

/** The kind of a registry error, for the alert block. */
function kindOf(error: unknown): string {
  return errorKind(error) ?? "Unknown";
}

function Row(props: {
  readonly booked: Booking;
  readonly onCancel: (id: string) => void;
  readonly onEdit: (id: string) => void;
  readonly onCancelSeries: (seriesId: string) => void;
}): ReactElement {
  const { booked, onCancel, onEdit, onCancelSeries } = props;
  const { seriesId } = booked;
  return (
    <li>
      <span>{booked.title}</span>
      <span>{booked.room}</span>
      <span>{booked.date}</span>
      <span>
        {timeLabel(booked.start)}–{timeLabel(booked.end)}
      </span>
      <button type="button" aria-label={`Cancel ${booked.title}`} onClick={() => onCancel(booked.id)}>
        Cancel
      </button>
      <button type="button" aria-label={`Edit ${booked.title}`} onClick={() => onEdit(booked.id)}>
        Edit
      </button>
      {seriesId !== undefined ? (
        <button type="button" onClick={() => onCancelSeries(seriesId)}>
          Cancel series
        </button>
      ) : undefined}
    </li>
  );
}

/** The open draft's editor. Remounts per drafted id, so the fields seed once
 * from the copy; a failed save keeps the draft open and the fields as typed. */
function DraftEditor(props: {
  readonly draft: Booking;
  readonly onSave: (input: {
    readonly id: string;
    readonly title: string;
    readonly room: string;
    readonly date: string;
    readonly start: number;
    readonly end: number;
  }) => void;
  readonly onDiscard: (id: string) => void;
}): ReactElement {
  const { draft, onSave, onDiscard } = props;
  const [title, setTitle] = useState(draft.title);
  const [room, setRoom] = useState<string>(draft.room);
  const [date, setDate] = useState(draft.date);
  const [start, setStart] = useState(timeLabel(draft.start));
  const [end, setEnd] = useState(timeLabel(draft.end));

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const startMinute = toMinute(start);
    const endMinute = toMinute(end);
    if (startMinute === undefined || endMinute === undefined) {
      onSave({ id: draft.id, title, room, date, start: -1, end: -1 });
      return;
    }
    onSave({ id: draft.id, title, room, date, start: startMinute, end: endMinute });
  };

  return (
    <form onSubmit={submit}>
      <label>
        Edit title
        <input name="Edit title" value={title} onChange={(event) => setTitle(event.target.value)} />
      </label>
      <label>
        Edit room
        <input name="Edit room" value={room} onChange={(event) => setRoom(event.target.value)} />
      </label>
      <label>
        Edit date
        <input name="Edit date" value={date} onChange={(event) => setDate(event.target.value)} />
      </label>
      <label>
        Edit start time
        <input
          name="Edit start time"
          placeholder="09:00"
          value={start}
          onChange={(event) => setStart(event.target.value)}
        />
      </label>
      <label>
        Edit end time
        <input
          name="Edit end time"
          placeholder="10:00"
          value={end}
          onChange={(event) => setEnd(event.target.value)}
        />
      </label>
      <button type="submit">Save</button>
      <button type="button" onClick={() => onDiscard(draft.id)}>
        Discard
      </button>
    </form>
  );
}

function BookingScreen(): ReactElement {
  const list = useData(bookings);
  const draft = useData(editDraft);
  const [filter, setFilter] = useState<Filter>("All");
  const [title, setTitle] = useState("");
  const [room, setRoom] = useState("Cedar");
  const [date, setDate] = useState(defaultDate);
  const [start, setStart] = useState("09:00");
  const [end, setEnd] = useState("10:00");
  const [weeks, setWeeks] = useState("1");
  const [kind, setKind] = useState<string | undefined>(undefined);

  const book = useRun(bookBooking, {
    onSuccess: () => {
      setTitle("");
      setKind(undefined);
    },
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const series = useRun(bookSeries, {
    onSuccess: () => {
      setTitle("");
      setKind(undefined);
    },
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const cancel = useRun(cancelBooking, {
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const cancelWholeSeries = useRun(cancelSeries, {
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const open = useRun(openEdit, {
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const save = useRun(saveEdit, {
    onSuccess: () => {
      setKind(undefined);
    },
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const undo = useRun(undoChange, {
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const discard = useRun(discardEdit, {
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const startMinute = toMinute(start);
    const endMinute = toMinute(end);
    if (startMinute === undefined || endMinute === undefined) {
      setKind("BadTime");
      return;
    }
    book.run({ input: { title, room, date, start: startMinute, end: endMinute } });
  };

  const submitSeries = () => {
    const startMinute = toMinute(start);
    const endMinute = toMinute(end);
    if (startMinute === undefined || endMinute === undefined) {
      setKind("BadTime");
      return;
    }
    series.run({ input: { title, room, date, start: startMinute, end: endMinute, weeks: Number(weeks) } });
  };

  const saveDraft = (input: {
    readonly id: string;
    readonly title: string;
    readonly room: string;
    readonly date: string;
    readonly start: number;
    readonly end: number;
  }) => {
    if (input.start < 0 || input.end < 0) {
      setKind("BadTime");
      return;
    }
    save.run({ input });
  };

  return (
    <main>
      <form onSubmit={submit}>
        <label>
          Title
          <input name="Title" value={title} onChange={(event) => setTitle(event.target.value)} />
        </label>
        <label>
          Room
          <input name="Room" value={room} onChange={(event) => setRoom(event.target.value)} />
        </label>
        <label>
          Date
          <input name="Date" value={date} onChange={(event) => setDate(event.target.value)} />
        </label>
        <label>
          Start time
          <input
            name="Start time"
            placeholder="09:00"
            value={start}
            onChange={(event) => setStart(event.target.value)}
          />
        </label>
        <label>
          End time
          <input
            name="End time"
            placeholder="10:00"
            value={end}
            onChange={(event) => setEnd(event.target.value)}
          />
        </label>
        <label>
          Weeks
          <input name="Weeks" value={weeks} onChange={(event) => setWeeks(event.target.value)} />
        </label>
        <button type="submit">Book</button>
        <button type="button" onClick={() => submitSeries()}>
          Book series
        </button>
        <button type="button" onClick={() => undo.run()}>
          Undo
        </button>
        {kind !== undefined ? <div role="alert">{kind}</div> : undefined}
      </form>
      {draft !== undefined ? (
        <DraftEditor draft={draft} onSave={saveDraft} onDiscard={(id) => discard.run({ input: { id } })} />
      ) : undefined}
      <div>
        {filters.map((each) => (
          <button key={each} type="button" aria-pressed={filter === each} onClick={() => setFilter(each)}>
            {each}
          </button>
        ))}
      </div>
      <ul>
        {visible(list, filter).map((booked) => (
          <Row
            key={booked.id}
            booked={booked}
            onCancel={(id) => cancel.run({ input: { id } })}
            onEdit={(id) => open.run({ input: { id } })}
            onCancelSeries={(seriesId) => cancelWholeSeries.run({ input: { seriesId } })}
          />
        ))}
      </ul>
    </main>
  );
}

/** One mounted app owns one scope; two roots share nothing. */
export function BookingApp(): ReactElement {
  return (
    <ScopeProvider create={() => createScope()}>
      <BookingScreen />
    </ScopeProvider>
  );
}

