const filters: readonly ("All" | Room)[] = ["All", "Cedar", "Maple"];

/** The rows the current filter shows; filtering hides rows, it never deletes. */
function visible(list: readonly Booking[], filter: Room | "All"): readonly Booking[] {
  if (filter === "All") return list;
  return list.filter((booked) => booked.room === filter);
}

/** One booking row: its title, room, date, and time, with its cancel and edit
 * buttons and, for a series occurrence, cancel-series and rename-series
 * buttons. */
function Row(props: {
  readonly booked: Booking;
  readonly onCancel: (id: string) => void;
  readonly onEdit: (id: string) => void;
  readonly onCancelSeries: (seriesId: string) => void;
  readonly onRenameSeries: (id: string) => void;
}): ReactElement {
  const { booked, onCancel, onEdit, onCancelSeries, onRenameSeries } = props;
  const { seriesId } = booked;
  return (
    <li>
      <span>{booked.title}</span>
      <span>{booked.room}</span>
      <span>{booked.date}</span>
      <span>
        {timeLabel(booked.start)}–{timeLabel(booked.end)}
      </span>
      <button type="button" aria-label={`Cancel ${booked.title}`} onClick={() => onCancel(booked.id)}>
        Cancel
      </button>
      <button type="button" aria-label={`Edit ${booked.title}`} onClick={() => onEdit(booked.id)}>
        Edit
      </button>
      {seriesId !== undefined ? (
        <>
          <button type="button" onClick={() => onCancelSeries(seriesId)}>
            Cancel series
          </button>
          <button
            type="button"
            aria-label={`Rename series ${booked.title}`}
            onClick={() => onRenameSeries(booked.id)}
          >
            Rename series
          </button>
        </>
      ) : undefined}
    </li>
  );
}

/** The open draft's editor. Every field reads and writes the `editForm` cell,
 * so the fields always show the drafted booking's current text: opening another
 * booking replaces the text, and a failed save keeps it as typed. */
function DraftEditor(props: { readonly draft: EditFormText }): ReactElement {
  const { draft } = props;
  const type = useRun(typeEditField);
  const save = useRun(submitSave);
  const discard = useRun(submitDiscard);
  return (
    <form
      onSubmit={(event: FormEvent<HTMLFormElement>) => {
        event.preventDefault();
        save.run();
      }}
    >
      <label>
        Edit title
        <input
          name="Edit title"
          value={draft.title}
          onChange={(event) => type.run({ input: { field: "title", value: event.target.value } })}
        />
      </label>
      <label>
        Edit room
        <input
          name="Edit room"
          value={draft.room}
          onChange={(event) => type.run({ input: { field: "room", value: event.target.value } })}
        />
      </label>
      <label>
        Edit date
        <input
          name="Edit date"
          value={draft.date}
          onChange={(event) => type.run({ input: { field: "date", value: event.target.value } })}
        />
      </label>
      <label>
        Edit start time
        <input
          name="Edit start time"
          placeholder="09:00"
          value={draft.start}
          onChange={(event) => type.run({ input: { field: "start", value: event.target.value } })}
        />
      </label>
      <label>
        Edit end time
        <input
          name="Edit end time"
          placeholder="10:00"
          value={draft.end}
          onChange={(event) => type.run({ input: { field: "end", value: event.target.value } })}
        />
      </label>
      <button type="submit">Save</button>
      <button type="button" onClick={() => discard.run({ input: { id: draft.id } })}>
        Discard
