            name="Room"
            value={form.room}
            onChange={(event) => type.run({ input: { field: "room", value: event.target.value } })}
          />
        </label>
        <label>
          Date
          <input
            name="Date"
            value={form.date}
            onChange={(event) => type.run({ input: { field: "date", value: event.target.value } })}
          />
        </label>
        <label>
          Start time
          <input
            name="Start time"
            placeholder="09:00"
            value={form.start}
            onChange={(event) => type.run({ input: { field: "start", value: event.target.value } })}
          />
        </label>
        <label>
          End time
          <input
            name="End time"
            placeholder="10:00"
            value={form.end}
            onChange={(event) => type.run({ input: { field: "end", value: event.target.value } })}
          />
        </label>
        <label>
          Weeks
          <input
            name="Weeks"
            value={form.weeks}
            onChange={(event) => type.run({ input: { field: "weeks", value: event.target.value } })}
          />
        </label>
        <button type="submit">Book</button>
        <button type="button" onClick={() => series.run()}>
          Book series
