import type { Item, Place } from "./model.ts";

/** Every failure this app can produce, with the payload each kind carries. */
type Payloads = {
  /** An item name that is not one of the `items`. */
  UnknownItem: { item: unknown };
  /** A place name that is not one of the `places`. */
  UnknownPlace: { place: unknown };
  /** A move whose two places are the same one. */
  SamePlace: { place: string };
  /** A quantity that is not a positive safe integer. */
  BadQuantity: { quantity: unknown };
  /** A move larger than the stock standing in its source row. */
  ShortStock: { item: Item; place: Place; available: number; requested: number };
  /** A move id with no open draft or saved move. */
  NotFound: { id: string };
  /** An undo requested with no history left. */
  EmptyUndo: {};
};

/** The app error registry: names, payloads, and the typed error value each name carries. */
export declare namespace Errors {
  /** Every app error name. */
  type Name = keyof Payloads;
  /** The payload carried by one error name. */
  type Payload<N extends Name> = Payloads[N];
  /** An app error: identified by `kind`, carrying a typed `payload`. */
  type Of<N extends Name = Name> = Error & {
    readonly kind: N;
    readonly payload: Payloads[N];
  };
}

/** Every app error name, in registry order. */
const names: readonly Errors.Name[] = [
  "UnknownItem",
  "UnknownPlace",
  "SamePlace",
  "BadQuantity",
  "ShortStock",
  "NotFound",
  "EmptyUndo",
];

/** Raise the one registry error for `kind`; the only place the app creates a failure. */
export function raise<N extends Errors.Name>(kind: N, payload: Errors.Payload<N>): never {
  throw Object.assign(new Error(kind), { kind, payload });
}

/** Narrow an unknown thrown value to one registry entry; callers rethrow on mismatch. */
export function isError<N extends Errors.Name>(value: unknown, kind: N): value is Errors.Of<N> {
  return value instanceof Error && "kind" in value && value.kind === kind;
}

/** Narrow a thrown value to any registry entry, or `undefined` when it is not one of ours. */
export function managed(value: unknown): Errors.Of | undefined {
  for (const name of names) {
    if (isError(value, name)) return value;
  }
  return undefined;
}

