import { createScope } from "@tinker/core";
import { describe, expect, it } from "vitest";
import {
  bookBooking,
  bookSeries,
  bookings,
  cancelBooking,
  cancelSeries,
  editDraft,
  isError,
  openEdit,
  saveEdit,
  undoChange,
} from "../src/index.ts";

function capture(action: () => unknown): unknown {
  try {
    action();
    return undefined;
  } catch (error) {
    return error;
  }
}

describe("undoChange", () => {
  it("reverses one book per undo and reports EmptyUndo when none is left", () => {
    const scope = createScope();
    const a = scope.run(bookBooking, {
      input: { title: "A", room: "Cedar", start: 540, end: 600 },
    });
    const b = scope.run(bookBooking, {
      input: { title: "B", room: "Cedar", start: 600, end: 660 },
    });
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([a]);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([]);
    const error = capture(() => scope.run(undoChange, {}));
    if (!isError(error, "EmptyUndo")) {
      expect.fail("expected EmptyUndo");
    }
    expect(error.payload).toEqual({});
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("reports EmptyUndo on a fresh scope", () => {
    const scope = createScope();
    const error = capture(() => scope.run(undoChange, {}));
    if (!isError(error, "EmptyUndo")) {
      expect.fail("expected EmptyUndo");
    }
    expect(error.payload).toEqual({});
  });

  it("keeps stacking after an undo: a new change is its own step", () => {
    const scope = createScope();
    const a = scope.run(bookBooking, {
      input: { title: "A", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(bookBooking, {
      input: { title: "B", room: "Cedar", start: 600, end: 660 },
    });
    scope.run(undoChange, {});
    const c = scope.run(bookBooking, {
      input: { title: "C", room: "Maple", start: 540, end: 600 },
    });
    expect(scope.resolve(bookings)).toEqual([a, c]);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([a]);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("restores an edited booking exactly", () => {
    const scope = createScope();
    const a = scope.run(bookBooking, {
      input: { title: "A", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: a.id } });
    scope.run(saveEdit, {
      input: {
        id: a.id,
        title: "A2",
        room: "Maple",
        date: "2026-10-02",
        start: 60,
        end: 120,
      },
    });
    expect(scope.resolve(bookings)[0].title).toBe("A2");
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([a]);
  });

  it("restores one series edit without losing the series", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "A",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 2,
      },
    });
    scope.run(openEdit, { input: { id: made[0].id } });
    scope.run(saveEdit, {
      input: {
        id: made[0].id,
        title: "A2",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
      },
    });
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual(made);
  });

  it("undoes a whole series book in one step", () => {
    const scope = createScope();
    scope.run(bookSeries, {
      input: {
        title: "A",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    expect(scope.resolve(bookings)).toHaveLength(3);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([]);
    const error = capture(() => scope.run(undoChange, {}));
    if (!isError(error, "EmptyUndo")) {
      expect.fail("expected EmptyUndo");
    }
    expect(error.payload).toEqual({});
  });

  it("undoes a one-off cancel and brings the booking back", () => {
    const scope = createScope();
    const a = scope.run(bookBooking, {
      input: { title: "A", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(cancelBooking, { input: { id: a.id } });
    expect(scope.resolve(bookings)).toEqual([]);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([a]);
  });

  it("one undo restores every occurrence of a canceled series at once", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "A",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    scope.run(cancelSeries, { input: { seriesId: made[0].seriesId ?? "" } });
    expect(scope.resolve(bookings)).toEqual([]);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual(made);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("failed actions add no undo step", () => {
    const scope = createScope();
    const a = scope.run(bookBooking, {
      input: { title: "A", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(bookBooking, {
      input: { title: "B", room: "Cedar", start: 600, end: 660 },
    });
    scope.run(openEdit, { input: { id: a.id } });
    const clash = capture(() =>
      scope.run(saveEdit, {
        input: {
          id: a.id,
          title: "A2",
          room: "Cedar",
          start: 540,
          end: 660,
        },
      }),
    );
    if (!isError(clash, "Clash")) {
      expect.fail("expected Clash");
    }
    expect(clash.payload).toEqual({ room: "Cedar", start: 540, end: 660 });
    const blank = capture(() =>
      scope.run(bookBooking, {
        input: { title: "  ", room: "Cedar", start: 700, end: 720 },
      }),
    );
    if (!isError(blank, "BlankTitle")) {
      expect.fail("expected BlankTitle");
    }
    expect(blank.payload).toEqual({ title: "  " });
    const missing = capture(() =>
      scope.run(cancelBooking, { input: { id: "missing" } }),
    );
    if (!isError(missing, "NotFound")) {
      expect.fail("expected NotFound");
    }
    expect(missing.payload).toEqual({ id: "missing" });
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)[0].title).toBe("A");
    expect(scope.resolve(bookings)).toHaveLength(1);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([]);
    const empty = capture(() => scope.run(undoChange, {}));
    if (!isError(empty, "EmptyUndo")) {
      expect.fail("expected EmptyUndo");
    }
    expect(empty.payload).toEqual({});
  });

  it("the open draft survives undos, and openEdit adds no undo step", () => {
    const scope = createScope();
    const a = scope.run(bookBooking, {
      input: { title: "A", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(bookBooking, {
      input: { title: "B", room: "Cedar", start: 600, end: 660 },
    });
    const draft = scope.run(openEdit, { input: { id: a.id } });
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)[0].title).toBe("A");
    expect(scope.resolve(editDraft)).toEqual(draft);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([]);
    expect(scope.resolve(editDraft)).toEqual(draft);
    const empty = capture(() => scope.run(undoChange, {}));
    if (!isError(empty, "EmptyUndo")) {
      expect.fail("expected EmptyUndo");
    }
    expect(empty.payload).toEqual({});
  });

  it("a save after an undo is a new change with its own step", () => {
    const scope = createScope();
    const a = scope.run(bookBooking, {
      input: { title: "A", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(undoChange, {});
    const again = scope.run(bookBooking, {
      input: { title: "A again", room: "Cedar", start: 540, end: 600 },
    });
    expect(again.id).not.toBe(a.id);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([]);
  });
});

import { data, operation } from "@tinker/core";
import type { Data, Operation, Scope } from "@tinker/core";
import { asManaged, fail } from "./errors";
import type { Errors } from "./errors";
import type { Course } from "./course";
import {
  addLink,
  completeCourseIn,
  removeLink,
  reopenCourseIn,
  replaceCourse,
} from "./rules";
import type { PlanFilter } from "./rules";

/** One saved course in the learning plan. */
export type { Course } from "./course";

/** Every saved course of one scope, in creation order. */
export const courses: Data.Cell<readonly Course[]> = data({ label: "courses", initial: [] });

const nextId: Data.Cell<number> = data({ label: "next course id", initial: 0 });
const history: Data.Cell<readonly (readonly Course[])[]> = data({
  label: "undo history",
  initial: [],
});

/** The error the screen shows in its shared alert block, or `undefined` when none. */
export const notice: Data.Cell<Errors.Of | undefined> = data({ label: "notice", initial: undefined });

/** The new-course form's draft title. */
export const titleDraft: Data.Cell<string> = data({ label: "title draft", initial: "" });

/** Which filter the course table shows. */
export const filter: Data.Cell<PlanFilter> = data({ label: "filter", initial: "all" });

/** The id chosen in the link form's Course select, empty when nothing is chosen. */
export const selectedCourseId: Data.Cell<string> = data({
  label: "selected course",
  initial: "",
});

/** The id chosen in the link form's Prerequisite select, empty when nothing is chosen. */
export const selectedPrerequisiteId: Data.Cell<string> = data({
  label: "selected prerequisite",
  initial: "",
});

/** The call's input as authored, falling back to its raw form for input checks. */
function callSource<I>(ctx: Operation.Ctx<I>): unknown {
  return ctx.input ?? ctx.rawInput;
}

/** The `title` field of a call, or the whole call when it is not an object. */
function titleOf(source: unknown): unknown {
  return typeof source === "object" && source !== null && "title" in source
    ? source.title
    : source;
}

/** The string id a call carries, or the empty string when it names nothing. */
function idOf(source: unknown): string {
  const value =
    typeof source === "object" && source !== null && "id" in source ? source.id : undefined;
  return typeof value === "string" ? value : "";
}

/** The pair of ids a link call carries, empty strings when a side names nothing. */
function linkOf(source: unknown): { courseId: string; prerequisiteId: string } {
  const courseId =
    typeof source === "object" && source !== null && "courseId" in source
      ? source.courseId
      : undefined;
  const prerequisiteId =
    typeof source === "object" && source !== null && "prerequisiteId" in source
      ? source.prerequisiteId
      : undefined;
  return {
    courseId: typeof courseId === "string" ? courseId : "",
    prerequisiteId: typeof prerequisiteId === "string" ? prerequisiteId : "",
  };
}

/** Record a managed error in the shared notice, then hand it back to the caller. */
function report(notice: Scope.DataController<Errors.Of | undefined>, error: unknown): never {
  const managed = asManaged(error);
  if (managed === undefined) throw error;
  notice.set(managed);
  throw managed;
}

/** Create an incomplete course with a trimmed title and no prerequisites. */
export const createCourse: Operation.Handle<Course, { title: string }> = operation({
  label: "create course",
  depends: {
    courses: courses.controller,
    nextId: nextId.controller,
    history: history.controller,
    notice: notice.controller,
  },
  run: ({ courses, nextId, history, notice }, ctx) => {
    try {
      const value = titleOf(callSource(ctx));
      if (typeof value !== "string" || value.trim() === "") {
        throw fail("BlankTitle", { title: value });
      }
      const saved: Course = {
        id: `course-${nextId.get()}`,
        title: value.trim(),
        done: false,
        prerequisiteIds: [],
      };
      history.set([...history.get(), courses.get()]);
      nextId.set(nextId.get() + 1);
      courses.set([...courses.get(), saved]);
      notice.set(undefined);
      return saved;
    } catch (error) {
      report(notice, error);
    }
  },
});

/** Record that `courseId` requires `prerequisiteId`, rejecting cycles and closed courses. */
export const addPrerequisite: Operation.Handle<
  Course,
  { courseId: string; prerequisiteId: string }
> = operation({
  label: "add requirement",
  depends: {
    courses: courses.controller,
    history: history.controller,
    notice: notice.controller,
  },
  run: ({ courses, history, notice }, ctx) => {
    try {
      const before = courses.get();
      const { courseId, prerequisiteId } = linkOf(callSource(ctx));
      const saved = addLink(before, courseId, prerequisiteId);
      if (!before.includes(saved)) {
        history.set([...history.get(), before]);
        courses.set(replaceCourse(before, saved));
      }
      notice.set(undefined);
      return saved;
    } catch (error) {
      report(notice, error);
    }
  },
});

/** Record that `courseId` no longer requires `prerequisiteId`. */
export const removePrerequisite: Operation.Handle<
  Course,
  { courseId: string; prerequisiteId: string }
> = operation({
  label: "remove requirement",
  depends: {
    courses: courses.controller,
    history: history.controller,
    notice: notice.controller,
  },
  run: ({ courses, history, notice }, ctx) => {
    try {
      const before = courses.get();
      const { courseId, prerequisiteId } = linkOf(callSource(ctx));
      const saved = removeLink(before, courseId, prerequisiteId);
      if (!before.includes(saved)) {
        history.set([...history.get(), before]);
        courses.set(replaceCourse(before, saved));
      }
      notice.set(undefined);
      return saved;
    } catch (error) {
      report(notice, error);
    }
  },
});

/** Complete a course whose direct prerequisites are all done. */
export const completeCourse: Operation.Handle<Course, { id: string }> = operation({
  label: "complete course",
  depends: {
    courses: courses.controller,
    history: history.controller,
    notice: notice.controller,
  },
  run: ({ courses, history, notice }, ctx) => {
    try {
      const before = courses.get();
      const saved = completeCourseIn(before, idOf(callSource(ctx)));
      if (!before.includes(saved)) {
        history.set([...history.get(), before]);
        courses.set(replaceCourse(before, saved));
      }
      notice.set(undefined);
      return saved;
    } catch (error) {
      report(notice, error);
    }
  },
});

/** Reopen a course that no completed course directly requires. */
export const reopenCourse: Operation.Handle<Course, { id: string }> = operation({
  label: "reopen course",
  depends: {
    courses: courses.controller,
    history: history.controller,
    notice: notice.controller,
  },
  run: ({ courses, history, notice }, ctx) => {
    try {
      const before = courses.get();
      const saved = reopenCourseIn(before, idOf(callSource(ctx)));
      if (!before.includes(saved)) {
        history.set([...history.get(), before]);
        courses.set(replaceCourse(before, saved));
      }
      notice.set(undefined);
      return saved;
    } catch (error) {
      report(notice, error);
    }
  },
});

/** Restore the exact course list from before the last passing change. */
export const undoPlan: Operation.Handle<void, void> = operation({
  label: "undo plan",
  depends: {
    courses: courses.controller,
    history: history.controller,
    notice: notice.controller,
  },
  run: ({ courses, history, notice }) => {
    try {
      const past = history.get();
      const last = past[past.length - 1];
      if (last === undefined) throw fail("EmptyUndo", {});
      history.set(past.slice(0, -1));
      courses.set(last);
      notice.set(undefined);
    } catch (error) {
      report(notice, error);
    }
  },
});

/** Store the form's draft title; typing always passes. */
export const setTitle: Operation.Handle<void, { text: string }> = operation({
  label: "set title draft",
  depends: { title: titleDraft.controller, notice: notice.controller },
  run: ({ title, notice }, ctx) => {
    title.set(ctx.input.text);
    notice.set(undefined);
  },
});

/** Choose the link form's Course selection; choosing always passes. */
export const chooseCourse: Operation.Handle<void, { id: string }> = operation({
  label: "choose course",
  depends: { selected: selectedCourseId.controller, notice: notice.controller },
  run: ({ selected, notice }, ctx) => {
    selected.set(ctx.input.id);
    notice.set(undefined);
  },
});

/** Choose the link form's Prerequisite selection; choosing always passes. */
export const choosePrerequisite: Operation.Handle<void, { id: string }> = operation({
  label: "choose prerequisite",
  depends: { selected: selectedPrerequisiteId.controller, notice: notice.controller },
  run: ({ selected, notice }, ctx) => {
    selected.set(ctx.input.id);
    notice.set(undefined);
  },
});

/** Choose the course table's filter; filtering always passes. */
export const chooseFilter: Operation.Handle<void, { filter: PlanFilter }> = operation({
  label: "choose filter",
  depends: { filter: filter.controller, notice: notice.controller },
  run: ({ filter, notice }, ctx) => {
    filter.set(ctx.input.filter);
    notice.set(undefined);
  },
});

/** Add the course the form drafted, clearing the draft on success. */
export const submitCourse: Operation.Handle<Course, void> = operation({
  label: "submit new course",
  depends: { create: createCourse.controller, title: titleDraft.controller },
  run: ({ create, title }) => {
    const saved = create.run({ input: { title: title.get() } });
    title.set("");
    return saved;
  },
});

/** Add the requirement the link form selected, keeping both selections. */
export const submitAdd: Operation.Handle<Course, void> = operation({
  label: "submit add requirement",
  depends: {
    add: addPrerequisite.controller,
    courseId: selectedCourseId.controller,
    prerequisiteId: selectedPrerequisiteId.controller,
  },
  run: ({ add, courseId, prerequisiteId }) => {
    return add.run({
      input: { courseId: courseId.get(), prerequisiteId: prerequisiteId.get() },
    });
  },
});

/** Remove the requirement the link form selected, keeping both selections. */
export const submitRemove: Operation.Handle<Course, void> = operation({
  label: "submit remove requirement",
  depends: {
    remove: removePrerequisite.controller,
    courseId: selectedCourseId.controller,
    prerequisiteId: selectedPrerequisiteId.controller,
  },
  run: ({ remove, courseId, prerequisiteId }) => {
    return remove.run({
      input: { courseId: courseId.get(), prerequisiteId: prerequisiteId.get() },
    });
  },
});

import { data, operation, type Data, type Edge, type Operation, type Scope } from "@tinker/core";
import { appError } from "./errors.ts";

/** The two bookable rooms. */
export type Room = "Cedar" | "Maple";

const ROOM_LIST: readonly ["Cedar", "Maple"] = ["Cedar", "Maple"];

export const rooms: readonly Room[] = ROOM_LIST;

/** The day round 1 fixed; still the default whenever a call omits `date`. */
export const DEFAULT_DATE = "2026-10-01";

/** A saved booking. `start`/`end` are minutes since midnight, 0..1439, end > start.
 * `date` is a real `YYYY-MM-DD` day. Series members carry a shared `seriesId`;
 * one-off bookings carry no `seriesId` key at all. */
export type Booking = {
  readonly id: string;
  readonly title: string;
  readonly room: Room;
  readonly date: string;
  readonly start: number;
  readonly end: number;
  readonly seriesId?: string;
};

/** What a caller hands `bookBooking`. `room` is a plain string: the op rejects unknown rooms.
 * `date` is optional; an absent date books the round 1 day, 2026-10-01. */
export type BookInput = {
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

/** What a caller hands `saveEdit`: a booking id plus the same slot fields as booking
 * (so `date` is optional there too and defaults to 2026-10-01). */
export type EditInput = {
  readonly id: string;
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

/** What a caller hands `bookSeries`: one slot plus how many weeks it repeats (1..12). */
export type SeriesInput = {
  readonly title: string;
  readonly room: string;
  readonly date: string;
  readonly start: number;
  readonly end: number;
  readonly weeks: number;
};

/** The saved list, sorted by date, then start time, then creation order. */
export const bookings: Data.Cell<readonly Booking[]> = data<readonly Booking[]>({
  label: "bookings",
  initial: [],
});

/** The one open edit draft; `undefined` when no edit is open. */
export const editDraft: Data.Cell<Booking | undefined> = data<Booking | undefined>({
  label: "editDraft",
  initial: undefined,
});

/** Creation sequence per id — the tie-break behind date and start time. Internal. */
const created = data<Readonly<Record<string, number>>>({
  label: "created",
  initial: {},
});

/** Monotonic id source, so ids stay unique in a scope even after cancels. Internal. */
const idCount = data<number>({ label: "idCount", initial: 0 });

/** One undo step: the booking list exactly as it stood before a passing change. Internal. */
type Snapshot = readonly Booking[];

/** Undo steps, newest last: one entry per passing booking write, none for a failure. Internal. */
const undoHistory = data<readonly Snapshot[]>({ label: "undoHistory", initial: [] });

type ListCtrl = Edge<"controller", Data.Cell<readonly Booking[]>>;
type DraftCtrl = Edge<"controller", Data.Cell<Booking | undefined>>;
type OrderCtrl = Edge<"controller", Data.Cell<Readonly<Record<string, number>>>>;
type CountCtrl = Edge<"controller", Data.Cell<number>>;
type HistoryCtrl = Edge<"controller", Data.Cell<readonly Snapshot[]>>;
/** The undo-history slot as a `run` body receives it: the read/write controller. */
type HistoryValue = Scope.DataController<readonly Snapshot[]>;

type BookDeps = {
  readonly list: ListCtrl;
  readonly order: OrderCtrl;
  readonly count: CountCtrl;
  readonly history: HistoryCtrl;
};
/** Cancels write the list, so they record an undo step; opening a draft does not. */
type SlotDeps = {
  readonly list: ListCtrl;
  readonly draft: DraftCtrl;
  readonly history: HistoryCtrl;
};
type ViewDeps = {
  readonly list: ListCtrl;
  readonly draft: DraftCtrl;
};
type SaveDeps = {
  readonly list: ListCtrl;
  readonly draft: DraftCtrl;
  readonly order: OrderCtrl;
  readonly history: HistoryCtrl;
};
type DiscardDeps = {
  readonly draft: DraftCtrl;
};
type UndoDeps = {
  readonly list: ListCtrl;
  readonly history: HistoryCtrl;
};

/** A slot that passed every field rule. */
type Checked = {
  readonly title: string;
  readonly room: Room;
  readonly date: string;
  readonly start: number;
  readonly end: number;
};

/** Pull the known keys off any raw call value, without trusting its shape. */
function readFields(raw: unknown): {
  readonly id: unknown;
  readonly title: unknown;
  readonly room: unknown;
  readonly date: unknown;
  readonly start: unknown;
  readonly end: unknown;
  readonly weeks: unknown;
  readonly seriesId: unknown;
} {
  if (typeof raw !== "object" || raw === null) {
    return {
      id: undefined,
      title: undefined,
      room: undefined,
      date: undefined,
      start: undefined,
      end: undefined,
      weeks: undefined,
      seriesId: undefined,
    };
  }
  return {
    id: "id" in raw ? raw.id : undefined,
    title: "title" in raw ? raw.title : undefined,
    room: "room" in raw ? raw.room : undefined,
    date: "date" in raw ? raw.date : undefined,
    start: "start" in raw ? raw.start : undefined,
    end: "end" in raw ? raw.end : undefined,
    weeks: "weeks" in raw ? raw.weeks : undefined,
    seriesId: "seriesId" in raw ? raw.seriesId : undefined,
  };
}

/** A booking id as a string; non-strings become not-found ids. */
function readId(raw: unknown): string {
  const id = readFields(raw).id;
  return typeof id === "string" ? id : String(id);
}

/** A series id as a string; non-strings become not-found ids. */
function readSeriesId(raw: unknown): string {
  const seriesId = readFields(raw).seriesId;
  return typeof seriesId === "string" ? seriesId : String(seriesId);
}

function describeTitle(value: unknown): string {
  return typeof value === "string" ? value : String(value);
}

function findRoom(value: string): Room | undefined {
  return ROOM_LIST.find((room) => room === value);
}

/** Days since the Unix epoch for a real `YYYY-MM-DD` day; `null` when the text is not one.
 * The round trip through `setUTCFullYear` rejects impossible days (2026-02-30, 2026-13-01)
 * and keeps years below 100 from being read as 1900-based. */
function parseDate(value: string): number | null {
  const match = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/.exec(value);
  if (match === null) {
    return null;
  }
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const at = new Date(0);
  at.setUTCHours(0, 0, 0, 0);
  at.setUTCFullYear(year, month - 1, day);
  if (
    at.getUTCFullYear() !== year ||
    at.getUTCMonth() !== month - 1 ||
    at.getUTCDate() !== day
  ) {
    return null;
  }
  return Math.floor(at.getTime() / 86_400_000);
}

/** Epoch days back to `YYYY-MM-DD`; `null` once the day leaves the four-digit-year range. */
function formatDate(epochDay: number): string | null {
  const at = new Date(epochDay * 86_400_000);
  if (Number.isNaN(at.getTime())) {
    return null;
  }
  const year = String(at.getUTCFullYear()).padStart(4, "0");
  const month = String(at.getUTCMonth() + 1).padStart(2, "0");
  const day = String(at.getUTCDate()).padStart(2, "0");
  const text = `${year}-${month}-${day}`;
  return /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(text) ? text : null;
}

/** The date rule: an absent date books the round 1 day; anything else must be a real day. */
function checkDate(value: unknown): string {
  if (value === undefined) {
    return DEFAULT_DATE;
  }
  if (typeof value !== "string" || parseDate(value) === null) {
    throw appError("BadDate", { date: value });
  }
  return value;
}

/** The weeks rule: an integer from 1 to 12, else `BadCount`. */
function checkWeeks(value: unknown): number {
  if (typeof value !== "number" || !Number.isInteger(value) || value < 1 || value > 12) {
    throw appError("BadCount", { weeks: value });
  }
  return value;
}

function checkMinute(value: unknown): number {
  if (typeof value !== "number" || !Number.isInteger(value) || value < 0 || value > 1439) {
    throw appError("BadTime", { value });
  }
  return value;
}

/** Field rules shared by booking, series booking, and saving: title, room, date, minutes. */
function checkSlot(raw: unknown): Checked {
  const fields = readFields(raw);
  if (typeof fields.title !== "string") {
    throw appError("BlankTitle", { title: describeTitle(fields.title) });
  }
  const title = fields.title.trim();
  if (title === "") {
    throw appError("BlankTitle", { title: fields.title });
  }
  if (typeof fields.room !== "string") {
    throw appError("UnknownRoom", { room: String(fields.room) });
  }
  const room = findRoom(fields.room);
  if (room === undefined) {
    throw appError("UnknownRoom", { room: fields.room });
  }
  const date = checkDate(fields.date);
  const start = checkMinute(fields.start);
  const end = checkMinute(fields.end);
  if (end <= start) {
    throw appError("EmptySlot", { start, end });
  }
  return { title, room, date, start, end };
}

/** True when `room` already holds a booking that overlaps the requested times on `date`.
 * Rooms never share slots, and the same slot on another day never clashes. */
function hasClash(
  list: readonly Booking[],
  room: Room,
  date: string,
  start: number,
  end: number,
  skipId: string | undefined = undefined,
): boolean {
  return list.some(
    (other) =>
      other.id !== skipId &&
      other.room === room &&
      other.date === date &&
      other.start < end &&
      start < other.end,
  );
}

/** Date first (YYYY-MM-DD text order is calendar order), then start time, then creation order. */
function sortedBookings(
  list: readonly Booking[],
  order: Readonly<Record<string, number>>,
): readonly Booking[] {
  return [...list].sort(
    (a, b) =>
      (a.date < b.date ? -1 : a.date > b.date ? 1 : 0) ||
      a.start - b.start ||
      order[a.id] - order[b.id],
  );
}

/** Push the pre-change list onto undo history. Called only after every rule passed, so a
 * failed action adds no step; the stored array is never mutated later, so it stays exact. */
function record(history: HistoryValue, before: Snapshot): void {
  history.set([...history.get(), before]);
}

/** The `weeks` dates of a series: the start day and six-day steps, seven days apart. */
function seriesDates(date: string, weeks: number): readonly string[] {
  const start = parseDate(date);
  if (start === null) {
    throw appError("BadDate", { date });
  }
  const dates: string[] = [];
  for (let index = 0; index < weeks; index += 1) {
    const text = formatDate(start + index * 7);
    if (text === null) {
      throw appError("BadDate", { date: text });
    }
    dates.push(text);
  }
  return dates;
}

/** Validate the raw call value once: the boundary every operation reads through. */
function rawCall(input: unknown, rawInput: unknown): unknown {
  return input ?? rawInput;
}

export const bookBooking: Operation.Handle<Booking, BookInput> = operation<
  BookDeps,
  Booking,
  BookInput
>({
  label: "bookBooking",
  depends: {
    list: bookings.controller,
    order: created.controller,
    count: idCount.controller,
    history: undoHistory.controller,
  },
  run: (deps, ctx) => {
    const slot = checkSlot(rawCall(ctx.input, ctx.rawInput));
    const list = deps.list.get();
    if (hasClash(list, slot.room, slot.date, slot.start, slot.end)) {
      throw appError("Clash", { room: slot.room, start: slot.start, end: slot.end });
    }
    const sequence = deps.count.get();
    const id = `b-${sequence}`;
    const booking: Booking = { id, ...slot };
    const order = { ...deps.order.get(), [id]: sequence };
    deps.list.set(sortedBookings([...list, booking], order));
    deps.count.set(sequence + 1);
    record(deps.history, list);
    return booking;
  },
});

export const bookSeries: Operation.Handle<readonly Booking[], SeriesInput> = operation<
  BookDeps,
  readonly Booking[],
  SeriesInput
>({
  label: "bookSeries",
  depends: {
    list: bookings.controller,
    order: created.controller,
    count: idCount.controller,
    history: undoHistory.controller,
  },
  run: (deps, ctx) => {
    const raw = rawCall(ctx.input, ctx.rawInput);
    const slot = checkSlot(raw);
    const weeks = checkWeeks(readFields(raw).weeks);
    // Every date is checked before any write: one failing date books none of them.
    const dates = seriesDates(slot.date, weeks);
    const list = deps.list.get();
    for (const date of dates) {
      if (hasClash(list, slot.room, date, slot.start, slot.end)) {
        throw appError("Clash", { room: slot.room, start: slot.start, end: slot.end });
      }
    }
    const sequence = deps.count.get();
    const seriesId = `s-${sequence}`;
    const order = { ...deps.order.get() };
    const made: Booking[] = dates.map((date, index) => {
      const id = `b-${sequence + index}`;
      order[id] = sequence + index;
      return { id, ...slot, date, seriesId };
    });
    deps.list.set(sortedBookings([...list, ...made], order));
    deps.count.set(sequence + weeks);
    record(deps.history, list);
    return made;
  },
});

export const cancelBooking: Operation.Handle<void, { id: string }> = operation<
  SlotDeps,
  void,
  { id: string }
>({
  label: "cancelBooking",
  depends: { list: bookings.controller, draft: editDraft.controller, history: undoHistory.controller },
  run: (deps, ctx) => {
    const id = readId(rawCall(ctx.input, ctx.rawInput));
    const list = deps.list.get();
    if (!list.some((booking) => booking.id === id)) {
      throw appError("NotFound", { id });
    }
    deps.list.set(list.filter((booking) => booking.id !== id));
    record(deps.history, list);
    const draft = deps.draft.get();
    if (draft !== undefined && draft.id === id) {
      deps.draft.set(undefined);
    }
  },
});

export const cancelSeries: Operation.Handle<void, { seriesId: string }> = operation<
  SlotDeps,
  void,
  { seriesId: string }
>({
  label: "cancelSeries",
  depends: { list: bookings.controller, draft: editDraft.controller, history: undoHistory.controller },
  run: (deps, ctx) => {
    const seriesId = readSeriesId(rawCall(ctx.input, ctx.rawInput));
    const list = deps.list.get();
    if (!list.some((booking) => booking.seriesId === seriesId)) {
      throw appError("NotFound", { id: seriesId });
    }
    deps.list.set(list.filter((booking) => booking.seriesId !== seriesId));
    record(deps.history, list);
    const draft = deps.draft.get();
    if (draft !== undefined && draft.seriesId === seriesId) {
      deps.draft.set(undefined);
    }
  },
});

export const openEdit: Operation.Handle<Booking, { id: string }> = operation<
  ViewDeps,
  Booking,
  { id: string }
>({
  label: "openEdit",
  depends: { list: bookings.controller, draft: editDraft.controller },
  run: (deps, ctx) => {
    const id = readId(rawCall(ctx.input, ctx.rawInput));
    const found = deps.list.get().find((booking) => booking.id === id);
    if (found === undefined) {
      throw appError("NotFound", { id });
    }
    // Two copies: the draft cell and the caller's result never alias each other.
    deps.draft.set({ ...found });
    return { ...found };
  },
});

export const saveEdit: Operation.Handle<Booking, EditInput> = operation<
  SaveDeps,
  Booking,
  EditInput
>({
  label: "saveEdit",
  depends: {
    list: bookings.controller,
    draft: editDraft.controller,
    order: created.controller,
    history: undoHistory.controller,
  },
  run: (deps, ctx) => {
    const raw = rawCall(ctx.input, ctx.rawInput);
    const id = readId(raw);
    const draft = deps.draft.get();
    if (draft === undefined || draft.id !== id) {
      throw appError("NotFound", { id });
    }
    const list = deps.list.get();
    const found = list.find((booking) => booking.id === id);
    if (found === undefined) {
      throw appError("NotFound", { id });
    }
    const slot = checkSlot(raw);
    if (hasClash(list, slot.room, slot.date, slot.start, slot.end, id)) {
      throw appError("Clash", { room: slot.room, start: slot.start, end: slot.end });
    }
    // The save rewrites the checked fields over the saved row; a series member stays
    // a member, because `seriesId` is identity, not one of the edited fields.
    const saved: Booking = { ...found, ...slot };
    const rest = list.filter((booking) => booking.id !== id);
    deps.list.set(sortedBookings([...rest, saved], deps.order.get()));
    record(deps.history, list);
    deps.draft.set(undefined);
    return saved;
  },
});

export const discardEdit: Operation.Handle<void, { id: string }> = operation<
  DiscardDeps,
  void,
  { id: string }
>({
  label: "discardEdit",
  depends: { draft: editDraft.controller },
  run: (deps, ctx) => {
    const id = readId(rawCall(ctx.input, ctx.rawInput));
    const draft = deps.draft.get();
    if (draft === undefined || draft.id !== id) {
      throw appError("NotFound", { id });
    }
    deps.draft.set(undefined);
  },
});

/** Undo the last passing booking change: pop one history step and restore the list it held.
 * A restore adds no step of its own, so two undos reverse two changes; an empty history
 * reports `EmptyUndo`. Drafts, form text, and filters are booking data, so they stay put. */
export const undoChange: Operation.Handle<void, void> = operation<UndoDeps, void, void>({
  label: "undoChange",
  depends: { list: bookings.controller, history: undoHistory.controller },
  run: (deps) => {
    const stack = deps.history.get();
    const last = stack.at(-1);
    if (last === undefined) {
      throw appError("EmptyUndo", {});
    }
    deps.history.set(stack.slice(0, -1));
    deps.list.set(last);
  },
});

import { afterEach, beforeEach, afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { chromium } from 'playwright';
import type { Browser, Locator, Page } from 'playwright';

const baseUrl = inject('baseUrl');

let browser: Browser;
let page: Page;

beforeAll(async () => {
  browser = await chromium.launch({ headless: true });
  page = await browser.newPage();
});

afterAll(async () => {
  await browser?.close();
});

