import { createRoot } from "react-dom/client";
import { BookingApp } from "./index.ts";

const root = document.getElementById("root");
if (root !== null) {
  createRoot(root).render(<BookingApp />);
}

import { operation } from '@tinker/core';
import type { Operation, Scope } from '@tinker/core';
import { appError } from './errors.ts';
import type { Errors, Payloads } from './errors.ts';
import { inputOf, readId, readItem, readPlace, readQuantity } from './fields.ts';
import type { Raise } from './fields.ts';
import {
  editDraft,
  editFrom,
  editItem,
  editQuantity,
  editTo,
  history,
  issueId,
  idSeq,
  moves,
  notice,
  quantityAt,
  stock,
  transfer,
} from './model.ts';
import type { Snapshot } from './model.ts';
import type { EditMoveInput, Move, MoveInput, Stock } from './types.ts';

/** A rule reporter that also records the failure in the shared notice cell. */
const noticeRaiser =
  (setNotice: (error: Errors.Of | undefined) => void): Raise =>
  (kind: Errors.Name, payload: Payloads[Errors.Name]): never => {
    const error = appError(kind, payload);
    setNotice(error);
    throw error;
  };

/** Save one undo step for the change that is about to land. */
const pushHistory = (
  undo: Scope.DataController<readonly Snapshot[]>,
  current: readonly Stock[],
  saved: readonly Move[],
  setNotice: (error: Errors.Of | undefined) => void,
): void => {
  undo.set([...undo.get(), { stock: current, moves: saved }]);
  setNotice(undefined);
};

/** Move stock between two places, saving one Move. */
export const moveStock: Operation.Handle<Move, MoveInput> = operation({
  label: 'moveStock',
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    idSeq: idSeq.controller,
    history: history.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    const raise: Raise = noticeRaiser(deps.notice.set);
    const raw = inputOf(ctx);
    const item = readItem(raw, raise);
    const from = readPlace(raw, 'from', raise);
    const to = readPlace(raw, 'to', raise);
    const quantity = readQuantity(raw, raise);
    if (from === to) raise('SamePlace', { place: from });
    const current = deps.stock.get();
    const available = quantityAt(current, item, from);
    if (available < quantity) {
      raise('ShortStock', { item, place: from, available, requested: quantity });
    }
    const before = deps.moves.get();
    const saved: Move = { id: issueId(deps.idSeq), item, from, to, quantity };
    pushHistory(deps.history, current, before, deps.notice.set);
    deps.stock.set(transfer(current, item, from, to, quantity));
    deps.moves.set([...before, saved]);
    return saved;
  },
});

/** Copy one saved move into the editor, replacing any open draft. */
export const openMoveEdit: Operation.Handle<Move, { id: string }> = operation({
  label: 'openMoveEdit',
  depends: {
    moves: moves.controller,
    editDraft: editDraft.controller,
    editItem: editItem.controller,
    editFrom: editFrom.controller,
    editTo: editTo.controller,
    editQuantity: editQuantity.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    const raise: Raise = noticeRaiser(deps.notice.set);
    const id = readId(inputOf(ctx));
    const found = deps.moves.get().find(move => move.id === id);
    if (!found) raise('NotFound', { id });
    deps.editDraft.set(found);
    deps.editItem.set(found.item);
    deps.editFrom.set(found.from);
    deps.editTo.set(found.to);
    deps.editQuantity.set(String(found.quantity));
    deps.notice.set(undefined);
    return found;
  },
});

/** Replace the open draft's saved move, reversal first, in one undo step. */
export const saveMoveEdit: Operation.Handle<Move, EditMoveInput> = operation({
  label: 'saveMoveEdit',
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    editDraft: editDraft.controller,
    history: history.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    const raise: Raise = noticeRaiser(deps.notice.set);
    const raw = inputOf(ctx);
    const id = readId(raw);
    const item = readItem(raw, raise);
    const from = readPlace(raw, 'from', raise);
    const to = readPlace(raw, 'to', raise);
    const quantity = readQuantity(raw, raise);
    if (from === to) raise('SamePlace', { place: from });
    const saved = deps.moves.get();
    const draft = deps.editDraft.get();
    const index = saved.findIndex(move => move.id === id);
    if (draft === undefined || draft.id !== id || index < 0) raise('NotFound', { id });
    const previous = saved[index];
    const current = deps.stock.get();
    const held = quantityAt(current, previous.item, previous.to);
    if (held < previous.quantity) {
      raise('ShortStock', {
        item: previous.item,
        place: previous.to,
        available: held,
        requested: previous.quantity,
      });
    }
    const restored = transfer(current, previous.item, previous.to, previous.from, previous.quantity);
    const available = quantityAt(restored, item, from);
    if (available < quantity) {
      raise('ShortStock', { item, place: from, available, requested: quantity });
    }
    const replacement: Move = { id, item, from, to, quantity };
    pushHistory(deps.history, current, saved, deps.notice.set);
    deps.stock.set(transfer(restored, item, from, to, quantity));
    deps.moves.set(saved.map((move, at) => (at === index ? replacement : move)));
    deps.editDraft.set(undefined);
    return replacement;
  },
});

/** Close the open draft without touching stock, moves, or history. */
export const discardMoveEdit: Operation.Handle<void, { id: string }> = operation({
  label: 'discardMoveEdit',
  depends: {
    editDraft: editDraft.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    const raise: Raise = noticeRaiser(deps.notice.set);
    const id = readId(inputOf(ctx));
    const draft = deps.editDraft.get();
    if (draft === undefined || draft.id !== id) raise('NotFound', { id });
    deps.editDraft.set(undefined);
    deps.notice.set(undefined);
  },
});

/** Restore the stock and move list from the last passing change. */
export const undoMove: Operation.Handle<void, void> = operation({
  label: 'undoMove',
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    history: history.controller,
    notice: notice.controller,
  },
  run: deps => {
    const raise: Raise = noticeRaiser(deps.notice.set);
    const past = deps.history.get();
    if (past.length === 0) raise('EmptyUndo', {});
    const last = past[past.length - 1];
    deps.history.set(past.slice(0, -1));
    deps.stock.set(last.stock);
    deps.moves.set(last.moves);
    deps.notice.set(undefined);
  },
});

