import { type Operation, type Scope, operation } from "@tinker/core";
import { appError } from "./errors.ts";
import {
  type BookInput,
  type Booking,
  type EditInput,
  type Fields,
  type SeriesInput,
  bookings,
  clashesWith,
  editDraft,
  issuedIds,
  occurrenceDates,
  field,
  requireId,
  requireSeriesId,
  requireTitle,
  retitledSeries,
  seriesRows,
  shapeBooking,
  shapeEdit,
  shapeSeries,
  shapeSeriesRename,
  sortedBookings,
  undoHistory,
  validateFields,
  weekCount,
} from "./model.ts";

function parseBookInput(raw: unknown): BookInput {
  return shapeBooking(raw);
}

function parseSeriesInput(raw: unknown): SeriesInput {
  return shapeSeries(raw);
}

function parseIdInput(raw: unknown): { id: string } {
  return { id: requireId(raw) };
}

function parseSeriesIdInput(raw: unknown): { seriesId: string } {
  return { seriesId: requireSeriesId(raw) };
}

function parseSeriesRename(raw: unknown): { seriesId: string; title: string } {
  return shapeSeriesRename(raw);
}

function parseEditInput(raw: unknown): EditInput {
  return shapeEdit(raw);
}

/** The value the caller actually passed, on either call shape. */
function source(ctx: {
  readonly rawInput: unknown;
  readonly input: unknown;
}): unknown {
  return ctx.rawInput !== undefined ? ctx.rawInput : ctx.input;
}

function savedBooking(
  fields: Fields,
  id: string,
  seriesId: string | undefined,
): Booking {
  const booking: Booking = {
    id,
    title: fields.title,
    room: fields.room,
    date: fields.date,
    start: fields.start,
    end: fields.end,
  };
  return seriesId === undefined ? booking : { ...booking, seriesId };
}

function clash(fields: Fields): Error {
  return appError("Clash", {
    room: fields.room,
    start: fields.start,
    end: fields.end,
  });
}

type ChangeDeps = {
  readonly list: Scope.DataController<readonly Booking[]>;
  readonly history: Scope.DataController<readonly (readonly Booking[])[]>;
};

/** Save one undo step, then the new list: one passing change per call. */
function applyChange(deps: ChangeDeps, next: readonly Booking[]): void {
  deps.history.set([...deps.history.get(), deps.list.get()]);
  deps.list.set(next);
}

/** Book a slot: one more saved booking unless the room's slot on that date is taken. */
export const bookBooking: Operation.Handle<Booking, BookInput> = operation({
  label: "bookBooking",
  input: parseBookInput,
  depends: {
    list: bookings.controller,
    issued: issuedIds.controller,
    history: undoHistory.controller,
  },
  run(deps, ctx): Booking {
    const fields = validateFields(source(ctx));
    const list = deps.list.get();
    if (clashesWith(list, fields.room, fields.date, fields.start, fields.end)) {
      throw clash(fields);
    }
    const issued = deps.issued.get();
    const id = `booking-${issued.length}`;
    const booking = savedBooking(fields, id, undefined);
    deps.issued.set([...issued, id]);
    applyChange(deps, sortedBookings([...list, booking], [...issued, id]));
    return booking;
  },
});

/** Book a weekly series: all occurrences land together, or none when one date fails. */
export const bookSeries: Operation.Handle<readonly Booking[], SeriesInput> =
  operation({
    label: "bookSeries",
    input: parseSeriesInput,
    depends: {
      list: bookings.controller,
      issued: issuedIds.controller,
      history: undoHistory.controller,
    },
    run(deps, ctx): readonly Booking[] {
      const fields = validateFields(source(ctx));
      const weeks = weekCount(source(ctx));
      const list = deps.list.get();
      const dates = occurrenceDates(fields.date, weeks);
      for (const date of dates) {
        if (clashesWith(list, fields.room, date, fields.start, fields.end)) {
          throw clash(fields);
        }
      }
      const seriesId = `series-${deps.issued.get().length}`;
      let issued = deps.issued.get();
      const made: Booking[] = [];
      const added: string[] = [];
      for (const date of dates) {
        const id = `booking-${issued.length + added.length}`;
        made.push(savedBooking({ ...fields, date }, id, seriesId));
        added.push(id);
      }
      issued = [...issued, ...added];
      deps.issued.set(issued);
      applyChange(deps, sortedBookings([...list, ...made], issued));
      return made;
    },
  });

/** Cancel one booking by id; a second cancel of the id reports NotFound. */
export const cancelBooking: Operation.Handle<void, { id: string }> = operation({
  label: "cancelBooking",
  input: parseIdInput,
  depends: {
    list: bookings.controller,
    draft: editDraft.controller,
    history: undoHistory.controller,
  },
  run(deps, ctx): void {
    const id = requireId(source(ctx));
    const list = deps.list.get();
    if (!list.some((booking) => booking.id === id)) {
      throw appError("NotFound", { id });
    }
    applyChange(deps, list.filter((booking) => booking.id !== id));
    const draft = deps.draft.get();
    if (draft?.id === id) {
      deps.draft.set(undefined);
    }
  },
});

/** Cancel every occurrence of one series by its series id. */
export const cancelSeries: Operation.Handle<void, { seriesId: string }> =
  operation({
    label: "cancelSeries",
    input: parseSeriesIdInput,
    depends: {
      list: bookings.controller,
      draft: editDraft.controller,
      history: undoHistory.controller,
    },
    run(deps, ctx): void {
      const seriesId = requireSeriesId(source(ctx));
      const list = deps.list.get();
      const gone = list.filter((booking) => booking.seriesId === seriesId);
      if (gone.length === 0) {
        throw appError("NotFound", { id: seriesId });
      }
      applyChange(
        deps,
        list.filter((booking) => booking.seriesId !== seriesId),
      );
      const draft = deps.draft.get();
      if (draft && gone.some((booking) => booking.id === draft.id)) {
        deps.draft.set(undefined);
      }
    },
  });

/** Rename every remaining occurrence of one series: one trimmed title, one undo step, nothing else moves. */
export const renameSeries: Operation.Handle<
  readonly Booking[],
  { seriesId: string; title: string }
> = operation({
  label: "renameSeries",
  input: parseSeriesRename,
  depends: { list: bookings.controller, history: undoHistory.controller },
  run(deps, ctx): readonly Booking[] {
    const raw = source(ctx);
    const title = requireTitle(field(raw, "title"));
    const seriesId = requireSeriesId(raw);
    const list = deps.list.get();
    const rows = seriesRows(list, seriesId);
    if (rows.length === 0) {
      throw appError("NotFound", { id: seriesId });
    }
    const next = retitledSeries(list, seriesId, title);
    applyChange(deps, next);
    return seriesRows(next, seriesId);
  },
});

/** Open an edit draft: a copy of the saved booking, never the saved row itself. */
export const openEdit: Operation.Handle<Booking, { id: string }> = operation({
  label: "openEdit",
  input: parseIdInput,
  depends: { list: bookings.controller, draft: editDraft.controller },
  run(deps, ctx): Booking {
    const id = requireId(source(ctx));
    const saved = deps.list.get().find((booking) => booking.id === id);
    if (!saved) {
      throw appError("NotFound", { id });
    }
    const draft: Booking = { ...saved };
    deps.draft.set(draft);
    return draft;
  },
});

/** Save the open draft: it replaces the booking and closes the draft. */
export const saveEdit: Operation.Handle<Booking, EditInput> = operation({
  label: "saveEdit",
  input: parseEditInput,
  depends: {
    list: bookings.controller,
    draft: editDraft.controller,
    issued: issuedIds.controller,
    history: undoHistory.controller,
  },
  run(deps, ctx): Booking {
    const fields = validateFields(source(ctx));
    const id = requireId(source(ctx));
    const draft = deps.draft.get();
    if (!draft || draft.id !== id) {
      throw appError("NotFound", { id });
    }
    const list = deps.list.get();
    const saved = list.find((booking) => booking.id === id);
    if (!saved) {
      throw appError("NotFound", { id });
    }
    if (
      clashesWith(list, fields.room, fields.date, fields.start, fields.end, id)
    ) {
      throw clash(fields);
    }
    const updated = savedBooking(fields, id, saved.seriesId);
    applyChange(
      deps,
      sortedBookings(
        list.map((booking) => (booking.id === id ? updated : booking)),
        deps.issued.get(),
      ),
    );
    deps.draft.set(undefined);
    return updated;
  },
});

/** Drop the open draft untouched; the saved booking stays as it was. */
export const discardEdit: Operation.Handle<void, { id: string }> = operation({
  label: "discardEdit",
  input: parseIdInput,
  depends: { draft: editDraft.controller },
  run(deps, ctx): void {
    const id = requireId(source(ctx));
    const draft = deps.draft.get();
    if (!draft || draft.id !== id) {
      throw appError("NotFound", { id });
    }
    deps.draft.set(undefined);
  },
});

/** Reverse the last passing booking change; with no step left it reports EmptyUndo. */
export const undoChange: Operation.Handle<void, void> = operation({
  label: "undoChange",
  depends: { list: bookings.controller, history: undoHistory.controller },
  run(deps): void {
    const history = deps.history.get();
    const before = history.at(-1);
    if (before === undefined) {
      throw appError("EmptyUndo", {});
    }
    deps.history.set(history.slice(0, history.length - 1));
    deps.list.set(before);
  },
});

