/** Parse a 24-hour `HH:MM` text into minutes since midnight. */
export function toMinute(raw: string): number | undefined {
  const match = /^(\d{1,2}):(\d{2})$/.exec(raw.trim());
  if (match === null) return undefined;
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (hours > 23 || minutes > 59) return undefined;
  return hours * 60 + minutes;
}

/** Render minutes since midnight as `HH:MM`. */
export function timeLabel(minute: number): string {
  const hours = String(Math.floor(minute / 60)).padStart(2, "0");
  const minutes = String(minute % 60).padStart(2, "0");
  return `${hours}:${minutes}`;
}

/** The record with one text field replaced. */
function withText<F extends string, T extends Readonly<Record<F, string>>>(
  record: T,
  field: F,
  value: string,
): T {
  return { ...record, [field]: value };
}

/** Parse the form's two times; a cleared or malformed time reports `BadTime`
 * with the text the user typed. */
function timesOf(start: string, end: string): { readonly start: number; readonly end: number } {
  const startMinute = toMinute(start);
  const endMinute = toMinute(end);
  if (startMinute === undefined) throw fail("BadTime", { value: start });
  if (endMinute === undefined) throw fail("BadTime", { value: end });
  return { start: startMinute, end: endMinute };
}

/** Run one body, showing the first managed error's kind in the notice cell and
 * rethrowing any value that is not one of this app's registry errors. */
function withNotice<R>(body: () => R, noticeCell: Scope.DataController<Name | undefined>): R {
  try {
    return body();
  } catch (error) {
    const kind = errorKind(error);
    if (kind === undefined) throw error;
    noticeCell.set(kind);
    throw error;
  }
}

