export type { EditMoveInput, Item, Move, MoveInput, Place, Stock } from "./model.ts";
export { items, places } from "./model.ts";
export { isError, type Errors } from "./errors.ts";
export { editDraft, moves, stock } from "./state.ts";
export {
  discardMoveEdit,
  moveStock,
  openMoveEdit,
  saveMoveEdit,
  undoMove,
} from "./operations.ts";
export { StockApp } from "./StockApp.tsx";

import { fail } from "./errors.ts";

/** A stock line's item kind. */
export type Item = "Cable" | "Stand";

/** A stock location. */
export type Place = "East" | "West";

/** Every item, in desk order. */
export const items: readonly Item[] = ["Cable", "Stand"];

/** Every place, in desk order. */
export const places: readonly Place[] = ["East", "West"];

/** One stock line: how much of one item sits at one place. */
export type Stock = {
  item: Item;
  place: Place;
  quantity: number;
};

/** One saved move. */
export type Move = {
  id: string;
  item: Item;
  from: Place;
  to: Place;
  quantity: number;
};

/** Input for one new move: names are raw text, quantity is a raw API number. */
export type MoveInput = {
  item: string;
  from: string;
  to: string;
  quantity: number;
};

/** Input for replacing the open draft's saved move: {@link MoveInput} plus the move id. */
export type EditMoveInput = MoveInput & { id: string };

/** The typed text held by one four-field move form. */
export type FormText = {
  item: string;
  from: string;
  to: string;
  quantity: string;
};

/** The raw, still-unvalidated fields read off one move submission. */
export type RawFields = {
  id: unknown;
  item: unknown;
  from: unknown;
  to: unknown;
  quantity: unknown;
};

/** The four stock lines a fresh scope starts with, in desk order. */
export function initialStock(): readonly Stock[] {
  return [
    { item: "Cable", place: "East", quantity: 8 },
    { item: "Cable", place: "West", quantity: 2 },
    { item: "Stand", place: "East", quantity: 3 },
    { item: "Stand", place: "West", quantity: 1 },
  ];
}

/** Whether a raw value is an object that can carry named fields. */
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

/** Read one named field off untyped input; missing or shapeless input reads as `undefined`. */
function readField(raw: unknown, key: string): unknown {
  return isRecord(raw) ? raw[key] : undefined;
}

/** Split one raw submission into its named fields, keeping every value untyped. */
export function readFields(raw: unknown): RawFields {
  return {
    id: readField(raw, "id"),
    item: readField(raw, "item"),
    from: readField(raw, "from"),
    to: readField(raw, "to"),
    quantity: readField(raw, "quantity"),
  };
}

/** Narrow a raw value to a known item, or fail `UnknownItem` with the original value. */
export function asItem(value: unknown): Item {
  for (const item of items) {
    if (value === item) return item;
  }
  return fail("UnknownItem", { item: value });
}

/** Narrow a raw value to a known place, or fail `UnknownPlace` with the original value. */
export function asPlace(value: unknown): Place {
  for (const place of places) {
    if (value === place) return place;
  }
  return fail("UnknownPlace", { place: value });
}

/**
 * Narrow a raw value to an API quantity: a positive safe integer, or fail
 * `BadQuantity` with the original value.
 */
export function asQuantity(value: unknown): number {
  if (typeof value === "number" && Number.isSafeInteger(value) && value > 0) return value;
  return fail("BadQuantity", { quantity: value });
}

/** Narrow a raw value to a saved-move id, or fail `NotFound` (an unnamed id is never found). */
export function asId(value: unknown): string {
  return typeof value === "string" ? value : fail("NotFound", { id: "" });
}

/**
 * Parse one quantity field's text at the input boundary: readable number text
 * becomes its number, anything else (a cleared or unreadable field) keeps its
 * original text so `BadQuantity` can report it.
 */
export function quantityFromText(text: string): number | string {
  const parsed = Number(text);
  return text.trim() === "" || Number.isNaN(parsed) ? text : parsed;
}

/** The form text with one field retyped. */
export function withField(text: FormText, field: keyof FormText, value: string): FormText {
  switch (field) {
    case "item":
      return { ...text, item: value };
    case "from":
      return { ...text, from: value };
    case "to":
      return { ...text, to: value };
    case "quantity":
      return { ...text, quantity: value };
  }
}

/** The raw fields one form submits, with quantity text parsed at the input boundary. */
export function submitFields(form: FormText): { item: string; from: string; to: string; quantity: number | string } {
  return { item: form.item, from: form.from, to: form.to, quantity: quantityFromText(form.quantity) };
}

/** The fixed slot one stock line occupies in desk order. */
function slotOf(item: Item, place: Place): number {
  return items.indexOf(item) * places.length + places.indexOf(place);
}

/** How much of one item currently sits at one place. */
export function quantityAt(rows: readonly Stock[], item: Item, place: Place): number {
  return rows[slotOf(item, place)].quantity;
}

/**
 * The stock rows after moving `quantity` of `item` from one place to another,
 * or a `ShortStock` failure naming the source and its shortfall.
 */
export function applyMove(rows: readonly Stock[], item: Item, from: Place, to: Place, quantity: number): readonly Stock[] {
  const available = quantityAt(rows, item, from);
  if (available < quantity) fail("ShortStock", { item, place: from, available, requested: quantity });
  return rows.map((row) =>
    row.item === item && row.place === from
      ? { ...row, quantity: row.quantity - quantity }
      : row.item === item && row.place === to
        ? { ...row, quantity: row.quantity + quantity }
        : row,
  );
}

/**
 * The stock rows after putting one saved move back: `quantity` of `item` leaves
 * the old target for the old source, or a `ShortStock` failure naming the old
 * target and the old quantity when it cannot cover the reversal.
 */
export function reverseMove(rows: readonly Stock[], move: Move): readonly Stock[] {
  const available = quantityAt(rows, move.item, move.to);
  if (available < move.quantity) fail("ShortStock", { item: move.item, place: move.to, available, requested: move.quantity });
  return rows.map((row) =>
    row.item === move.item && row.place === move.to
      ? { ...row, quantity: row.quantity - move.quantity }
      : row.item === move.item && row.place === move.from
        ? { ...row, quantity: row.quantity + move.quantity }
        : row,
  );
}

import { createScope } from "@tinker/core";
import { describe, expect, it } from "vitest";
import {
  bookBooking,
  bookSeries,
  bookings,
  cancelBooking,
  cancelSeries,
  discardEdit,
  editDraft,
  isError,
  openEdit,
  saveEdit,
} from "../src/index.ts";

function capture(action: () => unknown): unknown {
  try {
    action();
    return undefined;
  } catch (error) {
    return error;
  }
}

describe("bookSeries", () => {
  it("books weeks dates, seven days apart, under one series id", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    expect(made.map((booking) => booking.date)).toEqual([
      "2026-10-06",
      "2026-10-13",
      "2026-10-20",
    ]);
    const seriesId = made[0]?.seriesId;
    expect(seriesId).toBeTypeOf("string");
    for (const booking of made) {
      expect(booking.seriesId).toBe(seriesId);
    }
    expect(scope.resolve(bookings)).toEqual(made);
  });

  it("carries no series id on a one-off booking", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Solo", room: "Cedar", start: 540, end: 600 },
    });
    expect(saved.seriesId).toBeUndefined();
  });

  it("crosses a month boundary seven days at a time", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Review",
        room: "Maple",
        date: "2026-10-27",
        start: 600,
        end: 660,
        weeks: 3,
      },
    });
    expect(made.map((booking) => booking.date)).toEqual([
      "2026-10-27",
      "2026-11-03",
      "2026-11-10",
    ]);
  });

  it("rejects weeks outside 1 to 12 or not an integer", () => {
    const scope = createScope();
    for (const weeks of [0, -1, 13, 1.5, Number.NaN]) {
      const error = capture(() =>
        scope.run(bookSeries, {
          input: {
            title: "Standup",
            room: "Cedar",
            date: "2026-10-06",
            start: 540,
            end: 600,
            weeks,
          },
        }),
      );
      if (!isError(error, "BadCount")) {
        expect.fail(String(weeks));
      }
      expect(error.payload.weeks).toBe(weeks);
    }
    const notNumber = capture(() =>
      scope.run(bookSeries, {
        rawInput: {
          title: "Standup",
          room: "Cedar",
          date: "2026-10-06",
          start: 540,
          end: 600,
          weeks: "3",
        },
      }),
    );
    if (!isError(notNumber, "BadCount")) {
      expect.fail("expected BadCount");
    }
    expect(notNumber.payload.weeks).toBe("3");
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("accepts weeks = 1 and weeks = 12 as the bounds", () => {
    const scope = createScope();
    const one = scope.run(bookSeries, {
      input: {
        title: "One",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 1,
      },
    });
    expect(one).toHaveLength(1);
    const twelve = scope.run(bookSeries, {
      input: {
        title: "Twelve",
        room: "Maple",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 12,
      },
    });
    expect(twelve).toHaveLength(12);
    expect(twelve[11]?.date).toBe("2026-12-22");
  });

  it("books none and reports Clash when one date is taken", () => {
    const scope = createScope();
    scope.run(bookBooking, {
      input: {
        title: "Busy",
        room: "Cedar",
        date: "2026-10-13",
        start: 550,
        end: 590,
      },
    });
    const error = capture(() =>
      scope.run(bookSeries, {
        input: {
          title: "Standup",
          room: "Cedar",
          date: "2026-10-06",
          start: 540,
          end: 600,
          weeks: 3,
        },
      }),
    );
    if (!isError(error, "Clash")) {
      expect.fail("expected Clash");
    }
    expect(error.payload).toEqual({ room: "Cedar", start: 540, end: 600 });
    expect(scope.resolve(bookings)).toHaveLength(1);
  });

  it("leaves saved bookings unchanged when the title is blank", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Kept", room: "Maple", start: 540, end: 600 },
    });
    const error = capture(() =>
      scope.run(bookSeries, {
        input: {
          title: "   ",
          room: "Cedar",
          date: "2026-10-06",
          start: 540,
          end: 600,
          weeks: 2,
        },
      }),
    );
    if (!isError(error, "BlankTitle")) {
      expect.fail("expected BlankTitle");
    }
    expect(error.payload).toEqual({ title: "   " });
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("rejects a bad date before booking anything", () => {
    const scope = createScope();
    const error = capture(() =>
      scope.run(bookSeries, {
        input: {
          title: "Standup",
          room: "Cedar",
          date: "2026-02-30",
          start: 540,
          end: 600,
          weeks: 2,
        },
      }),
    );
    if (!isError(error, "BadDate")) {
      expect.fail("expected BadDate");
    }
    expect(error.payload).toEqual({ date: "2026-02-30" });
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("overlaps in another room or on another date never clash", () => {
    const scope = createScope();
    scope.run(bookSeries, {
      input: {
        title: "Cedar run",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    const maple = scope.run(bookSeries, {
      input: {
        title: "Maple run",
        room: "Maple",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    expect(maple).toHaveLength(3);
    const otherDates = scope.run(bookSeries, {
      input: {
        title: "Cedar later",
        room: "Cedar",
        date: "2026-10-07",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    expect(otherDates).toHaveLength(3);
    expect(scope.resolve(bookings)).toHaveLength(9);
  });
});

describe("cancelSeries", () => {
  it("frees every occurrence of the series", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    const seriesId = made[0]?.seriesId ?? "";
    scope.run(cancelSeries, { input: { seriesId } });
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("canceling one id leaves the rest of its series", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    const middle = made[1];
    if (!middle) expect.fail("missing occurrence");
    scope.run(cancelBooking, { input: { id: middle.id } });
    const list = scope.resolve(bookings);
    expect(list).toHaveLength(2);
    expect(list.map((booking) => booking.date)).toEqual([
      "2026-10-06",
      "2026-10-20",
    ]);
    for (const booking of list) {
      expect(booking.seriesId).toBe(made[0]?.seriesId);
    }
  });

  it("reports NotFound for an unknown series id, with that id", () => {
    const scope = createScope();
    const error = capture(() =>
      scope.run(cancelSeries, { input: { seriesId: "nope" } }),
    );
    if (!isError(error, "NotFound")) {
      expect.fail("expected NotFound");
    }
    expect(error.payload.id).toBe("nope");
  });

  it("reports NotFound on a second cancel of one series id", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 2,
      },
    });
    const seriesId = made[0]?.seriesId ?? "";
    scope.run(cancelSeries, { input: { seriesId } });
    const error = capture(() =>
      scope.run(cancelSeries, { input: { seriesId } }),
    );
    if (!isError(error, "NotFound")) {
      expect.fail("expected NotFound");
    }
    expect(error.payload).toEqual({ id: seriesId });
  });

  it("cancelSeries closes the draft of an occurrence it removes", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 2,
      },
    });
    const first = made[0];
    if (!first || first.seriesId === undefined) {
      expect.fail("missing occurrence");
    }
    scope.run(openEdit, { input: { id: first.id } });
    scope.run(cancelSeries, { input: { seriesId: first.seriesId } });
    expect(scope.resolve(editDraft)).toBeUndefined();
    const saveError = capture(() =>
      scope.run(saveEdit, {
        input: {
          id: first.id,
          title: "Renamed",
          room: "Cedar",
          start: 540,
          end: 600,
        },
      }),
    );
    if (!isError(saveError, "NotFound")) {
      expect.fail("expected NotFound");
    }
    expect(saveError.payload).toEqual({ id: first.id });
  });

  it("keeps the series tie when one occurrence is edited", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 2,
      },
    });
    const first = made[0];
    if (!first || first.seriesId === undefined) {
      expect.fail("missing occurrence");
    }
    scope.run(openEdit, { input: { id: first.id } });
    const updated = scope.run(saveEdit, {
      input: {
        id: first.id,
        title: "Renamed",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
      },
    });
    expect(updated.seriesId).toBe(first.seriesId);
    const closed = capture(() =>
      scope.run(discardEdit, { input: { id: first.id } }),
    );
    if (!isError(closed, "NotFound")) {
      expect.fail("expected NotFound");
    }
    expect(closed.payload).toEqual({ id: first.id });
  });

  it("books another room while a draft is open: the draft blocks nothing", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 1,
      },
    });
    const first = made[0];
    if (!first) expect.fail("missing occurrence");
    scope.run(openEdit, { input: { id: first.id } });
    const other = scope.run(bookBooking, {
      input: {
        title: "Planning",
        room: "Maple",
        date: "2026-10-06",
        start: 540,
        end: 600,
      },
    });
    expect(other.title).toBe("Planning");
    expect(scope.resolve(bookings)).toHaveLength(2);
  });
});

import { describe, expect, it } from "vitest";
import { createScope } from "@tinker/core";
import {
  bookBooking,
  bookings,
  bookSeries,
  cancelBooking,
  cancelSeries,
  isError,
} from "../src/index.ts";
import type { Booking, BookInput } from "../src/index.ts";

function book(
  scope: ReturnType<typeof createScope>,
  input: BookInput,
): Booking {
  return scope.run(bookBooking, { input });
}

describe("dates", () => {
  it("defaults to 2026-10-01 when no date is given", () => {
    const scope = createScope();
    const saved = book(scope, {
      title: "Standup",
      room: "Cedar",
      start: 540,
      end: 600,
    });
    expect(saved.date).toBe("2026-10-01");
    expect(saved.seriesId).toBeUndefined();
  });

  it("saves an explicit date", () => {
    const scope = createScope();
    const saved = book(scope, {
      title: "Standup",
      room: "Cedar",
      date: "2026-10-02",
      start: 540,
      end: 600,
    });
    expect(saved.date).toBe("2026-10-02");
  });

  it("rejects an unreal or malformed date with BadDate", () => {
    const scope = createScope();
    for (const date of ["2026-02-30", "2026-13-01", "2026-1-1", "not a date", 42]) {
      try {
        book(scope, {
          title: "Standup",
          room: "Cedar",
          date: date as unknown as string,
          start: 540,
          end: 600,
        });
        throw new Error("expected a throw");
      } catch (error) {
        expect(isError(error, "BadDate")).toBe(true);
        if (isError(error, "BadDate")) {
          expect(error.payload.date).toBe(date);
        }
      }
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("never clashes across dates but does clash within one date", () => {
    const scope = createScope();
    book(scope, {
      title: "Standup",
      room: "Cedar",
      date: "2026-10-01",
      start: 540,
      end: 600,
    });
    book(scope, {
      title: "Standup",
      room: "Cedar",
      date: "2026-10-02",
      start: 540,
      end: 600,
    });
    expect(scope.resolve(bookings)).toHaveLength(2);
    try {
      book(scope, {
        title: "Other",
        room: "Cedar",
        date: "2026-10-01",
        start: 570,
        end: 630,
      });
      throw new Error("expected a throw");
    } catch (error) {
      expect(isError(error, "Clash")).toBe(true);
    }
    expect(scope.resolve(bookings)).toHaveLength(2);
  });

  it("sorts by date, then start, then creation order", () => {
    const scope = createScope();
    const second = book(scope, {
      title: "Late day",
      room: "Cedar",
      date: "2026-10-02",
      start: 540,
      end: 600,
    });
    const first = book(scope, {
      title: "Early day",
      room: "Cedar",
      date: "2026-10-01",
      start: 600,
      end: 660,
    });
    const sameDayLater = book(scope, {
      title: "Same day later",
      room: "Maple",
      date: "2026-10-01",
      start: 700,
      end: 760,
    });
    const sameDateStartFirst = book(scope, {
      title: "Same date, same start",
      room: "Maple",
      date: "2026-10-02",
      start: 540,
      end: 600,
    });
    expect(scope.resolve(bookings).map((b) => b.id)).toEqual([
      first.id,
      sameDayLater.id,
      second.id,
      sameDateStartFirst.id,
    ]);
  });
});

describe("bookSeries", () => {
  it("books one occurrence per week, sharing a seriesId", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    expect(made.map((b) => b.date)).toEqual([
      "2026-10-06",
      "2026-10-13",
      "2026-10-20",
    ]);
    const seriesIds = new Set(made.map((b) => b.seriesId));
    expect(seriesIds.size).toBe(1);
    expect(made[0]?.seriesId).toBeTypeOf("string");
    expect(scope.resolve(bookings)).toHaveLength(3);
  });

  it("books nothing when any date clashes, reporting Clash", () => {
    const scope = createScope();
    book(scope, {
      title: "Existing",
      room: "Cedar",
      date: "2026-10-13",
      start: 540,
      end: 600,
    });
    try {
      scope.run(bookSeries, {
        input: {
          title: "Standup",
          room: "Cedar",
          date: "2026-10-06",
          start: 540,
          end: 600,
          weeks: 3,
        },
      });
      throw new Error("expected a throw");
    } catch (error) {
      expect(isError(error, "Clash")).toBe(true);
    }
    expect(scope.resolve(bookings)).toHaveLength(1);
  });

  it("reports BadCount for a weeks value outside 1..12 or not an integer", () => {
    const scope = createScope();
    for (const weeks of [0, 13, 1.5, Number.NaN]) {
      try {
        scope.run(bookSeries, {
          input: {
            title: "Standup",
            room: "Cedar",
            date: "2026-10-06",
            start: 540,
            end: 600,
            weeks,
          },
        });
        throw new Error("expected a throw");
      } catch (error) {
        expect(isError(error, "BadCount")).toBe(true);
        if (isError(error, "BadCount")) {
          expect(error.payload.weeks).toBe(weeks);
        }
      }
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("one occurrence cancel leaves the rest of its series", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    const middle = made[1];
    if (middle === undefined) {
      throw new Error("expected three occurrences");
    }
    scope.run(cancelBooking, { input: { id: middle.id } });
    expect(scope.resolve(bookings).map((b) => b.date)).toEqual([
      "2026-10-06",
      "2026-10-20",
    ]);
  });

  it("cancelSeries removes every occurrence", () => {
    const scope = createScope();
    const made = scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 3,
      },
    });
    scope.run(cancelSeries, { input: { seriesId: made[0]?.seriesId ?? "" } });
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("cancelSeries reports NotFound for an unknown id", () => {
    const scope = createScope();
    try {
      scope.run(cancelSeries, { input: { seriesId: "nope" } });
      throw new Error("expected a throw");
    } catch (error) {
      expect(isError(error, "NotFound")).toBe(true);
      if (isError(error, "NotFound")) {
        expect(error.payload.id).toBe("nope");
      }
    }
  });

  it("allows the same series slot in another room on the same dates", () => {
    const scope = createScope();
    scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Cedar",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 2,
      },
    });
    scope.run(bookSeries, {
      input: {
        title: "Standup",
        room: "Maple",
        date: "2026-10-06",
        start: 540,
        end: 600,
        weeks: 2,
      },
    });
    expect(scope.resolve(bookings)).toHaveLength(4);
  });
});

import { afterEach, beforeEach, afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { chromium } from 'playwright';
import type { Browser, Locator, Page } from 'playwright';

const baseUrl = inject('baseUrl');

let browser: Browser;
let page: Page;

beforeAll(async () => {
  browser = await chromium.launch({ headless: true });
  page = await browser.newPage();
});

afterAll(async () => {
  await browser?.close();
});

beforeEach(async () => {
  await page.goto(baseUrl);
});

const startingStock = [
  ['Cable', 'East', '8'],
  ['Cable', 'West', '2'],
  ['Stand', 'East', '3'],
  ['Stand', 'West', '1'],
];

type Area = Page | Locator;

function savedRows(area: Area, name: string): Locator {
  return area.getByRole('table', { name }).locator('tbody tr');
}

async function rows(area: Area, name: string): Promise<string[][]> {
  const found = await area.getByRole('table', { name }).locator('tbody tr').all();
  return Promise.all(
    found.map(async (row) => (await row.locator('td').allTextContents()).slice(0, 4)),
  );
}

function expectStock(area: Area, cells: string[][]): Promise<void> {
  return expect.poll(() => rows(area, 'Stock'), { timeout: 5000 }).toEqual(cells);
}

function expectMoves(area: Area, cells: string[][]): Promise<void> {
  return expect.poll(() => rows(area, 'Moves'), { timeout: 5000 }).toEqual(cells);
}

async function alertText(): Promise<string> {
  return (await page.getByRole('alert').textContent()) ?? '';
}

async function inputValue(label: string): Promise<string> {
  return page.getByLabel(label).inputValue();
}

describe('stock desk screen', () => {
  it('renders the four starting stock rows, an empty move list, and the default form', async () => {
    await expectStock(page, startingStock);
    await expectMoves(page, []);
    await expect(inputValue('Item')).resolves.toBe('Cable');
    await expect(inputValue('From')).resolves.toBe('East');
    await expect(inputValue('To')).resolves.toBe('West');
    await expect(inputValue('Quantity')).resolves.toBe('1');
    await expect(alertText()).resolves.toBe('');
  });

  it('a passing form move saves the move and keeps the form text', async () => {
    await page.getByLabel('Quantity').fill('3');
    await page.getByRole('button', { name: 'Move stock' }).click();
    await expectStock(page, [
      ['Cable', 'East', '5'],
      ['Cable', 'West', '5'],
      ['Stand', 'East', '3'],
      ['Stand', 'West', '1'],
    ]);
    await expectMoves(page, [['Cable', 'East', 'West', '3']]);
    await expect(inputValue('Item')).resolves.toBe('Cable');
    await expect(inputValue('Quantity')).resolves.toBe('3');
    await expect(alertText()).resolves.toBe('');
  });

  it('reports BadQuantity for unreadable quantity text and keeps it', async () => {
    await page.getByLabel('Quantity').fill('abc');
    await page.getByRole('button', { name: 'Move stock' }).click();
    await expect.poll(alertText, { timeout: 5000 }).toBe('BadQuantity');
    await expectStock(page, startingStock);
    await expectMoves(page, []);
    await expect(inputValue('Quantity')).resolves.toBe('abc');
  });

  it('reports BadQuantity for a cleared quantity', async () => {
    await page.getByLabel('Quantity').fill('');
