import { createRoot } from "react-dom/client";
import { BookingApp } from "./index.ts";

const container = document.getElementById("root");
if (container === null) {
  throw new Error("root container is missing");
}
createRoot(container).render(<BookingApp />);

import { createScope } from "@tinker/core";
import { describe, expect, it } from "vitest";
import {
  type BookInput,
  bookBooking,
  bookings,
  cancelBooking,
  isError,
} from "../src/index.ts";

function capture(action: () => unknown): unknown {
  try {
    action();
    return undefined;
  } catch (error) {
    return error;
  }
}

function book(input: BookInput): BookInput {
  return input;
}

describe("bookBooking", () => {
  it("rejects a second booking of the same room and slot", () => {
    const scope = createScope();
    const standup = scope.run(bookBooking, {
      input: book({ title: "Standup", room: "Cedar", start: 540, end: 600 }),
    });
    expect(standup).toEqual({
      id: standup.id,
      title: "Standup",
      room: "Cedar",
      date: "2026-10-01",
      start: 540,
      end: 600,
    });
    const clash = capture(() =>
      scope.run(bookBooking, {
        input: { title: "Again", room: "Cedar", start: 540, end: 600 },
      }),
    );
    expect(isError(clash, "Clash")).toBe(true);
    expect(scope.resolve(bookings)).toEqual([standup]);
  });

  it("allows the same slot in another room and a start when another ends", () => {
    const scope = createScope();
    const standup = scope.run(bookBooking, {
      input: book({ title: "Standup", room: "Cedar", start: 540, end: 600 }),
    });
    const maple = scope.run(bookBooking, {
      input: { title: "Maple copy", room: "Maple", start: 540, end: 600 },
    });
    const later = scope.run(bookBooking, {
      input: { title: "Planning", room: "Cedar", start: 600, end: 660 },
    });
    expect(scope.resolve(bookings)).toEqual([standup, maple, later]);
  });

  it("trims the saved title", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "  Standup  ", room: "Cedar", start: 60, end: 120 },
    });
    expect(saved.title).toBe("Standup");
  });

  it("rejects a blank title", () => {
    const scope = createScope();
    for (const title of ["", "   ", "\t\n"]) {
      const error = capture(() =>
        scope.run(bookBooking, {
          input: { title, room: "Cedar", start: 60, end: 120 },
        }),
      );
      expect(isError(error, "BlankTitle"), title).toBe(true);
      if (isError(error, "BlankTitle")) {
        expect(error.payload.title).toBe(title);
      }
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects an unknown room", () => {
    const scope = createScope();
    const error = capture(() =>
      scope.run(bookBooking, {
        input: { title: "Standup", room: "Attic", start: 60, end: 120 },
      }),
    );
    expect(isError(error, "UnknownRoom")).toBe(true);
    if (isError(error, "UnknownRoom")) {
      expect(error.payload.room).toBe("Attic");
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects a time outside 0..1439 or not an integer", () => {
    const scope = createScope();
    const badStarts = [-1, 1440, 25.5, Number.NaN, Number.POSITIVE_INFINITY];
    for (const start of badStarts) {
      const error = capture(() =>
        scope.run(bookBooking, {
          input: { title: "Standup", room: "Cedar", start, end: 120 },
        }),
      );
      expect(isError(error, "BadTime"), String(start)).toBe(true);
      if (isError(error, "BadTime")) {
        expect(error.payload.value).toBe(start);
      }
    }
    const badEnd = capture(() =>
      scope.run(bookBooking, {
        input: { title: "Standup", room: "Cedar", start: 120, end: 2000 },
      }),
    );
    expect(isError(badEnd, "BadTime")).toBe(true);
    if (isError(badEnd, "BadTime")) {
      expect(badEnd.payload.value).toBe(2000);
    }
    const notNumbers = capture(() =>
      scope.run(bookBooking, {
        rawInput: { title: "Standup", room: "Cedar", start: "9am", end: 120 },
      }),
    );
    expect(isError(notNumbers, "BadTime")).toBe(true);
    if (isError(notNumbers, "BadTime")) {
      expect(notNumbers.payload.value).toBe("9am");
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects an end at or before the start", () => {
    const scope = createScope();
    for (const [start, end] of [
      [600, 600],
      [600, 540],
    ] as const) {
      const error = capture(() =>
        scope.run(bookBooking, {
          input: { title: "Standup", room: "Cedar", start, end },
        }),
      );
      expect(isError(error, "EmptySlot"), `${start}-${end}`).toBe(true);
      if (isError(error, "EmptySlot")) {
        expect(error.payload).toEqual({ start, end });
      }
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects any overlap in one room and allows overlap across rooms", () => {
    const scope = createScope();
    scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const inside = capture(() =>
      scope.run(bookBooking, {
        input: { title: "Inside", room: "Cedar", start: 550, end: 590 },
      }),
    );
    expect(isError(inside, "Clash")).toBe(true);
    if (isError(inside, "Clash")) {
      expect(inside.payload).toEqual({ room: "Cedar", start: 550, end: 590 });
    }
    const across = scope.run(bookBooking, {
      input: { title: "Across", room: "Maple", start: 550, end: 590 },
    });
    expect(across.room).toBe("Maple");
  });

  it("allows back-to-back bookings: one starts exactly when another ends", () => {
    const scope = createScope();
    const early = scope.run(bookBooking, {
      input: { title: "Early", room: "Cedar", start: 540, end: 600 },
    });
    const late = scope.run(bookBooking, {
      input: { title: "Late", room: "Cedar", start: 600, end: 660 },
    });
    const tail = scope.run(bookBooking, {
      input: { title: "Tail", room: "Cedar", start: 480, end: 540 },
    });
    expect(scope.resolve(bookings)).toEqual([tail, early, late]);
  });

  it("lists bookings by start time, then creation order", () => {
    const scope = createScope();
    const b = scope.run(bookBooking, {
      input: { title: "B", room: "Cedar", start: 600, end: 660 },
    });
    const a2 = scope.run(bookBooking, {
      input: { title: "A2", room: "Cedar", start: 540, end: 600 },
    });
    const a1 = scope.run(bookBooking, {
      input: { title: "A1", room: "Maple", start: 540, end: 600 },
    });
    expect(scope.resolve(bookings)).toEqual([a2, a1, b]);
  });

  it("leaves saved bookings unchanged on a failed action", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    capture(() =>
      scope.run(bookBooking, {
        input: { title: "Bad", room: "", start: 1, end: 0 },
      }),
    );
    capture(() =>
      scope.run(bookBooking, {
        input: { title: "Clash", room: "Cedar", start: 550, end: 590 },
      }),
    );
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("creates exactly one booking for two calls on an empty slot", () => {
    const scope = createScope();
    const first = capture(() =>
      scope.run(bookBooking, {
        input: { title: "First", room: "Cedar", start: 540, end: 600 },
      }),
    );
    expect(isError(first, "Clash")).toBe(false);
    const second = capture(() =>
      scope.run(bookBooking, {
        input: { title: "Second", room: "Cedar", start: 545, end: 595 },
      }),
    );
    expect(isError(second, "Clash")).toBe(true);
    const list = scope.resolve(bookings);
    expect(list).toHaveLength(1);
    expect(list[0]?.title).toBe("First");
  });
});

describe("cancelBooking", () => {
  it("cancel removes the booking so its slot can be booked again", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(cancelBooking, { input: { id: saved.id } });
    expect(scope.resolve(bookings)).toEqual([]);
    const again = scope.run(bookBooking, {
      input: { title: "New", room: "Cedar", start: 540, end: 600 },
    });
    expect(again.title).toBe("New");
  });

  it("reports NotFound on a second cancel of one id", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(cancelBooking, { input: { id: saved.id } });
    const error = capture(() =>
      scope.run(cancelBooking, { input: { id: saved.id } }),
    );
    expect(isError(error, "NotFound")).toBe(true);
    if (isError(error, "NotFound")) {
      expect(error.payload.id).toBe(saved.id);
    }
  });

  it("reports NotFound for an unknown id", () => {
    const scope = createScope();
    const error = capture(() =>
      scope.run(cancelBooking, { input: { id: "nope" } }),
    );
    expect(isError(error, "NotFound")).toBe(true);
    if (isError(error, "NotFound")) {
      expect(error.payload.id).toBe("nope");
    }
  });
});

/**
 * The stock-desk screen: form, tables, editor, filters, undo, and the shared
 * error notice. Every value shown is read from a core cell; every action runs
 * an operation.
 */
import { useId } from 'react';
import type { ReactNode } from 'react';
import { createScope } from '@tinker/core';
import { ScopeProvider, useData, useRun } from '@tinker/react';
import {
  discardMoveEdit,
  editDraft,
  editFormFrom,
  editFormItem,
  editFormQuantity,
  editFormTo,
  formFrom,
  formItem,
  formQuantity,
  formTo,
  moveFilter,
  moveStock,
  moves,
  notice,
  openMoveEdit,
  saveMoveEdit,
  setMoveFilter,
  stock,
  undoMove,
} from './desk';
import type { MoveFilter } from './desk';

/**
 * Parse number text at the input boundary: readable text becomes a number,
 * anything else keeps its text so the operation can report it.
 */
function parseQuantityText(text: string): number | string {
  if (text.trim() === '') return text;
  const parsed = Number(text);
  return Number.isFinite(parsed) ? parsed : text;
}

function LabeledInput(props: { label: string; value: string; onChange: (next: string) => void }): ReactNode {
  const id = useId();
  return (
    <label htmlFor={id}>
      {props.label}
      <input
        id={id}
        value={props.value}
        onChange={(event) => props.onChange(event.target.value)}
      />
    </label>
  );
}

function Notice(): ReactNode {
  const kind = useData(notice);
  return <div role="alert">{kind ?? ''}</div>;
}

function MoveForm(): ReactNode {
  const [item, setItem] = useData(formItem, { writable: true });
  const [from, setFrom] = useData(formFrom, { writable: true });
  const [to, setTo] = useData(formTo, { writable: true });
  const [quantity, setQuantity] = useData(formQuantity, { writable: true });
  const runMove = useRun(moveStock);
  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        runMove.run({
          rawInput: {
            item,
            from,
            to,
            quantity: parseQuantityText(quantity),
          },
        });
      }}
    >
      <LabeledInput label="Item" value={item} onChange={setItem} />
      <LabeledInput label="From" value={from} onChange={setFrom} />
      <LabeledInput label="To" value={to} onChange={setTo} />
      <LabeledInput label="Quantity" value={quantity} onChange={setQuantity} />
      <button type="submit">Move stock</button>
    </form>
  );
}

function StockTable(): ReactNode {
  const rows = useData(stock);
  return (
    <table>
      <caption>Stock</caption>
      <thead>
        <tr>
          <th>Item</th>
          <th>Place</th>
          <th>Quantity</th>
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr key={`${row.item} ${row.place}`}>
            <td>{row.item}</td>
            <td>{row.place}</td>
            <td>{row.quantity}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function MoveFilters(): ReactNode {
  const runFilter = useRun(setMoveFilter);
  const choices: readonly MoveFilter[] = ['All', 'Cable', 'Stand'];
  return (
    <div>
      {choices.map((choice) => (
        <button key={choice} type="button" onClick={() => runFilter.run({ input: choice })}>
          {choice}
        </button>
      ))}
    </div>
  );
}

function MovesTable(): ReactNode {
  const saved = useData(moves);
  const filter = useData(moveFilter);
  const rows = filter === 'All' ? saved : saved.filter((move) => move.item === filter);
  const open = useRun(openMoveEdit);
  return (
    <table>
      <caption>Moves</caption>
      <thead>
        <tr>
