/** Payload type for each app error. The registry is the only place the app throws. */
type Payloads = {
  BlankTitle: { title: string };
  UnknownRoom: { room: string };
  BadTime: { value: unknown };
  EmptySlot: { start: number; end: number };
  Clash: { room: string; start: number; end: number };
  NotFound: { id: string };
  EmptyUndo: Record<string, never>;
  BadDate: { date: unknown };
  BadCount: { weeks: unknown };
};

export declare namespace Errors {
  /** Every app error name. */
  type Name = keyof Payloads;
  /** The typed payload carried by one error name. */
  type Payload<N extends Name> = Payloads[N];
  /** An app error: identified by `kind`, carrying a typed `payload`. */
  type Of<N extends Name = Name> = Error & {
    readonly kind: N;
    readonly payload: Payload<N>;
  };
}

const names = [
  "BlankTitle",
  "UnknownRoom",
  "BadTime",
  "EmptySlot",
  "Clash",
  "NotFound",
  "EmptyUndo",
  "BadDate",
  "BadCount",
] as const;

function isName(value: unknown): value is Errors.Name {
  return names.some((name) => name === value);
}

/** Narrow an unknown error to one registry entry; callers rethrow on mismatch. */
export function isError<N extends Errors.Name>(
  value: unknown,
  kind: N,
): value is Errors.Of<N> {
  return (
    value instanceof Error &&
    "kind" in value &&
    value.kind === kind &&
    "payload" in value
  );
}

/** Build one registry error: an `Error` carrying its `kind` and typed `payload`. */
export function appError<N extends Errors.Name>(
  kind: N,
  payload: Errors.Payload<N>,
): Errors.Of<N> {
  return Object.assign(new Error(kind), { kind, payload });
}

/** The registry name an error carries, or `undefined` for anything else. */
export function errorKind(value: unknown): Errors.Name | undefined {
  if (value instanceof Error && "kind" in value && isName(value.kind)) {
    return value.kind;
  }
  return undefined;
}

