export type SelectedRoom = Room | "All";

/** The booking form cell. It starts at the round 3 defaults and keeps typed text after a
 * failure; a passing booking clears only the title. */
export const bookForm: Data.Cell<BookForm> = data<BookForm>({
  label: "bookForm",
  initial: { title: "", room: "", date: DEFAULT_DATE, start: "", end: "", weeks: "1" },
});

/** The text of no draft at all: what a closed draft leaves behind. */
const EMPTY_EDIT: EditText = { title: "", room: "", date: DEFAULT_DATE, start: "", end: "" };

/** Text of the one open edit draft. Opening a booking writes its fields here, and the text is
 * dropped as soon as the draft closes, so the fields always show the booking being edited. */
export const editText: Data.Cell<EditText> = data<EditText>({
  label: "editText",
  initial: EMPTY_EDIT,
});

/** Which rooms the list shows; filtering hides rows and never deletes them. */
export const selectedRoom: Data.Cell<SelectedRoom> = data<SelectedRoom>({
  label: "selectedRoom",
  initial: "All",
});

