/** Typing into the booking form: the keystroke lands in the form cell and nothing else moves. */
export const typeBook: Operation.Handle<void, { readonly field: BookField; readonly value: string }> =
  operation<TypeBookDeps, void, { readonly field: BookField; readonly value: string }>({
    label: "typeBook",
    depends: { form: bookForm.controller },
    run: (deps, ctx) => {
      deps.form.update((previous) => ({ ...previous, [ctx.input.field]: ctx.input.value }));
    },
  });

