/** Opening the series-title editor for one row: the editor takes the clicked row's series id
 * and that row's own saved title, so an occurrence edited away from the series' first title
 * still opens with the title on its own row. Any title the previous editor held is dropped.
 * A row outside a series no remaining booking belongs to reports `NotFound`. */
export const pressRenameSeries: Operation.Handle<
  void,
  { readonly seriesId: string; readonly id: string }
> = operation<OpenSeriesDeps, void, { readonly seriesId: string; readonly id: string }>({
  label: "pressRenameSeries",
  depends: {
    list: bookings.controller,
    editor: seriesEdit.controller,
    alert: alertKind.controller,
  },
  run: (deps, ctx) => {
    try {
      const clicked = deps.list
        .get()
        .find(
          (booking) => booking.id === ctx.input.id && booking.seriesId === ctx.input.seriesId,
        );
      if (clicked === undefined) {
        throw appError("NotFound", { id: ctx.input.seriesId });
      }
      deps.editor.set({ seriesId: ctx.input.seriesId, title: clicked.title });
      deps.alert.set(undefined);
    } catch (thrown) {
      deps.alert.set(errorKind(thrown));
      throw thrown;
    }
  },
});

