import { describe, expect, it } from "vitest";
import { createScope, type Scope } from "@tinker/core";
import {
  bookings,
  bookBooking,
  bookSeries,
  cancelBooking,
  cancelSeries,
  editDraft,
  isError,
  openEdit,
  saveEdit,
  type Errors,
} from "../src/index.ts";

function freshScope(): Scope.Handle {
  return createScope();
}

/** Run a call that must fail; rethrow a wrong failure, report a silent success. */
function expectKind<K extends Errors.Name>(call: () => unknown, kind: K): Errors.Of<K> {
  try {
    call();
  } catch (thrown) {
    if (isError(thrown, kind)) {
      return thrown;
    }
    throw thrown;
  }
  throw new Error(`expected the call to fail with ${kind}`);
}

/** `date|start` fingerprints of the saved list, for order and content checks. */
function stamps(scope: Scope.Handle): string[] {
  return scope.resolve(bookings).map((booking) => `${booking.date}|${booking.start}`);
}

describe("dates", () => {
  it("an input without a date saves the booking on 2026-10-01", () => {
    const scope = freshScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    expect(saved.date).toBe("2026-10-01");
    expect(scope.resolve(bookings)[0]?.date).toBe("2026-10-01");
  });

  it("input carrying date 2026-10-07 saves that date on the booking", () => {
    const scope = freshScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-07", start: 540, end: 600 },
    });
    expect(saved.date).toBe("2026-10-07");
  });

  it("rejects a date that is not a real YYYY-MM-DD day with BadDate", () => {
    const scope = freshScope();
    // Typed strings that are still not real days, through the typed input.
    const badTexts: readonly string[] = [
      "2026-02-30",
      "2026-13-01",
      "2026-00-10",
      "2026-10-00",
      "10/01/2026",
      "2026-10-1",
      "October 1",
      "",
      " 2026-10-01 ",
    ];
    for (const date of badTexts) {
      const failure = expectKind(
        () =>
          scope.run(bookBooking, {
            input: { title: "X", room: "Cedar", date, start: 540, end: 600 },
          }),
        "BadDate",
      );
      expect(failure.payload.date).toBe(date);
    }
    // Values that are not text at all arrive through the raw boundary.
    const badValues: readonly unknown[] = [20261001, null, true];
    for (const date of badValues) {
      const failure = expectKind(
        () =>
          scope.run(bookBooking, {
            rawInput: { title: "X", room: "Cedar", date, start: 540, end: 600 },
          }),
        "BadDate",
      );
      expect(failure.payload.date).toBe(date);
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("keeps leap days and month edges as real days", () => {
    const scope = freshScope();
    for (const date of ["2028-02-29", "2026-02-28", "2026-12-31"]) {
      scope.run(bookBooking, {
        input: { title: `T ${date}`, room: "Cedar", date, start: 0, end: 30 },
      });
    }
    expect(scope.resolve(bookings).map((booking) => booking.date)).toEqual([
      "2026-02-28",
      "2026-12-31",
      "2028-02-29",
    ]);
  });

  it("never clashes the same slot on two dates", () => {
    const scope = freshScope();
    scope.run(bookBooking, {
      input: { title: "First day", room: "Cedar", date: "2026-10-01", start: 540, end: 600 },
    });
    const other = scope.run(bookBooking, {
      input: { title: "Second day", room: "Cedar", date: "2026-10-02", start: 540, end: 600 },
    });
    expect(other.date).toBe("2026-10-02");
    expect(scope.resolve(bookings)).toHaveLength(2);
  });

  it("partial overlap on 2026-10-01 reports Clash while Maple on 2026-10-01 and Cedar on 2026-10-05 both save", () => {
    const scope = freshScope();
    scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-01", start: 540, end: 600 },
    });
    const clash = expectKind(
      () =>
        scope.run(bookBooking, {
          input: { title: "Dup", room: "Cedar", date: "2026-10-01", start: 570, end: 630 },
        }),
      "Clash",
    );
    // The payload reports the requested slot, as in round 1.
    expect(clash.payload).toEqual({ room: "Cedar", start: 570, end: 630 });
    // The other room on that date, and Cedar on another date, both still book.
    scope.run(bookBooking, {
      input: { title: "Other room", room: "Maple", date: "2026-10-01", start: 540, end: 600 },
    });
    scope.run(bookBooking, {
      input: { title: "Other day", room: "Cedar", date: "2026-10-05", start: 540, end: 600 },
    });
    expect(scope.resolve(bookings)).toHaveLength(3);
  });

  it("lists by date, then start time, then creation order", () => {
    const scope = freshScope();
    scope.run(bookBooking, { input: { title: "Later day", room: "Cedar", date: "2026-10-03", start: 60, end: 90 } });
    scope.run(bookBooking, { input: { title: "Same twin A", room: "Cedar", date: "2026-10-02", start: 540, end: 570 } });
    scope.run(bookBooking, { input: { title: "Same twin B", room: "Maple", date: "2026-10-02", start: 540, end: 570 } });
    scope.run(bookBooking, { input: { title: "Early day", room: "Cedar", date: "2026-10-02", start: 600, end: 660 } });
    expect(scope.resolve(bookings).map((booking) => booking.title)).toEqual([
      "Same twin A",
      "Same twin B",
      "Early day",
      "Later day",
    ]);
    expect(stamps(scope)).toEqual([
      "2026-10-02|540",
      "2026-10-02|540",
      "2026-10-02|600",
      "2026-10-03|60",
    ]);
  });
});

describe("bookSeries", () => {
  it("books weeks dates seven days apart under one seriesId", () => {
    const scope = freshScope();
    const made = scope.run(bookSeries, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 3 },
    });
    expect(made.map((booking) => booking.date)).toEqual(["2026-10-06", "2026-10-13", "2026-10-20"]);
    expect(made.every((booking) => booking.seriesId !== undefined)).toBe(true);
    expect(new Set(made.map((booking) => booking.seriesId)).size).toBe(1);
    expect(new Set(made.map((booking) => booking.id)).size).toBe(3);
    expect(scope.resolve(bookings)).toEqual(made);
  });

  it("gives a one-off booking no seriesId key", () => {
    const scope = freshScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Once", room: "Cedar", start: 0, end: 30 },
    });
    expect("seriesId" in saved).toBe(false);
    expect(scope.resolve(bookings)[0]).not.toHaveProperty("seriesId");
  });

  it("books one date when weeks is 1", () => {
    const scope = freshScope();
    const made = scope.run(bookSeries, {
      input: { title: "Solo", room: "Cedar", date: "2026-10-06", start: 0, end: 30, weeks: 1 },
    });
    expect(made).toHaveLength(1);
    expect(made[0]?.seriesId).not.toBeUndefined();
  });

  it("rejects weeks outside 1..12 or that are not integers with BadCount", () => {
    const scope = freshScope();
    const badNumbers: readonly number[] = [0, 13, -1, 1.5, Number.NaN];
    for (const weeks of badNumbers) {
      const failure = expectKind(
        () =>
          scope.run(bookSeries, {
            input: { title: "X", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks },
          }),
        "BadCount",
      );
      expect(failure.payload.weeks).toBe(weeks);
    }
    // Values that are not numbers at all arrive through the raw boundary.
    const badValues: readonly unknown[] = ["3", null, undefined];
    for (const weeks of badValues) {
      const failure = expectKind(
        () =>
          scope.run(bookSeries, {
            rawInput: { title: "X", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks },
          }),
        "BadCount",
      );
      expect(failure.payload.weeks).toBe(weeks);
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("reports BadCount from rawInput weeks, not a schema failure", () => {
    const scope = freshScope();
    const failure = expectKind(
      () =>
        scope.run(bookSeries, {
          rawInput: { title: "X", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: "2" },
        }),
      "BadCount",
    );
    expect(failure.payload.weeks).toBe("2");
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("books nothing when any date clashes: the whole series fails with Clash", () => {
    const scope = freshScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Taken", room: "Cedar", date: "2026-10-13", start: 540, end: 600 },
    });
    expectKind(
      () =>
        scope.run(bookSeries, {
          input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 3 },
        }),
      "Clash",
    );
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("rejects a blank title, unknown room, out-of-range time, empty slot, and bad date with that kind", () => {
    const scope = freshScope();
    expectKind(
      () =>
        scope.run(bookSeries, {
          input: { title: "   ", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 2 },
        }),
      "BlankTitle",
    );
    expectKind(
      () =>
        scope.run(bookSeries, {
          input: { title: "X", room: "Kitchen", date: "2026-10-06", start: 540, end: 600, weeks: 2 },
        }),
      "UnknownRoom",
    );
    expectKind(
      () =>
        scope.run(bookSeries, {
          input: { title: "X", room: "Cedar", date: "2026-10-31", start: 1440, end: 1470, weeks: 2 },
        }),
      "BadTime",
    );
    expectKind(
      () =>
        scope.run(bookSeries, {
          input: { title: "X", room: "Cedar", date: "2026-10-31", start: 600, end: 540, weeks: 2 },
        }),
      "EmptySlot",
    );
    expectKind(
      () =>
        scope.run(bookSeries, {
          input: { title: "X", room: "Cedar", date: "2026-10-32", start: 540, end: 600, weeks: 2 },
        }),
      "BadDate",
    );
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("two series in different rooms at one time both save: four rows, two dates", () => {
    const scope = freshScope();
    scope.run(bookSeries, {
      input: { title: "Cedar weekly", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 2 },
    });
    scope.run(bookSeries, {
      input: { title: "Maple weekly", room: "Maple", date: "2026-10-06", start: 540, end: 600, weeks: 2 },
    });
    expect(scope.resolve(bookings)).toHaveLength(4);
    expect(stamps(scope)).toEqual([
      "2026-10-06|540",
      "2026-10-06|540",
      "2026-10-13|540",
      "2026-10-13|540",
    ]);
  });
});

describe("cancel series", () => {
  it("cancels one occurrence by id and leaves the rest of its series", () => {
    const scope = freshScope();
    const made = scope.run(bookSeries, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 3 },
    });
    scope.run(cancelBooking, { input: { id: made[1]!.id } });
    const left = scope.resolve(bookings);
    expect(left.map((booking) => booking.date)).toEqual(["2026-10-06", "2026-10-20"]);
    // Only the canceled day frees up; the other two dates still clash.
    expectKind(
      () =>
        scope.run(bookBooking, {
          input: { title: "Dup", room: "Cedar", date: "2026-10-06", start: 540, end: 600 },
        }),
      "Clash",
    );
    scope.run(bookBooking, {
      input: { title: "Free now", room: "Cedar", date: "2026-10-13", start: 540, end: 600 },
    });
    expect(scope.resolve(bookings)).toHaveLength(3);
  });

  it("cancels every occurrence by the series id", () => {
    const scope = freshScope();
    const made = scope.run(bookSeries, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 3 },
    });
    const result = scope.run(cancelSeries, { input: { seriesId: made[0]!.seriesId! } });
    expect(result).toBeUndefined();
    expect(scope.resolve(bookings)).toEqual([]);
    scope.run(bookBooking, {
      input: { title: "Again", room: "Cedar", date: "2026-10-13", start: 540, end: 600 },
    });
    expect(scope.resolve(bookings)).toHaveLength(1);
  });

  it("cancelSeries drops its two ids and keeps the other series plus the one-off", () => {
    const scope = freshScope();
    const series = scope.run(bookSeries, {
      input: { title: "Keep me", room: "Maple", date: "2026-10-06", start: 0, end: 30, weeks: 2 },
    });
    const doomed = scope.run(bookSeries, {
      input: { title: "Doomed", room: "Cedar", date: "2026-10-06", start: 0, end: 30, weeks: 2 },
    });
    const once = scope.run(bookBooking, {
      input: { title: "Once", room: "Cedar", date: "2026-10-20", start: 0, end: 30 },
    });
    scope.run(cancelSeries, { input: { seriesId: doomed[0]!.seriesId! } });
    const ids = scope.resolve(bookings).map((booking) => booking.id);
    expect(ids).toContain(once.id);
    expect(ids).toContain(series[0]!.id);
    expect(ids).not.toContain(doomed[0]!.id);
    expect(scope.resolve(bookings)).toHaveLength(3);
  });

  it("reports NotFound with the id on an unknown or already-canceled series id", () => {
    const scope = freshScope();
    const missing = expectKind(
      () => scope.run(cancelSeries, { input: { seriesId: "ghost" } }),
      "NotFound",
    );
    expect(missing.payload.id).toBe("ghost");
    const made = scope.run(bookSeries, {
      input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 2 },
