import { describe, expect, it } from "vitest";
import { createScope, type Scope } from "@tinker/core";
import {
  bookings,
  bookBooking,
  bookSeries,
  cancelBooking,
  editDraft,
  isError,
  openEdit,
  renameSeries,
  saveEdit,
  undoChange,
  type Errors,
} from "../src/index.ts";

function freshScope(): Scope.Handle {
  return createScope();
}

/** Run a call that must fail; rethrow a wrong failure, report a silent success. */
function expectKind<K extends Errors.Name>(call: () => unknown, kind: K): Errors.Of<K> {
  try {
    call();
  } catch (thrown) {
    if (isError(thrown, kind)) {
      return thrown;
    }
    throw thrown;
  }
  throw new Error(`expected the call to fail with ${kind}`);
}

function titles(scope: Scope.Handle): string[] {
  return scope.resolve(bookings).map((booking) => booking.title);
}

/** Book "Standup" in Cedar, 09:00-10:00, for three weeks from 2026-10-06. */
function bookStandupSeries(scope: Scope.Handle): void {
  scope.run(bookSeries, {
    input: { title: "Standup", room: "Cedar", date: "2026-10-06", start: 540, end: 600, weeks: 3 },
  });
}

/** The series id the saved occurrences titled `title` share. */
function seriesIdOf(scope: Scope.Handle, title: string): string {
  const member = scope.resolve(bookings).find((booking) => booking.title === title);
  if (member === undefined || member.seriesId === undefined) {
    throw new Error(`no series member titled ${title}`);
  }
  return member.seriesId;
}

describe("renameSeries", () => {
  it("trims the new title and renames every occurrence, keeping ids, dates, rooms, times, and order", () => {
    const scope = freshScope();
    bookStandupSeries(scope);
    scope.run(bookBooking, {
      input: { title: "One-off", room: "Maple", date: "2026-10-06", start: 540, end: 600 },
    });
    const before = scope.resolve(bookings);
    const seriesId = seriesIdOf(scope, "Standup");

    const renamed = scope.run(renameSeries, { input: { seriesId, title: "  Sync  " } });

    expect(renamed.map((booking) => booking.title)).toEqual(["Sync", "Sync", "Sync"]);
    expect(scope.resolve(bookings)).toEqual(
      before.map((booking) => (booking.seriesId === seriesId ? { ...booking, title: "Sync" } : booking)),
    );
  });

  it("renaming one series leaves another series and a one-off booking untouched", () => {
    const scope = freshScope();
    bookStandupSeries(scope);
    scope.run(bookSeries, {
      input: { title: "Review", room: "Maple", date: "2026-10-06", start: 540, end: 600, weeks: 2 },
    });
    scope.run(bookBooking, {
      input: { title: "Solo", room: "Cedar", date: "2026-10-06", start: 660, end: 720 },
    });
    const seriesId = seriesIdOf(scope, "Standup");

    scope.run(renameSeries, { input: { seriesId, title: "Sync" } });

    expect(titles(scope)).toEqual(["Sync", "Review", "Solo", "Sync", "Review", "Sync"]);
  });

  it("returns the renamed bookings in saved list order rather than creation order", () => {
    const scope = freshScope();
    bookStandupSeries(scope);
    const last = scope
      .resolve(bookings)
      .find((booking) => booking.date === "2026-10-20" && booking.title === "Standup");
    if (last === undefined) {
      throw new Error("the last occurrence of the series is missing");
    }
    scope.run(openEdit, { input: { id: last.id } });
    scope.run(saveEdit, {
      input: { id: last.id, title: "Standup", room: "Cedar", date: "2026-10-05", start: 540, end: 600 },
    });
    const seriesId = seriesIdOf(scope, "Standup");

    const renamed = scope.run(renameSeries, { input: { seriesId, title: "Sync" } });

    const listOrder = scope
      .resolve(bookings)
      .filter((booking) => booking.seriesId === seriesId)
      .map((booking) => booking.id);
    expect(renamed.map((booking) => booking.id)).toEqual(listOrder);
    expect(listOrder[0]).toBe(last.id);
    expect(renamed.map((booking) => booking.title)).toEqual(["Sync", "Sync", "Sync"]);
  });

  it("rejects a blank new title with BlankTitle, changes nothing, and adds no undo step", () => {
    const scope = freshScope();
    bookStandupSeries(scope);
    const seriesId = seriesIdOf(scope, "Standup");
    const before = scope.resolve(bookings);

    const failure = expectKind(
      () => scope.run(renameSeries, { input: { seriesId, title: "   " } }),
      "BlankTitle",
    );

    expect(failure.payload).toEqual({ title: "   " });
    expect(scope.resolve(bookings)).toEqual(before);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([]);
    expectKind(() => scope.run(undoChange, {}), "EmptyUndo");
  });

  it("reports NotFound with the series id for a series that has no remaining booking", () => {
    const scope = freshScope();
    scope.run(bookBooking, { input: { title: "Solo", room: "Cedar", start: 0, end: 30 } });
    const before = scope.resolve(bookings);

    const failure = expectKind(
      () => scope.run(renameSeries, { input: { seriesId: "s-missing", title: "Sync" } }),
      "NotFound",
    );

    expect(failure.payload).toEqual({ id: "s-missing" });
    expect(scope.resolve(bookings)).toEqual(before);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([]);
    expectKind(() => scope.run(undoChange, {}), "EmptyUndo");
  });

  it("renames only the occurrences that remain after one is canceled", () => {
    const scope = freshScope();
    bookStandupSeries(scope);
    const middle = scope.resolve(bookings).find((booking) => booking.date === "2026-10-13");
    if (middle === undefined) {
      throw new Error("the middle occurrence of the series is missing");
    }
    scope.run(cancelBooking, { input: { id: middle.id } });
    const seriesId = seriesIdOf(scope, "Standup");

    const renamed = scope.run(renameSeries, { input: { seriesId, title: "Sync" } });

    expect(renamed.map((booking) => booking.date)).toEqual(["2026-10-06", "2026-10-20"]);
    expect(titles(scope)).toEqual(["Sync", "Sync"]);
  });

  it("records one undo step for the whole series and undo restores the exact prior list", () => {
    const scope = freshScope();
    bookStandupSeries(scope);
    const seriesId = seriesIdOf(scope, "Standup");
    const before = scope.resolve(bookings);

    scope.run(renameSeries, { input: { seriesId, title: "Sync" } });
    expect(titles(scope)).toEqual(["Sync", "Sync", "Sync"]);

    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual(before);
    scope.run(undoChange, {});
    expect(scope.resolve(bookings)).toEqual([]);
    const failure = expectKind(() => scope.run(undoChange, {}), "EmptyUndo");
    expect(failure.payload).toEqual({});
  });

  it("renaming a series leaves an open booking draft alone even when it belongs to that series", () => {
    const scope = freshScope();
    bookStandupSeries(scope);
    const seriesId = seriesIdOf(scope, "Standup");
    const member = scope.resolve(bookings).find((booking) => booking.date === "2026-10-06");
    if (member === undefined) {
      throw new Error("the first occurrence of the series is missing");
    }
    const draft = scope.run(openEdit, { input: { id: member.id } });
    expect(draft.title).toBe("Standup");

    scope.run(renameSeries, { input: { seriesId, title: "Sync" } });

    expect(scope.resolve(editDraft)).toEqual(draft);
    const saved = scope.run(saveEdit, {
      input: { id: member.id, title: "Drafted", room: "Cedar", date: "2026-10-06", start: 540, end: 600 },
    });
    expect(saved.title).toBe("Drafted");
    expect(titles(scope)).toEqual(["Drafted", "Sync", "Sync"]);
  });

  it("keeps scopes separate: a rename in one scope leaves the other scope's series alone", () => {
    const first = freshScope();
    const second = freshScope();
    bookStandupSeries(first);
    bookStandupSeries(second);

    first.run(renameSeries, { input: { seriesId: seriesIdOf(first, "Standup"), title: "Sync" } });

    expect(titles(first)).toEqual(["Sync", "Sync", "Sync"]);
    expect(titles(second)).toEqual(["Standup", "Standup", "Standup"]);
  });
});

import { operation } from '@tinker/core';
import type { Operation, Scope } from '@tinker/core';
import { appError } from './errors.ts';
import type { Errors, Payloads } from './errors.ts';
import { inputOf, readId, readItem, readPlace, readQuantity } from './fields.ts';
import type { Raise } from './fields.ts';
import {
  editDraft,
  editFrom,
  editItem,
  editQuantity,
  editTo,
  filter,
  formFrom,
  formItem,
  formQuantity,
  formTo,
  history,
  issueId,
  idSeq,
  moves,
  notice,
  quantityAt,
  stock,
  transfer,
} from './model.ts';
import type { Filter, Snapshot } from './model.ts';
import type { EditMoveInput, Move, MoveInput, Stock } from './types.ts';

/** A rule reporter that also records the failure in the shared notice cell. */
const noticeRaiser =
  (setNotice: (error: Errors.Of | undefined) => void): Raise =>
  (kind: Errors.Name, payload: Payloads[Errors.Name]): never => {
    const error = appError(kind, payload);
    setNotice(error);
    throw error;
  };

/** Save one undo step for the change that is about to land. */
const pushHistory = (
  undo: Scope.DataController<readonly Snapshot[]>,
  current: readonly Stock[],
  saved: readonly Move[],
  setNotice: (error: Errors.Of | undefined) => void,
): void => {
  undo.set([...undo.get(), { stock: current, moves: saved }]);
  setNotice(undefined);
};

/** Move stock between two places, saving one Move. */
export const moveStock: Operation.Handle<Move, MoveInput> = operation({
  label: 'moveStock',
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    idSeq: idSeq.controller,
    history: history.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    const raise: Raise = noticeRaiser(deps.notice.set);
    const raw = inputOf(ctx);
    const item = readItem(raw, raise);
    const from = readPlace(raw, 'from', raise);
    const to = readPlace(raw, 'to', raise);
    const quantity = readQuantity(raw, raise);
    if (from === to) raise('SamePlace', { place: from });
    const current = deps.stock.get();
    const available = quantityAt(current, item, from);
    if (available < quantity) {
      raise('ShortStock', { item, place: from, available, requested: quantity });
    }
    const before = deps.moves.get();
    const saved: Move = { id: issueId(deps.idSeq), item, from, to, quantity };
    pushHistory(deps.history, current, before, deps.notice.set);
    deps.stock.set(transfer(current, item, from, to, quantity));
    deps.moves.set([...before, saved]);
    return saved;
  },
});

/** The text cells a screen field writes through `typeText`. */
export type TextTarget =
  | 'formItem'
  | 'formFrom'
  | 'formTo'
  | 'formQuantity'
  | 'editItem'
  | 'editFrom'
  | 'editTo'
  | 'editQuantity';

/** Write the text a labeled field is showing into the cell that owns that field. */
export const typeText: Operation.Handle<void, { target: TextTarget; value: string }> = operation({
  label: 'typeText',
  depends: {
    formItem: formItem.controller,
    formFrom: formFrom.controller,
    formTo: formTo.controller,
    formQuantity: formQuantity.controller,
    editItem: editItem.controller,
    editFrom: editFrom.controller,
    editTo: editTo.controller,
    editQuantity: editQuantity.controller,
    notice: notice.controller,
  },
  run: (deps, ctx: Operation.Ctx<{ target: TextTarget; value: string }>) => {
    deps[ctx.input.target].set(ctx.input.value);
    deps.notice.set(undefined);
  },
});

/** Show one item's moves only, leaving the saved list and stock alone. */
export const chooseFilter: Operation.Handle<void, { value: Filter }> = operation({
  label: 'chooseFilter',
  depends: { filter: filter.controller, notice: notice.controller },
  run: (deps, ctx: Operation.Ctx<{ value: Filter }>) => {
    deps.filter.set(ctx.input.value);
    deps.notice.set(undefined);
  },
});

/** Copy one saved move into the editor, replacing any open draft. */
export const openMoveEdit: Operation.Handle<Move, { id: string }> = operation({
  label: 'openMoveEdit',
  depends: {
    moves: moves.controller,
    editDraft: editDraft.controller,
    editItem: editItem.controller,
    editFrom: editFrom.controller,
    editTo: editTo.controller,
    editQuantity: editQuantity.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    const raise: Raise = noticeRaiser(deps.notice.set);
    const id = readId(inputOf(ctx));
    const found = deps.moves.get().find(move => move.id === id);
    if (!found) raise('NotFound', { id });
    const draft: Move = { ...found };
    deps.editDraft.set(draft);
    deps.editItem.set(draft.item);
    deps.editFrom.set(draft.from);
    deps.editTo.set(draft.to);
    deps.editQuantity.set(String(draft.quantity));
    deps.notice.set(undefined);
    return draft;
  },
});

/** Replace the open draft's saved move, reversal first, in one undo step. */
export const saveMoveEdit: Operation.Handle<Move, EditMoveInput> = operation({
  label: 'saveMoveEdit',
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    editDraft: editDraft.controller,
    history: history.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    const raise: Raise = noticeRaiser(deps.notice.set);
    const raw = inputOf(ctx);
    const id = readId(raw);
    const item = readItem(raw, raise);
    const from = readPlace(raw, 'from', raise);
    const to = readPlace(raw, 'to', raise);
    const quantity = readQuantity(raw, raise);
    if (from === to) raise('SamePlace', { place: from });
    const saved = deps.moves.get();
    const draft = deps.editDraft.get();
    const index = saved.findIndex(move => move.id === id);
    if (draft === undefined || draft.id !== id || index < 0) raise('NotFound', { id });
    const previous = saved[index];
    const current = deps.stock.get();
    const held = quantityAt(current, previous.item, previous.to);
    if (held < previous.quantity) {
      raise('ShortStock', {
        item: previous.item,
        place: previous.to,
        available: held,
        requested: previous.quantity,
      });
    }
    const restored = transfer(current, previous.item, previous.to, previous.from, previous.quantity);
    const available = quantityAt(restored, item, from);
    if (available < quantity) {
      raise('ShortStock', { item, place: from, available, requested: quantity });
    }
    const replacement: Move = { id, item, from, to, quantity };
    pushHistory(deps.history, current, saved, deps.notice.set);
    deps.stock.set(transfer(restored, item, from, to, quantity));
    deps.moves.set(saved.map((move, at) => (at === index ? replacement : move)));
    deps.editDraft.set(undefined);
    return replacement;
  },
});

/** Close the open draft without touching stock, moves, or history. */
export const discardMoveEdit: Operation.Handle<void, { id: string }> = operation({
  label: 'discardMoveEdit',
  depends: {
    editDraft: editDraft.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    const raise: Raise = noticeRaiser(deps.notice.set);
    const id = readId(inputOf(ctx));
    const draft = deps.editDraft.get();
    if (draft === undefined || draft.id !== id) raise('NotFound', { id });
    deps.editDraft.set(undefined);
    deps.notice.set(undefined);
  },
});

/** Restore the stock and move list from the last passing change. */
export const undoMove: Operation.Handle<void, void> = operation({
  label: 'undoMove',
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    history: history.controller,
    notice: notice.controller,
  },
  run: deps => {
    const raise: Raise = noticeRaiser(deps.notice.set);
    const past = deps.history.get();
    if (past.length === 0) raise('EmptyUndo', {});
    const last = past[past.length - 1];
    deps.history.set(past.slice(0, -1));
    deps.stock.set(last.stock);
    deps.moves.set(last.moves);
    deps.notice.set(undefined);
  },
});

import { defineBrowserProvider } from "@vitest/browser";
import { chromium, type Browser, type Page } from "playwright";
import type { BrowserProvider, BrowserProviderOption } from "vitest/node";

function browserProvider(): BrowserProvider {
  let browser: Browser | undefined;
  const pages = new Map<string, Page>();
  return {
    name: "playwright",
    supportsParallelism: false,
    getCommandsContext: () => ({}),
    openPage: async (sessionId: string, url: string): Promise<void> => {
      browser ??= await chromium.launch({ headless: true });
      const page = await browser.newPage();
      pages.set(sessionId, page);
      await page.goto(url);
    },
    close: async (): Promise<void> => {
      pages.clear();
      await browser?.close();
      browser = undefined;
    },
  };
}

/** Browser tests run in real headless Chromium driven by Playwright. */
export function headlessChromium(): BrowserProviderOption {
  return defineBrowserProvider({
    name: "playwright",
    supportedBrowser: ["chromium"],
    providerFactory: browserProvider,
  });
}

import { vi, expect } from "vitest";
