/** A plan app mounted on a fresh root to drive through the real DOM. */
export type Mounted = {
  readonly container: HTMLElement;
  readonly unmount: () => void;
};

export async function mountPlan(): Promise<Mounted> {
  const container = document.createElement("div");
  document.body.append(container);
  const root: Root = createRoot(container);
  root.render(<PlanApp />);
  await vi.waitFor(() => {
    expect(getByLabelText(container, "Title")).toBeTruthy();
  });
  return {
    container,
    unmount: () => {
      root.unmount();
      container.remove();
    },
  };
}

