  it("rejects blank titles and keeps the list empty", () => {
    const scope = freshScope();
    const blank = expectKind(
      () => scope.run(bookBooking, { input: { title: "   ", room: "Cedar", start: 540, end: 600 } }),
      "BlankTitle",
    );
    expect(blank.payload.title).toBe("   ");
    expectKind(
      () => scope.run(bookBooking, { input: { title: "", room: "Cedar", start: 540, end: 600 } }),
      "BlankTitle",
    );
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects an unknown room", () => {
    const scope = freshScope();
    const failure = expectKind(
      () => scope.run(bookBooking, { input: { title: "X", room: "Kitchen", start: 540, end: 600 } }),
      "UnknownRoom",
    );
    expect(failure.payload.room).toBe("Kitchen");
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects times outside 0..1439 or that are not integers", () => {
    const scope = freshScope();
    const cases: readonly { start: number; end: number; value: number }[] = [
      { start: -1, end: 600, value: -1 },
      { start: 540, end: 1440, value: 1440 },
      { start: 1.5, end: 600, value: 1.5 },
      { start: 540, end: 60.5, value: 60.5 },
      { start: 540, end: Number.NaN, value: Number.NaN },
    ];
    for (const times of cases) {
      const failure = expectKind(
        () =>
          scope.run(bookBooking, {
            input: { title: "X", room: "Cedar", start: times.start, end: times.end },
          }),
        "BadTime",
      );
      expect(failure.payload.value).toBe(times.value);
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects an end at or before the start with EmptySlot and saves nothing", () => {
    const scope = freshScope();
    const same = expectKind(
      () => scope.run(bookBooking, { input: { title: "X", room: "Cedar", start: 600, end: 600 } }),
      "EmptySlot",
    );
    expect(same.payload).toEqual({ start: 600, end: 600 });
    expectKind(
      () => scope.run(bookBooking, { input: { title: "X", room: "Cedar", start: 600, end: 300 } }),
      "EmptySlot",
    );
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects an overlap in one room and leaves bookings unchanged", () => {
    const scope = freshScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const clash = expectKind(
      () => scope.run(bookBooking, { input: { title: "Dup", room: "Cedar", start: 540, end: 600 } }),
      "Clash",
    );
    expect(clash.payload).toEqual({ room: "Cedar", start: 540, end: 600 });
    expectKind(
      () => scope.run(bookBooking, { input: { title: "Partial", room: "Cedar", start: 570, end: 630 } }),
      "Clash",
    );
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("books Maple at Cedar's taken times and keeps both bookings in the list", () => {
    const scope = freshScope();
    scope.run(bookBooking, { input: { title: "Standup", room: "Cedar", start: 540, end: 600 } });
    const second = scope.run(bookBooking, {
      input: { title: "Planning", room: "Maple", start: 540, end: 600 },
    });
    expect(second.room).toBe("Maple");
    expect(scope.resolve(bookings)).toHaveLength(2);
  });

  it("books a slot that starts when another ends: back-to-back is not a clash", () => {
    const scope = freshScope();
    scope.run(bookBooking, { input: { title: "First", room: "Cedar", start: 540, end: 600 } });
    scope.run(bookBooking, { input: { title: "Next", room: "Cedar", start: 600, end: 660 } });
    expect(titles(scope)).toEqual(["First", "Next"]);
  });

  it("lists by start time, then creation order", () => {
    const scope = freshScope();
    scope.run(bookBooking, { input: { title: "Later", room: "Cedar", start: 600, end: 660 } });
    scope.run(bookBooking, { input: { title: "First twin", room: "Cedar", start: 300, end: 330 } });
    scope.run(bookBooking, { input: { title: "Second twin", room: "Maple", start: 300, end: 330 } });
    expect(titles(scope)).toEqual(["First twin", "Second twin", "Later"]);
  });

  it("creates exactly one booking when the same slot is called twice", () => {
    const scope = freshScope();
    const first = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    expectKind(
      () => scope.run(bookBooking, { input: { title: "Standup", room: "Cedar", start: 540, end: 600 } }),
      "Clash",
    );
    const list = scope.resolve(bookings);
    expect(list).toHaveLength(1);
    expect(list[0]?.id).toBe(first.id);
  });

  it("gives every booking a unique id", () => {
    const scope = freshScope();
    scope.run(bookBooking, { input: { title: "A", room: "Cedar", start: 0, end: 30 } });
    scope.run(bookBooking, { input: { title: "B", room: "Cedar", start: 30, end: 60 } });
    scope.run(bookBooking, { input: { title: "C", room: "Maple", start: 0, end: 30 } });
    const ids = scope.resolve(bookings).map((booking) => booking.id);
    expect(new Set(ids).size).toBe(3);
  });

  it("rawInput with start \"noon\" fails with BadTime, not DataValidationFailed", () => {
    const scope = freshScope();
    const failure = expectKind(
      () =>
        scope.run(bookBooking, {
          rawInput: { title: "X", room: "Cedar", start: "noon", end: 600 },
        }),
      "BadTime",
    );
    expect(failure.payload.value).toBe("noon");
  });

  it("keeps two scopes independent", () => {
    const first = freshScope();
    const second = freshScope();
    first.run(bookBooking, { input: { title: "A", room: "Cedar", start: 0, end: 30 } });
    expect(second.resolve(bookings)).toEqual([]);
  });
});

describe("cancelBooking", () => {
  it("removes the booking and frees its slot", () => {
    const scope = freshScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const result = scope.run(cancelBooking, { input: { id: saved.id } });
    expect(result).toBeUndefined();
    expect(scope.resolve(bookings)).toEqual([]);
    scope.run(bookBooking, { input: { title: "Again", room: "Cedar", start: 540, end: 600 } });
    expect(titles(scope)).toEqual(["Again"]);
  });

  it("reports NotFound on a second cancel and on an unknown id", () => {
    const scope = freshScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(cancelBooking, { input: { id: saved.id } });
    const twice = expectKind(() => scope.run(cancelBooking, { input: { id: saved.id } }), "NotFound");
    expect(twice.payload.id).toBe(saved.id);
    expectKind(() => scope.run(cancelBooking, { input: { id: "ghost" } }), "NotFound");
    expect(scope.resolve(bookings)).toEqual([]);
  });
});

describe("edit draft", () => {
  it("opens with a copy that never changes the saved booking", () => {
    const scope = freshScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    expect(scope.resolve(editDraft)).toBeUndefined();
    const draft = scope.run(openEdit, { input: { id: saved.id } });
    expect(draft).toEqual(saved);
    expect(draft).not.toBe(saved);
    Object.assign(draft, { title: "Changed only in the copy" });
    expect(scope.resolve(bookings)[0]?.title).toBe("Standup");
    expect(scope.resolve(editDraft)?.title).toBe("Standup");
  });

  it("reports NotFound for an unknown id", () => {
    const scope = freshScope();
    const failure = expectKind(() => scope.run(openEdit, { input: { id: "ghost" } }), "NotFound");
    expect(failure.payload.id).toBe("ghost");
    expect(scope.resolve(editDraft)).toBeUndefined();
  });

  it("keeps one draft: opening a second id closes the first", () => {
    const scope = freshScope();
    const first = scope.run(bookBooking, {
      input: { title: "One", room: "Cedar", start: 0, end: 30 },
    });
    const second = scope.run(bookBooking, {
      input: { title: "Two", room: "Cedar", start: 30, end: 60 },
    });
    scope.run(openEdit, { input: { id: first.id } });
    scope.run(openEdit, { input: { id: second.id } });
    expect(scope.resolve(editDraft)?.id).toBe(second.id);
    const closed = expectKind(
      () =>
        scope.run(saveEdit, {
          input: { id: first.id, title: "Nope", room: "Cedar", start: 0, end: 30 },
        }),
      "NotFound",
    );
    expect(closed.payload.id).toBe(first.id);
    expect(titles(scope)).toEqual(["One", "Two"]);
  });

  it("saves a passing draft over the booking", () => {
    const scope = freshScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const updated = scope.run(saveEdit, {
      input: { id: saved.id, title: "  Planning  ", room: "Cedar", start: 600, end: 660 },
    });
    expect(updated).toEqual({
      id: saved.id,
      title: "Planning",
      room: "Cedar",
      date: "2026-10-01",
      start: 600,
      end: 660,
    });
    expect(scope.resolve(bookings)).toEqual([updated]);
    expect(scope.resolve(editDraft)).toBeUndefined();
  });

  it("keeps the booking and the draft when a save fails", () => {
    const scope = freshScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    expectKind(
      () => scope.run(saveEdit, { input: { id: saved.id, title: "   ", room: "Cedar", start: 540, end: 600 } }),
      "BlankTitle",
    );
    expect(scope.resolve(bookings)).toEqual([saved]);
    expect(scope.resolve(editDraft)?.title).toBe("Standup");
    expectKind(
      () => scope.run(saveEdit, { input: { id: saved.id, title: "X", room: "Venus", start: 540, end: 600 } }),
      "UnknownRoom",
    );
    expect(scope.resolve(editDraft)).not.toBeUndefined();
  });

  it("keeps its own slot on save but blocks another booking's slot", () => {
    const scope = freshScope();
    const cedar = scope.run(bookBooking, {
      input: { title: "Cedar talk", room: "Cedar", start: 540, end: 600 },
    });
    const maple = scope.run(bookBooking, {
      input: { title: "Maple talk", room: "Maple", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: cedar.id } });
    const kept = scope.run(saveEdit, {
      input: { id: cedar.id, title: "Cedar talk", room: "Cedar", start: 540, end: 600 },
    });
    expect(kept.title).toBe("Cedar talk");
    scope.run(openEdit, { input: { id: maple.id } });
    const clash = expectKind(
      () =>
        scope.run(saveEdit, {
          input: { id: maple.id, title: "Maple talk", room: "Cedar", start: 540, end: 600 },
        }),
      "Clash",
    );
    expect(clash.payload.room).toBe("Cedar");
    expect(scope.resolve(bookings).find((booking) => booking.id === maple.id)?.room).toBe("Maple");
    expect(scope.resolve(editDraft)?.id).toBe(maple.id);
  });

  it("discardEdit clears editDraft and leaves the saved booking exactly as it was", () => {
    const scope = freshScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    const result = scope.run(discardEdit, { input: { id: saved.id } });
    expect(result).toBeUndefined();
    expect(scope.resolve(bookings)).toEqual([saved]);
    expect(scope.resolve(editDraft)).toBeUndefined();
  });

  it("reports NotFound for save or discard on a closed or missing draft", () => {
    const scope = freshScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const saveClosed = expectKind(
      () =>
        scope.run(saveEdit, {
          input: { id: saved.id, title: "X", room: "Cedar", start: 540, end: 600 },
        }),
      "NotFound",
    );
    expect(saveClosed.payload.id).toBe(saved.id);
    const discardClosed = expectKind(
      () => scope.run(discardEdit, { input: { id: saved.id } }),
      "NotFound",
    );
    expect(discardClosed.payload.id).toBe(saved.id);
    scope.run(openEdit, { input: { id: saved.id } });
    scope.run(discardEdit, { input: { id: saved.id } });
    expectKind(() => scope.run(discardEdit, { input: { id: saved.id } }), "NotFound");
    expectKind(
      () =>
        scope.run(saveEdit, {
          input: { id: saved.id, title: "X", room: "Cedar", start: 540, end: 600 },
        }),
      "NotFound",
    );
    expect(titles(scope)).toEqual(["Standup"]);
  });

  it("reports NotFound when saving an id that is gone", () => {
    const scope = freshScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(cancelBooking, { input: { id: saved.id } });
    const failure = expectKind(
      () =>
        scope.run(saveEdit, {
          input: { id: saved.id, title: "X", room: "Cedar", start: 540, end: 600 },
        }),
      "NotFound",
    );
    expect(failure.payload.id).toBe(saved.id);
  });

  it("closes the draft when its booking is canceled", () => {
    const scope = freshScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    scope.run(openEdit, { input: { id: saved.id } });
    expect(scope.resolve(editDraft)).not.toBeUndefined();
    scope.run(cancelBooking, { input: { id: saved.id } });
    expect(scope.resolve(editDraft)).toBeUndefined();
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("keeps list order after a save that moves the start time", () => {
    const scope = freshScope();
    const early = scope.run(bookBooking, {
      input: { title: "Early", room: "Cedar", start: 100, end: 130 },
    });
    scope.run(bookBooking, { input: { title: "Late", room: "Cedar", start: 600, end: 630 } });
    scope.run(openEdit, { input: { id: early.id } });
    scope.run(saveEdit, { input: { id: early.id, title: "Early", room: "Cedar", start: 700, end: 730 } });
    expect(titles(scope)).toEqual(["Late", "Early"]);
  });
});

import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { build, preview } from "vite";
import type { PreviewServer } from "vite";
import { chromium } from "playwright";
import type { Browser, Locator, Page } from "playwright";

let server: PreviewServer;
let browser: Browser;
let page: Page;
let baseUrl: string;

beforeAll(async () => {
  await build({ root: process.cwd(), logLevel: "silent" });
  server = await preview({
    root: process.cwd(),
    logLevel: "silent",
    preview: { host: "127.0.0.1", port: 5200, strictPort: false },
  });
  const url = server.resolvedUrls?.local[0];
  if (url === undefined) {
    throw new Error("preview server did not report a url");
  }
  baseUrl = url;
  browser = await chromium.launch({ args: ["--no-sandbox"] });
  page = await browser.newPage();
  await page.goto(baseUrl);
}, 60000);

afterAll(async () => {
  await browser?.close();
  await server?.close();
});

const TIMEOUT = { timeout: 5000 };

function rows(): Locator {
  return page.locator("tbody tr");
}

async function expectRows(count: number): Promise<void> {
  await expect.poll(() => rows().count(), TIMEOUT).toBe(count);
}

async function expectRowContains(index: number, text: string): Promise<void> {
  await expect.poll(() => rows().nth(index).textContent(), TIMEOUT).toContain(
    text,
  );
}

async function expectAlert(text: string): Promise<void> {
  await expect
    .poll(async () => {
      const alert = page.getByRole("alert");
      return (await alert.count()) === 0 ? null : alert.first().textContent();
    }, TIMEOUT)
    .toBe(text);
}

async function expectInput(label: string, value: string): Promise<void> {
  await expect
    .poll(() => page.getByLabel(label, { exact: true }).inputValue(), TIMEOUT)
    .toBe(value);
}

async function reload(): Promise<void> {
  await page.goto(baseUrl);
}

describe("booking screen with dates and series", () => {
  it(
    "defaults the date and books a weekly series",
    async () => {
      await reload();
      await expectRows(0);
      await expectInput("Date", "2026-10-01");
      await page.getByLabel("Title", { exact: true }).fill("Standup");
      await page.getByLabel("Room", { exact: true }).fill("Cedar");
      await page.getByLabel("Start time", { exact: true }).fill("09:00");
      await page.getByLabel("End time", { exact: true }).fill("10:00");
      await page.getByLabel("Date", { exact: true }).fill("2026-10-06");
      await page.getByLabel("Weeks", { exact: true }).fill("3");
      await page.getByRole("button", { name: "Book series", exact: true }).click();
      await expectRows(3);
      await expectRowContains(0, "2026-10-06");
      await expectRowContains(1, "2026-10-13");
      await expectRowContains(2, "2026-10-20");
      await expectRowContains(0, "Standup");
      await expectRowContains(0, "09:00-10:00");
      await expectInput("Title", "");
    },
    30000,
  );

  it(
    "shows BadCount for a bad weeks value without booking",
    async () => {
      await reload();
      await page.getByLabel("Title", { exact: true }).fill("Standup");
      await page.getByLabel("Room", { exact: true }).fill("Cedar");
      await page.getByLabel("Start time", { exact: true }).fill("09:00");
      await page.getByLabel("End time", { exact: true }).fill("10:00");
      await page.getByLabel("Weeks", { exact: true }).fill("13");
      await page.getByRole("button", { name: "Book series", exact: true }).click();
      await expectAlert("BadCount");
      await expectRows(0);
    },
    30000,
  );

  it(
    "cancels a whole series from one row",
    async () => {
      await reload();
      await page.getByLabel("Title", { exact: true }).fill("Standup");
      await page.getByLabel("Room", { exact: true }).fill("Cedar");
      await page.getByLabel("Start time", { exact: true }).fill("09:00");
      await page.getByLabel("End time", { exact: true }).fill("10:00");
      await page.getByLabel("Date", { exact: true }).fill("2026-10-06");
      await page.getByLabel("Weeks", { exact: true }).fill("2");
      await page.getByRole("button", { name: "Book series", exact: true }).click();
      await expectRows(2);
      await page
        .getByRole("button", { name: "Cancel series", exact: true })
        .first()
        .click();
      await expectRows(0);
    },
    30000,
  );

  it(
    "shows BadDate beside the form for an unreal date",
    async () => {
      await reload();
      await page.getByLabel("Title", { exact: true }).fill("Standup");
      await page.getByLabel("Room", { exact: true }).fill("Cedar");
      await page.getByLabel("Start time", { exact: true }).fill("09:00");
      await page.getByLabel("End time", { exact: true }).fill("10:00");
      await page.getByLabel("Date", { exact: true }).fill("2026-02-30");
      await page.getByRole("button", { name: "Book", exact: true }).click();
      await expectAlert("BadDate");
      await expectRows(0);
    },
    30000,
  );
});

import { useId, type ReactNode } from "react";
import { createScope } from "@tinker/core";
import { ScopeProvider, useData, useRun } from "@tinker/react";
import { items, submitFields, type FormText } from "./model.ts";
import { editDraft, editForm, filter, moves, newForm, notice, stock } from "./state.ts";
import { chooseFilter, discardMoveEdit, moveStock, openMoveEdit, saveMoveEdit, typeEdit, typeNew, undoMove } from "./operations.ts";

/** One labeled text input bound to one form field's owned text. */
function Field(props: { label: string; value: string; onType: (value: string) => void }): ReactNode {
  const id = useId();
  return (
    <p>
      <label htmlFor={id}>{props.label}</label>
      <input id={id} type="text" value={props.value} onChange={(event) => props.onType(event.target.value)} />
    </p>
  );
}

/** The one shared notice block, showing the managed error kind of the last failed action. */
function Notice(): ReactNode {
  const error = useData(notice);
  return <div role="alert">{error === undefined ? "" : error.kind}</div>;
}

/** The new-move form; its typed text survives both passing and failing moves. */
function NewMoveForm(): ReactNode {
  const text = useData(newForm);
  const typed = useRun(typeNew);
  const mover = useRun(moveStock);
  const type = (field: keyof FormText) => (value: string) => typed.run({ input: { field, value } });
  return (
    <section>
      <Field label="Item" value={text.item} onType={type("item")} />
      <Field label="From" value={text.from} onType={type("from")} />
      <Field label="To" value={text.to} onType={type("to")} />
      <Field label="Quantity" value={text.quantity} onType={type("quantity")} />
      <button type="button" onClick={() => mover.run({ rawInput: submitFields(text) })}>
        Move stock
      </button>
    </section>
  );
}

/** The stock table, always in saved-list order. */
function StockTable(): ReactNode {
  const rows = useData(stock);
  return (
    <table aria-label="Stock">
      <thead>
        <tr>
          <th>Item</th>
          <th>Place</th>
          <th>Quantity</th>
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr key={`${row.item}-${row.place}`}>
            <td>{row.item}</td>
            <td>{row.place}</td>
            <td>{row.quantity}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

/** The moves table with its filter buttons; filtering hides rows but deletes nothing. */
function MovesTable(): ReactNode {
  const saved = useData(moves);
  const active = useData(filter);
  const filtering = useRun(chooseFilter);
  const opening = useRun(openMoveEdit);
  const rows = active === "All" ? saved : saved.filter((move) => move.item === active);
  return (
    <div>
      <button type="button" onClick={() => filtering.run({ input: { filter: "All" } })}>
        All
      </button>
      {items.map((item) => (
        <button key={item} type="button" onClick={() => filtering.run({ input: { filter: item } })}>
          {item}
        </button>
      ))}
      <table aria-label="Moves">
        <thead>
          <tr>
            <th>Item</th>
            <th>From</th>
            <th>To</th>
            <th>Quantity</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {rows.map((move) => (
            <tr key={move.id}>
              <td>{move.item}</td>
              <td>{move.from}</td>
              <td>{move.to}</td>
              <td>{move.quantity}</td>
              <td>
                <button type="button" onClick={() => opening.run({ input: { id: move.id } })}>
                  Edit move
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/** The single move editor, shown only while a draft is open and seeded when it opens. */
function MoveEditor(): ReactNode {
  const draft = useData(editDraft);
  const text = useData(editForm);
  const typed = useRun(typeEdit);
  const saving = useRun(saveMoveEdit);
  const discarding = useRun(discardMoveEdit);
  if (draft === undefined) return null;
  const type = (field: keyof FormText) => (value: string) => typed.run({ input: { field, value } });
  return (
    <section>
      <Field label="Edit item" value={text.item} onType={type("item")} />
      <Field label="Edit from" value={text.from} onType={type("from")} />
      <Field label="Edit to" value={text.to} onType={type("to")} />
      <Field label="Edit quantity" value={text.quantity} onType={type("quantity")} />
      <button type="button" onClick={() => saving.run({ rawInput: { id: draft.id, ...submitFields(text) } })}>
        Save move
      </button>
      <button type="button" onClick={() => discarding.run({ input: { id: draft.id } })}>
        Discard move
      </button>
    </section>
  );
}

/** The always-available undo button. */
function UndoButton(): ReactNode {
  const undoing = useRun(undoMove);
  return (
    <button type="button" onClick={() => undoing.run({})}>
      Undo
    </button>
  );
}

/** Everything one desk shows, inside the scope its root owns. */
function Desk(): ReactNode {
  return (
    <div>
      <Notice />
      <NewMoveForm />
      <StockTable />
      <MovesTable />
      <MoveEditor />
      <UndoButton />
    </div>
  );
}

/** The stock desk root: owns one fresh scope per mount, shared with nothing else on the page. */
export function StockApp(): ReactNode {
  return (
    <ScopeProvider create={createScope}>
      <Desk />
    </ScopeProvider>
  );
}

