      title: "Standup",
      room: "Cedar",
      date: "2026-10-01",
      start: 540,
      end: 600,
    });
    const clash = capture(() =>
      scope.run(bookBooking, {
        input: { title: "Again", room: "Cedar", start: 540, end: 600 },
      }),
    );
    if (!isError(clash, "Clash")) {
      expect.fail("expected Clash");
    }
    expect(clash.payload).toEqual({ room: "Cedar", start: 540, end: 600 });
    expect(scope.resolve(bookings)).toEqual([standup]);
  });

  it("allows the same slot in another room and a start when another ends", () => {
    const scope = createScope();
