      input: book({ title: "Standup", room: "Cedar", start: 540, end: 600 }),
    });
    const maple = scope.run(bookBooking, {
      input: { title: "Maple copy", room: "Maple", start: 540, end: 600 },
    });
    const later = scope.run(bookBooking, {
      input: { title: "Planning", room: "Cedar", start: 600, end: 660 },
    });
    expect(scope.resolve(bookings)).toEqual([standup, maple, later]);
  });

  it("trims the saved title", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "  Standup  ", room: "Cedar", start: 60, end: 120 },
    });
    expect(saved.title).toBe("Standup");
  });

  it("rejects a blank title", () => {
    const scope = createScope();
    for (const title of ["", "   ", "\t\n"]) {
      const error = capture(() =>
        scope.run(bookBooking, {
          input: { title, room: "Cedar", start: 60, end: 120 },
        }),
      );
      if (!isError(error, "BlankTitle")) {
        expect.fail(title);
      }
      expect(error.payload.title).toBe(title);
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects an unknown room", () => {
    const scope = createScope();
    const error = capture(() =>
      scope.run(bookBooking, {
        input: { title: "Standup", room: "Attic", start: 60, end: 120 },
      }),
    );
    if (!isError(error, "UnknownRoom")) {
      expect.fail("expected UnknownRoom");
    }
    expect(error.payload.room).toBe("Attic");
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects a time outside 0..1439 or not an integer", () => {
    const scope = createScope();
    const badStarts = [-1, 1440, 25.5, Number.NaN, Number.POSITIVE_INFINITY];
    for (const start of badStarts) {
      const error = capture(() =>
        scope.run(bookBooking, {
          input: { title: "Standup", room: "Cedar", start, end: 120 },
        }),
      );
      if (!isError(error, "BadTime")) {
        expect.fail(String(start));
      }
      expect(error.payload.value).toBe(start);
    }
    const badEnd = capture(() =>
      scope.run(bookBooking, {
        input: { title: "Standup", room: "Cedar", start: 120, end: 2000 },
      }),
    );
    if (!isError(badEnd, "BadTime")) {
      expect.fail("expected BadTime");
    }
    expect(badEnd.payload.value).toBe(2000);
    const notNumbers = capture(() =>
      scope.run(bookBooking, {
        rawInput: { title: "Standup", room: "Cedar", start: "9am", end: 120 },
      }),
    );
    if (!isError(notNumbers, "BadTime")) {
      expect.fail("expected BadTime");
    }
    expect(notNumbers.payload.value).toBe("9am");
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects an end at or before the start", () => {
    const scope = createScope();
    for (const [start, end] of [
      [600, 600],
      [600, 540],
    ] as const) {
      const error = capture(() =>
        scope.run(bookBooking, {
          input: { title: "Standup", room: "Cedar", start, end },
        }),
      );
      if (!isError(error, "EmptySlot")) {
        expect.fail(`${start}-${end}`);
      }
      expect(error.payload).toEqual({ start, end });
    }
    expect(scope.resolve(bookings)).toEqual([]);
  });

  it("rejects any overlap in one room and allows overlap across rooms", () => {
    const scope = createScope();
    scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    const inside = capture(() =>
      scope.run(bookBooking, {
        input: { title: "Inside", room: "Cedar", start: 550, end: 590 },
      }),
    );
    if (!isError(inside, "Clash")) {
      expect.fail("expected Clash");
    }
    expect(inside.payload).toEqual({ room: "Cedar", start: 550, end: 590 });
    const across = scope.run(bookBooking, {
      input: { title: "Across", room: "Maple", start: 550, end: 590 },
    });
    expect(across.room).toBe("Maple");
  });

  it("allows back-to-back bookings: one starts exactly when another ends", () => {
    const scope = createScope();
    const early = scope.run(bookBooking, {
      input: { title: "Early", room: "Cedar", start: 540, end: 600 },
    });
    const late = scope.run(bookBooking, {
      input: { title: "Late", room: "Cedar", start: 600, end: 660 },
    });
    const tail = scope.run(bookBooking, {
      input: { title: "Tail", room: "Cedar", start: 480, end: 540 },
    });
    expect(scope.resolve(bookings)).toEqual([tail, early, late]);
  });

  it("lists bookings by start time, then creation order", () => {
    const scope = createScope();
    const b = scope.run(bookBooking, {
      input: { title: "B", room: "Cedar", start: 600, end: 660 },
    });
    const a2 = scope.run(bookBooking, {
      input: { title: "A2", room: "Cedar", start: 540, end: 600 },
    });
    const a1 = scope.run(bookBooking, {
      input: { title: "A1", room: "Maple", start: 540, end: 600 },
    });
    expect(scope.resolve(bookings)).toEqual([a2, a1, b]);
  });

  it("leaves saved bookings unchanged on a failed action", () => {
    const scope = createScope();
    const saved = scope.run(bookBooking, {
      input: { title: "Standup", room: "Cedar", start: 540, end: 600 },
    });
    capture(() =>
      scope.run(bookBooking, {
        input: { title: "Bad", room: "", start: 1, end: 0 },
      }),
    );
    capture(() =>
      scope.run(bookBooking, {
        input: { title: "Clash", room: "Cedar", start: 550, end: 590 },
      }),
    );
    expect(scope.resolve(bookings)).toEqual([saved]);
  });

  it("creates exactly one booking for two calls on an empty slot", () => {
    const scope = createScope();
    const first = scope.run(bookBooking, {
      input: { title: "First", room: "Cedar", start: 540, end: 600 },
    });
    expect(first.title).toBe("First");
    const second = capture(() =>
      scope.run(bookBooking, {
        input: { title: "Second", room: "Cedar", start: 545, end: 595 },
      }),
    );
    if (!isError(second, "Clash")) {
      expect.fail("expected Clash");
    }
    expect(second.payload).toEqual({ room: "Cedar", start: 545, end: 595 });
    const list = scope.resolve(bookings);
    expect(list).toHaveLength(1);
    expect(list[0]?.title).toBe("First");
  });
});

