import { createRoot } from "react-dom/client";
import { StockApp } from "../../src/index.ts";

const first = document.getElementById("app-a") ?? document.body;
const second = document.getElementById("app-b") ?? document.body;
createRoot(first).render(<StockApp />);
createRoot(second).render(<StockApp />);

/**
 * Pure booking rules over plain values: rooms, times, real calendar days, clashes, and
 * list order. Nothing here reads or writes a cell; the operations own every state change.
 */

import {
  badCount,
  badDate,
  badTime,
  blankTitle,
  emptySlot,
  unknownRoom,
} from "./errors.ts";

/** The two fixed rooms. */
export type Room = "Cedar" | "Maple";

/** The two fixed rooms, in display order. */
export const rooms: readonly Room[] = ["Cedar", "Maple"];

/** The default calendar day, used when a call omits `date`. */
export const DEFAULT_DATE = "2026-10-01";

/** One saved booking. `id` is opaque to callers; `seriesId` ties a weekly series. */
export type Booking = {
  readonly id: string;
  readonly title: string;
  readonly room: Room;
  readonly date: string;
  readonly start: number;
  readonly end: number;
  readonly seriesId?: string;
};

/** The input `bookBooking` takes; `room` is a plain string, `date` defaults. */
export type BookInput = {
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

/** The input `saveEdit` takes: an existing id plus the edited fields. */
export type EditInput = {
  readonly id: string;
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

/** The input `bookSeries` takes: one booking repeated weekly. */
export type SeriesInput = {
  readonly title: string;
  readonly room: string;
  readonly date: string;
  readonly start: number;
  readonly end: number;
  readonly weeks: number;
};

/** One validated booking, before it gains an id. */
export type ValidFields = {
  readonly title: string;
  readonly room: Room;
  readonly date: string;
  readonly start: number;
  readonly end: number;
};

const MINUTES_PER_HOUR = 60;
const LAST_MINUTE = 1439;
const MIN_WEEKS = 1;
const MAX_WEEKS = 12;
const DAYS_PER_WEEK = 7;
const MONTHS_PER_YEAR = 12;
const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;
const TIME_PATTERN = /^(\d{1,2}):(\d{2})$/;
const DAYS_IN_MONTH: readonly number[] = [
  31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31,
];

/** Format minutes since midnight as 24-hour `HH:MM`. */
export function formatTime(minutes: number): string {
  const hours = Math.floor(minutes / MINUTES_PER_HOUR);
  const mins = minutes % MINUTES_PER_HOUR;
  return `${String(hours).padStart(2, "0")}:${String(mins).padStart(2, "0")}`;
}

/** Parse 24-hour `HH:MM` into minutes since midnight, or undefined when malformed. */
export function parseTime(raw: string): number | undefined {
  const match = TIME_PATTERN.exec(raw.trim());
  if (match === null) {
    return undefined;
  }
  const hours = Number(match[1]);
  const mins = Number(match[2]);
  if (hours > 23 || mins > 59) {
    return undefined;
  }
  return hours * MINUTES_PER_HOUR + mins;
}

/** True when a four-digit year is a Gregorian leap year, year 0 included. */
function isLeapYear(year: number): boolean {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

/** How many days a month of that year really has. */
function daysInMonth(year: number, month: number): number {
  const length = DAYS_IN_MONTH[month - 1];
  if (length === undefined) {
    return 0;
  }
  return month === 2 && isLeapYear(year) ? 29 : length;
}

/** Check one real `YYYY-MM-DD` day; a four-digit year below 100 is still real. */
export function checkDate(value: unknown): string {
  if (typeof value !== "string") {
    throw badDate(value);
  }
  const match = DATE_PATTERN.exec(value);
  if (match === null) {
    throw badDate(value);
  }
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (month < 1 || month > MONTHS_PER_YEAR) {
    throw badDate(value);
  }
  if (day < 1 || day > daysInMonth(year, month)) {
    throw badDate(value);
  }
  return value;
}

/** Check one time value against the 0..1439 integer rule. */
export function checkTime(value: number): number {
  if (!Number.isInteger(value) || value < 0 || value > LAST_MINUTE) {
    throw badTime(value);
  }
  return value;
}

/** Check the weekly repeat count against the 1..12 integer rule. */
export function checkWeeks(value: number): number {
  if (!Number.isInteger(value) || value < MIN_WEEKS || value > MAX_WEEKS) {
    throw badCount(value);
  }
  return value;
}

/** Move a real `YYYY-MM-DD` day forward by whole days, keeping the same format. */
export function addDays(date: string, days: number): string {
  const match = DATE_PATTERN.exec(date);
  if (match === null) {
    throw badDate(date);
  }
  let year = Number(match[1]);
  let month = Number(match[2]);
  let day = Number(match[3]) + days;
  let limit = daysInMonth(year, month);
  while (day > limit) {
    day -= limit;
    month += 1;
    if (month > MONTHS_PER_YEAR) {
      month = 1;
      year += 1;
    }
    limit = daysInMonth(year, month);
  }
  const textYear = String(year).padStart(4, "0");
  const textMonth = String(month).padStart(2, "0");
  const textDay = String(day).padStart(2, "0");
  return `${textYear}-${textMonth}-${textDay}`;
}

/** Resolve a raw room string to a known room without a cast. */
export function toRoom(value: string): Room | undefined {
  return rooms.find((candidate) => candidate === value);
}

/** Title, room, date, and time rules shared by booking, editing, and series. */
export function checkFields(input: {
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
}): ValidFields {
  const title = input.title.trim();
  if (title.length === 0) {
    throw blankTitle(title);
  }
  const room = toRoom(input.room);
  if (room === undefined) {
    throw unknownRoom(input.room);
  }
  const date = input.date === undefined ? DEFAULT_DATE : checkDate(input.date);
  const start = checkTime(input.start);
  const end = checkTime(input.end);
  if (end <= start) {
    throw emptySlot(start, end);
  }
  return { title, room, date, start, end };
}

/** True when two half-open time ranges share a minute. */
function overlaps(
  aStart: number,
  aEnd: number,
  bStart: number,
  bEnd: number,
): boolean {
  return aStart < bEnd && bStart < aEnd;
}

/** True when an existing booking in the same room and date overlaps the slot. */
export function hasConflict(
  list: readonly Booking[],
  room: Room,
  date: string,
  start: number,
  end: number,
  skipId?: string,
): boolean {
  return list.some(
    (booking) =>
      booking.id !== skipId &&
      booking.room === room &&
      booking.date === date &&
      overlaps(start, end, booking.start, booking.end),
  );
}

/** The creation position of an id, after every id actually in the list. */
function creationIndex(order: readonly string[], id: string): number {
  const index = order.indexOf(id);
  return index < 0 ? Number.MAX_SAFE_INTEGER : index;
}

/** Order by date, then start time, then creation order from `order`. */
export function sortBookings(
  list: readonly Booking[],
  order: readonly string[],
): Booking[] {
  return [...list].sort((a, b) => {
    if (a.date !== b.date) {
      return a.date < b.date ? -1 : 1;
    }
    if (a.start !== b.start) {
      return a.start - b.start;
    }
    return creationIndex(order, a.id) - creationIndex(order, b.id);
  });
}

/** A copy of one booking that shares no field with the original. */
export function copyBooking(booking: Booking): Booking {
  const copy: Booking = {
    id: booking.id,
    title: booking.title,
    room: booking.room,
    date: booking.date,
    start: booking.start,
    end: booking.end,
  };
  if (booking.seriesId === undefined) {
    return copy;
  }
  return { ...copy, seriesId: booking.seriesId };
}

/** The dates of a weekly series, one week apart, starting from `date`. */
export function seriesDates(date: string, weeks: number): readonly string[] {
  const dates: string[] = [];
  for (let week = 0; week < weeks; week += 1) {
    dates.push(addDays(date, week * DAYS_PER_WEEK));
  }
  return dates;
}

/** Trim a new series title; a blank one reports BlankTitle with the text as given. */
export function checkRenameTitle(value: string): string {
  const title = value.trim();
  if (title.length === 0) {
    throw blankTitle(value);
  }
  return title;
}

/** Retitle every occurrence of one series, keeping its other fields and the list order. */
export function retitleSeries(
  list: readonly Booking[],
  seriesId: string,
  title: string,
): Booking[] {
  return list
    .filter((booking) => booking.seriesId === seriesId)
    .map((booking) => ({ ...booking, title }));
}

/**
 * Clock and count text helpers: the one place raw field text becomes typed minutes or weeks,
 * and the one place minutes become `HH:MM` text for a field.
 */

/** Minutes since midnight when `text` is `HH:MM` (24-hour) clock text such as `09:00`.
 * Text that is not a clock time is passed through unchanged, so the operation's own time
 * rule reports the text as typed instead of a converted stand-in. */
export function toMinutes(text: string): number | string {
  const match = /^([0-9]{2}):([0-9]{2})$/.exec(text.trim());
  if (match === null) {
    return text;
  }
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (hours > 23 || minutes > 59) {
    return text;
  }
  return hours * 60 + minutes;
}

/** Minutes since midnight back to `HH:MM` text for a field. */
export function toClock(minutes: number): string {
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  return `${String(hours).padStart(2, "0")}:${String(rest).padStart(2, "0")}`;
}

/** The `Weeks` field as a count: text that reads as a number converts, anything else is
 * passed through unchanged so `bookSeries` reports `BadCount` with the text as typed. */
export function toWeeks(text: string): number | string {
  const clean = text.trim();
  if (clean === "") {
    return text;
  }
  const value = Number(clean);
  return Number.isNaN(value) ? text : value;
}

import { operation, type Operation, type Scope } from "@tinker/core";
import { managed, raise } from "./errors.ts";
import {
  items,
  places,
  type EditMoveInput,
  type Item,
  type Move,
  type MoveInput,
  type Place,
  type Stock,
} from "./model.ts";
import {
  editDraft,
  editFromText,
  editItemText,
  editQuantityText,
  editToText,
  issuedIds,
  moveFilter,
  moves,
  notice,
  stock,
  undoHistory,
  type MoveFilter,
  type Notice,
  type UndoStep,
} from "./state.ts";

/** Raw text typed into the new-move form, one field per input. */
export type MoveForm = { item: string; from: string; to: string; quantity: string };

/** Raw text typed into the editor, plus the open move it replaces. */
export type EditForm = MoveForm & { id: string };

/** Show `current` the failure when it is one of ours, then rethrow the original value. */
function report(error: unknown, current: Scope.DataController<Notice>): never {
  const failure = managed(error);
  if (failure !== undefined) current.set(failure);
  throw error;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** One field of an operation's input, read the same way whether the call carried it typed or raw. */
function field(input: unknown, key: string): unknown {
  if (!isRecord(input)) return undefined;
  return input[key];
}

/** The input this call carried, whichever of the two shapes the caller used. */
function calledInput<I>(ctx: Operation.Ctx<I>): unknown {
  return ctx.input ?? ctx.rawInput;
}

function isItem(value: unknown): value is Item {
  return items.some((name) => name === value);
}

function isPlace(value: unknown): value is Place {
  return places.some((name) => name === value);
}

function requireItem(value: unknown): Item {
  if (isItem(value)) return value;
  raise("UnknownItem", { item: value });
}

function requirePlace(value: unknown): Place {
  if (isPlace(value)) return value;
  raise("UnknownPlace", { place: value });
}

function requireQuantity(value: unknown): number {
  if (typeof value === "number" && Number.isSafeInteger(value) && value > 0) return value;
  raise("BadQuantity", { quantity: value });
}

function requireId(value: unknown): string {
  if (typeof value === "string") return value;
  raise("NotFound", { id: String(value) });
}

/** Read a quantity field's text as a number; text that reads as nothing keeps its own value in the error. */
function requireQuantityText(value: unknown): number {
  if (typeof value !== "string") raise("BadQuantity", { quantity: value });
  const trimmed = value.trim();
  if (trimmed === "") raise("BadQuantity", { quantity: value });
  const parsed = Number(trimmed);
  if (Number.isNaN(parsed)) raise("BadQuantity", { quantity: value });
  return parsed;
}

/** The quantity held by one row; a row that is not listed holds nothing. */
function quantityAt(rows: readonly Stock[], item: Item, place: Place): number {
  const row = rows.find((candidate) => candidate.item === item && candidate.place === place);
  if (row === undefined) return 0;
  return row.quantity;
}

/** The same rows with one row shifted by `delta`; every other row is left as it was. */
function adjust(rows: readonly Stock[], item: Item, place: Place, delta: number): readonly Stock[] {
  return rows.map((row) =>
    row.item === item && row.place === place ? { ...row, quantity: row.quantity + delta } : row,
  );
}

function findMove(rows: readonly Move[], id: string): Move | undefined {
  return rows.find((move) => move.id === id);
}

/** Issue the next opaque id from this scope's counter, which never runs backwards. */
function mintId(counter: Scope.DataController<number>): string {
  const next = counter.get() + 1;
  counter.set(next);
  return `move-${next}`;
}

function pushUndo(history: Scope.DataController<readonly UndoStep[]>, before: UndoStep): void {
  history.update((steps) => [...steps, before]);
}

/** Move a quantity of one item from one place to another, recording one move and one undo step. */
export const moveStock: Operation.Handle<Move, MoveInput> = operation({
  label: "moveStock",
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    history: undoHistory.controller,
    issued: issuedIds.controller,
    notice: notice.controller,
  },
  run(deps, ctx) {
    try {
      const input = calledInput(ctx);
      const item = requireItem(field(input, "item"));
      const from = requirePlace(field(input, "from"));
      const to = requirePlace(field(input, "to"));
      if (from === to) raise("SamePlace", { place: from });
      const quantity = requireQuantity(field(input, "quantity"));
      const before = deps.stock.get();
      const available = quantityAt(before, item, from);
      if (quantity > available) {
        raise("ShortStock", { item, place: from, available, requested: quantity });
      }
      const saved = deps.moves.get();
      const move: Move = { id: mintId(deps.issued), item, from, to, quantity };
      pushUndo(deps.history, { stock: before, moves: saved });
      deps.stock.set(adjust(adjust(before, item, from, -quantity), item, to, quantity));
      deps.moves.set([...saved, move]);
      deps.notice.set(undefined);
      return move;
    } catch (error) {
      return report(error, deps.notice);
    }
  },
});

/** Copy a saved move into `editDraft` and seed the editor fields from it. */
export const openMoveEdit: Operation.Handle<Move, { id: string }> = operation({
  label: "openMoveEdit",
  depends: {
    moves: moves.controller,
    draft: editDraft.controller,
    notice: notice.controller,
    item: editItemText.controller,
    from: editFromText.controller,
    to: editToText.controller,
    quantity: editQuantityText.controller,
  },
  run(deps, ctx) {
    try {
      const id = requireId(field(calledInput(ctx), "id"));
      const saved = findMove(deps.moves.get(), id);
      if (saved === undefined) raise("NotFound", { id });
      const draft: Move = { ...saved };
      deps.draft.set(draft);
      deps.item.set(draft.item);
      deps.from.set(draft.from);
      deps.to.set(draft.to);
      deps.quantity.set(String(draft.quantity));
      deps.notice.set(undefined);
      return draft;
    } catch (error) {
      return report(error, deps.notice);
    }
  },
});

/** Replace the open move in place, reversing it and reapplying it against current stock. */
export const saveMoveEdit: Operation.Handle<Move, EditMoveInput> = operation({
  label: "saveMoveEdit",
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    draft: editDraft.controller,
    history: undoHistory.controller,
    notice: notice.controller,
  },
  run(deps, ctx) {
    try {
      const input = calledInput(ctx);
      const id = requireId(field(input, "id"));
      const open = deps.draft.get();
      const saved = findMove(deps.moves.get(), id);
      if (open === undefined || open.id !== id || saved === undefined) {
        raise("NotFound", { id });
      }
      const item = requireItem(field(input, "item"));
      const from = requirePlace(field(input, "from"));
      const to = requirePlace(field(input, "to"));
      if (from === to) raise("SamePlace", { place: from });
      const quantity = requireQuantity(field(input, "quantity"));
      const beforeStock = deps.stock.get();
      const beforeMoves = deps.moves.get();
      const held = quantityAt(beforeStock, saved.item, saved.to);
      if (held < saved.quantity) {
        raise("ShortStock", {
          item: saved.item,
          place: saved.to,
          available: held,
          requested: saved.quantity,
        });
      }
      const reversed = adjust(
        adjust(beforeStock, saved.item, saved.to, -saved.quantity),
        saved.item,
        saved.from,
        saved.quantity,
      );
      const available = quantityAt(reversed, item, from);
      if (quantity > available) {
        raise("ShortStock", { item, place: from, available, requested: quantity });
      }
      const applied = adjust(adjust(reversed, item, from, -quantity), item, to, quantity);
      const replaced: Move = { id, item, from, to, quantity };
      pushUndo(deps.history, { stock: beforeStock, moves: beforeMoves });
      deps.stock.set(applied);
      deps.moves.set(beforeMoves.map((move) => (move.id === id ? replaced : move)));
      deps.draft.set(undefined);
      deps.notice.set(undefined);
      return replaced;
    } catch (error) {
      return report(error, deps.notice);
    }
  },
});

/** Close the open draft, leaving stock, moves, and undo history alone. */
export const discardMoveEdit: Operation.Handle<void, { id: string }> = operation({
  label: "discardMoveEdit",
  depends: {
    draft: editDraft.controller,
    notice: notice.controller,
  },
  run(deps, ctx) {
    try {
      const id = requireId(field(calledInput(ctx), "id"));
      const open = deps.draft.get();
      if (open === undefined || open.id !== id) raise("NotFound", { id });
      deps.draft.set(undefined);
      deps.notice.set(undefined);
    } catch (error) {
      return report(error, deps.notice);
    }
  },
});

/** Restore the stock and move list that stood before the last passing change. */
export const undoMove: Operation.Handle<void, void> = operation({
  label: "undoMove",
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    history: undoHistory.controller,
    notice: notice.controller,
  },
  run(deps) {
    try {
      const steps = deps.history.get();
      const before = steps[steps.length - 1];
      if (before === undefined) raise("EmptyUndo", {});
      deps.history.set(steps.slice(0, -1));
      deps.stock.set(before.stock);
      deps.moves.set(before.moves);
      deps.notice.set(undefined);
    } catch (error) {
      return report(error, deps.notice);
    }
  },
});

/** Show one item's moves in the list; filtering never touches stock or saved moves. */
export const chooseFilter: Operation.Handle<void, MoveFilter> = operation({
  label: "chooseFilter",
  depends: {
    filter: moveFilter.controller,
    notice: notice.controller,
  },
  run(deps, ctx) {
    try {
      const input = calledInput(ctx);
      if (input !== "All" && !isItem(input)) raise("UnknownItem", { item: input });
      deps.filter.set(input);
      deps.notice.set(undefined);
    } catch (error) {
      return report(error, deps.notice);
    }
  },
});

/** Read the new-move form's text and hand a typed move to `moveStock`. */
export const submitMoveForm: Operation.Handle<Move, MoveForm> = operation({
  label: "submitMoveForm",
  depends: {
    moveStock,
    notice: notice.controller,
  },
  run(deps, ctx) {
    try {
      const input = calledInput(ctx);
      const quantity = requireQuantityText(field(input, "quantity"));
      return deps.moveStock.run({
        rawInput: {
          item: field(input, "item"),
          from: field(input, "from"),
          to: field(input, "to"),
          quantity,
        },
      });
    } catch (error) {
      return report(error, deps.notice);
    }
  },
});

/** Read the editor's text and hand a typed replacement to `saveMoveEdit`. */
export const submitEditForm: Operation.Handle<Move, EditForm> = operation({
  label: "submitEditForm",
  depends: {
    saveMoveEdit,
    notice: notice.controller,
  },
  run(deps, ctx) {
    try {
      const input = calledInput(ctx);
      const quantity = requireQuantityText(field(input, "quantity"));
      return deps.saveMoveEdit.run({
        rawInput: {
          id: field(input, "id"),
          item: field(input, "item"),
          from: field(input, "from"),
          to: field(input, "to"),
          quantity,
        },
      });
    } catch (error) {
      return report(error, deps.notice);
    }
  },
});

import { createScope } from "@tinker/core";
import { ScopeProvider, useData, useScope } from "@tinker/react";
