type Filter = "All" | Room;

type DraftFields = {
  readonly title: string;
  readonly room: string;
  readonly date: string | undefined;
  readonly start: number;
  readonly end: number;
};

function formatTime(minute: number): string {
  const hour = Math.floor(minute / 60)
    .toString()
    .padStart(2, "0");
  const rest = (minute % 60).toString().padStart(2, "0");
  return `${hour}:${rest}`;
}

function parseTime(text: string): number {
  const match = /^(\d{1,2}):(\d{2})$/.exec(text.trim());
  if (!match) return Number.NaN;
  const hour = Number(match[1]);
  const minute = Number(match[2]);
  if (hour > 23 || minute > 59) return Number.NaN;
  return hour * 60 + minute;
}

/** A blank date field reads as absent, so the default day applies. */
function parseDate(text: string): string | undefined {
  const date = text.trim();
  return date === "" ? undefined : date;
}

function parseWeeks(text: string): number {
  return Number(text.trim());
}

function shownKind(caught: unknown): string {
  return errorKind(caught) ?? "Error";
}

function EditForm(props: {
  draft: Booking;
  onSave: (fields: DraftFields) => void;
  onDiscard: () => void;
}): ReactElement {
  const { draft } = props;
  const formId = useId();
  const [title, setTitle] = useState(draft.title);
  const [room, setRoom] = useState<string>(draft.room);
  const [date, setDate] = useState(draft.date);
  const [start, setStart] = useState(formatTime(draft.start));
  const [end, setEnd] = useState(formatTime(draft.end));
  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        props.onSave({
          title,
          room,
          date: parseDate(date),
          start: parseTime(start),
          end: parseTime(end),
        });
      }}
    >
      <label htmlFor={`${formId}-title`}>Edit title</label>
      <input
        id={`${formId}-title`}
        name="Edit title"
        type="text"
        value={title}
        onChange={(event) => setTitle(event.target.value)}
      />
      <label htmlFor={`${formId}-room`}>Edit room</label>
      <input
        id={`${formId}-room`}
        name="Edit room"
        type="text"
        value={room}
        onChange={(event) => setRoom(event.target.value)}
      />
      <label htmlFor={`${formId}-date`}>Date</label>
      <input
        id={`${formId}-date`}
        name="Date"
        type="text"
        value={date}
        onChange={(event) => setDate(event.target.value)}
      />
      <label htmlFor={`${formId}-start`}>Edit start time</label>
      <input
        id={`${formId}-start`}
        name="Edit start time"
        type="text"
        value={start}
        onChange={(event) => setStart(event.target.value)}
      />
      <label htmlFor={`${formId}-end`}>Edit end time</label>
      <input
        id={`${formId}-end`}
        name="Edit end time"
        type="text"
        value={end}
        onChange={(event) => setEnd(event.target.value)}
      />
      <button type="submit">Save</button>
      <button type="button" onClick={props.onDiscard}>
        Discard
      </button>
    </form>
  );
}

function BookingScreen(): ReactElement {
  const scope = useScope();
  const formId = useId();
  const list = useData(bookings);
  const draft = useData(editDraft);
  const [filter, setFilter] = useState<Filter>("All");
  const [error, setError] = useState<string | undefined>(undefined);
  const [title, setTitle] = useState("");
  const [room, setRoom] = useState("");
  const [date, setDate] = useState(defaultDate);
  const [start, setStart] = useState("");
  const [end, setEnd] = useState("");
  const [weeks, setWeeks] = useState("1");

  const run = (action: () => void): void => {
    try {
      action();
      setError(undefined);
    } catch (caught) {
      setError(shownKind(caught));
    }
  };

  const bookOne = (): void =>
    run(() => {
      scope.run(bookBooking, {
        input: {
          title,
          room,
          date: parseDate(date),
          start: parseTime(start),
          end: parseTime(end),
        },
      });
      setTitle("");
    });

  const bookMany = (): void =>
    run(() => {
      scope.run(bookSeries, {
        input: {
          title,
          room,
          date: parseDate(date) ?? defaultDate,
          start: parseTime(start),
          end: parseTime(end),
          weeks: parseWeeks(weeks),
        },
      });
      setTitle("");
    });

  return (
    <div>
      <form
        onSubmit={(event) => {
          event.preventDefault();
          bookOne();
        }}
      >
        <label htmlFor={`${formId}-title`}>Title</label>
        <input
          id={`${formId}-title`}
          name="Title"
          type="text"
          value={title}
          onChange={(event) => setTitle(event.target.value)}
        />
        <label htmlFor={`${formId}-room`}>Room</label>
        <input
          id={`${formId}-room`}
          name="Room"
          type="text"
          value={room}
          onChange={(event) => setRoom(event.target.value)}
        />
        <label htmlFor={`${formId}-date`}>Date</label>
        <input
          id={`${formId}-date`}
          name="Date"
          type="text"
          value={date}
          onChange={(event) => setDate(event.target.value)}
        />
        <label htmlFor={`${formId}-start`}>Start time</label>
        <input
          id={`${formId}-start`}
          name="Start time"
          type="text"
          value={start}
          onChange={(event) => setStart(event.target.value)}
        />
        <label htmlFor={`${formId}-end`}>End time</label>
        <input
          id={`${formId}-end`}
          name="End time"
          type="text"
          value={end}
          onChange={(event) => setEnd(event.target.value)}
        />
        <label htmlFor={`${formId}-weeks`}>Weeks</label>
        <input
          id={`${formId}-weeks`}
          name="Weeks"
          type="text"
          value={weeks}
          onChange={(event) => setWeeks(event.target.value)}
        />
        <button type="submit">Book</button>
        <button type="button" onClick={bookMany}>
          Book series
        </button>
      </form>
      <div role="alert">{error ?? ""}</div>
      <div>
        <button
          type="button"
          onClick={() =>
            run(() => {
              scope.run(undoChange, {});
            })
          }
        >
          Undo
        </button>
      </div>
      <div>
        <button type="button" onClick={() => setFilter("All")}>
          All
        </button>
        <button type="button" onClick={() => setFilter("Cedar")}>
          Cedar
        </button>
        <button type="button" onClick={() => setFilter("Maple")}>
          Maple
        </button>
      </div>
      {draft ? (
        <EditForm
          key={draft.id}
          draft={draft}
          onSave={(fields) =>
            run(() => {
              scope.run(saveEdit, { input: { id: draft.id, ...fields } });
            })
          }
          onDiscard={() =>
            run(() => {
              scope.run(discardEdit, { input: { id: draft.id } });
            })
          }
        />
      ) : null}
      <table>
        <tbody>
          {list.map((booking) => (
            <tr
              key={booking.id}
              hidden={filter !== "All" && filter !== booking.room}
            >
              <td>{booking.title}</td>
              <td>{booking.room}</td>
              <td>{booking.date}</td>
              <td>
                {formatTime(booking.start)} - {formatTime(booking.end)}
              </td>
              <td>
                <button
                  type="button"
                  aria-label={`Edit ${booking.title}`}
                  onClick={() =>
                    run(() => {
                      scope.run(openEdit, { input: { id: booking.id } });
                    })
                  }
                >
                  Edit
                </button>
                <button
                  type="button"
                  aria-label={`Cancel ${booking.title}`}
                  onClick={() =>
                    run(() => {
                      scope.run(cancelBooking, { input: { id: booking.id } });
                    })
                  }
                >
                  Cancel
                </button>
                {booking.seriesId === undefined ? null : (
                  <button
                    type="button"
                    onClick={() =>
                      run(() => {
                        if (booking.seriesId !== undefined) {
                          scope.run(cancelSeries, {
                            input: { seriesId: booking.seriesId },
                          });
                        }
                      })
                    }
                  >
                    Cancel series
                  </button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/** The room-booking screen: it owns its scope, so two mounted apps share nothing. */
