  );
}

import type { Errors, Payloads } from './errors.ts';
import type { Item, Place } from './types.ts';

/** Report one managed failure and stop the current rule. */
export type Raise = (
  kind: Errors.Name,
  payload: Payloads[Errors.Name],
) => never;

/** The values an operation was called with, raw input winning when supplied. */
export const inputOf = (ctx: {
  readonly rawInput: unknown;
  readonly input: unknown;
}): unknown => (ctx.rawInput !== undefined ? ctx.rawInput : ctx.input);

const field = (source: unknown, key: string): unknown => {
  if (typeof source !== 'object' || source === null) return undefined;
  return Reflect.get(source, key);
};

/** Read a known item, keeping the original value when it is unknown. */
export const readItem = (source: unknown, raise: Raise): Item => {
  const value = field(source, 'item');
  if (value === 'Cable' || value === 'Stand') return value;
  return raise('UnknownItem', { item: value });
};

/** Read one known place, keeping the original value when it is unknown. */
export const readPlace = (source: unknown, key: 'from' | 'to', raise: Raise): Place => {
  const value = field(source, key);
  if (value === 'East' || value === 'West') return value;
  return raise('UnknownPlace', { place: value });
};

/** Read a quantity that is a positive safe integer, else keep the original value. */
export const readQuantity = (source: unknown, raise: Raise): number => {
  const value = field(source, 'quantity');
  if (typeof value === 'number' && Number.isSafeInteger(value) && value > 0) return value;
  return raise('BadQuantity', { quantity: value });
};

/** Read a move id as text. */
export const readId = (source: unknown): string => {
  const value = field(source, 'id');
  return typeof value === 'string' ? value : '';
};

/** Turn quantity text into a number when it reads as one, else keep the text. */
export const parseQuantityText = (text: string): number | string => {
  if (text.trim() === '') return text;
  const value = Number(text);
  return Number.isFinite(value) ? value : text;
};

export type { Item, Place, Stock, Move, MoveInput, EditMoveInput } from "./model.ts";
export { items, places } from "./model.ts";
export { stock, moves, editDraft } from "./state.ts";
export { moveStock, openMoveEdit, saveMoveEdit, discardMoveEdit, undoMove } from "./operations.ts";
export { StockApp } from "./StockApp.tsx";
export { isError } from "./errors.ts";
export type { Errors } from "./errors.ts";

/**
 * The stock-desk state and operations. Every piece of app state lives in a
 * core cell; every state change runs through an operation.
 */
import { data, operation } from '@tinker/core';
import type { Operation, Scope } from '@tinker/core';
import { appError, errorKind } from './errors';
import type { Item, Move, MoveInput, EditMoveInput, Place, Stock } from './domain';
import { initialStock } from './domain';

/** The saved stock rows, always in desk order. */
export const stock = data<readonly Stock[]>({ label: 'stock', initial: initialStock });

/** The saved moves, in creation order. */
export const moves = data<readonly Move[]>({ label: 'moves', initial: [] });

/** The move currently open in the editor, if any. */
export const editDraft = data<Move | undefined>({ label: 'editDraft', initial: undefined });

/** The managed error kind the screen shows, or undefined after a passing action. */
export const notice = data<string | undefined>({ label: 'notice', initial: undefined });

/** Which saved moves the screen lists. */
export type MoveFilter = 'All' | Item;

export const moveFilter = data<MoveFilter>({ label: 'moveFilter', initial: 'All' });

/** The new-move form text; kept as typed, through passing and failing moves alike. */
export const formItem = data<string>({ label: 'formItem', initial: 'Cable' });
export const formFrom = data<string>({ label: 'formFrom', initial: 'East' });
export const formTo = data<string>({ label: 'formTo', initial: 'West' });
export const formQuantity = data<string>({ label: 'formQuantity', initial: '1' });

/** The editor form text; seeded when a move is opened and replaced on every open. */
export const editFormItem = data<string>({ label: 'editFormItem', initial: '' });
export const editFormFrom = data<string>({ label: 'editFormFrom', initial: '' });
export const editFormTo = data<string>({ label: 'editFormTo', initial: '' });
export const editFormQuantity = data<string>({ label: 'editFormQuantity', initial: '' });

type UndoStep = { stock: readonly Stock[]; moves: readonly Move[] };

const undoHistory = data<readonly UndoStep[]>({ label: 'undoHistory', initial: [] });

/** Ids already issued stay spent, so undo never makes the desk reuse one. */
const moveSeq = data<number>({ label: 'moveSeq', initial: 0 });

type MovesCell = typeof moves;
type NoticeCell = typeof notice;

type MoveDeps = {
  stock: typeof stock.controller;
  moves: MovesCell['controller'];
  history: typeof undoHistory.controller;
  seq: typeof moveSeq.controller;
  notice: NoticeCell['controller'];
};

type OpenDeps = {
  moves: MovesCell['controller'];
  draft: typeof editDraft.controller;
  item: typeof editFormItem.controller;
  from: typeof editFormFrom.controller;
  to: typeof editFormTo.controller;
  quantity: typeof editFormQuantity.controller;
  notice: NoticeCell['controller'];
};

type SaveDeps = {
  stock: typeof stock.controller;
  moves: MovesCell['controller'];
  draft: typeof editDraft.controller;
  history: typeof undoHistory.controller;
  notice: NoticeCell['controller'];
};

type DiscardDeps = { draft: typeof editDraft.controller; notice: NoticeCell['controller'] };

type UndoDeps = {
  stock: typeof stock.controller;
  moves: MovesCell['controller'];
  history: typeof undoHistory.controller;
  notice: NoticeCell['controller'];
};

type FilterDeps = { filter: typeof moveFilter.controller };

/** Read one field off a raw call object without trusting its shape. */
function field(raw: unknown, key: string): unknown {
  if (typeof raw !== 'object' || raw === null) return undefined;
  for (const entry of Object.entries(raw)) {
    if (entry[0] === key) return entry[1];
  }
  return undefined;
}

/** The saved-move id a call names; only strings can name one. */
function readId(raw: unknown): string {
  const value = field(raw, 'id');
  return typeof value === 'string' ? value : '';
}

function asItem(value: unknown): Item {
  if (value === 'Cable' || value === 'Stand') return value;
  throw appError('UnknownItem', { item: value });
}

function asPlace(value: unknown): Place {
  if (value === 'East' || value === 'West') return value;
  throw appError('UnknownPlace', { place: value });
}

/** A quantity must be a positive safe integer; every other value is refused as given. */
function asQuantity(value: unknown): number {
  if (typeof value === 'number' && Number.isSafeInteger(value) && value > 0) return value;
  throw appError('BadQuantity', { quantity: value });
}

function stockAt(rows: readonly Stock[], item: Item, place: Place): number {
  const row = rows.find((candidate) => candidate.item === item && candidate.place === place);
  return row === undefined ? 0 : row.quantity;
}

/** Move quantity of an item from one place to another; other rows are untouched. */
function shiftStock(
  rows: readonly Stock[],
  item: Item,
  from: Place,
  to: Place,
  quantity: number,
): readonly Stock[] {
  return rows.map((row) => {
    if (row.item !== item) return row;
    if (row.place === from) return { ...row, quantity: row.quantity - quantity };
    if (row.place === to) return { ...row, quantity: row.quantity + quantity };
    return row;
  });
}

/** Show a managed failure on the screen, then let it reject the run; anything else is a bug. */
function fail(deps: { notice: Scope.DataController<string | undefined> }, error: unknown): never {
  const kind = errorKind(error);
  if (kind === undefined) throw error;
  deps.notice.set(kind);
  throw error;
}

/**
 * Move stock from one place to another: validates the raw call, checks the
 * source, then saves the move, the new stock, and one undo step.
 */
export const moveStock: Operation.Handle<Move, MoveInput> = operation<MoveDeps, Move, MoveInput>({
  label: 'moveStock',
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    history: undoHistory.controller,
    seq: moveSeq.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    try {
      const item = asItem(field(ctx.rawInput, 'item'));
      const from = asPlace(field(ctx.rawInput, 'from'));
      const to = asPlace(field(ctx.rawInput, 'to'));
      const quantity = asQuantity(field(ctx.rawInput, 'quantity'));
      if (from === to) throw appError('SamePlace', { place: from });
      const currentStock = deps.stock.get();
      const available = stockAt(currentStock, item, from);
      if (available < quantity) {
        throw appError('ShortStock', { item, place: from, available, requested: quantity });
      }
      const currentMoves = deps.moves.get();
      const seq = deps.seq.get() + 1;
      const move: Move = { id: `move-${seq}`, item, from, to, quantity };
      deps.seq.set(seq);
      deps.history.set([...deps.history.get(), { stock: currentStock, moves: currentMoves }]);
      deps.stock.set(shiftStock(currentStock, item, from, to, quantity));
      deps.moves.set([...currentMoves, move]);
      deps.notice.set(undefined);
      return move;
    } catch (error) {
      fail(deps, error);
    }
  },
});

/**
 * Open a saved move in the editor: copy it into the draft and seed the editor
 * text from it. Opening adds no undo step.
 */
export const openMoveEdit: Operation.Handle<Move, { id: string }> = operation<OpenDeps, Move, { id: string }>({
  label: 'openMoveEdit',
  depends: {
    moves: moves.controller,
    draft: editDraft.controller,
    item: editFormItem.controller,
    from: editFormFrom.controller,
    to: editFormTo.controller,
    quantity: editFormQuantity.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    try {
      const id = readId(ctx.rawInput);
      const saved = deps.moves.get().find((candidate) => candidate.id === id);
      if (saved === undefined) throw appError('NotFound', { id });
      const draft: Move = { ...saved };
      deps.draft.set(draft);
      deps.item.set(saved.item);
      deps.from.set(saved.from);
      deps.to.set(saved.to);
      deps.quantity.set(String(saved.quantity));
      deps.notice.set(undefined);
      return draft;
    } catch (error) {
      fail(deps, error);
    }
  },
});

/**
 * Replace a saved move: requires its draft to be open, reverses the old move
 * against current stock, then applies the replacement against that restored
 * stock. Both steps are checked before anything is written.
 */
export const saveMoveEdit: Operation.Handle<Move, EditMoveInput> = operation<SaveDeps, Move, EditMoveInput>({
  label: 'saveMoveEdit',
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    draft: editDraft.controller,
    history: undoHistory.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    try {
      const raw = ctx.rawInput;
      const id = readId(raw);
      const draft = deps.draft.get();
      const saved = deps.moves.get().find((candidate) => candidate.id === id);
      if (draft === undefined || draft.id !== id || saved === undefined) {
        throw appError('NotFound', { id });
      }
      const item = asItem(field(raw, 'item'));
      const from = asPlace(field(raw, 'from'));
      const to = asPlace(field(raw, 'to'));
      const quantity = asQuantity(field(raw, 'quantity'));
      if (from === to) throw appError('SamePlace', { place: from });
      const currentStock = deps.stock.get();
      const restoredAvailable = stockAt(currentStock, saved.item, saved.to);
      if (restoredAvailable < saved.quantity) {
        throw appError('ShortStock', {
          item: saved.item,
          place: saved.to,
          available: restoredAvailable,
          requested: saved.quantity,
        });
      }
      const restored = shiftStock(currentStock, saved.item, saved.to, saved.from, saved.quantity);
      const available = stockAt(restored, item, from);
      if (available < quantity) {
        throw appError('ShortStock', { item, place: from, available, requested: quantity });
      }
      const replacement: Move = { id, item, from, to, quantity };
      const currentMoves = deps.moves.get();
      const nextMoves = currentMoves.map((candidate) => (candidate.id === id ? replacement : candidate));
      deps.history.set([...deps.history.get(), { stock: currentStock, moves: currentMoves }]);
      deps.stock.set(shiftStock(restored, item, from, to, quantity));
      deps.moves.set(nextMoves);
      deps.draft.set(undefined);
      deps.notice.set(undefined);
      return replacement;
    } catch (error) {
      fail(deps, error);
    }
  },
});

/** Close the editor without touching stock, moves, or undo history. */
export const discardMoveEdit: Operation.Handle<void, { id: string }> = operation<DiscardDeps, void, { id: string }>({
  label: 'discardMoveEdit',
  depends: { draft: editDraft.controller, notice: notice.controller },
  run: (deps, ctx) => {
    try {
      const id = readId(ctx.rawInput);
      const draft = deps.draft.get();
      if (draft === undefined || draft.id !== id) throw appError('NotFound', { id });
      deps.draft.set(undefined);
      deps.notice.set(undefined);
    } catch (error) {
      fail(deps, error);
    }
  },
});

/** Restore the exact stock and move list from before the last passing change. */
export const undoMove: Operation.Handle<void, void> = operation<UndoDeps, void, void>({
  label: 'undoMove',
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    history: undoHistory.controller,
    notice: notice.controller,
  },
  run: (deps) => {
    try {
      const history = deps.history.get();
      const last = history.at(-1);
      if (last === undefined) throw appError('EmptyUndo', {});
      deps.history.set(history.slice(0, -1));
      deps.stock.set(last.stock);
      deps.moves.set(last.moves);
      deps.notice.set(undefined);
    } catch (error) {
      fail(deps, error);
    }
  },
});

/** List only the saved moves of one item. */
export const setMoveFilter: Operation.Handle<void, MoveFilter> = operation<FilterDeps, void, MoveFilter>({
  label: 'setMoveFilter',
  depends: { filter: moveFilter.controller },
  run: (deps, ctx) => {
    deps.filter.set(ctx.input);
  },
});

