/** One saved course. */
export type Course = {
  /** The scope-unique id other courses name in `prerequisiteIds`. */
  id: string;
  /** The trimmed title shown in the Title column. */
  title: string;
  /** Whether the course has been completed. */
  done: boolean;
  /** The direct requirements, in the order they were added. */
  prerequisiteIds: readonly string[];
};

/** Which rows the screen shows. */
export type Filter = "all" | "ready" | "done";

/** The text one row shows in its Status column. */
export type Status = "Done" | "Ready" | "Blocked";

/** Find one saved course by id. */
export function courseAt(list: readonly Course[], id: string): Course | undefined {
  return list.find((course) => course.id === id);
}

/** The ids of the direct requirements that are not done, in link order. */
export function openPrerequisites(list: readonly Course[], course: Course): readonly string[] {
  return course.prerequisiteIds.filter((id) => courseAt(list, id)?.done !== true);
}

/** The ids of the completed courses that require `id`, in saved course list order. */
export function completedDependents(list: readonly Course[], id: string): readonly string[] {
  return list
    .filter((course) => course.done && course.prerequisiteIds.includes(id))
    .map((course) => course.id);
}

/** Whether `from` already requires `target` through any chain of links. */
export function requiresThrough(list: readonly Course[], from: string, target: string): boolean {
  const seen = new Set<string>();
  const queue: string[] = [from];
  for (const id of queue) {
    if (id === target) return true;
    if (seen.has(id)) continue;
    seen.add(id);
    const course = courseAt(list, id);
    if (course !== undefined) queue.push(...course.prerequisiteIds);
  }
  return false;
}

/** The Status column text of one row. */
export function statusOf(list: readonly Course[], course: Course): Status {
  if (course.done) return "Done";
  return openPrerequisites(list, course).length === 0 ? "Ready" : "Blocked";
}

/** The Requires column text of one row: requirement titles in link order, or `None`. */
export function requiresText(list: readonly Course[], course: Course): string {
  const titles: string[] = [];
  for (const id of course.prerequisiteIds) {
    const prerequisite = courseAt(list, id);
    if (prerequisite !== undefined) titles.push(prerequisite.title);
  }
  return titles.length === 0 ? "None" : titles.join(", ");
}

/** One option a link select shows. */
export type Option = {
  /** What the option submits: empty, a course id, or a removed selection. */
  value: string;
  /** What the option shows as its text. */
  label: string;
};

/** The options one link select shows: the empty choice, courses in creation order, then a removed selection. */
export function selectOptions(list: readonly Course[], selected: string): readonly Option[] {
  const options: Option[] = [{ value: "", label: "Choose course" }];
  for (const course of list) options.push({ value: course.id, label: course.title });
  if (selected !== "" && courseAt(list, selected) === undefined) {
    options.push({ value: selected, label: "Removed course" });
  }
  return options;
}

/** The rows one filter shows, in saved course list order. */
export function visibleRows(list: readonly Course[], filter: Filter): readonly Course[] {
  if (filter === "all") return list;
  if (filter === "done") return list.filter((course) => course.done);
  return list.filter((course) => statusOf(list, course) === "Ready");
}

