function capture(run: () => unknown): unknown {
  try {
    run();
  } catch (error) {
    return error;
  }
  throw new Error("expected the call to fail");
}

describe("creation order ties", () => {
  it("keeps the older booking first when an edit ties the start times", () => {
    const scope = createScope();
    const older = scope.run(bookBooking, {
      input: { title: "Older", room: "Cedar", start: 600, end: 660 },
    });
    const newer = scope.run(bookBooking, {
      input: { title: "Newer", room: "Maple", start: 540, end: 600 },
    });
    expect(scope.resolve(bookings).map((b) => b.id)).toEqual([
      newer.id,
      older.id,
    ]);

    scope.run(openEdit, { input: { id: older.id } });
    scope.run(saveEdit, {
      input: {
        id: older.id,
        title: "Older",
        room: "Cedar",
        start: 540,
        end: 600,
      },
    });

    expect(scope.resolve(bookings).map((b) => b.id)).toEqual([
      older.id,
      newer.id,
    ]);
  });

  it("keeps creation order when a tie is rebooked after a cancel", () => {
    const scope = createScope();
    const first = scope.run(bookBooking, {
      input: { title: "First", room: "Cedar", start: 540, end: 600 },
    });
    const second = scope.run(bookBooking, {
      input: { title: "Second", room: "Maple", start: 540, end: 600 },
    });
    scope.run(cancelBooking, { input: { id: first.id } });
