} from "../src/index.ts";

/** A fresh plan scope. */
function plan(): Scope.Handle {
  return createScope();
}

/** Create one course through the public handle. */
function create(scope: Scope.Handle, title: string): Course {
  return scope.run(createCourse, { input: { title } });
}

/** Run one action that must fail and hand back the error it raised. */
function raised(run: () => unknown): unknown {
  try {
    run();
  } catch (error) {
    return error;
  }
  return expect.fail("expected a managed failure");
}

/** Narrow a raised error to one kind and hand back its payload. */
function payload<N extends Errors.Name>(error: unknown, kind: N): Errors.Payload<N> {
  if (isError(error, kind)) return error.payload;
  return expect.fail(`expected ${kind}, received ${String(error)}`);
}

