import { operation, type Operation, type Scope } from "@tinker/core";
import { managed, raise } from "./errors.ts";
import {
  items,
  places,
  type EditMoveInput,
  type Item,
  type Move,
  type MoveInput,
  type Place,
  type Stock,
} from "./model.ts";
import {
  editDraft,
  editFromText,
  editItemText,
  editQuantityText,
  editToText,
  fromText,
  issuedIds,
  itemText,
  moveFilter,
  moves,
  notice,
  quantityText,
  stock,
  toText,
  undoHistory,
  type MoveFilter,
  type Notice,
  type UndoStep,
} from "./state.ts";

/** Raw text typed into the new-move form, one field per input. */
export type MoveForm = { item: string; from: string; to: string; quantity: string };

/** Raw text typed into the editor, plus the open move it replaces. */
export type EditForm = MoveForm & { id: string };

/** Show `current` the failure when it is one of ours, then rethrow the original value. */
function report(error: unknown, current: Scope.DataController<Notice>): never {
  const failure = managed(error);
  if (failure !== undefined) current.set(failure);
  throw error;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** One field of an operation's input, read the same way whether the call carried it typed or raw. */
function field(input: unknown, key: string): unknown {
  if (!isRecord(input)) return undefined;
  return input[key];
}

/** The input this call carried, whichever of the two shapes the caller used. */
function calledInput<I>(ctx: Operation.Ctx<I>): unknown {
  return ctx.input ?? ctx.rawInput;
}

function isItem(value: unknown): value is Item {
  return items.some((name) => name === value);
}

function isPlace(value: unknown): value is Place {
  return places.some((name) => name === value);
}

function requireItem(value: unknown): Item {
  if (isItem(value)) return value;
  raise("UnknownItem", { item: value });
}

function requirePlace(value: unknown): Place {
  if (isPlace(value)) return value;
  raise("UnknownPlace", { place: value });
}

function requireQuantity(value: unknown): number {
  if (typeof value === "number" && Number.isSafeInteger(value) && value > 0) return value;
  raise("BadQuantity", { quantity: value });
}

function requireId(value: unknown): string {
  if (typeof value === "string") return value;
  raise("NotFound", { id: String(value) });
}

/** Read a quantity field's text as a number; text that reads as nothing keeps its own value in the error. */
function requireQuantityText(value: unknown): number {
  if (typeof value !== "string") raise("BadQuantity", { quantity: value });
  const trimmed = value.trim();
  if (trimmed === "") raise("BadQuantity", { quantity: value });
  const parsed = Number(trimmed);
  if (Number.isNaN(parsed)) raise("BadQuantity", { quantity: value });
  return parsed;
}

/** The quantity held by one row; a row that is not listed holds nothing. */
function quantityAt(rows: readonly Stock[], item: Item, place: Place): number {
  const row = rows.find((candidate) => candidate.item === item && candidate.place === place);
  if (row === undefined) return 0;
  return row.quantity;
}

/** The same rows with one row shifted by `delta`; every other row is left as it was. */
function adjust(rows: readonly Stock[], item: Item, place: Place, delta: number): readonly Stock[] {
  return rows.map((row) =>
    row.item === item && row.place === place ? { ...row, quantity: row.quantity + delta } : row,
  );
}

function findMove(rows: readonly Move[], id: string): Move | undefined {
  return rows.find((move) => move.id === id);
}

/** Issue the next opaque id from this scope's counter, which never runs backwards. */
function mintId(counter: Scope.DataController<number>): string {
  const next = counter.get() + 1;
  counter.set(next);
  return `move-${next}`;
}

function pushUndo(history: Scope.DataController<readonly UndoStep[]>, before: UndoStep): void {
  history.update((steps) => [...steps, before]);
}

/** Move a quantity of one item from one place to another, recording one move and one undo step. */
export const moveStock: Operation.Handle<Move, MoveInput> = operation({
  label: "moveStock",
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    history: undoHistory.controller,
    issued: issuedIds.controller,
    notice: notice.controller,
  },
  run(deps, ctx) {
    try {
      const input = calledInput(ctx);
      const item = requireItem(field(input, "item"));
      const from = requirePlace(field(input, "from"));
      const to = requirePlace(field(input, "to"));
      if (from === to) raise("SamePlace", { place: from });
      const quantity = requireQuantity(field(input, "quantity"));
      const before = deps.stock.get();
      const available = quantityAt(before, item, from);
      if (quantity > available) {
        raise("ShortStock", { item, place: from, available, requested: quantity });
      }
      const saved = deps.moves.get();
      const move: Move = { id: mintId(deps.issued), item, from, to, quantity };
      pushUndo(deps.history, { stock: before, moves: saved });
      deps.stock.set(adjust(adjust(before, item, from, -quantity), item, to, quantity));
      deps.moves.set([...saved, move]);
      deps.notice.set(undefined);
      return move;
    } catch (error) {
      return report(error, deps.notice);
    }
  },
});

/** Copy a saved move into `editDraft` and seed the editor fields from it. */
export const openMoveEdit: Operation.Handle<Move, { id: string }> = operation({
  label: "openMoveEdit",
  depends: {
    moves: moves.controller,
    draft: editDraft.controller,
    notice: notice.controller,
    item: editItemText.controller,
    from: editFromText.controller,
    to: editToText.controller,
    quantity: editQuantityText.controller,
  },
  run(deps, ctx) {
    try {
      const id = requireId(field(calledInput(ctx), "id"));
      const saved = findMove(deps.moves.get(), id);
      if (saved === undefined) raise("NotFound", { id });
      const draft: Move = { ...saved };
      deps.draft.set(draft);
      deps.item.set(draft.item);
      deps.from.set(draft.from);
      deps.to.set(draft.to);
      deps.quantity.set(String(draft.quantity));
      deps.notice.set(undefined);
      return draft;
    } catch (error) {
      return report(error, deps.notice);
    }
  },
});

/** Replace the open move in place, reversing it and reapplying it against current stock. */
export const saveMoveEdit: Operation.Handle<Move, EditMoveInput> = operation({
  label: "saveMoveEdit",
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    draft: editDraft.controller,
    history: undoHistory.controller,
    notice: notice.controller,
  },
  run(deps, ctx) {
    try {
      const input = calledInput(ctx);
      const id = requireId(field(input, "id"));
      const open = deps.draft.get();
      const saved = findMove(deps.moves.get(), id);
      if (open === undefined || open.id !== id || saved === undefined) {
        raise("NotFound", { id });
      }
      const item = requireItem(field(input, "item"));
      const from = requirePlace(field(input, "from"));
      const to = requirePlace(field(input, "to"));
      if (from === to) raise("SamePlace", { place: from });
      const quantity = requireQuantity(field(input, "quantity"));
      const beforeStock = deps.stock.get();
      const beforeMoves = deps.moves.get();
      const held = quantityAt(beforeStock, saved.item, saved.to);
      if (held < saved.quantity) {
        raise("ShortStock", {
          item: saved.item,
          place: saved.to,
          available: held,
          requested: saved.quantity,
        });
      }
      const reversed = adjust(
        adjust(beforeStock, saved.item, saved.to, -saved.quantity),
        saved.item,
        saved.from,
        saved.quantity,
      );
      const available = quantityAt(reversed, item, from);
      if (quantity > available) {
        raise("ShortStock", { item, place: from, available, requested: quantity });
      }
      const applied = adjust(adjust(reversed, item, from, -quantity), item, to, quantity);
      const replaced: Move = { id, item, from, to, quantity };
      pushUndo(deps.history, { stock: beforeStock, moves: beforeMoves });
      deps.stock.set(applied);
      deps.moves.set(beforeMoves.map((move) => (move.id === id ? replaced : move)));
      deps.draft.set(undefined);
      deps.notice.set(undefined);
      return replaced;
    } catch (error) {
      return report(error, deps.notice);
    }
  },
});

/** Close the open draft, leaving stock, moves, and undo history alone. */
export const discardMoveEdit: Operation.Handle<void, { id: string }> = operation({
  label: "discardMoveEdit",
  depends: {
    draft: editDraft.controller,
    notice: notice.controller,
  },
  run(deps, ctx) {
    try {
      const id = requireId(field(calledInput(ctx), "id"));
      const open = deps.draft.get();
      if (open === undefined || open.id !== id) raise("NotFound", { id });
      deps.draft.set(undefined);
      deps.notice.set(undefined);
    } catch (error) {
      return report(error, deps.notice);
    }
  },
});

/** Restore the stock and move list that stood before the last passing change. */
export const undoMove: Operation.Handle<void, void> = operation({
  label: "undoMove",
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    history: undoHistory.controller,
    notice: notice.controller,
  },
  run(deps) {
    try {
      const steps = deps.history.get();
      const before = steps[steps.length - 1];
      if (before === undefined) raise("EmptyUndo", {});
      deps.history.set(steps.slice(0, -1));
      deps.stock.set(before.stock);
      deps.moves.set(before.moves);
      deps.notice.set(undefined);
    } catch (error) {
      return report(error, deps.notice);
    }
  },
});

/** Show one item's moves in the list; filtering never touches stock or saved moves. */
export const chooseFilter: Operation.Handle<void, MoveFilter> = operation({
  label: "chooseFilter",
  depends: {
    filter: moveFilter.controller,
    notice: notice.controller,
  },
  run(deps, ctx) {
    try {
      const input = calledInput(ctx);
      if (input !== "All" && !isItem(input)) raise("UnknownItem", { item: input });
      deps.filter.set(input);
      deps.notice.set(undefined);
    } catch (error) {
      return report(error, deps.notice);
    }
  },
});

/** Which field of a form one keystroke changed. */
export type FormField = "item" | "from" | "to" | "quantity";

/** One keystroke: the field it landed in and the text that field now holds. */
export type FieldText = { field: FormField; text: string };

/** Record one keystroke typed into the new-move form: it changes the field's text and, because
 * typing is an action that passes, clears the notice the last failing action left behind. */
export const typeMoveField: Operation.Handle<void, FieldText> = operation({
  label: "typeMoveField",
  depends: {
    item: itemText.controller,
    from: fromText.controller,
    to: toText.controller,
    quantity: quantityText.controller,
    notice: notice.controller,
  },
  run(deps, ctx) {
    const { field, text } = ctx.input;
    if (field === "item") deps.item.set(text);
    else if (field === "from") deps.from.set(text);
    else if (field === "to") deps.to.set(text);
    else deps.quantity.set(text);
    deps.notice.set(undefined);
  },
});

/** Record one keystroke typed into the editor: it changes the draft text and, because typing is
 * an action that passes, clears the notice the last failing action left behind. */
export const typeEditField: Operation.Handle<void, FieldText> = operation({
  label: "typeEditField",
  depends: {
    item: editItemText.controller,
    from: editFromText.controller,
    to: editToText.controller,
    quantity: editQuantityText.controller,
    notice: notice.controller,
  },
  run(deps, ctx) {
    const { field, text } = ctx.input;
    if (field === "item") deps.item.set(text);
    else if (field === "from") deps.from.set(text);
    else if (field === "to") deps.to.set(text);
    else deps.quantity.set(text);
    deps.notice.set(undefined);
  },
});

/** Read the new-move form's text and hand a typed move to `moveStock`. */
export const submitMoveForm: Operation.Handle<Move, MoveForm> = operation({
  label: "submitMoveForm",
  depends: {
    moveStock,
    notice: notice.controller,
  },
  run(deps, ctx) {
    try {
      const input = calledInput(ctx);
      const quantity = requireQuantityText(field(input, "quantity"));
      return deps.moveStock.run({
        rawInput: {
          item: field(input, "item"),
          from: field(input, "from"),
          to: field(input, "to"),
          quantity,
        },
      });
    } catch (error) {
      return report(error, deps.notice);
    }
  },
});

/** Read the editor's text and hand a typed replacement to `saveMoveEdit`. */
export const submitEditForm: Operation.Handle<Move, EditForm> = operation({
  label: "submitEditForm",
  depends: {
    saveMoveEdit,
    notice: notice.controller,
  },
  run(deps, ctx) {
    try {
      const input = calledInput(ctx);
      const quantity = requireQuantityText(field(input, "quantity"));
      return deps.saveMoveEdit.run({
        rawInput: {
          id: field(input, "id"),
          item: field(input, "item"),
          from: field(input, "from"),
          to: field(input, "to"),
          quantity,
        },
      });
    } catch (error) {
      return report(error, deps.notice);
    }
  },
});

import { data, operation, type Data, type Edge, type Operation, type Scope } from "@tinker/core";
import { appError } from "./errors.ts";

/** The two bookable rooms. */
export type Room = "Cedar" | "Maple";

const ROOM_LIST: readonly ["Cedar", "Maple"] = ["Cedar", "Maple"];

export const rooms: readonly Room[] = ROOM_LIST;

/** The day round 1 fixed; still the default whenever a call omits `date`. */
export const DEFAULT_DATE = "2026-10-01";

/** A saved booking. `start`/`end` are minutes since midnight, 0..1439, end > start.
 * `date` is a real `YYYY-MM-DD` day. Series members carry a shared `seriesId`;
 * one-off bookings carry no `seriesId` key at all. */
export type Booking = {
  readonly id: string;
  readonly title: string;
  readonly room: Room;
  readonly date: string;
  readonly start: number;
  readonly end: number;
  readonly seriesId?: string;
};

/** What a caller hands `bookBooking`. `room` is a plain string: the op rejects unknown rooms.
 * `date` is optional; an absent date books the round 1 day, 2026-10-01. */
export type BookInput = {
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

/** What a caller hands `saveEdit`: a booking id plus the same slot fields as booking
 * (so `date` is optional there too and defaults to 2026-10-01). */
export type EditInput = {
  readonly id: string;
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

/** What a caller hands `bookSeries`: one slot plus how many weeks it repeats (1..12). */
export type SeriesInput = {
  readonly title: string;
  readonly room: string;
  readonly date: string;
  readonly start: number;
  readonly end: number;
  readonly weeks: number;
};

/** The saved list, sorted by date, then start time, then creation order. */
export const bookings: Data.Cell<readonly Booking[]> = data<readonly Booking[]>({
  label: "bookings",
  initial: [],
});

/** The one open edit draft; `undefined` when no edit is open. */
export const editDraft: Data.Cell<Booking | undefined> = data<Booking | undefined>({
  label: "editDraft",
  initial: undefined,
});

/** Creation sequence per id — the tie-break behind date and start time. Internal. */
const created = data<Readonly<Record<string, number>>>({
  label: "created",
  initial: {},
});

/** Monotonic id source, so ids stay unique in a scope even after cancels. Internal. */
const idCount = data<number>({ label: "idCount", initial: 0 });

/** One undo step: the booking list exactly as it stood before a passing change. Internal. */
type Snapshot = readonly Booking[];

/** Undo steps, newest last: one entry per passing booking write, none for a failure. Internal. */
const undoHistory = data<readonly Snapshot[]>({ label: "undoHistory", initial: [] });

type ListCtrl = Edge<"controller", Data.Cell<readonly Booking[]>>;
type DraftCtrl = Edge<"controller", Data.Cell<Booking | undefined>>;
type OrderCtrl = Edge<"controller", Data.Cell<Readonly<Record<string, number>>>>;
type CountCtrl = Edge<"controller", Data.Cell<number>>;
type HistoryCtrl = Edge<"controller", Data.Cell<readonly Snapshot[]>>;
/** The undo-history slot as a `run` body receives it: the read/write controller. */
type HistoryValue = Scope.DataController<readonly Snapshot[]>;

type BookDeps = {
  readonly list: ListCtrl;
  readonly order: OrderCtrl;
  readonly count: CountCtrl;
  readonly history: HistoryCtrl;
};
/** Cancels write the list, so they record an undo step; opening a draft does not. */
type SlotDeps = {
  readonly list: ListCtrl;
  readonly draft: DraftCtrl;
  readonly history: HistoryCtrl;
};
type ViewDeps = {
  readonly list: ListCtrl;
  readonly draft: DraftCtrl;
};
type SaveDeps = {
  readonly list: ListCtrl;
  readonly draft: DraftCtrl;
  readonly order: OrderCtrl;
  readonly history: HistoryCtrl;
};
type DiscardDeps = {
  readonly draft: DraftCtrl;
};
type UndoDeps = {
  readonly list: ListCtrl;
  readonly history: HistoryCtrl;
};

/** A slot that passed every field rule. */
type Checked = {
  readonly title: string;
  readonly room: Room;
  readonly date: string;
  readonly start: number;
  readonly end: number;
};

/** Pull the known keys off any raw call value, without trusting its shape. */
function readFields(raw: unknown): {
  readonly id: unknown;
  readonly title: unknown;
  readonly room: unknown;
  readonly date: unknown;
  readonly start: unknown;
  readonly end: unknown;
  readonly weeks: unknown;
  readonly seriesId: unknown;
} {
  if (typeof raw !== "object" || raw === null) {
    return {
      id: undefined,
      title: undefined,
      room: undefined,
      date: undefined,
      start: undefined,
      end: undefined,
      weeks: undefined,
      seriesId: undefined,
    };
  }
  return {
    id: "id" in raw ? raw.id : undefined,
    title: "title" in raw ? raw.title : undefined,
    room: "room" in raw ? raw.room : undefined,
    date: "date" in raw ? raw.date : undefined,
    start: "start" in raw ? raw.start : undefined,
    end: "end" in raw ? raw.end : undefined,
    weeks: "weeks" in raw ? raw.weeks : undefined,
    seriesId: "seriesId" in raw ? raw.seriesId : undefined,
  };
}

/** A booking id as a string; non-strings become not-found ids. */
function readId(raw: unknown): string {
  const id = readFields(raw).id;
  return typeof id === "string" ? id : String(id);
}

/** A series id as a string; non-strings become not-found ids. */
function readSeriesId(raw: unknown): string {
  const seriesId = readFields(raw).seriesId;
  return typeof seriesId === "string" ? seriesId : String(seriesId);
}

function describeTitle(value: unknown): string {
  return typeof value === "string" ? value : String(value);
}

function findRoom(value: string): Room | undefined {
  return ROOM_LIST.find((room) => room === value);
}

/** Days since the Unix epoch for a real `YYYY-MM-DD` day; `null` when the text is not one.
 * The round trip through `setUTCFullYear` rejects impossible days (2026-02-30, 2026-13-01)
 * and keeps years below 100 from being read as 1900-based. */
function parseDate(value: string): number | null {
  const match = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/.exec(value);
  if (match === null) {
    return null;
  }
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const at = new Date(0);
  at.setUTCHours(0, 0, 0, 0);
  at.setUTCFullYear(year, month - 1, day);
  if (
    at.getUTCFullYear() !== year ||
    at.getUTCMonth() !== month - 1 ||
    at.getUTCDate() !== day
  ) {
    return null;
  }
  return Math.floor(at.getTime() / 86_400_000);
}

/** Epoch days back to `YYYY-MM-DD`; `null` once the day leaves the four-digit-year range. */
function formatDate(epochDay: number): string | null {
  const at = new Date(epochDay * 86_400_000);
  if (Number.isNaN(at.getTime())) {
    return null;
  }
  const year = String(at.getUTCFullYear()).padStart(4, "0");
  const month = String(at.getUTCMonth() + 1).padStart(2, "0");
  const day = String(at.getUTCDate()).padStart(2, "0");
  const text = `${year}-${month}-${day}`;
  return /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(text) ? text : null;
}

/** The date rule: an absent date books the round 1 day; anything else must be a real day. */
function checkDate(value: unknown): string {
  if (value === undefined) {
    return DEFAULT_DATE;
  }
  if (typeof value !== "string" || parseDate(value) === null) {
    throw appError("BadDate", { date: value });
  }
  return value;
}

/** The weeks rule: an integer from 1 to 12, else `BadCount`. */
function checkWeeks(value: unknown): number {
  if (typeof value !== "number" || !Number.isInteger(value) || value < 1 || value > 12) {
    throw appError("BadCount", { weeks: value });
  }
  return value;
}

function checkMinute(value: unknown): number {
  if (typeof value !== "number" || !Number.isInteger(value) || value < 0 || value > 1439) {
    throw appError("BadTime", { value });
  }
  return value;
}

/** Field rules shared by booking, series booking, and saving: title, room, date, minutes. */
function checkSlot(raw: unknown): Checked {
  const fields = readFields(raw);
  if (typeof fields.title !== "string") {
    throw appError("BlankTitle", { title: describeTitle(fields.title) });
  }
  const title = fields.title.trim();
  if (title === "") {
    throw appError("BlankTitle", { title: fields.title });
  }
  if (typeof fields.room !== "string") {
    throw appError("UnknownRoom", { room: String(fields.room) });
  }
  const room = findRoom(fields.room);
  if (room === undefined) {
    throw appError("UnknownRoom", { room: fields.room });
  }
  const date = checkDate(fields.date);
  const start = checkMinute(fields.start);
  const end = checkMinute(fields.end);
  if (end <= start) {
    throw appError("EmptySlot", { start, end });
  }
  return { title, room, date, start, end };
}

/** True when `room` already holds a booking that overlaps the requested times on `date`.
 * Rooms never share slots, and the same slot on another day never clashes. */
function hasClash(
  list: readonly Booking[],
  room: Room,
  date: string,
  start: number,
  end: number,
  skipId: string | undefined = undefined,
): boolean {
  return list.some(
    (other) =>
      other.id !== skipId &&
      other.room === room &&
      other.date === date &&
      other.start < end &&
      start < other.end,
  );
}

/** Date first (YYYY-MM-DD text order is calendar order), then start time, then creation order. */
function sortedBookings(
  list: readonly Booking[],
  order: Readonly<Record<string, number>>,
): readonly Booking[] {
  return [...list].sort(
    (a, b) =>
      (a.date < b.date ? -1 : a.date > b.date ? 1 : 0) ||
      a.start - b.start ||
      order[a.id] - order[b.id],
  );
}

/** Push the pre-change list onto undo history. Called only after every rule passed, so a
 * failed action adds no step; the stored array is never mutated later, so it stays exact. */
function record(history: HistoryValue, before: Snapshot): void {
  history.set([...history.get(), before]);
}

/** The `weeks` dates of a series: the start day and six-day steps, seven days apart. */
function seriesDates(date: string, weeks: number): readonly string[] {
  const start = parseDate(date);
  if (start === null) {
    throw appError("BadDate", { date });
  }
  const dates: string[] = [];
  for (let index = 0; index < weeks; index += 1) {
    const text = formatDate(start + index * 7);
    if (text === null) {
      throw appError("BadDate", { date: text });
    }
    dates.push(text);
  }
  return dates;
}

/** Validate the raw call value once: the boundary every operation reads through. */
function rawCall(input: unknown, rawInput: unknown): unknown {
  return input ?? rawInput;
}

export const bookBooking: Operation.Handle<Booking, BookInput> = operation<
  BookDeps,
  Booking,
  BookInput
>({
  label: "bookBooking",
  depends: {
    list: bookings.controller,
    order: created.controller,
    count: idCount.controller,
    history: undoHistory.controller,
  },
  run: (deps, ctx) => {
    const slot = checkSlot(rawCall(ctx.input, ctx.rawInput));
    const list = deps.list.get();
    if (hasClash(list, slot.room, slot.date, slot.start, slot.end)) {
      throw appError("Clash", { room: slot.room, start: slot.start, end: slot.end });
    }
    const sequence = deps.count.get();
    const id = `b-${sequence}`;
    const booking: Booking = { id, ...slot };
    const order = { ...deps.order.get(), [id]: sequence };
    deps.list.set(sortedBookings([...list, booking], order));
    deps.count.set(sequence + 1);
    record(deps.history, list);
    return booking;
  },
});

export const bookSeries: Operation.Handle<readonly Booking[], SeriesInput> = operation<
  BookDeps,
  readonly Booking[],
  SeriesInput
>({
  label: "bookSeries",
  depends: {
    list: bookings.controller,
    order: created.controller,
    count: idCount.controller,
    history: undoHistory.controller,
  },
  run: (deps, ctx) => {
    const raw = rawCall(ctx.input, ctx.rawInput);
    const slot = checkSlot(raw);
    const weeks = checkWeeks(readFields(raw).weeks);
    // Every date is checked before any write: one failing date books none of them.
    const dates = seriesDates(slot.date, weeks);
    const list = deps.list.get();
    for (const date of dates) {
      if (hasClash(list, slot.room, date, slot.start, slot.end)) {
        throw appError("Clash", { room: slot.room, start: slot.start, end: slot.end });
      }
    }
    const sequence = deps.count.get();
    const seriesId = `s-${sequence}`;
    const order = { ...deps.order.get() };
    const made: Booking[] = dates.map((date, index) => {
      const id = `b-${sequence + index}`;
      order[id] = sequence + index;
      return { id, ...slot, date, seriesId };
    });
    deps.list.set(sortedBookings([...list, ...made], order));
    deps.count.set(sequence + weeks);
    record(deps.history, list);
    return made;
  },
});

export const cancelBooking: Operation.Handle<void, { id: string }> = operation<
  SlotDeps,
  void,
  { id: string }
>({
  label: "cancelBooking",
  depends: { list: bookings.controller, draft: editDraft.controller, history: undoHistory.controller },
  run: (deps, ctx) => {
    const id = readId(rawCall(ctx.input, ctx.rawInput));
    const list = deps.list.get();
    if (!list.some((booking) => booking.id === id)) {
      throw appError("NotFound", { id });
    }
    deps.list.set(list.filter((booking) => booking.id !== id));
    record(deps.history, list);
    const draft = deps.draft.get();
    if (draft !== undefined && draft.id === id) {
      deps.draft.set(undefined);
    }
  },
});

export const cancelSeries: Operation.Handle<void, { seriesId: string }> = operation<
  SlotDeps,
  void,
  { seriesId: string }
>({
  label: "cancelSeries",
  depends: { list: bookings.controller, draft: editDraft.controller, history: undoHistory.controller },
  run: (deps, ctx) => {
    const seriesId = readSeriesId(rawCall(ctx.input, ctx.rawInput));
    const list = deps.list.get();
    if (!list.some((booking) => booking.seriesId === seriesId)) {
      throw appError("NotFound", { id: seriesId });
    }
    deps.list.set(list.filter((booking) => booking.seriesId !== seriesId));
    record(deps.history, list);
    const draft = deps.draft.get();
    if (draft !== undefined && draft.seriesId === seriesId) {
      deps.draft.set(undefined);
    }
  },
});

export const openEdit: Operation.Handle<Booking, { id: string }> = operation<
  ViewDeps,
  Booking,
  { id: string }
>({
  label: "openEdit",
  depends: { list: bookings.controller, draft: editDraft.controller },
  run: (deps, ctx) => {
    const id = readId(rawCall(ctx.input, ctx.rawInput));
    const found = deps.list.get().find((booking) => booking.id === id);
    if (found === undefined) {
      throw appError("NotFound", { id });
    }
    // Two copies: the draft cell and the caller's result never alias each other.
    deps.draft.set({ ...found });
    return { ...found };
  },
});

export const saveEdit: Operation.Handle<Booking, EditInput> = operation<
  SaveDeps,
  Booking,
  EditInput
>({
  label: "saveEdit",
  depends: {
    list: bookings.controller,
    draft: editDraft.controller,
    order: created.controller,
    history: undoHistory.controller,
  },
  run: (deps, ctx) => {
    const raw = rawCall(ctx.input, ctx.rawInput);
    const id = readId(raw);
    const draft = deps.draft.get();
    if (draft === undefined || draft.id !== id) {
      throw appError("NotFound", { id });
    }
    const list = deps.list.get();
    const found = list.find((booking) => booking.id === id);
    if (found === undefined) {
      throw appError("NotFound", { id });
    }
    const slot = checkSlot(raw);
    if (hasClash(list, slot.room, slot.date, slot.start, slot.end, id)) {
      throw appError("Clash", { room: slot.room, start: slot.start, end: slot.end });
    }
    // The save rewrites the checked fields over the saved row; a series member stays
    // a member, because `seriesId` is identity, not one of the edited fields.
    const saved: Booking = { ...found, ...slot };
    const rest = list.filter((booking) => booking.id !== id);
    deps.list.set(sortedBookings([...rest, saved], deps.order.get()));
    record(deps.history, list);
    deps.draft.set(undefined);
    return saved;
  },
});

export const discardEdit: Operation.Handle<void, { id: string }> = operation<
  DiscardDeps,
  void,
  { id: string }
>({
  label: "discardEdit",
  depends: { draft: editDraft.controller },
  run: (deps, ctx) => {
    const id = readId(rawCall(ctx.input, ctx.rawInput));
    const draft = deps.draft.get();
    if (draft === undefined || draft.id !== id) {
      throw appError("NotFound", { id });
    }
    deps.draft.set(undefined);
  },
});

/** Undo the last passing booking change: pop one history step and restore the list it held.
 * A restore adds no step of its own, so two undos reverse two changes; an empty history
 * reports `EmptyUndo`. Drafts, form text, and filters are booking data, so they stay put. */
export const undoChange: Operation.Handle<void, void> = operation<UndoDeps, void, void>({
  label: "undoChange",
  depends: { list: bookings.controller, history: undoHistory.controller },
  run: (deps) => {
    const stack = deps.history.get();
    const last = stack.at(-1);
    if (last === undefined) {
      throw appError("EmptyUndo", {});
    }
    deps.history.set(stack.slice(0, -1));
    deps.list.set(last);
  },
});

import { data, operation } from "@tinker/core";
import type { Data, Operation, Scope } from "@tinker/core";
import { fail } from "./errors.ts";

/** A bookable room. */
export type Room = "Cedar" | "Maple";

export const rooms: readonly Room[] = ["Cedar", "Maple"];

/** The default calendar day, `YYYY-MM-DD` UTC. */
export const defaultDate = "2026-10-01";

/** One booking: a room on one date, with a start and end time in minutes
 * since midnight. A series booking carries the `seriesId` tying its
 * occurrences together; a one-off booking has none. */
export type Booking = {
  readonly id: string;
  readonly title: string;
  readonly room: Room;
  readonly date: string;
  readonly start: number;
  readonly end: number;
  readonly seriesId?: string;
};

/** What a caller hands to `bookBooking`. The room is a plain string; the
 * operation rejects unknown rooms itself. An omitted date means the default day. */
export type BookInput = {
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

/** What a caller hands to `saveEdit`: the booking to replace, with the new
 * values. An omitted date means the default day. */
export type EditInput = {
  readonly id: string;
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

/** What a caller hands to `bookSeries`: one slot repeated weekly. */
export type SeriesInput = {
  readonly title: string;
  readonly room: string;
  readonly date: string;
  readonly start: number;
  readonly end: number;
  readonly weeks: number;
};

const FIRST_MINUTE = 0;
const LAST_MINUTE = 1439;
const FIRST_WEEK = 1;
const LAST_WEEK = 12;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

const emptyList: readonly Booking[] = [];
const emptyHistory: readonly (readonly Booking[])[] = [];
const emptyOrder: Record<string, number> = {};

/** Every booking, ordered by date, then start time, then creation order. */
export const bookings: Data.Cell<readonly Booking[]> = data({
  label: "bookings",
  initial: emptyList,
});

/** The one open draft: a copy of the booking being edited, or nothing. */
export const editDraft: Data.Cell<Booking | undefined> = data({
  label: "editDraft",
  initial: undefined,
});

/** The creation sequence of each booking id, in creation order. The list cell
 * is kept sorted, so this record is the tie-break that keeps creation order
 * when dates and start times become tied, including after edits and undo. */
const creationOrder: Data.Cell<Readonly<Record<string, number>>> = data({
  label: "creationOrder",
  initial: emptyOrder,
});

/** The saved booking list before each passing change, one entry per step.
 * The newest step is last; an undo pops it and restores its snapshot. */
const undoHistory: Data.Cell<readonly (readonly Booking[])[]> = data({
  label: "undoHistory",
  initial: emptyHistory,
});

/** An id unique in its scope; callers treat it as opaque. */
function newId(): string {
  return globalThis.crypto.randomUUID();
}

function isMinute(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isInteger(value) &&
    value >= FIRST_MINUTE &&
    value <= LAST_MINUTE
  );
}

/** Trim the title; reject a blank or non-text title. */
function titleOf(raw: unknown): string {
  if (typeof raw !== "string") throw fail("BlankTitle", { title: String(raw) });
  const title = raw.trim();
  if (title === "") throw fail("BlankTitle", { title: raw });
  return title;
}

/** Accept only a known room. */
function roomOf(raw: unknown): Room {
  if (raw !== "Cedar" && raw !== "Maple") throw fail("UnknownRoom", { room: String(raw) });
  return raw;
}

/** Accept only an integer minute in 0..1439. */
function minuteOf(raw: unknown): number {
  if (!isMinute(raw)) throw fail("BadTime", { value: raw });
  return raw;
}

/** Accept only a real `YYYY-MM-DD` day; an omitted date means the default day. */
function dateOf(raw: unknown): string {
  if (raw === undefined) return defaultDate;
  if (typeof raw !== "string" || !DATE_PATTERN.test(raw) || !isRealDay(raw)) {
    throw fail("BadDate", { date: raw });
  }
  return raw;
}

/** Days from 1970-01-01 to `year-month-day` in the proleptic Gregorian
 * calendar. Plain integer math, so years below 100 keep their real value. */
function daysFromCivil(year: number, month: number, day: number): number {
  const shifted = month <= 2 ? year - 1 : year;
  const era = Math.floor(shifted / 400);
  const yearOfEra = shifted - era * 400;
  const monthPattern = (month + 9) % 12;
  const dayOfYear = Math.floor((153 * monthPattern + 2) / 5) + day - 1;
  const dayOfEra =
    yearOfEra * 365 + Math.floor(yearOfEra / 4) - Math.floor(yearOfEra / 100) + dayOfYear;
  return era * 146097 + dayOfEra - 719468;
}

/** The calendar day `days` after 1970-01-01, as year, month, day numbers. */
function civilFromDays(days: number): { readonly year: number; readonly month: number; readonly day: number } {
  const shifted = days + 719468;
  const era = Math.floor(shifted / 146097);
  const dayOfEra = shifted - era * 146097;
  const yearOfEra = Math.floor(
    (dayOfEra - Math.floor(dayOfEra / 1460) + Math.floor(dayOfEra / 36524) - Math.floor(dayOfEra / 146096)) / 365,
  );
  const year = yearOfEra + era * 400;
  const dayOfYear =
    dayOfEra - (365 * yearOfEra + Math.floor(yearOfEra / 4) - Math.floor(yearOfEra / 100));
  const monthPattern = Math.floor((5 * dayOfYear + 2) / 153);
  const day = dayOfYear - Math.floor((153 * monthPattern + 2) / 5) + 1;
  const month = monthPattern < 10 ? monthPattern + 3 : monthPattern - 9;
  return { year: month <= 2 ? year + 1 : year, month, day };
}

/** Does the `YYYY-MM-DD` text name a day that exists, leap years included? */
function isRealDay(raw: string): boolean {
  const year = Number(raw.slice(0, 4));
  const month = Number(raw.slice(5, 7));
  const day = Number(raw.slice(8, 10));
  const round = civilFromDays(daysFromCivil(year, month, day));
  return round.year === year && round.month === month && round.day === day;
}

/** Accept only an integer week count in 1..12. */
function weeksOf(raw: unknown): number {
  if (
    typeof raw !== "number" ||
    !Number.isInteger(raw) ||
    raw < FIRST_WEEK ||
    raw > LAST_WEEK
  ) {
    throw fail("BadCount", { weeks: raw });
  }
  return raw;
}

/** The `YYYY-MM-DD` date `days` after `date`. */
function addDays(date: string, days: number): string {
  const start = daysFromCivil(
    Number(date.slice(0, 4)),
    Number(date.slice(5, 7)),
    Number(date.slice(8, 10)),
  );
  const { year, month, day } = civilFromDays(start + days);
  const yearText = String(year).padStart(4, "0");
  const monthText = String(month).padStart(2, "0");
  const dayText = String(day).padStart(2, "0");
  return `${yearText}-${monthText}-${dayText}`;
}

/** Reject any overlap in one room on one date; the same slot on two dates
 * never clashes and back-to-back times are allowed. `skipId` keeps a
 * booking's own slot while it is being edited. */
function assertFree(
  list: readonly Booking[],
  room: Room,
  date: string,
  start: number,
  end: number,
  skipId?: string,
): void {
  for (const booked of list) {
    if (booked.id === skipId) continue;
    if (
      booked.room === room &&
      booked.date === date &&
      start < booked.end &&
      booked.start < end
    ) {
      throw fail("Clash", { room, start, end });
    }
  }
}

/** Order by date, then start time, then creation order. */
function byDateTime(
  list: readonly Booking[],
  order: Readonly<Record<string, number>>,
): readonly Booking[] {
  return [...list].sort((a, b) => {
    if (a.date !== b.date) return a.date < b.date ? -1 : 1;
    if (a.start !== b.start) return a.start - b.start;
    return (order[a.id] ?? 0) - (order[b.id] ?? 0);
  });
}

/** Record new booking ids as created after every existing one. The record only
 * grows: entries for canceled ids stay but are never read again, and undo
 * restores booking data only, so a monotone record stays a valid tie-break. */
function recordCreation(
  order: Scope.DataController<Readonly<Record<string, number>>>,
  ids: readonly string[],
): void {
  order.update((previous) => {
    let highest = 0;
    for (const value of Object.values(previous)) {
      if (value > highest) highest = value;
    }
    const next = { ...previous };
    ids.forEach((id, index) => {
      next[id] = highest + 1 + index;
    });
    return next;
  });
}

/** Record the prior list as one undo step; call only once a change will pass. */
function pushUndoStep(
  history: Scope.DataController<readonly (readonly Booking[])[]>,
  list: readonly Booking[],
): void {
  history.update((prev) => [...prev, list]);
}

/** Undo the last passing booking change: restore its prior booking state and
 * pop the step. Restores booking data only — form text, drafts, and filters
 * are untouched. With no step left it reports `EmptyUndo`. */
export const undoChange: Operation.Handle<void, void> = operation({
  label: "undoChange",
  depends: { list: bookings.controller, history: undoHistory.controller },
  run: ({ list, history }, _ctx) => {
    const steps = history.get();
    const last = steps[steps.length - 1];
    if (last === undefined) throw fail("EmptyUndo", {});
    list.set(last);
    history.set(steps.slice(0, -1));
  },
});

/** Book one slot in one room on one date. Fails on any rule breach; saved
 * bookings are untouched then. */
export const bookBooking: Operation.Handle<Booking, BookInput> = operation({
  label: "bookBooking",
  depends: { list: bookings.controller, order: creationOrder.controller, history: undoHistory.controller },
  run: ({ list, order, history }, ctx) => {
    const title = titleOf(ctx.input.title);
    const room = roomOf(ctx.input.room);
    const date = dateOf(ctx.input.date);
    const start = minuteOf(ctx.input.start);
    const end = minuteOf(ctx.input.end);
    if (end <= start) throw fail("EmptySlot", { start, end });
    const current = list.get();
    assertFree(current, room, date, start, end);
    const booking: Booking = { id: newId(), title, room, date, start, end };
    pushUndoStep(history, current);
    recordCreation(order, [booking.id]);
    list.set(byDateTime([...current, booking], order.get()));
    return booking;
  },
});

/** Book the same slot on `weeks` dates, seven days apart, starting from
 * `date`. Every date is checked first: if any fails, nothing is booked and
 * that error is reported. All occurrences share one `seriesId`. */
export const bookSeries: Operation.Handle<readonly Booking[], SeriesInput> = operation({
  label: "bookSeries",
  depends: { list: bookings.controller, order: creationOrder.controller, history: undoHistory.controller },
  run: ({ list, order, history }, ctx) => {
    const title = titleOf(ctx.input.title);
    const room = roomOf(ctx.input.room);
    const firstDate = dateOf(ctx.input.date);
    const start = minuteOf(ctx.input.start);
    const end = minuteOf(ctx.input.end);
    if (end <= start) throw fail("EmptySlot", { start, end });
    const weeks = weeksOf(ctx.input.weeks);
    const dates: readonly string[] = Array.from(
      { length: weeks },
      (_, index) => addDays(firstDate, index * 7),
    );
    const current = list.get();
    for (const date of dates) assertFree(current, room, date, start, end);
    const seriesId = newId();
    const made: readonly Booking[] = dates.map((date) => ({
      id: newId(),
      title,
      room,
      date,
      start,
      end,
      seriesId,
    }));
    pushUndoStep(history, current);
    recordCreation(order, made.map((booked) => booked.id));
    list.set(byDateTime([...current, ...made], order.get()));
    return made;
  },
});

/** Cancel one booking by id; a second cancel of one id reports not found.
 * Canceling the drafted booking closes its draft too. */
export const cancelBooking: Operation.Handle<void, { readonly id: string }> = operation({
  label: "cancelBooking",
  depends: { list: bookings.controller, draft: editDraft.controller, history: undoHistory.controller },
  run: ({ list, draft, history }, ctx) => {
    const id = ctx.input.id;
    const current = list.get();
    const next = current.filter((booked) => booked.id !== id);
    if (next.length === current.length) throw fail("NotFound", { id });
    pushUndoStep(history, current);
    list.set(next);
    const open = draft.get();
    if (open !== undefined && open.id === id) draft.set(undefined);
  },
});

/** Cancel every occurrence of one series by its series id; an unknown id
 * reports not found. A drafted occurrence of the series loses its draft. */
export const cancelSeries: Operation.Handle<void, { readonly seriesId: string }> = operation({
  label: "cancelSeries",
  depends: { list: bookings.controller, draft: editDraft.controller, history: undoHistory.controller },
  run: ({ list, draft, history }, ctx) => {
    const seriesId = ctx.input.seriesId;
    const current = list.get();
    const next = current.filter((booked) => booked.seriesId !== seriesId);
    if (next.length === current.length) throw fail("NotFound", { id: seriesId });
    pushUndoStep(history, current);
    list.set(next);
    const open = draft.get();
    if (open !== undefined && open.seriesId === seriesId) draft.set(undefined);
  },
});

/** Open one booking for edit as a copy; writing to the copy never changes the
 * saved list. A unknown id reports `NotFound`. Opening a second id closes the
 * first draft, unsaved text lost. */
export const openEdit: Operation.Handle<Booking, { readonly id: string }> = operation({
  label: "openEdit",
  depends: { list: bookings.controller, draft: editDraft.controller },
  run: ({ list, draft }, ctx) => {
    const id = ctx.input.id;
    const saved = list.get().find((booked) => booked.id === id);
    if (saved === undefined) throw fail("NotFound", { id });
    const copy: Booking = { ...saved };
    draft.set(copy);
    return copy;
  },
});

/** Save the open draft: the same title, room, date, and time rules as booking,
 * with the clash check skipping only the booking being edited. A failed save
 * keeps the saved booking and the draft as they were. */
export const saveEdit: Operation.Handle<Booking, EditInput> = operation({
  label: "saveEdit",
  depends: {
    list: bookings.controller,
    order: creationOrder.controller,
    draft: editDraft.controller,
    history: undoHistory.controller,
  },
  run: ({ list, order, draft, history }, ctx) => {
    const id = ctx.input.id;
    const open = draft.get();
    if (open === undefined || open.id !== id) throw fail("NotFound", { id });
    const title = titleOf(ctx.input.title);
    const room = roomOf(ctx.input.room);
    const date = dateOf(ctx.input.date);
    const start = minuteOf(ctx.input.start);
    const end = minuteOf(ctx.input.end);
    if (end <= start) throw fail("EmptySlot", { start, end });
    const current = list.get();
    const savedBefore = current.find((booked) => booked.id === id);
    if (savedBefore === undefined) throw fail("NotFound", { id });
    assertFree(current, room, date, start, end, id);
    const saved: Booking = {
      id,
      title,
      room,
      date,
      start,
      end,
      ...(savedBefore.seriesId !== undefined ? { seriesId: savedBefore.seriesId } : {}),
    };
    pushUndoStep(history, current);
    list.set(byDateTime(current.map((booked) => (booked.id === id ? saved : booked)), order.get()));
    draft.set(undefined);
    return saved;
  },
});

/** Drop the open draft; the saved booking stays. An unknown id reports `NotFound`. */
export const discardEdit: Operation.Handle<void, { readonly id: string }> = operation({
  label: "discardEdit",
  depends: { draft: editDraft.controller },
  run: ({ draft }, ctx) => {
    const id = ctx.input.id;
    const open = draft.get();
    if (open === undefined || open.id !== id) throw fail("NotFound", { id });
    draft.set(undefined);
  },
});

/** Rename every remaining occurrence of one series: the trimmed title replaces
 * each occurrence's title, and ids, series ids, dates, rooms, times, and saved
 * order all stay. An unknown series reports `NotFound` with the series id; a
 * blank title reports `BlankTitle` with the text as typed. A passing rename is
 * one undo step for the whole series; a failed one changes nothing. An open
 * booking draft is left alone, even when it belongs to the series. */
export const renameSeries: Operation.Handle<
  readonly Booking[],
  { readonly seriesId: string; readonly title: string }
> = operation({
  label: "renameSeries",
  depends: { list: bookings.controller, history: undoHistory.controller },
  run: ({ list, history }, ctx) => {
    const title = titleOf(ctx.input.title);
    const seriesId = ctx.input.seriesId;
    const current = list.get();
    const targets = current.filter((booked) => booked.seriesId === seriesId);
    if (targets.length === 0) throw fail("NotFound", { id: seriesId });
    pushUndoStep(history, current);
    const renamed = targets.map((booked) => ({ ...booked, title }));
    const byId = new Map(renamed.map((booked) => [booked.id, booked] as const));
    list.set(current.map((booked) => byId.get(booked.id) ?? booked));
    return renamed;
  },
});

import { fileURLToPath } from "node:url";
import { afterAll, afterEach, beforeAll, beforeEach, expect, test } from "vitest";
import { chromium, type Browser, type Locator, type Page } from "playwright";
import { createServer, type ViteDevServer } from "vite";

/** Any query root: the page itself, or one mounted app inside a page. */
type Root = Page | Locator;

/** One of the two labelled link selects. */
type SelectLabel = "Course" | "Prerequisite";

let server: ViteDevServer;
let browser: Browser;
let page: Page;
let origin: string;

beforeAll(async () => {
  server = await createServer({
    root: fileURLToPath(new URL("..", import.meta.url)),
    logLevel: "silent",
    server: { host: "127.0.0.1", port: 5199, strictPort: false },
  });
  await server.listen();
  const address = server.httpServer?.address();
  origin =
    address !== null && address !== undefined && typeof address !== "string"
      ? `http://127.0.0.1:${address.port}`
      : expect.fail("the dev server opened no port");
  browser = await chromium.launch();
}, 120_000);

beforeEach(async () => {
  page = await browser.newPage();
  await page.goto(`${origin}/`);
}, 60_000);

afterEach(async () => {
  await page.close();
}, 30_000);

afterAll(async () => {
  await browser.close();
  await server.close();
}, 30_000);

/** The one row whose Title cell shows exactly this title. */
function row(root: Root, title: string): Locator {
  return root.locator("td:first-child").getByText(title, { exact: true }).locator("xpath=..");
}

/** The Status cell of one row. */
function statusCell(root: Root, title: string): Locator {
  return row(root, title).getByRole("cell").nth(1);
}

/** The Requires cell of one row. */
function requiresCell(root: Root, title: string): Locator {
  return row(root, title).getByRole("cell").nth(2);
}

/** Wait until one row shows this status. */
async function statusShows(root: Root, title: string, status: string): Promise<void> {
  await statusCell(root, title).getByText(status, { exact: true }).waitFor();
}

/** Wait until one row shows this requirement text. */
async function requiresShows(root: Root, title: string, text: string): Promise<void> {
  await requiresCell(root, title).getByText(text, { exact: true }).waitFor();
}

/** Type a title and press Add course. */
async function addCourse(root: Root, title: string): Promise<void> {
  await root.getByLabel("Title").fill(title);
  await root.getByRole("button", { name: "Add course", exact: true }).click();
}

/** Choose one option in one of the link selects. */
async function choose(root: Root, label: SelectLabel, title: string): Promise<void> {
  await root.getByLabel(label).selectOption({ label: title });
}

/** The text of the option one link select currently shows. */
async function selectedText(root: Root, label: SelectLabel): Promise<string> {
  return (await root.getByLabel(label).locator("option:checked").textContent()) ?? "";
}

/** Wait for the shared alert and read the managed kind it shows. */
async function notice(root: Root): Promise<string> {
  const alert = root.getByRole("alert");
  await alert.waitFor({ state: "visible" });
  return (await alert.textContent()) ?? "";
}

/** Wait until no alert is on screen. */
async function noNotice(root: Root): Promise<void> {
  await root.getByRole("alert").waitFor({ state: "detached" });
}

test(
  "a fresh screen starts empty with All selected and no alert",
  async () => {
    const table = page.getByRole("table", { name: "Courses" });
    await table.waitFor();
    expect(await table.getByRole("columnheader").allTextContents()).toEqual([
      "Title",
      "Status",
