import { data, operation } from "@tinker/core";
import type { Data, Operation, Scope } from "@tinker/core";
import {
  bookBooking,
  bookings,
  bookSeries,
  cancelBooking,
  cancelSeries,
  discardEdit,
  editDraft,
  openEdit,
  renameSeries,
  saveEdit,
  undoChange,
} from "./bookings.ts";
import type { Booking, Room } from "./bookings.ts";
import { defaultDate } from "./bookings.ts";
import { errorKind, fail } from "./errors.ts";
import type { Name } from "./errors.ts";

/** The booking form's text, exactly as typed. Times stay `HH:MM` text until a
 * submit parses them; parsing runs once here, at the text-to-value boundary. */
export type BookingFormText = {
  readonly title: string;
  readonly room: string;
  readonly date: string;
  readonly start: string;
  readonly end: string;
  readonly weeks: string;
};

/** The edit draft's text, exactly as typed, for the drafted booking's id. */
export type EditFormText = {
  readonly id: string;
  readonly title: string;
  readonly room: string;
  readonly date: string;
  readonly start: string;
  readonly end: string;
};

/** Which rows the list shows. */
export type ListFilter = "All" | Room;

/** The booking form's text. Every keystroke updates this cell. */
export const bookingForm: Data.Cell<BookingFormText> = data({
  label: "bookingForm",
  initial: {
    title: "",
    room: "Cedar",
    date: defaultDate,
    start: "09:00",
    end: "10:00",
    weeks: "1",
  },
});

/** The edit draft's text. `openDraft` seeds it from the saved copy, so opening
 * another booking replaces the first draft's unsaved text; typing updates it. */
export const editForm: Data.Cell<EditFormText | undefined> = data({
  label: "editForm",
  initial: undefined,
});

/** The room filter the list applies. */
export const listFilter: Data.Cell<ListFilter> = data({
  label: "listFilter",
  initial: "All",
});

/** The kind of the last managed error, shown in the alert block; empty when
 * the last booking change or save passed. */
export const notice: Data.Cell<Name | undefined> = data({
  label: "notice",
  initial: undefined,
});

/** Parse a 24-hour `HH:MM` text into minutes since midnight. */
export function toMinute(raw: string): number | undefined {
  const match = /^(\d{1,2}):(\d{2})$/.exec(raw.trim());
  if (match === null) return undefined;
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (hours > 23 || minutes > 59) return undefined;
  return hours * 60 + minutes;
}

/** Render minutes since midnight as `HH:MM`. */
export function timeLabel(minute: number): string {
  const hours = String(Math.floor(minute / 60)).padStart(2, "0");
  const minutes = String(minute % 60).padStart(2, "0");
  return `${hours}:${minutes}`;
}

/** The record with one text field replaced. */
function withText<F extends string, T extends Readonly<Record<F, string>>>(
  record: T,
  field: F,
  value: string,
): T {
  return { ...record, [field]: value };
}

/** Parse the form's two times; a cleared or malformed time reports `BadTime`
 * with the text the user typed. */
function timesOf(start: string, end: string): { readonly start: number; readonly end: number } {
  const startMinute = toMinute(start);
  const endMinute = toMinute(end);
  if (startMinute === undefined) throw fail("BadTime", { value: start });
  if (endMinute === undefined) throw fail("BadTime", { value: end });
  return { start: startMinute, end: endMinute };
}

/** Run one body, showing the first managed error's kind in the notice cell and
 * rethrowing any value that is not one of this app's registry errors. */
function withNotice<R>(body: () => R, noticeCell: Scope.DataController<Name | undefined>): R {
  try {
    return body();
  } catch (error) {
    const kind = errorKind(error);
    if (kind === undefined) throw error;
    noticeCell.set(kind);
    throw error;
  }
}

/** Type into one booking form field. */
export const typeBookingField: Operation.Handle<void, { readonly field: keyof BookingFormText; readonly value: string }> =
  operation({
    label: "typeBookingField",
    depends: { form: bookingForm.controller },
    run: ({ form }, ctx) => {
      form.set(withText(form.get(), ctx.input.field, ctx.input.value));
    },
  });

/** Type into one edit draft field; the draft's id is not editable. */
export const typeEditField: Operation.Handle<void, { readonly field: Exclude<keyof EditFormText, "id">; readonly value: string }> =
  operation({
    label: "typeEditField",
    depends: { edit: editForm.controller },
    run: ({ edit }, ctx) => {
      const current = edit.get();
      if (current === undefined) return;
      edit.set(withText(current, ctx.input.field, ctx.input.value));
    },
  });

/** Show one room, or every room. */
export const chooseFilter: Operation.Handle<void, ListFilter> = operation({
  label: "chooseFilter",
  depends: { filter: listFilter.controller },
  run: ({ filter }, ctx) => {
    filter.set(ctx.input);
  },
});

/** Book the form's slot. On success the title clears; a managed failure keeps
 * the form and shows its kind in the alert block. */
export const submitBooking: Operation.Handle<Booking, void> = operation({
  label: "submitBooking",
  depends: {
    form: bookingForm.controller,
    noticeCell: notice.controller,
    book: bookBooking.controller,
  },
  run: ({ form, noticeCell, book }, ctx) =>
    withNotice(() => {
      const text = form.get();
      const times = timesOf(text.start, text.end);
      const saved = book.run({
        input: {
          title: text.title,
          room: text.room,
          date: text.date,
          start: times.start,
          end: times.end,
        },
      });
      form.set({ ...text, title: "" });
      noticeCell.set(undefined);
      return saved;
    }, noticeCell),
});

/** Book the form's slot for `weeks` weeks. The week text parses to a number;
 * anything the operation rejects reports `BadCount`. On success the title
 * clears; a managed failure keeps the form and shows its kind. */
export const submitSeries: Operation.Handle<readonly Booking[], void> = operation({
  label: "submitSeries",
  depends: {
    form: bookingForm.controller,
    noticeCell: notice.controller,
    series: bookSeries.controller,
  },
  run: ({ form, noticeCell, series }, ctx) =>
    withNotice(() => {
      const text = form.get();
      const times = timesOf(text.start, text.end);
      const made = series.run({
        input: {
          title: text.title,
          room: text.room,
          date: text.date,
          start: times.start,
          end: times.end,
          weeks: Number(text.weeks),
        },
      });
      form.set({ ...text, title: "" });
      noticeCell.set(undefined);
      return made;
    }, noticeCell),
});

/** Open one booking for edit: the draft fields seed from the saved copy, so
 * any earlier draft's unsaved text is replaced by the newly selected booking. */
export const openDraft: Operation.Handle<Booking, { readonly id: string }> = operation({
  label: "openDraft",
  depends: {
    edit: editForm.controller,
    noticeCell: notice.controller,
    open: openEdit.controller,
  },
  run: ({ edit, noticeCell, open }, ctx) => {
    const copy = open.run({ input: ctx.input });
    edit.set({
      id: copy.id,
      title: copy.title,
      room: copy.room,
      date: copy.date,
      start: timeLabel(copy.start),
      end: timeLabel(copy.end),
    });
    noticeCell.set(undefined);
    return copy;
  },
});

/** Save the open draft. On success the draft closes; a managed failure keeps
 * the draft and its text open for another try and shows the kind. With no open
 * draft there is nothing to save, so nothing runs. */
export const submitSave: Operation.Handle<Booking | undefined, void> = operation({
  label: "submitSave",
  depends: {
    edit: editForm.controller,
    noticeCell: notice.controller,
    save: saveEdit.controller,
  },
  run: ({ edit, noticeCell, save }, ctx) =>
    withNotice(() => {
      const text = edit.get();
      if (text === undefined) return undefined;
      const times = timesOf(text.start, text.end);
      const saved = save.run({
        input: {
          id: text.id,
          title: text.title,
          room: text.room,
          date: text.date,
          start: times.start,
          end: times.end,
        },
      });
      edit.set(undefined);
      noticeCell.set(undefined);
      return saved;
    }, noticeCell),
});

/** Drop the open draft; the saved booking stays. */
export const submitDiscard: Operation.Handle<void, { readonly id: string }> = operation({
  label: "submitDiscard",
  depends: {
    edit: editForm.controller,
    noticeCell: notice.controller,
    discard: discardEdit.controller,
  },
  run: ({ edit, noticeCell, discard }, ctx) => {
    discard.run({ input: ctx.input });
    edit.set(undefined);
    noticeCell.set(undefined);
  },
});

/** Cancel one booking by id; a drafted occurrence that was canceled loses its
 * draft text too. */
export const cancelRow: Operation.Handle<void, { readonly id: string }> = operation({
  label: "cancelRow",
  depends: {
    edit: editForm.controller,
    draft: editDraft.controller,
    noticeCell: notice.controller,
    cancel: cancelBooking.controller,
  },
  run: ({ edit, draft, noticeCell, cancel }, ctx) => {
    const before = draft.get();
    cancel.run({ input: ctx.input });
    if (draft.get() !== before) edit.set(undefined);
    noticeCell.set(undefined);
  },
});

/** Cancel every occurrence of one series; a drafted occurrence of the series
 * loses its draft text too. */
export const cancelSeriesRow: Operation.Handle<void, { readonly seriesId: string }> = operation({
  label: "cancelSeriesRow",
  depends: {
    edit: editForm.controller,
    draft: editDraft.controller,
    noticeCell: notice.controller,
    cancel: cancelSeries.controller,
  },
  run: ({ edit, draft, noticeCell, cancel }, ctx) => {
    const before = draft.get();
    cancel.run({ input: ctx.input });
    if (draft.get() !== before) edit.set(undefined);
    noticeCell.set(undefined);
  },
});

/** Undo the last passing booking change; booking data only, never the form,
 * draft, or filter. An empty undo shows `EmptyUndo` in the alert block. */
export const undoLast: Operation.Handle<void, void> = operation({
  label: "undoLast",
  depends: { noticeCell: notice.controller, undo: undoChange.controller },
  run: ({ noticeCell, undo }) => {
    try {
      undo.run({});
      noticeCell.set(undefined);
    } catch (error) {
      const kind = errorKind(error);
      if (kind === undefined) throw error;
      noticeCell.set(kind);
      throw error;
    }
  },
});

/** The series-title editor's text: the series being renamed and the title as
 * typed. It is open only while a `Rename series` button has been clicked. */
export type SeriesTitleText = {
  readonly seriesId: string;
  readonly title: string;
};

/** The open series-title editor, or nothing. Opening another series replaces
 * the first one's unsaved text; typing updates this cell. */
export const seriesForm: Data.Cell<SeriesTitleText | undefined> = data({
  label: "seriesForm",
  initial: undefined,
});

/** Open the series-title editor for one series row: the editor seeds from the
 * clicked row's saved title. The booking must be a series occurrence. */
export const openSeriesTitle: Operation.Handle<void, { readonly id: string }> = operation({
  label: "openSeriesTitle",
  depends: {
    list: bookings.controller,
    series: seriesForm.controller,
    noticeCell: notice.controller,
  },
  run: ({ list, series, noticeCell }, ctx) => {
    const booked = list.get().find((each) => each.id === ctx.input.id);
    const seriesId = booked?.seriesId;
    if (booked === undefined || seriesId === undefined) throw fail("NotFound", { id: ctx.input.id });
    series.set({ seriesId, title: booked.title });
    noticeCell.set(undefined);
  },
});

/** Type into the open series-title editor. */
export const typeSeriesTitle: Operation.Handle<void, { readonly value: string }> = operation({
  label: "typeSeriesTitle",
  depends: { series: seriesForm.controller },
  run: ({ series }, ctx) => {
    const current = series.get();
    if (current === undefined) return;
    series.set({ ...current, title: ctx.input.value });
  },
});

/** Save the series title through `renameSeries`. On success the editor closes;
 * a managed failure keeps the editor and its text open for another try and
 * shows the error kind in the alert block. With no open editor nothing runs. */
export const submitSeriesTitle: Operation.Handle<readonly Booking[] | undefined, void> = operation({
  label: "submitSeriesTitle",
  depends: {
    series: seriesForm.controller,
    noticeCell: notice.controller,
    rename: renameSeries.controller,
  },
  run: ({ series, noticeCell, rename }, ctx) =>
    withNotice(() => {
      const editor = series.get();
      if (editor === undefined) return undefined;
      const renamed = rename.run({
        input: { seriesId: editor.seriesId, title: editor.title },
      });
      series.set(undefined);
      noticeCell.set(undefined);
      return renamed;
    }, noticeCell),
});

/** Drop the series-title editor; the saved series and undo history stay. */
export const discardSeriesTitle: Operation.Handle<void, void> = operation({
  label: "discardSeriesTitle",
  depends: { series: seriesForm.controller, noticeCell: notice.controller },
  run: ({ series, noticeCell }) => {
    series.set(undefined);
    noticeCell.set(undefined);
  },
});

