/** A stock line's item kind. */
export type Item = "Cable" | "Stand";

/** A stock location. */
export type Place = "East" | "West";

/** Every item, in desk order. */
export const items: readonly Item[] = ["Cable", "Stand"];

/** Every place, in desk order. */
export const places: readonly Place[] = ["East", "West"];

/** One stock line: how much of one item sits at one place. */
export type Stock = {
  item: Item;
  place: Place;
  quantity: number;
};

/** One saved move. */
export type Move = {
  id: string;
  item: Item;
  from: Place;
  to: Place;
  quantity: number;
};

/** Input for one new move: names are raw text, quantity is a raw API number. */
export type MoveInput = {
  item: string;
  from: string;
  to: string;
  quantity: number;
};

/** Input for replacing the open draft's saved move: {@link MoveInput} plus the move id. */
export type EditMoveInput = MoveInput & { id: string };

/** The typed text held by one four-field move form. */
export type FormText = {
  item: string;
  from: string;
  to: string;
  quantity: string;
};

/** The raw, still-unvalidated fields read off one move submission. */
export type RawFields = {
  id: unknown;
  item: unknown;
  from: unknown;
  to: unknown;
  quantity: unknown;
};

/** The four stock lines a fresh scope starts with, in desk order. */
export function initialStock(): readonly Stock[] {
  return [
    { item: "Cable", place: "East", quantity: 8 },
    { item: "Cable", place: "West", quantity: 2 },
    { item: "Stand", place: "East", quantity: 3 },
    { item: "Stand", place: "West", quantity: 1 },
  ];
}

/** Whether a raw value is an object that can carry named fields. */
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

/** Read one named field off untyped input; missing or shapeless input reads as `undefined`. */
function readField(raw: unknown, key: string): unknown {
  return isRecord(raw) ? raw[key] : undefined;
}

/** Split one raw submission into its named fields, keeping every value untyped. */
export function readFields(raw: unknown): RawFields {
  return {
    id: readField(raw, "id"),
    item: readField(raw, "item"),
    from: readField(raw, "from"),
    to: readField(raw, "to"),
    quantity: readField(raw, "quantity"),
  };
}

/** Narrow a raw value to a known item, or fail `UnknownItem` with the original value. */
export function asItem(value: unknown): Item {
  for (const item of items) {
    if (value === item) return item;
  }
  return fail("UnknownItem", { item: value });
}

/** Narrow a raw value to a known place, or fail `UnknownPlace` with the original value. */
export function asPlace(value: unknown): Place {
  for (const place of places) {
    if (value === place) return place;
  }
  return fail("UnknownPlace", { place: value });
}

/**
 * Narrow a raw value to an API quantity: a positive safe integer, or fail
 * `BadQuantity` with the original value.
 */
export function asQuantity(value: unknown): number {
  if (typeof value === "number" && Number.isSafeInteger(value) && value > 0) return value;
  return fail("BadQuantity", { quantity: value });
}

/** Narrow a raw value to a saved-move id, or fail `NotFound` (an unnamed id is never found). */
export function asId(value: unknown): string {
  return typeof value === "string" ? value : fail("NotFound", { id: "" });
}

/**
 * Parse one quantity field's text at the input boundary: readable number text
 * becomes its number, anything else (a cleared or unreadable field) keeps its
 * original text so `BadQuantity` can report it.
 */
export function quantityFromText(text: string): number | string {
  const parsed = Number(text);
  return text.trim() === "" || Number.isNaN(parsed) ? text : parsed;
}

/** The form text with one field retyped. */
export function withField(text: FormText, field: keyof FormText, value: string): FormText {
  switch (field) {
    case "item":
      return { ...text, item: value };
    case "from":
      return { ...text, from: value };
    case "to":
      return { ...text, to: value };
    case "quantity":
      return { ...text, quantity: value };
  }
}

/** The raw fields one form submits, with quantity text parsed at the input boundary. */
export function submitFields(form: FormText): { item: string; from: string; to: string; quantity: number | string } {
  return { item: form.item, from: form.from, to: form.to, quantity: quantityFromText(form.quantity) };
}

/** The fixed slot one stock line occupies in desk order. */
function slotOf(item: Item, place: Place): number {
  return items.indexOf(item) * places.length + places.indexOf(place);
}

/** How much of one item currently sits at one place. */
export function quantityAt(rows: readonly Stock[], item: Item, place: Place): number {
  return rows[slotOf(item, place)].quantity;
}

/**
 * The stock rows after moving `quantity` of `item` from one place to another,
 * or a `ShortStock` failure naming the source and its shortfall.
 */
export function applyMove(rows: readonly Stock[], item: Item, from: Place, to: Place, quantity: number): readonly Stock[] {
  const available = quantityAt(rows, item, from);
  if (available < quantity) fail("ShortStock", { item, place: from, available, requested: quantity });
  return rows.map((row) =>
    row.item === item && row.place === from
      ? { ...row, quantity: row.quantity - quantity }
      : row.item === item && row.place === to
        ? { ...row, quantity: row.quantity + quantity }
        : row,
  );
}

/**
 * The stock rows after putting one saved move back: `quantity` of `item` leaves
 * the old target for the old source, or a `ShortStock` failure naming the old
 * target and the old quantity when it cannot cover the reversal.
 */
export function reverseMove(rows: readonly Stock[], move: Move): readonly Stock[] {
  const available = quantityAt(rows, move.item, move.to);
  if (available < move.quantity) fail("ShortStock", { item: move.item, place: move.to, available, requested: move.quantity });
  return rows.map((row) =>
    row.item === move.item && row.place === move.to
      ? { ...row, quantity: row.quantity - move.quantity }
      : row.item === move.item && row.place === move.from
        ? { ...row, quantity: row.quantity + move.quantity }
        : row,
  );
}

