/** Every managed failure the plan can report, with the payload it carries: the one registry. */
export type Payloads = {
  /** The title was empty or was not text; `title` keeps the original input value. */
  BlankTitle: { title: unknown };
  /** No saved course in this scope carries this id. */
  NotFound: { id: string };
  /** A course was asked to require itself; `id` is that course. */
  SelfRequirement: { id: string };
  /** The requested link would close a loop of requirements. */
  Cycle: { courseId: string; prerequisiteId: string };
  /** A completed course had its requirements changed; `id` is that course. */
  CourseDone: { id: string };
  /** The named link is not on the course, so there is nothing to remove. */
  NotRequired: { courseId: string; prerequisiteId: string };
  /** The course is not completable yet; the ids are open requirements in link order. */
  PrerequisitesOpen: { id: string; prerequisiteIds: readonly string[] };
  /** The course is not reopenable yet; the ids are completed dependents in saved order. */
  DependentsDone: { id: string; dependentIds: readonly string[] };
  /** Undo was asked for with no passing change left to restore. */
  EmptyUndo: {};
};

/** The app's managed errors: one name per kind, its typed payload, and the error carrying both. */
export declare namespace Errors {
  /** Every managed failure name. */
  type Name = keyof Payloads;
  /** The payload one failure name carries. */
  type Payload<N extends Name> = Payloads[N];
  /** A managed failure: identified by `kind`, carrying a typed `payload`. */
  type Of<N extends Name = Name> = Error & {
    readonly kind: N;
    readonly payload: Payloads[N];
  };
}

/** Narrow an unknown value to one registry entry; callers fail or rethrow on mismatch. */
export function isError<N extends Errors.Name>(value: unknown, kind: N): value is Errors.Of<N> {
  return value instanceof Error && "kind" in value && typeof value.kind === "string" && value.kind === kind;
}

/** Raise one managed failure; the only place this app builds an error. */
export function raise<N extends Errors.Name>(kind: N, payload: Errors.Payload<N>): never {
  throw Object.assign(new Error(kind), { kind, payload });
}

