import { data, operation } from "@tinker/core";
import type { Data, Operation, Scope } from "@tinker/core";
import { fail } from "./errors.ts";

/** A bookable room. */
export type Room = "Cedar" | "Maple";

export const rooms: readonly Room[] = ["Cedar", "Maple"];

/** The default calendar day, `YYYY-MM-DD` UTC. */
export const defaultDate = "2026-10-01";

/** One booking: a room on one date, with a start and end time in minutes
 * since midnight. A series booking carries the `seriesId` tying its
 * occurrences together; a one-off booking has none. */
export type Booking = {
  readonly id: string;
  readonly title: string;
  readonly room: Room;
  readonly date: string;
  readonly start: number;
  readonly end: number;
  readonly seriesId?: string;
};

/** What a caller hands to `bookBooking`. The room is a plain string; the
 * operation rejects unknown rooms itself. An omitted date means the default day. */
export type BookInput = {
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

/** What a caller hands to `saveEdit`: the booking to replace, with the new
 * values. An omitted date means the default day. */
export type EditInput = {
  readonly id: string;
  readonly title: string;
  readonly room: string;
  readonly date?: string;
  readonly start: number;
  readonly end: number;
};

/** What a caller hands to `bookSeries`: one slot repeated weekly. */
export type SeriesInput = {
  readonly title: string;
  readonly room: string;
  readonly date: string;
  readonly start: number;
  readonly end: number;
  readonly weeks: number;
};

const FIRST_MINUTE = 0;
const LAST_MINUTE = 1439;
const FIRST_WEEK = 1;
const LAST_WEEK = 12;
const DAY_MS = 86_400_000;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

const emptyList: readonly Booking[] = [];
const emptyHistory: readonly (readonly Booking[])[] = [];

/** Every booking, ordered by date, then start time, then creation order. */
export const bookings: Data.Cell<readonly Booking[]> = data({
  label: "bookings",
  initial: emptyList,
});

/** The one open draft: a copy of the booking being edited, or nothing. */
export const editDraft: Data.Cell<Booking | undefined> = data({
  label: "editDraft",
  initial: undefined,
});

/** The saved booking list before each passing change, one entry per step.
 * The newest step is last; an undo pops it and restores its snapshot. */
const undoHistory: Data.Cell<readonly (readonly Booking[])[]> = data({
  label: "undoHistory",
  initial: emptyHistory,
});

let idCounter = 0;

/** An id unique in its scope; callers treat it as opaque. */
function newId(): string {
  const uuid = globalThis.crypto?.randomUUID?.();
  if (uuid !== undefined) return uuid;
  idCounter += 1;
  return `booking-${idCounter}`;
}

function isMinute(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isInteger(value) &&
    value >= FIRST_MINUTE &&
    value <= LAST_MINUTE
  );
}

/** Trim the title; reject a blank or non-text title. */
function titleOf(raw: unknown): string {
  if (typeof raw !== "string") throw fail("BlankTitle", { title: String(raw) });
  const title = raw.trim();
  if (title === "") throw fail("BlankTitle", { title: raw });
  return title;
}

/** Accept only a known room. */
function roomOf(raw: unknown): Room {
  if (raw !== "Cedar" && raw !== "Maple") throw fail("UnknownRoom", { room: String(raw) });
  return raw;
}

/** Accept only an integer minute in 0..1439. */
function minuteOf(raw: unknown): number {
  if (!isMinute(raw)) throw fail("BadTime", { value: raw });
  return raw;
}

/** Accept only a real `YYYY-MM-DD` day; an omitted date means the default day. */
function dateOf(raw: unknown): string {
  if (raw === undefined) return defaultDate;
  if (typeof raw !== "string" || !DATE_PATTERN.test(raw) || !isRealDay(raw)) {
    throw fail("BadDate", { date: raw });
  }
  return raw;
}

/** Does the `YYYY-MM-DD` text name a day that exists, leap years included? */
function isRealDay(raw: string): boolean {
  const year = Number(raw.slice(0, 4));
  const month = Number(raw.slice(5, 7));
  const day = Number(raw.slice(8, 10));
  const check = new Date(Date.UTC(year, month - 1, day));
  return (
    check.getUTCFullYear() === year &&
    check.getUTCMonth() === month - 1 &&
    check.getUTCDate() === day
  );
}

/** Accept only an integer week count in 1..12. */
function weeksOf(raw: unknown): number {
  if (
    typeof raw !== "number" ||
    !Number.isInteger(raw) ||
    raw < FIRST_WEEK ||
    raw > LAST_WEEK
  ) {
    throw fail("BadCount", { weeks: raw });
  }
  return raw;
}

/** The date `days` after `date`, still `YYYY-MM-DD` in UTC. */
function addDays(date: string, days: number): string {
  const start = Date.UTC(
    Number(date.slice(0, 4)),
    Number(date.slice(5, 7)) - 1,
    Number(date.slice(8, 10)),
  );
  return new Date(start + days * DAY_MS).toISOString().slice(0, 10);
}

/** Reject any overlap in one room on one date; the same slot on two dates
 * never clashes and back-to-back times are allowed. `skipId` keeps a
 * booking's own slot while it is being edited. */
function assertFree(
  list: readonly Booking[],
  room: Room,
  date: string,
  start: number,
  end: number,
  skipId?: string,
): void {
  for (const booked of list) {
    if (booked.id === skipId) continue;
    if (
      booked.room === room &&
      booked.date === date &&
      start < booked.end &&
      booked.start < end
    ) {
      throw fail("Clash", { room, start, end });
    }
  }
}

/** Order by date, then start time; the sort is stable, so ties keep creation order. */
function byDateTime(list: readonly Booking[]): readonly Booking[] {
  return [...list].sort((a, b) => {
    if (a.date !== b.date) return a.date < b.date ? -1 : 1;
    return a.start - b.start;
  });
}

/** Record the prior list as one undo step; call only once a change will pass. */
function pushUndoStep(
  history: Scope.DataController<readonly (readonly Booking[])[]>,
  list: readonly Booking[],
): void {
  history.update((prev) => [...prev, list]);
}

/** Undo the last passing booking change: restore its prior booking state and
 * pop the step. Restores booking data only — form text, drafts, and filters
 * are untouched. With no step left it reports `EmptyUndo`. */
export const undoChange: Operation.Handle<void, void> = operation({
  label: "undoChange",
  depends: { list: bookings.controller, history: undoHistory.controller },
  run: ({ list, history }, _ctx) => {
    const steps = history.get();
    const last = steps[steps.length - 1];
    if (last === undefined) throw fail("EmptyUndo", {});
    list.set(last);
    history.set(steps.slice(0, -1));
  },
});

/** Book one slot in one room on one date. Fails on any rule breach; saved
 * bookings are untouched then. */
export const bookBooking: Operation.Handle<Booking, BookInput> = operation({
  label: "bookBooking",
  depends: { list: bookings.controller, history: undoHistory.controller },
  run: ({ list, history }, ctx) => {
    const title = titleOf(ctx.input.title);
    const room = roomOf(ctx.input.room);
    const date = dateOf(ctx.input.date);
    const start = minuteOf(ctx.input.start);
    const end = minuteOf(ctx.input.end);
    if (end <= start) throw fail("EmptySlot", { start, end });
    const current = list.get();
    assertFree(current, room, date, start, end);
    const booking: Booking = { id: newId(), title, room, date, start, end };
    pushUndoStep(history, current);
    list.set(byDateTime([...current, booking]));
    return booking;
  },
});

/** Book the same slot on `weeks` dates, seven days apart, starting from
 * `date`. Every date is checked first: if any fails, nothing is booked and
 * that error is reported. All occurrences share one `seriesId`. */
export const bookSeries: Operation.Handle<readonly Booking[], SeriesInput> = operation({
  label: "bookSeries",
  depends: { list: bookings.controller, history: undoHistory.controller },
  run: ({ list, history }, ctx) => {
    const title = titleOf(ctx.input.title);
    const room = roomOf(ctx.input.room);
    const firstDate = dateOf(ctx.input.date);
    const start = minuteOf(ctx.input.start);
    const end = minuteOf(ctx.input.end);
    if (end <= start) throw fail("EmptySlot", { start, end });
    const weeks = weeksOf(ctx.input.weeks);
    const dates: readonly string[] = Array.from(
      { length: weeks },
      (_, index) => addDays(firstDate, index * 7),
    );
    const current = list.get();
    for (const date of dates) assertFree(current, room, date, start, end);
    const seriesId = newId();
    const made: readonly Booking[] = dates.map((date) => ({
      id: newId(),
      title,
      room,
      date,
      start,
      end,
      seriesId,
    }));
    pushUndoStep(history, current);
    list.set(byDateTime([...current, ...made]));
    return made;
  },
});

/** Cancel one booking by id; a second cancel of one id reports not found.
 * Canceling the drafted booking closes its draft too. */
export const cancelBooking: Operation.Handle<void, { readonly id: string }> = operation({
  label: "cancelBooking",
  depends: { list: bookings.controller, draft: editDraft.controller, history: undoHistory.controller },
  run: ({ list, draft, history }, ctx) => {
    const id = ctx.input.id;
    const current = list.get();
    const next = current.filter((booked) => booked.id !== id);
    if (next.length === current.length) throw fail("NotFound", { id });
    pushUndoStep(history, current);
    list.set(next);
    const open = draft.get();
    if (open !== undefined && open.id === id) draft.set(undefined);
  },
});

/** Cancel every occurrence of one series by its series id; an unknown id
 * reports not found. A drafted occurrence of the series loses its draft. */
export const cancelSeries: Operation.Handle<void, { readonly seriesId: string }> = operation({
  label: "cancelSeries",
  depends: { list: bookings.controller, draft: editDraft.controller, history: undoHistory.controller },
  run: ({ list, draft, history }, ctx) => {
    const seriesId = ctx.input.seriesId;
    const current = list.get();
    const next = current.filter((booked) => booked.seriesId !== seriesId);
    if (next.length === current.length) throw fail("NotFound", { id: seriesId });
    pushUndoStep(history, current);
    list.set(next);
    const open = draft.get();
    if (open !== undefined && open.seriesId === seriesId) draft.set(undefined);
  },
});

/** Open one booking for edit as a copy; writing to the copy never changes the
 * saved list. A unknown id reports `NotFound`. Opening a second id closes the
 * first draft, unsaved text lost. */
export const openEdit: Operation.Handle<Booking, { readonly id: string }> = operation({
  label: "openEdit",
  depends: { list: bookings.controller, draft: editDraft.controller },
  run: ({ list, draft }, ctx) => {
    const id = ctx.input.id;
    const saved = list.get().find((booked) => booked.id === id);
    if (saved === undefined) throw fail("NotFound", { id });
    const copy: Booking = { ...saved };
    draft.set(copy);
    return copy;
  },
});

/** Save the open draft: the same title, room, date, and time rules as booking,
 * with the clash check skipping only the booking being edited. A failed save
 * keeps the saved booking and the draft as they were. */
export const saveEdit: Operation.Handle<Booking, EditInput> = operation({
  label: "saveEdit",
  depends: { list: bookings.controller, draft: editDraft.controller, history: undoHistory.controller },
  run: ({ list, draft, history }, ctx) => {
    const id = ctx.input.id;
    const open = draft.get();
    if (open === undefined || open.id !== id) throw fail("NotFound", { id });
    const title = titleOf(ctx.input.title);
    const room = roomOf(ctx.input.room);
    const date = dateOf(ctx.input.date);
    const start = minuteOf(ctx.input.start);
    const end = minuteOf(ctx.input.end);
    if (end <= start) throw fail("EmptySlot", { start, end });
    const current = list.get();
    const savedBefore = current.find((booked) => booked.id === id);
    if (savedBefore === undefined) throw fail("NotFound", { id });
    assertFree(current, room, date, start, end, id);
    const saved: Booking = {
      id,
      title,
      room,
      date,
      start,
      end,
      ...(savedBefore.seriesId !== undefined ? { seriesId: savedBefore.seriesId } : {}),
    };
    pushUndoStep(history, current);
    list.set(byDateTime(current.map((booked) => (booked.id === id ? saved : booked))));
    draft.set(undefined);
    return saved;
  },
});

/** Drop the open draft; the saved booking stays. An unknown id reports `NotFound`. */
export const discardEdit: Operation.Handle<void, { readonly id: string }> = operation({
  label: "discardEdit",
  depends: { draft: editDraft.controller },
  run: ({ draft }, ctx) => {
    const id = ctx.input.id;
    const open = draft.get();
    if (open === undefined || open.id !== id) throw fail("NotFound", { id });
    draft.set(undefined);
  },
});

/** One stock item this desk handles. */
export type Item = "Cable" | "Stand";

/** One place stock can stand in. */
export type Place = "East" | "West";

/** Every item, in `Cable`, `Stand` order. */
export const items: readonly Item[] = ["Cable", "Stand"];

/** Every place, in `East`, `West` order. */
export const places: readonly Place[] = ["East", "West"];

/** One stock row: how much of an item is held in one place. */
export type Stock = { item: Item; place: Place; quantity: number };

/** One recorded move, addressed by its scope-unique `id`. */
export type Move = { id: string; item: Item; from: Place; to: Place; quantity: number };

/** A move as the API accepts it: names are untrusted text, the quantity is a number. */
export type MoveInput = { item: string; from: string; to: string; quantity: number };

/** A replacement for the saved move with `id`, accepted by `saveMoveEdit`. */
export type EditMoveInput = MoveInput & { id: string };

import type { Item, Place } from "./model.ts";

/** Every failure this app can produce, with the payload each kind carries. */
type Payloads = {
  /** An item name that is not one of the `items`. */
  UnknownItem: { item: unknown };
  /** A place name that is not one of the `places`. */
  UnknownPlace: { place: unknown };
  /** A move whose two places are the same one. */
  SamePlace: { place: string };
  /** A quantity that is not a positive safe integer. */
  BadQuantity: { quantity: unknown };
  /** A move larger than the stock standing in its source row. */
  ShortStock: { item: Item; place: Place; available: number; requested: number };
  /** A move id with no open draft or saved move. */
  NotFound: { id: string };
  /** An undo requested with no history left. */
  EmptyUndo: {};
};

/** The app error registry: names, payloads, and the typed error value each name carries. */
export declare namespace Errors {
  /** Every app error name. */
  type Name = keyof Payloads;
  /** The payload carried by one error name. */
  type Payload<N extends Name> = Payloads[N];
  /** An app error: identified by `kind`, carrying a typed `payload`. */
  type Of<N extends Name = Name> = Error & {
    readonly kind: N;
    readonly payload: Payloads[N];
  };
}

/** Every app error name, in registry order. */
const names: readonly Errors.Name[] = [
  "UnknownItem",
  "UnknownPlace",
  "SamePlace",
  "BadQuantity",
  "ShortStock",
  "NotFound",
  "EmptyUndo",
];

/** Raise the one registry error for `kind`; the only place the app creates a failure. */
export function raise<N extends Errors.Name>(kind: N, payload: Errors.Payload<N>): never {
  throw Object.assign(new Error(kind), { kind, payload });
}

/** Narrow an unknown thrown value to one registry entry; callers rethrow on mismatch. */
export function isError<N extends Errors.Name>(value: unknown, kind: N): value is Errors.Of<N> {
  return value instanceof Error && "kind" in value && value.kind === kind;
}

/** Narrow a thrown value to any registry entry, or `undefined` when it is not one of ours. */
export function managed(value: unknown): Errors.Of | undefined {
  for (const name of names) {
    if (isError(value, name)) return value;
  }
  return undefined;
}

/**
 * The stock-desk screen: form, tables, editor, filters, undo, and the shared
 * error notice. Every value shown is read from a core cell; every action runs
 * an operation.
 */
import { useId } from 'react';
import type { ReactNode } from 'react';
import { createScope } from '@tinker/core';
import { ScopeProvider, useData, useRun } from '@tinker/react';
import {
  discardMoveEdit,
  editDraft,
  editFormFrom,
  editFormItem,
  editFormQuantity,
  editFormTo,
  formFrom,
  formItem,
  formQuantity,
  formTo,
  moveFilter,
  moveStock,
  moves,
  notice,
  openMoveEdit,
  saveMoveEdit,
  setMoveFilter,
  stock,
  undoMove,
} from './desk';
import type { MoveFilter } from './desk';

/**
 * Parse number text at the input boundary: readable text becomes a number,
 * anything else keeps its text so the operation can report it.
 */
function parseQuantityText(text: string): number | string {
  if (text.trim() === '') return text;
  const parsed = Number(text);
  return Number.isFinite(parsed) ? parsed : text;
}

function LabeledInput(props: { label: string; value: string; onChange: (next: string) => void }): ReactNode {
  const id = useId();
  return (
    <label htmlFor={id}>
      {props.label}
      <input
        id={id}
        value={props.value}
        onChange={(event) => props.onChange(event.target.value)}
      />
    </label>
  );
}

function Notice(): ReactNode {
  const kind = useData(notice);
  return <div role="alert">{kind ?? ''}</div>;
}

function MoveForm(): ReactNode {
  const [item, setItem] = useData(formItem, { writable: true });
  const [from, setFrom] = useData(formFrom, { writable: true });
  const [to, setTo] = useData(formTo, { writable: true });
  const [quantity, setQuantity] = useData(formQuantity, { writable: true });
  const runMove = useRun(moveStock);
  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        runMove.run({
          rawInput: {
            item,
            from,
            to,
            quantity: parseQuantityText(quantity),
          },
        });
      }}
    >
      <LabeledInput label="Item" value={item} onChange={setItem} />
      <LabeledInput label="From" value={from} onChange={setFrom} />
      <LabeledInput label="To" value={to} onChange={setTo} />
      <LabeledInput label="Quantity" value={quantity} onChange={setQuantity} />
      <button type="submit">Move stock</button>
    </form>
  );
}

function StockTable(): ReactNode {
  const rows = useData(stock);
  return (
    <table>
      <caption>Stock</caption>
      <thead>
        <tr>
          <th>Item</th>
          <th>Place</th>
          <th>Quantity</th>
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr key={`${row.item} ${row.place}`}>
            <td>{row.item}</td>
            <td>{row.place}</td>
            <td>{row.quantity}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function MoveFilters(): ReactNode {
  const runFilter = useRun(setMoveFilter);
  const choices: readonly MoveFilter[] = ['All', 'Cable', 'Stand'];
  return (
    <div>
      {choices.map((choice) => (
        <button key={choice} type="button" onClick={() => runFilter.run({ input: choice })}>
          {choice}
        </button>
      ))}
    </div>
  );
}

function MovesTable(): ReactNode {
  const saved = useData(moves);
  const filter = useData(moveFilter);
  const rows = filter === 'All' ? saved : saved.filter((move) => move.item === filter);
  const open = useRun(openMoveEdit);
  return (
    <table>
      <caption>Moves</caption>
      <thead>
        <tr>
          <th>Item</th>
          <th>From</th>
          <th>To</th>
          <th>Quantity</th>
        </tr>
      </thead>
      <tbody>
        {rows.map((move) => (
          <tr key={move.id}>
            <td>{move.item}</td>
            <td>{move.from}</td>
            <td>{move.to}</td>
            <td>{move.quantity}</td>
            <td>
              <button type="button" onClick={() => open.run({ input: { id: move.id } })}>
                Edit move
              </button>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function MoveEditor(): ReactNode {
  const draft = useData(editDraft);
  const [item, setItem] = useData(editFormItem, { writable: true });
  const [from, setFrom] = useData(editFormFrom, { writable: true });
  const [to, setTo] = useData(editFormTo, { writable: true });
  const [quantity, setQuantity] = useData(editFormQuantity, { writable: true });
  const save = useRun(saveMoveEdit);
  const discard = useRun(discardMoveEdit);
  if (draft === undefined) return null;
  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        save.run({
          rawInput: {
            id: draft.id,
            item,
            from,
            to,
            quantity: parseQuantityText(quantity),
          },
        });
      }}
    >
      <LabeledInput label="Edit item" value={item} onChange={setItem} />
      <LabeledInput label="Edit from" value={from} onChange={setFrom} />
      <LabeledInput label="Edit to" value={to} onChange={setTo} />
      <LabeledInput label="Edit quantity" value={quantity} onChange={setQuantity} />
      <button type="submit">Save move</button>
      <button type="button" onClick={() => discard.run({ input: { id: draft.id } })}>
        Discard move
      </button>
    </form>
  );
}

function UndoButton(): ReactNode {
  const runUndo = useRun(undoMove);
  return (
    <button type="button" onClick={() => runUndo.run({})}>
      Undo
    </button>
  );
}

function Desk(): ReactNode {
  return (
    <>
      <Notice />
      <MoveForm />
      <StockTable />
      <MoveFilters />
      <MovesTable />
      <MoveEditor />
      <UndoButton />
    </>
  );
}

/**
 * The stock desk. Each mounted app owns one fresh scope, so two apps on one
 * page share no stock, moves, drafts, notices, or form text.
 */
export function StockApp(): ReactNode {
  return (
    <ScopeProvider create={() => createScope()}>
      <Desk />
    </ScopeProvider>
  );
}

import { operation } from "@tinker/core";
import type { Operation } from "@tinker/core";
import {
  draftTitle,
  filter,
  notice,
  selectedCourseId,
  selectedPrerequisiteId,
} from "./state.ts";
