/** Store the typed Title text; typing clears any error notice. */
export const typeTitle: Operation.Handle<void, { title: string }> = operation({
  label: "typeTitle",
  depends: { draftTitle: draftTitle.controller, notice: notice.controller },
  run: (deps, ctx) => {
    deps.notice.set(undefined);
    deps.draftTitle.set(ctx.input.title);
