state.source:
export function initialStock(): readonly Stock[] {
  return [
    { item: "Cable", place: "East", quantity: 8 },
    { item: "Cable", place: "West", quantity: 2 },
    { item: "Stand", place: "East", quantity: 3 },
    { item: "Stand", place: "West", quantity: 1 },
  ];
}

export function retitleSeries(
  list: readonly Booking[],
  seriesId: string,
  title: string,
): Booking[] {
  return list
    .filter((booking) => booking.seriesId === seriesId)
    .map((booking) => ({ ...booking, title }));
}

submitBooking: Operation.Handle<void, void> = operation({
  label: "submitBooking",
  depends: {
    bookingForm: bookingForm.controller,
    notice: notice.controller,
    bookBooking,
  },
  run: ({ bookingForm: form, notice: noticeStore, bookBooking: book }) => {
    const values = form.get();
    try {
      book.run({
        input: {
          title: values.title,
          room: values.room,
          date: values.date,
          start: minutesFromText(values.start),
          end: minutesFromText(values.end),
        },
      });
      form.set({ ...values, title: "" });
      noticeStore.set(undefined);
    } catch (error) {
      noticeStore.set(errorKind(error));
    }
  },
})

function creationIndex(order: readonly string[], id: string): number {
  const index = order.indexOf(id);
  return index < 0 ? Number.MAX_SAFE_INTEGER : index;
}

openDraft: Operation.Handle<void, { id: string }> = operation({
  label: "openDraft",
  depends: {
    editForm: editForm.controller,
    notice: notice.controller,
    openEdit,
  },
  run: ({ editForm: form, notice: noticeStore, openEdit: open }, ctx) => {
    try {
      const draft = open.run({ input: { id: ctx.input.id } });
      form.set({
        title: draft.title,
        room: draft.room,
        date: draft.date,
        start: formatTime(draft.start),
        end: formatTime(draft.end),
      });
      noticeStore.set(undefined);
    } catch (error) {
      noticeStore.set(errorKind(error));
    }
  },
})

function linkOf(source: unknown): { courseId: string; prerequisiteId: string } {
  const courseId =
    typeof source === "object" && source !== null && "courseId" in source
      ? source.courseId
      : undefined;
  const prerequisiteId =
    typeof source === "object" && source !== null && "prerequisiteId" in source
      ? source.prerequisiteId
      : undefined;
  return {
    courseId: typeof courseId === "string" ? courseId : "",
    prerequisiteId: typeof prerequisiteId === "string" ? prerequisiteId : "",
  };
}

function isReady(course: Course, all: readonly Course[]): boolean {
  return course.prerequisiteIds.every(
    (id) => all.find((other) => other.id === id)?.done ?? false,
  );
}

openMoveEdit: Operation.Handle<Move, { id: string }> = operation({
  label: 'openMoveEdit',
  depends: {
    moves: moves.controller,
    editDraft: editDraft.controller,
    editItem: editItem.controller,
    editFrom: editFrom.controller,
    editTo: editTo.controller,
    editQuantity: editQuantity.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    const raise: Raise = noticeRaiser(deps.notice.set);
    const id = readId(inputOf(ctx));
    const found = deps.moves.get().find(move => move.id === id);
    if (!found) raise('NotFound', { id });
    const draft: Move = { ...found };
    deps.editDraft.set(draft);
    deps.editItem.set(draft.item);
    deps.editFrom.set(draft.from);
    deps.editTo.set(draft.to);
    deps.editQuantity.set(String(draft.quantity));
    deps.notice.set(undefined);
    return draft;
  },
})

discardMoveEdit: Operation.Handle<void, { id: string }> = operation({
  label: 'discardMoveEdit',
  depends: {
    editDraft: editDraft.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    const raise: Raise = noticeRaiser(deps.notice.set);
    const id = readId(inputOf(ctx));
