}

function requireClock(value: string): number {
  const match = /^(\d{1,2}):(\d{2})$/.exec(value.trim());
  if (!match) {
    throw appError("BadTime", { value });
  }
  const hour = Number(match[1]);
  const minute = Number(match[2]);
  if (hour > 23 || minute > 59) {
    throw appError("BadTime", { value });
  }
  return hour * 60 + minute;
}

