export function requires(
  courses: readonly Course[],
  fromId: string,
  targetId: string,
): boolean {
  const seen = new Set<string>();
  const pending = [fromId];
  while (pending.length > 0) {
    const id = pending.pop();
    if (id === undefined || seen.has(id)) {
      continue;
    }
    if (id === targetId) {
      return true;
    }
    seen.add(id);
    const course = findCourse(courses, id);
    if (course !== undefined) {
      pending.push(...course.prerequisiteIds);
    }
  }
  return false;
}

function recordCreation(
  order: Scope.DataController<Readonly<Record<string, number>>>,
  ids: readonly string[],
): void {
  order.update((previous) => {
    let highest = 0;
    for (const value of Object.values(previous)) {
      if (value > highest) highest = value;
    }
    const next = { ...previous };
    ids.forEach((id, index) => {
      next[id] = highest + 1 + index;
    });
    return next;
  });
}

