export function validateFields(raw: unknown): Fields {
  const title = field(raw, "title");
  const room = field(raw, "room");
  const safeTitle = typeof title === "string" ? title : "";
  if (safeTitle.trim() === "") {
    throw appError("BlankTitle", { title: safeTitle });
  }
  const safeRoom = typeof room === "string" ? room : "";
  if (!isRoom(safeRoom)) {
    throw appError("UnknownRoom", { room: safeRoom });
  }
  const date = requireDate(field(raw, "date"));
  const start = requireMinute(field(raw, "start"));
  const end = requireMinute(field(raw, "end"));
  if (end <= start) {
    throw appError("EmptySlot", { start, end });
  }
  return { title: safeTitle, room: safeRoom, date, start, end };
}

