function formatTime(minute: number): string {
  const hour = Math.floor(minute / 60)
    .toString()
    .padStart(2, "0");
  const rest = (minute % 60).toString().padStart(2, "0");
  return `${hour}:${rest}`;
}

function readFields(raw: unknown): {
  readonly id: unknown;
