}

function source(ctx: {
  readonly rawInput: unknown;
  readonly input: unknown;
}): unknown {
  return ctx.rawInput !== undefined ? ctx.rawInput : ctx.input;
}

function parseTime(text: string): number {
  const match = /^(\d{1,2}):(\d{2})$/.exec(text.trim());
  if (!match) return Number.NaN;
  const hour = Number(match[1]);
  const minute = Number(match[2]);
  if (hour > 23 || minute > 59) return Number.NaN;
  return hour * 60 + minute;
}

function idField(raw: unknown, key: string): string {
  if (isRecord(raw)) {
    const value: unknown = raw[key];
    if (typeof value === "string") return value;
  }
  return "";
}

export function statusOf(list: readonly Course[], course: Course): Status {
  if (course.done) return "Done";
  return openPrerequisites(list, course).length === 0 ? "Ready" : "Blocked";
}

function text(value: unknown): string {
  return typeof value === "string" ? value : "";
}

function replaceCourse(list: readonly Course[], changed: Course): readonly Course[] {
  return list.map((course) => (course.id === changed.id ? changed : course));
}

function sortedBookings(
  list: readonly Booking[],
  order: Readonly<Record<string, number>>,
): readonly Booking[] {
  return [...list].sort(
    (a, b) =>
      (a.date < b.date ? -1 : a.date > b.date ? 1 : 0) ||
      a.start - b.start ||
      order[a.id] - order[b.id],
  );
}

function callSource<I>(ctx: Operation.Ctx<I>): unknown {
  return ctx.input ?? ctx.rawInput;
}

export function fail<N extends Errors.Name>(kind: N, payload: Errors.Payload<N>): Errors.Of<N> {
