function shiftStock(
  rows: readonly Stock[],
  item: Item,
  from: Place,
  to: Place,
  quantity: number,
): readonly Stock[] {
  return rows.map((row) => {
    if (row.item !== item) return row;
    if (row.place === from) return { ...row, quantity: row.quantity - quantity };
    if (row.place === to) return { ...row, quantity: row.quantity + quantity };
    return row;
  });
}

