function addDays(date: string, days: number): string {
  const parts = date.split("-").map(Number);
  const time = new Date(0);
  time.setUTCFullYear(parts[0], parts[1] - 1, parts[2] + days);
  time.setUTCHours(0, 0, 0, 0);
  const year = time.getUTCFullYear().toString().padStart(4, "0");
  const month = (time.getUTCMonth() + 1).toString().padStart(2, "0");
  const day = time.getUTCDate().toString().padStart(2, "0");
  return `${year}-${month}-${day}`;
}

