moveStock: Operation.Handle<Move, MoveInput> = operation({
  label: "moveStock",
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    undo: undoStack.controller,
    nextId: nextId.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    try {
      const fields = readFields(ctx.rawInput);
      const item = asItem(fields.item);
      const from = asPlace(fields.from);
      const to = asPlace(fields.to);
      if (from === to) fail("SamePlace", { place: from });
      const quantity = asQuantity(fields.quantity);
      const stockBefore = deps.stock.get();
      const movesBefore = deps.moves.get();
      const moved = applyMove(stockBefore, item, from, to, quantity);
      const record: Move = { id: `move-${deps.nextId.get()}`, item, from, to, quantity };
      deps.nextId.update((n) => n + 1);
      deps.undo.update((history) => [...history, { stock: stockBefore, moves: movesBefore }]);
      deps.stock.set(moved);
      deps.moves.set([...movesBefore, record]);
      deps.notice.set(undefined);
      return record;
    } catch (error) {
      throw recorded(deps.notice, error);
    }
  },
})

bookSeries: Operation.Handle<readonly Booking[], SeriesInput> =
  operation({
    label: "bookSeries",
    depends: {
      bookings: bookings.controller,
      history: history.controller,
      createdOrder: createdOrder.controller,
    },
    run: (
      { bookings: store, history: historyStore, createdOrder: order },
      ctx,
    ) => {
      const weeks = checkWeeks(ctx.input.weeks);
      const fields = checkFields(ctx.input);
      const dates = seriesDates(fields.date, weeks);
      const existing = store.get();
      for (const date of dates) {
        if (hasConflict(existing, fields.room, date, fields.start, fields.end)) {
          throw clash(fields.room, fields.start, fields.end);
        }
      }
      const seriesId = nextId();
      const created: Booking[] = dates.map((date) => ({
        id: nextId(),
        title: fields.title,
        room: fields.room,
        date,
        start: fields.start,
        end: fields.end,
        seriesId,
      }));
      const orderNext = [...order.get(), ...created.map((booking) => booking.id)];
      pushHistory(store, historyStore);
      order.set(orderNext);
      store.set(sortBookings([...existing, ...created], orderNext));
      return created;
    },
  })

