reopenCourse: Operation.Handle<Course, { id: string }> = operation({
  label: "plan.reopenCourse",
  depends: { list: courses.controller, history: history.controller, notice: notice.controller },
  run: (deps, ctx) => {
    const id = idField(ctx.rawInput, "id");
    const list = deps.list.get();
    const course = courseAt(list, id);
    if (course === undefined) reject(deps.notice, "NotFound", { id });
    if (!course.done) {
      deps.notice.set(undefined);
      return course;
    }
    const dependents = completedDependents(list, id);
    if (dependents.length > 0) {
      reject(deps.notice, "DependentsDone", { id, dependentIds: dependents });
    }
    const updated: Course = { ...course, done: false };
    deps.history.set([...deps.history.get(), list]);
    deps.list.set(list.map((saved) => (saved.id === id ? updated : saved)));
    deps.notice.set(undefined);
    return updated;
  },
})

