reopenCourse: Operation.Handle<Course, { id: string }> =
  operation({
    label: "reopenCourse",
    depends: {
      courses: courses.controller,
      history: history.controller,
      notice: notice.controller,
    },
    run: (deps, ctx) =>
      attempt(deps.notice, () => {
        const list = deps.courses.get();
        const course = findCourse(list, ctx.input.id);
        if (course === undefined) {
          return fail("NotFound", { id: ctx.input.id });
        }
        if (!course.done) {
          return course;
        }
        const dependents = doneDependents(list, course.id);
        if (dependents.length > 0) {
          return fail("DependentsDone", { id: course.id, dependentIds: dependents });
        }
        const changed: Course = { ...course, done: false };
        commit({ courses: deps.courses, history: deps.history }, replaceCourse(list, course.id, changed));
        return changed;
      }),
  })

