bookSeries: Operation.Handle<readonly Booking[], SeriesInput> =
  operation({
    label: "bookSeries",
    depends: {
      bookings: bookings.controller,
      history: history.controller,
      createdOrder: createdOrder.controller,
    },
    run: (
      { bookings: store, history: historyStore, createdOrder: order },
      ctx,
    ) => {
      const weeks = checkWeeks(ctx.input.weeks);
      const fields = checkFields(ctx.input);
      const dates = seriesDates(fields.date, weeks);
      const existing = store.get();
      for (const date of dates) {
        if (hasConflict(existing, fields.room, date, fields.start, fields.end)) {
          throw clash(fields.room, fields.start, fields.end);
        }
      }
      const seriesId = nextId();
      const created: Booking[] = dates.map((date) => ({
        id: nextId(),
        title: fields.title,
        room: fields.room,
        date,
        start: fields.start,
        end: fields.end,
        seriesId,
      }));
      const orderNext = [...order.get(), ...created.map((booking) => booking.id)];
      pushHistory(store, historyStore);
      order.set(orderNext);
      store.set(sortBookings([...existing, ...created], orderNext));
      return created;
    },
  })

moveStock: Operation.Handle<Move, MoveInput> = operation({
  label: "moveStock",
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    history: undoHistory.controller,
    issued: issuedIds.controller,
    notice: notice.controller,
  },
  run(deps, ctx) {
    try {
      const input = calledInput(ctx);
      const item = requireItem(field(input, "item"));
      const from = requirePlace(field(input, "from"));
      const to = requirePlace(field(input, "to"));
      if (from === to) raise("SamePlace", { place: from });
      const quantity = requireQuantity(field(input, "quantity"));
      const before = deps.stock.get();
      const available = quantityAt(before, item, from);
      if (quantity > available) {
        raise("ShortStock", { item, place: from, available, requested: quantity });
      }
      const saved = deps.moves.get();
      const move: Move = { id: mintId(deps.issued), item, from, to, quantity };
      pushUndo(deps.history, { stock: before, moves: saved });
      deps.stock.set(adjust(adjust(before, item, from, -quantity), item, to, quantity));
      deps.moves.set([...saved, move]);
      deps.notice.set(undefined);
      return move;
    } catch (error) {
      return report(error, deps.notice);
    }
  },
})

saveMoveEdit: Operation.Handle<Move, EditMoveInput> = operation<SaveDeps, Move, EditMoveInput>({
  label: 'saveMoveEdit',
  depends: {
    stock: stock.controller,
    moves: moves.controller,
    draft: editDraft.controller,
    history: undoHistory.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) => {
    try {
      const raw = ctx.rawInput;
      const id = readId(raw);
      const draft = deps.draft.get();
      const saved = deps.moves.get().find((candidate) => candidate.id === id);
      if (draft === undefined || draft.id !== id || saved === undefined) {
        throw appError('NotFound', { id });
      }
      const item = asItem(field(raw, 'item'));
      const from = asPlace(field(raw, 'from'));
      const to = asPlace(field(raw, 'to'));
      const quantity = asQuantity(field(raw, 'quantity'));
      if (from === to) throw appError('SamePlace', { place: from });
      const currentStock = deps.stock.get();
      const restoredAvailable = stockAt(currentStock, saved.item, saved.to);
      if (restoredAvailable < saved.quantity) {
        throw appError('ShortStock', {
          item: saved.item,
          place: saved.to,
          available: restoredAvailable,
          requested: saved.quantity,
        });
      }
      const restored = shiftStock(currentStock, saved.item, saved.to, saved.from, saved.quantity);
      const available = stockAt(restored, item, from);
      if (available < quantity) {
        throw appError('ShortStock', { item, place: from, available, requested: quantity });
      }
      const replacement: Move = { id, item, from, to, quantity };
      const currentMoves = deps.moves.get();
      const nextMoves = currentMoves.map((candidate) => (candidate.id === id ? replacement : candidate));
      deps.history.set([...deps.history.get(), { stock: currentStock, moves: currentMoves }]);
      deps.stock.set(shiftStock(restored, item, from, to, quantity));
      deps.moves.set(nextMoves);
      deps.draft.set(undefined);
      deps.notice.set(undefined);
      return replacement;
    } catch (error) {
      fail(deps, error);
    }
  },
})

reopenCourse = operation({
  label: "reopenCourse",
  depends: planDeps,
  run: (deps, ctx: Operation.Ctx<CourseId>): Course => {
    const { id } = ctx.input;
    const list = deps.list.get();
    const course = findCourse(list, id);
    if (course === undefined) return fail(deps.notice, "NotFound", { id });
    if (!course.done) {
      deps.notice.set(null);
      return course;
    }
    const dependents = list.filter((other) => other.done && other.prerequisiteIds.includes(id));
    if (dependents.length > 0) {
      return fail(deps.notice, "DependentsDone", {
        id,
        dependentIds: dependents.map((other) => other.id),
      });
    }
    const changed: Course = { ...course, done: false };
    deps.notice.set(null);
    deps.undo.set([...deps.undo.get(), list]);
    deps.list.set(replaceCourse(list, changed));
    return changed;
  },
})

