addPrerequisite = operation({
  label: "addPrerequisite",
  depends: planDeps,
  run: (deps, ctx: Operation.Ctx<LinkIds>): Course => {
    const { courseId, prerequisiteId } = ctx.input;
    const list = deps.list.get();
    const course = findCourse(list, courseId);
    if (course === undefined) return fail(deps.notice, "NotFound", { id: courseId });
    const prerequisite = findCourse(list, prerequisiteId);
    if (prerequisite === undefined) return fail(deps.notice, "NotFound", { id: prerequisiteId });
    if (courseId === prerequisiteId) return fail(deps.notice, "SelfRequirement", { id: courseId });
    if (requiresTransitively(list, prerequisiteId, courseId)) {
      return fail(deps.notice, "Cycle", { courseId, prerequisiteId });
    }
    if (course.prerequisiteIds.includes(prerequisiteId)) {
      deps.notice.set(null);
      return course;
    }
    if (course.done) return fail(deps.notice, "CourseDone", { id: courseId });
    const changed: Course = {
      ...course,
      prerequisiteIds: [...course.prerequisiteIds, prerequisiteId],
    };
    deps.notice.set(null);
    deps.undo.set([...deps.undo.get(), list]);
    deps.list.set(replaceCourse(list, changed));
    return changed;
  },
})

