export function requireSeriesId(raw: unknown): string {
  const id = field(raw, "seriesId");
  return typeof id === "string" ? id : "";
}

export function requireId(raw: unknown): string {
  const id = field(raw, "id");
  return typeof id === "string" ? id : "";
}

export function text(value: unknown): string {
  return typeof value === "string" ? value : "";
}

function readId(raw: unknown): string {
  const value = field(raw, 'id');
  return typeof value === 'string' ? value : '';
}

function idField(raw: unknown, key: string): string {
  if (isRecord(raw)) {
    const value: unknown = raw[key];
    if (typeof value === "string") return value;
  }
  return "";
}

function linkOf(source: unknown): { courseId: string; prerequisiteId: string } {
  const courseId =
    typeof source === "object" && source !== null && "courseId" in source
      ? source.courseId
      : undefined;
  const prerequisiteId =
    typeof source === "object" && source !== null && "prerequisiteId" in source
      ? source.prerequisiteId
      : undefined;
  return {
    courseId: typeof courseId === "string" ? courseId : "",
    prerequisiteId: typeof prerequisiteId === "string" ? prerequisiteId : "",
  };
}

function text(value: unknown): string {
  return typeof value === "string" ? value : "";
}

function idOf(source: unknown): string {
  const value =
    typeof source === "object" && source !== null && "id" in source ? source.id : undefined;
  return typeof value === "string" ? value : "";
}

function rankOf(order: Readonly<Record<string, number>>, id: string): number {
  return order[id] ?? 0;
}

export function shapeSeries(raw: unknown): SeriesInput {
  const booking = shapeBooking(raw);
  const weeks = field(raw, "weeks");
  return {
    ...booking,
    date: booking.date ?? defaultDate,
    weeks: typeof weeks === "number" ? weeks : Number.NaN,
  };
}

export function requiresText(
  courses: readonly Course[],
  course: Course,
): string {
  if (course.prerequisiteIds.length === 0) {
    return "None";
  }
  return course.prerequisiteIds
    .map((id) => findCourse(courses, id)?.title ?? "Removed course")
    .join(", ");
}

function rawCall(input: unknown, rawInput: unknown): unknown {
  return input ?? rawInput;
}

function byDateTime(
  list: readonly Booking[],
  order: Readonly<Record<string, number>>,
): readonly Booking[] {
  return [...list].sort((a, b) => {
    if (a.date !== b.date) return a.date < b.date ? -1 : 1;
    if (a.start !== b.start) return a.start - b.start;
    return (order[a.id] ?? 0) - (order[b.id] ?? 0);
  });
}

function shownKind(caught: unknown): string {
  return errorKind(caught) ?? "Error";
}

function kindOf(error: unknown): string {
  return errorKind(error) ?? "Unknown";
}

function errorKind(error: unknown): string {
  if (typeof error === "object" && error !== null && "kind" in error) {
    const { kind } = error;
    if (typeof kind === "string") {
      return kind;
    }
  }
  return "Unknown";
}

export function selectOptions(list: readonly Course[], selected: string): readonly Option[] {
  const options: Option[] = [{ value: "", label: "Choose course" }];
  for (const course of list) options.push({ value: course.id, label: course.title });
  if (selected !== "" && courseAt(list, selected) === undefined) {
    options.push({ value: selected, label: "Removed course" });
  }
  return options;
}

function source(ctx: {
  readonly rawInput: unknown;
  readonly input: unknown;
}): unknown {
  return ctx.rawInput !== undefined ? ctx.rawInput : ctx.input;
}

function parseWeeks(text: string): number {
  return Number(text.trim());
}

function requiresText(course: Course, all: readonly Course[]): string {
  if (course.prerequisiteIds.length === 0) return "None";
  return course.prerequisiteIds
    .map((id) => all.find((other) => other.id === id)?.title ?? id)
    .join(", ");
}

function selectChoices(all: readonly Course[], selected: string): readonly Choice[] {
  const choices: Choice[] = [
    { value: "", label: "Choose course" },
    ...all.map((course) => ({ value: course.id, label: course.title })),
  ];
  if (selected !== "" && !all.some((course) => course.id === selected)) {
    choices.push({ value: selected, label: "Removed course" });
  }
  return choices;
}

function readFields(raw: unknown): {
  readonly id: unknown;
  readonly title: unknown;
  readonly room: unknown;
  readonly date: unknown;
  readonly start: unknown;
  readonly end: unknown;
  readonly weeks: unknown;
  readonly seriesId: unknown;
} {
  if (typeof raw !== "object" || raw === null) {
    return {
      id: undefined,
      title: undefined,
      room: undefined,
      date: undefined,
      start: undefined,
      end: undefined,
      weeks: undefined,
      seriesId: undefined,
    };
  }
  return {
    id: "id" in raw ? raw.id : undefined,
    title: "title" in raw ? raw.title : undefined,
    room: "room" in raw ? raw.room : undefined,
    date: "date" in raw ? raw.date : undefined,
    start: "start" in raw ? raw.start : undefined,
    end: "end" in raw ? raw.end : undefined,
    weeks: "weeks" in raw ? raw.weeks : undefined,
    seriesId: "seriesId" in raw ? raw.seriesId : undefined,
  };
}

function readSeriesId(raw: unknown): string {
  const seriesId = readFields(raw).seriesId;
  return typeof seriesId === "string" ? seriesId : String(seriesId);
}

function readId(raw: unknown): string {
  const id = readFields(raw).id;
  return typeof id === "string" ? id : String(id);
}

function describeTitle(value: unknown): string {
  return typeof value === "string" ? value : String(value);
}

function addDays(date: string, days: number): string {
  const parts = date.split("-").map(Number);
  const time = new Date(0);
  time.setUTCFullYear(parts[0], parts[1] - 1, parts[2] + days);
  time.setUTCHours(0, 0, 0, 0);
  const year = time.getUTCFullYear().toString().padStart(4, "0");
  const month = (time.getUTCMonth() + 1).toString().padStart(2, "0");
  const day = time.getUTCDate().toString().padStart(2, "0");
  return `${year}-${month}-${day}`;
}

export function weekCount(raw: unknown): number {
  return requireWeeks(field(raw, "weeks"));
}

export function shapeBooking(raw: unknown): BookInput {
  const date = field(raw, "date");
  return {
    title: text(field(raw, "title")),
    room: text(field(raw, "room")),
    date: typeof date === "string" ? date : undefined,
    start: minute(field(raw, "start")),
    end: minute(field(raw, "end")),
  };
}

function parseSeriesInput(raw: unknown): SeriesInput {
  return shapeSeries(raw);
}

function parseEditInput(raw: unknown): EditInput {
  return shapeEdit(raw);
}

function isRealDay(raw: string): boolean {
  const year = Number(raw.slice(0, 4));
  const month = Number(raw.slice(5, 7));
  const day = Number(raw.slice(8, 10));
  const check = new Date(Date.UTC(year, month - 1, day));
  return (
    check.getUTCFullYear() === year &&
    check.getUTCMonth() === month - 1 &&
    check.getUTCDate() === day
  );
}

submitDiscard: Operation.Handle<void, { id: string }> = operation({
  label: "submitDiscard",
  input: shapeId,
  depends: {
    text: editText.controller,
    notice: notice.controller,
    discard: discardEdit,
  },
  run(deps, ctx): void {
    try {
      const form = deps.text.get();
      if (form === undefined || form.id !== ctx.input.id) {
        throw appError("NotFound", { id: ctx.input.id });
      }
      deps.discard.run({ input: { id: ctx.input.id } });
      deps.text.set(undefined);
      deps.notice.set(undefined);
    } catch (caught) {
      const kind = goneFailure(caught);
      if (kind === undefined) throw caught;
      deps.notice.set(kind);
    }
  },
})

function shiftStock(
  rows: readonly Stock[],
  item: Item,
  from: Place,
  to: Place,
  quantity: number,
): readonly Stock[] {
  return rows.map((row) => {
    if (row.item !== item) return row;
    if (row.place === from) return { ...row, quantity: row.quantity - quantity };
    if (row.place === to) return { ...row, quantity: row.quantity + quantity };
    return row;
  });
}

