function findRoom(value: string): Room | undefined {
  return ROOM_LIST.find((room) => room === value);
}

export function addDays(date: string, days: number): string {
  const match = DATE_PATTERN.exec(date);
  if (match === null) {
    throw badDate(date);
  }
  let year = Number(match[1]);
  let month = Number(match[2]);
  let day = Number(match[3]) + days;
  let limit = daysInMonth(year, month);
  while (day > limit) {
    day -= limit;
    month += 1;
    if (month > MONTHS_PER_YEAR) {
      month = 1;
      year += 1;
    }
    limit = daysInMonth(year, month);
  }
  const textYear = String(year).padStart(4, "0");
  const textMonth = String(month).padStart(2, "0");
  const textDay = String(day).padStart(2, "0");
  return `${textYear}-${textMonth}-${textDay}`;
}

function addDays(date: string, days: number): string {
  const start = Date.UTC(
    Number(date.slice(0, 4)),
    Number(date.slice(5, 7)) - 1,
    Number(date.slice(8, 10)),
  );
  return new Date(start + days * DAY_MS).toISOString().slice(0, 10);
}

export function requireWeeks(value: unknown): number {
  if (
    typeof value !== "number" ||
    !Number.isInteger(value) ||
    value < 1 ||
    value > 12
  ) {
    throw appError("BadCount", { weeks: value });
  }
  return value;
}

export function appError<N extends Errors.Name>(kind: N, payload: Errors.Payload<N>): Errors.Of<N> {
  return Object.assign(new Error(kind), { kind, payload });
}

function civilFromDays(days: number): { readonly year: number; readonly month: number; readonly day: number } {
  const shifted = days + 719468;
  const era = Math.floor(shifted / 146097);
  const dayOfEra = shifted - era * 146097;
  const yearOfEra = Math.floor(
    (dayOfEra - Math.floor(dayOfEra / 1460) + Math.floor(dayOfEra / 36524) - Math.floor(dayOfEra / 146096)) / 365,
  );
  const year = yearOfEra + era * 400;
  const dayOfYear =
    dayOfEra - (365 * yearOfEra + Math.floor(yearOfEra / 4) - Math.floor(yearOfEra / 100));
  const monthPattern = Math.floor((5 * dayOfYear + 2) / 153);
  const day = dayOfYear - Math.floor((153 * monthPattern + 2) / 5) + 1;
  const month = monthPattern < 10 ? monthPattern + 3 : monthPattern - 9;
  return { year: month <= 2 ? year + 1 : year, month, day };
}

export function addLink(list: readonly Course[], courseId: string, prerequisiteId: string): Course {
  const course = findCourse(list, courseId);
  findCourse(list, prerequisiteId);
  if (course.id === prerequisiteId) throw fail("SelfRequirement", { id: courseId });
  if (course.done) throw fail("CourseDone", { id: courseId });
  if (course.prerequisiteIds.includes(prerequisiteId)) return course;
  if (requires(list, prerequisiteId, courseId)) throw fail("Cycle", { courseId, prerequisiteId });
  return { ...course, prerequisiteIds: [...course.prerequisiteIds, prerequisiteId] };
}

addPrerequisite: Operation.Handle<Course, { courseId: string; prerequisiteId: string }> =
  operation({
    label: "plan.addPrerequisite",
    depends: { list: courses.controller, history: history.controller, notice: notice.controller },
    run: (deps, ctx) => {
      const raw = ctx.rawInput;
      const courseId = idField(raw, "courseId");
      const prerequisiteId = idField(raw, "prerequisiteId");
      const list = deps.list.get();
      const course = courseAt(list, courseId);
      if (course === undefined) reject(deps.notice, "NotFound", { id: courseId });
      if (courseAt(list, prerequisiteId) === undefined) {
        reject(deps.notice, "NotFound", { id: prerequisiteId });
      }
      if (courseId === prerequisiteId) reject(deps.notice, "SelfRequirement", { id: courseId });
      if (course.done) reject(deps.notice, "CourseDone", { id: courseId });
      if (course.prerequisiteIds.includes(prerequisiteId)) {
        deps.notice.set(undefined);
        return course;
      }
      if (requiresThrough(list, prerequisiteId, courseId)) {
        reject(deps.notice, "Cycle", { courseId, prerequisiteId });
      }
      const updated: Course = {
        ...course,
        prerequisiteIds: [...course.prerequisiteIds, prerequisiteId],
      };
      deps.history.set([...deps.history.get(), list]);
      deps.list.set(list.map((saved) => (saved.id === courseId ? updated : saved)));
      deps.notice.set(undefined);
      return updated;
    },
  })

removePrerequisite: Operation.Handle<Course, { courseId: string; prerequisiteId: string }> =
  operation({
    label: "plan.removePrerequisite",
    depends: { list: courses.controller, history: history.controller, notice: notice.controller },
    run: (deps, ctx) => {
      const raw = ctx.rawInput;
      const courseId = idField(raw, "courseId");
      const prerequisiteId = idField(raw, "prerequisiteId");
      const list = deps.list.get();
      const course = courseAt(list, courseId);
      if (course === undefined) reject(deps.notice, "NotFound", { id: courseId });
      if (courseAt(list, prerequisiteId) === undefined) {
        reject(deps.notice, "NotFound", { id: prerequisiteId });
      }
      if (courseId === prerequisiteId) reject(deps.notice, "SelfRequirement", { id: courseId });
      if (course.done) reject(deps.notice, "CourseDone", { id: courseId });
      if (!course.prerequisiteIds.includes(prerequisiteId)) {
        reject(deps.notice, "NotRequired", { courseId, prerequisiteId });
      }
      const updated: Course = {
        ...course,
        prerequisiteIds: course.prerequisiteIds.filter((id) => id !== prerequisiteId),
      };
      deps.history.set([...deps.history.get(), list]);
      deps.list.set(list.map((saved) => (saved.id === courseId ? updated : saved)));
      deps.notice.set(undefined);
      return updated;
    },
  })

reopenCourse: Operation.Handle<Course, { id: string }> = operation({
  label: "reopen course",
  depends: {
    courses: courses.controller,
    history: history.controller,
    notice: notice.controller,
  },
  run: ({ courses, history, notice }, ctx) => {
    try {
      const before = courses.get();
      const saved = reopenCourseIn(before, idOf(callSource(ctx)));
      if (!before.includes(saved)) {
        history.set([...history.get(), before]);
        courses.set(replaceCourse(before, saved));
      }
      notice.set(undefined);
      return saved;
    } catch (error) {
      report(notice, error);
    }
  },
})

export function applyMove(rows: readonly Stock[], item: Item, from: Place, to: Place, quantity: number): readonly Stock[] {
  const available = quantityAt(rows, item, from);
  if (available < quantity) fail("ShortStock", { item, place: from, available, requested: quantity });
  return rows.map((row) =>
    row.item === item && row.place === from
      ? { ...row, quantity: row.quantity - quantity }
      : row.item === item && row.place === to
        ? { ...row, quantity: row.quantity + quantity }
        : row,
  );
}

bookBooking: Operation.Handle<Booking, BookInput> = operation({
  label: "bookBooking",
  depends: { bookings: bookings.controller, history: history.controller },
  run: ({ bookings: store, history: historyStore }, ctx) => {
    const fields = validateFields(ctx.input);
    const existing = store.get();
    if (hasConflict(existing, fields.room, fields.date, fields.start, fields.end)) {
      throw clash(fields.room, fields.start, fields.end);
    }
    const booking: Booking = { id: nextId(), ...fields };
    pushHistory(store, historyStore);
    store.set(sortBookings([...existing, booking]));
    return booking;
  },
})

bookBooking: Operation.Handle<Booking, BookInput> = operation<
  BookDeps,
  Booking,
  BookInput
>({
  label: "bookBooking",
  depends: {
    list: bookings.controller,
    order: created.controller,
    count: idCount.controller,
    history: undoHistory.controller,
  },
  run: (deps, ctx) => {
    const slot = checkSlot(rawCall(ctx.input, ctx.rawInput));
    const list = deps.list.get();
    if (hasClash(list, slot.room, slot.date, slot.start, slot.end)) {
      throw appError("Clash", { room: slot.room, start: slot.start, end: slot.end });
    }
    const sequence = deps.count.get();
    const id = `b-${sequence}`;
    const booking: Booking = { id, ...slot };
    const order = { ...deps.order.get(), [id]: sequence };
    deps.list.set(sortedBookings([...list, booking], order));
    deps.count.set(sequence + 1);
    record(deps.history, list);
    return booking;
  },
})

bookSeries: Operation.Handle<readonly Booking[], SeriesInput> = operation<
  BookDeps,
  readonly Booking[],
  SeriesInput
>({
  label: "bookSeries",
  depends: {
    list: bookings.controller,
    order: created.controller,
    count: idCount.controller,
    history: undoHistory.controller,
  },
  run: (deps, ctx) => {
    const raw = rawCall(ctx.input, ctx.rawInput);
    const slot = checkSlot(raw);
    const weeks = checkWeeks(readFields(raw).weeks);
    // Every date is checked before any write: one failing date books none of them.
    const dates = seriesDates(slot.date, weeks);
    const list = deps.list.get();
    for (const date of dates) {
      if (hasClash(list, slot.room, date, slot.start, slot.end)) {
        throw appError("Clash", { room: slot.room, start: slot.start, end: slot.end });
      }
    }
    const sequence = deps.count.get();
    const seriesId = `s-${sequence}`;
    const order = { ...deps.order.get() };
    const made: Booking[] = dates.map((date, index) => {
      const id = `b-${sequence + index}`;
      order[id] = sequence + index;
      return { id, ...slot, date, seriesId };
    });
    deps.list.set(sortedBookings([...list, ...made], order));
    deps.count.set(sequence + weeks);
    record(deps.history, list);
    return made;
  },
})

saveEdit: Operation.Handle<Booking, EditInput> = operation<
  SaveDeps,
  Booking,
  EditInput
>({
  label: "saveEdit",
  depends: {
    list: bookings.controller,
    draft: editDraft.controller,
    order: created.controller,
    history: undoHistory.controller,
  },
  run: (deps, ctx) => {
    const raw = rawCall(ctx.input, ctx.rawInput);
    const id = readId(raw);
    const draft = deps.draft.get();
    if (draft === undefined || draft.id !== id) {
      throw appError("NotFound", { id });
    }
    const list = deps.list.get();
    const found = list.find((booking) => booking.id === id);
    if (found === undefined) {
      throw appError("NotFound", { id });
    }
    const slot = checkSlot(raw);
    if (hasClash(list, slot.room, slot.date, slot.start, slot.end, id)) {
      throw appError("Clash", { room: slot.room, start: slot.start, end: slot.end });
    }
    // The save rewrites the checked fields over the saved row; a series member stays
    // a member, because `seriesId` is identity, not one of the edited fields.
    const saved: Booking = { ...found, ...slot };
    const rest = list.filter((booking) => booking.id !== id);
    deps.list.set(sortedBookings([...rest, saved], deps.order.get()));
    record(deps.history, list);
    deps.draft.set(undefined);
    return saved;
  },
})

bookBooking: Operation.Handle<Booking, BookInput> = operation({
  label: "bookBooking",
  input: parseBookInput,
  depends: {
    list: bookings.controller,
    issued: issuedIds.controller,
    history: undoHistory.controller,
  },
  run(deps, ctx): Booking {
    const fields = validateFields(source(ctx));
    const list = deps.list.get();
    if (clashesWith(list, fields.room, fields.date, fields.start, fields.end)) {
      throw clash(fields);
    }
    const issued = deps.issued.get();
    const id = `booking-${issued.length}`;
    const booking = savedBooking(fields, id, undefined);
    deps.issued.set([...issued, id]);
    applyChange(deps, sortedBookings([...list, booking], [...issued, id]));
    return booking;
  },
})

function clash(fields: Fields): Error {
  return appError("Clash", {
    room: fields.room,
    start: fields.start,
    end: fields.end,
  });
}

saveEdit: Operation.Handle<Booking, EditInput> = operation({
  label: "saveEdit",
  input: parseEditInput,
  depends: {
    list: bookings.controller,
    draft: editDraft.controller,
    issued: issuedIds.controller,
    history: undoHistory.controller,
  },
  run(deps, ctx): Booking {
    const fields = validateFields(source(ctx));
    const id = requireId(source(ctx));
    const draft = deps.draft.get();
    if (!draft || draft.id !== id) {
      throw appError("NotFound", { id });
    }
    const list = deps.list.get();
    const saved = list.find((booking) => booking.id === id);
    if (!saved) {
      throw appError("NotFound", { id });
    }
    if (
      clashesWith(list, fields.room, fields.date, fields.start, fields.end, id)
    ) {
      throw clash(fields);
    }
    const updated = savedBooking(fields, id, saved.seriesId);
    applyChange(
      deps,
      sortedBookings(
        list.map((booking) => (booking.id === id ? updated : booking)),
        deps.issued.get(),
      ),
    );
    deps.draft.set(undefined);
    return updated;
  },
})

bookSeries: Operation.Handle<readonly Booking[], SeriesInput> =
  operation({
    label: "bookSeries",
    input: parseSeriesInput,
    depends: {
      list: bookings.controller,
      issued: issuedIds.controller,
      history: undoHistory.controller,
    },
    run(deps, ctx): readonly Booking[] {
      const fields = validateFields(source(ctx));
      const weeks = weekCount(source(ctx));
      const list = deps.list.get();
      const dates = occurrenceDates(fields.date, weeks);
      for (const date of dates) {
        if (clashesWith(list, fields.room, date, fields.start, fields.end)) {
          throw clash(fields);
        }
      }
      const seriesId = `series-${deps.issued.get().length}`;
      let issued = deps.issued.get();
      const made: Booking[] = [];
      const added: string[] = [];
      for (const date of dates) {
        const id = `booking-${issued.length + added.length}`;
        made.push(savedBooking({ ...fields, date }, id, seriesId));
        added.push(id);
      }
      issued = [...issued, ...added];
      deps.issued.set(issued);
      applyChange(deps, sortedBookings([...list, ...made], issued));
      return made;
    },
  })

bookSeries: Operation.Handle<readonly Booking[], SeriesInput> = operation({
  label: "bookSeries",
  depends: { list: bookings.controller, history: undoHistory.controller },
  run: ({ list, history }, ctx) => {
    const title = titleOf(ctx.input.title);
    const room = roomOf(ctx.input.room);
    const firstDate = dateOf(ctx.input.date);
    const start = minuteOf(ctx.input.start);
    const end = minuteOf(ctx.input.end);
    if (end <= start) throw fail("EmptySlot", { start, end });
    const weeks = weeksOf(ctx.input.weeks);
    const dates: readonly string[] = Array.from(
      { length: weeks },
      (_, index) => addDays(firstDate, index * 7),
    );
    const current = list.get();
    for (const date of dates) assertFree(current, room, date, start, end);
    const seriesId = newId();
    const made: readonly Booking[] = dates.map((date) => ({
      id: newId(),
      title,
      room,
      date,
      start,
      end,
      seriesId,
    }));
    pushUndoStep(history, current);
    list.set(byDateTime([...current, ...made]));
    return made;
  },
})

bookBooking: Operation.Handle<Booking, BookInput> = operation({
  label: "bookBooking",
  depends: { list: bookings.controller, history: undoHistory.controller },
  run: ({ list, history }, ctx) => {
    const title = titleOf(ctx.input.title);
    const room = roomOf(ctx.input.room);
    const date = dateOf(ctx.input.date);
    const start = minuteOf(ctx.input.start);
    const end = minuteOf(ctx.input.end);
    if (end <= start) throw fail("EmptySlot", { start, end });
    const current = list.get();
    assertFree(current, room, date, start, end);
    const booking: Booking = { id: newId(), title, room, date, start, end };
    pushUndoStep(history, current);
    list.set(byDateTime([...current, booking]));
    return booking;
  },
})

saveEdit: Operation.Handle<Booking, EditInput> = operation({
  label: "saveEdit",
  depends: { list: bookings.controller, draft: editDraft.controller, history: undoHistory.controller },
  run: ({ list, draft, history }, ctx) => {
    const id = ctx.input.id;
    const open = draft.get();
    if (open === undefined || open.id !== id) throw fail("NotFound", { id });
    const title = titleOf(ctx.input.title);
    const room = roomOf(ctx.input.room);
    const date = dateOf(ctx.input.date);
    const start = minuteOf(ctx.input.start);
    const end = minuteOf(ctx.input.end);
    if (end <= start) throw fail("EmptySlot", { start, end });
    const current = list.get();
    const savedBefore = current.find((booked) => booked.id === id);
    if (savedBefore === undefined) throw fail("NotFound", { id });
    assertFree(current, room, date, start, end, id);
    const saved: Booking = {
      id,
      title,
      room,
      date,
      start,
      end,
      ...(savedBefore.seriesId !== undefined ? { seriesId: savedBefore.seriesId } : {}),
    };
    pushUndoStep(history, current);
    list.set(byDateTime(current.map((booked) => (booked.id === id ? saved : booked))));
    draft.set(undefined);
    return saved;
  },
})

export function isError<N extends Errors.Name>(value: unknown, kind: N): value is Errors.Of<N> {
  return value instanceof Error && "kind" in value && value.kind === kind;
}

undoChange: Operation.Handle<void, void> = operation({
  label: "undoChange",
  depends: { list: bookings.controller, history: undoHistory.controller },
  run(deps): void {
    const history = deps.history.get();
    const before = history.at(-1);
    if (before === undefined) {
      throw appError("EmptyUndo", {});
    }
