function parseTime(raw: string): number | undefined {
  const match = /^(\d{1,2}):(\d{2})$/.exec(raw.trim());
  if (match === null) {
    return undefined;
  }
  const hours = Number(match[1]);
  const mins = Number(match[2]);
  if (hours > 23 || mins > 59) {
    return undefined;
  }
  const total = hours * MINUTES_PER_HOUR + mins;
  if (total < 0 || total > LAST_MINUTE) {
    return undefined;
  }
  return total;
}

