export function toMinutes(text: string): number | string {
  const match = /^([0-9]{2}):([0-9]{2})$/.exec(text.trim());
  if (match === null) {
    return text;
  }
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (hours > 23 || minutes > 59) {
    return text;
  }
  return hours * 60 + minutes;
}

function sortedBookings(
  list: readonly Booking[],
  order: Readonly<Record<string, number>>,
): readonly Booking[] {
  return [...list].sort(
    (a, b) =>
      (a.date < b.date ? -1 : a.date > b.date ? 1 : 0) ||
      a.start - b.start ||
      rankOf(order, a.id) - rankOf(order, b.id),
  );
}

