export function timeLabel(minute: number): string {
  const hours = String(Math.floor(minute / 60)).padStart(2, "0");
  const minutes = String(minute % 60).padStart(2, "0");
  return `${hours}:${minutes}`;
}

export function parseTime(raw: string): number | undefined {
  const match = TIME_PATTERN.exec(raw.trim());
  if (match === null) {
    return undefined;
  }
  const hours = Number(match[1]);
  const mins = Number(match[2]);
  if (hours > 23 || mins > 59) {
    return undefined;
  }
  return hours * MINUTES_PER_HOUR + mins;
}

export function checkDate(value: unknown): string {
  if (typeof value !== "string") {
    throw badDate(value);
  }
  const match = DATE_PATTERN.exec(value);
  if (match === null) {
    throw badDate(value);
  }
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (month < 1 || month > MONTHS_PER_YEAR) {
    throw badDate(value);
  }
  if (day < 1 || day > daysInMonth(year, month)) {
    throw badDate(value);
  }
  return value;
}

function withText<F extends string, T extends Readonly<Record<F, string>>>(
  record: T,
  field: F,
  value: string,
): T {
  return { ...record, [field]: value };
}

function undoFailure(caught: unknown): Errors.Name | undefined {
