        </button>
      </form>
      <div role="alert">{error ?? ""}</div>
      <div>
        <button
          type="button"
          onClick={() =>
            run(() => {
              scope.run(undoChange, {});
            })
          }
        >
          Undo
        </button>
      </div>
      <div>
        <button type="button" onClick={() => setFilter("All")}>
          All
        </button>
        <button type="button" onClick={() => setFilter("Cedar")}>
          Cedar
        </button>
        <button type="button" onClick={() => setFilter("Maple")}>
          Maple
        </button>
      </div>
      {draft ? (
        <EditForm
          key={draft.id}
          draft={draft}
          onSave={(fields) =>
            run(() => {
              scope.run(saveEdit, { input: { id: draft.id, ...fields } });
            })
          }
          onDiscard={() =>
            run(() => {
              scope.run(discardEdit, { input: { id: draft.id } });
            })
          }
        />
      ) : null}
      <table>
        <tbody>
          {list.map((booking) => (
            <tr
              key={booking.id}
              hidden={filter !== "All" && filter !== booking.room}
            >
              <td>{booking.title}</td>
              <td>{booking.room}</td>
              <td>{booking.date}</td>
              <td>
                {formatTime(booking.start)} - {formatTime(booking.end)}
              </td>
              <td>
                <button
                  type="button"
                  aria-label={`Edit ${booking.title}`}
                  onClick={() =>
                    run(() => {
                      scope.run(openEdit, { input: { id: booking.id } });
                    })
                  }
                >
                  Edit
                </button>
                <button
                  type="button"
                  aria-label={`Cancel ${booking.title}`}
                  onClick={() =>
                    run(() => {
                      scope.run(cancelBooking, { input: { id: booking.id } });
                    })
                  }
                >
                  Cancel
                </button>
                {booking.seriesId === undefined ? null : (
                  <button
                    type="button"
                    onClick={() =>
                      run(() => {
                        if (booking.seriesId !== undefined) {
                          scope.run(cancelSeries, {
                            input: { seriesId: booking.seriesId },
                          });
                        }
                      })
                    }
                  >
                    Cancel series
                  </button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

