function BookingScreen(): ReactElement {
  const list = useData(bookings);
  const draft = useData(editDraft);
  const [filter, setFilter] = useState<Filter>("All");
  const [title, setTitle] = useState("");
  const [room, setRoom] = useState("Cedar");
  const [date, setDate] = useState(defaultDate);
  const [start, setStart] = useState("09:00");
  const [end, setEnd] = useState("10:00");
  const [weeks, setWeeks] = useState("1");
  const [kind, setKind] = useState<string | undefined>(undefined);

  const book = useRun(bookBooking, {
    onSuccess: () => {
      setTitle("");
      setKind(undefined);
    },
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const series = useRun(bookSeries, {
    onSuccess: () => {
      setTitle("");
      setKind(undefined);
    },
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const cancel = useRun(cancelBooking, {
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const cancelWholeSeries = useRun(cancelSeries, {
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const open = useRun(openEdit, {
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const save = useRun(saveEdit, {
    onSuccess: () => {
      setKind(undefined);
    },
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const undo = useRun(undoChange, {
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const discard = useRun(discardEdit, {
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const startMinute = toMinute(start);
    const endMinute = toMinute(end);
    if (startMinute === undefined || endMinute === undefined) {
      setKind("BadTime");
      return;
    }
    book.run({ input: { title, room, date, start: startMinute, end: endMinute } });
  };

  const submitSeries = () => {
    const startMinute = toMinute(start);
    const endMinute = toMinute(end);
    if (startMinute === undefined || endMinute === undefined) {
      setKind("BadTime");
      return;
    }
    series.run({ input: { title, room, date, start: startMinute, end: endMinute, weeks: Number(weeks) } });
  };

  const saveDraft = (input: {
    readonly id: string;
    readonly title: string;
    readonly room: string;
    readonly date: string;
    readonly start: number;
    readonly end: number;
  }) => {
    if (input.start < 0 || input.end < 0) {
      setKind("BadTime");
      return;
    }
    save.run({ input });
  };

  return (
    <main>
      <form onSubmit={submit}>
        <label>
          Title
          <input name="Title" value={title} onChange={(event) => setTitle(event.target.value)} />
        </label>
        <label>
          Room
          <input name="Room" value={room} onChange={(event) => setRoom(event.target.value)} />
        </label>
        <label>
          Date
          <input name="Date" value={date} onChange={(event) => setDate(event.target.value)} />
        </label>
        <label>
          Start time
          <input
            name="Start time"
            placeholder="09:00"
            value={start}
            onChange={(event) => setStart(event.target.value)}
          />
        </label>
        <label>
          End time
          <input
            name="End time"
            placeholder="10:00"
            value={end}
            onChange={(event) => setEnd(event.target.value)}
          />
        </label>
        <label>
          Weeks
          <input name="Weeks" value={weeks} onChange={(event) => setWeeks(event.target.value)} />
        </label>
        <button type="submit">Book</button>
        <button type="button" onClick={() => submitSeries()}>
          Book series
        </button>
        <button type="button" onClick={() => undo.run()}>
          Undo
        </button>
        {kind !== undefined ? <div role="alert">{kind}</div> : undefined}
      </form>
      {draft !== undefined ? (
        <DraftEditor draft={draft} onSave={saveDraft} onDiscard={(id) => discard.run({ input: { id } })} />
      ) : undefined}
      <div>
        {filters.map((each) => (
          <button key={each} type="button" aria-pressed={filter === each} onClick={() => setFilter(each)}>
            {each}
          </button>
        ))}
      </div>
      <ul>
        {visible(list, filter).map((booked) => (
          <Row
            key={booked.id}
            booked={booked}
            onCancel={(id) => cancel.run({ input: { id } })}
            onEdit={(id) => open.run({ input: { id } })}
            onCancelSeries={(seriesId) => cancelWholeSeries.run({ input: { seriesId } })}
          />
        ))}
      </ul>
    </main>
  );
}

function BookingScreen(): ReactElement {
  const scope = useScope();
  const list = useData(bookings);
  const draft = useData(editDraft);

  const [title, setTitle] = useState("");
  const [room, setRoom] = useState("");
  const [date, setDate] = useState("2026-10-01");
  const [start, setStart] = useState("");
  const [end, setEnd] = useState("");
  const [weeks, setWeeks] = useState("1");
  const [filter, setFilter] = useState<Room | "All">("All");
  const [failure, setFailure] = useState<string | null>(null);

  function handleBook(event: FormEvent): void {
    event.preventDefault();
    setFailure(null);
    try {
      scope.run(bookBooking, {
        input: { title, room, date, start: toMinutes(start), end: toMinutes(end) },
      });
      setTitle("");
    } catch (thrown) {
      setFailure(errorKind(thrown));
    }
  }

  function handleBookSeries(): void {
    setFailure(null);
    try {
      scope.run(bookSeries, {
        input: { title, room, date, start: toMinutes(start), end: toMinutes(end), weeks: Number(weeks) },
      });
      setTitle("");
    } catch (thrown) {
      setFailure(errorKind(thrown));
    }
  }

  function handleCancel(id: string): void {
    setFailure(null);
    try {
      scope.run(cancelBooking, { input: { id } });
    } catch (thrown) {
      setFailure(errorKind(thrown));
    }
  }

  function handleCancelSeries(seriesId: string): void {
    setFailure(null);
    try {
      scope.run(cancelSeries, { input: { seriesId } });
    } catch (thrown) {
      setFailure(errorKind(thrown));
    }
  }

  function handleEdit(id: string): void {
    setFailure(null);
    try {
      scope.run(openEdit, { input: { id } });
    } catch (thrown) {
      setFailure(errorKind(thrown));
    }
  }

  function handleUndo(): void {
    setFailure(null);
    try {
      scope.run(undoChange, {});
    } catch (thrown) {
      setFailure(errorKind(thrown));
    }
  }

  function handleEditFailure(thrown: unknown): void {
    setFailure(errorKind(thrown));
  }

  function handleEditSuccess(): void {
    setFailure(null);
  }

  return (
    <main>
      <form className="booking-form" onSubmit={handleBook}>
        <label htmlFor="book-title">Title</label>
        <input
          id="book-title"
          name="Title"
          value={title}
          onChange={(event) => setTitle(event.target.value)}
        />
        <label htmlFor="book-room">Room</label>
        <input
          id="book-room"
          name="Room"
          value={room}
          onChange={(event) => setRoom(event.target.value)}
        />
        <label htmlFor="book-date">Date</label>
        <input
          id="book-date"
          name="Date"
          value={date}
          onChange={(event) => setDate(event.target.value)}
        />
        <label htmlFor="book-start">Start time</label>
        <input
          id="book-start"
          name="Start time"
          value={start}
          onChange={(event) => setStart(event.target.value)}
        />
        <label htmlFor="book-end">End time</label>
        <input
          id="book-end"
          name="End time"
          value={end}
          onChange={(event) => setEnd(event.target.value)}
        />
        <label htmlFor="book-weeks">Weeks</label>
        <input
          id="book-weeks"
          name="Weeks"
          value={weeks}
          onChange={(event) => setWeeks(event.target.value)}
        />
        <button type="submit">Book</button>
        <button type="button" onClick={handleBookSeries}>
          Book series
        </button>
      </form>
      {failure !== null && <div role="alert">{failure}</div>}

      <div className="history">
        <button type="button" onClick={handleUndo}>
          Undo
        </button>
      </div>

      <div className="filters">
        <button type="button" aria-pressed={filter === "All"} onClick={() => setFilter("All")}>
          All
        </button>
        {rooms.map((roomName) => (
          <button
            key={roomName}
            type="button"
            aria-pressed={filter === roomName}
            onClick={() => setFilter(roomName)}
          >
            {roomName}
          </button>
        ))}
      </div>

      <div className="booking-list">
        {list.map((booking) => {
          const seriesId = booking.seriesId;
          return (
            <div
              key={booking.id}
              className="booking-row"
              style={filter === "All" || booking.room === filter ? undefined : { display: "none" }}
            >
              <span className="booking-row-title">{booking.title}</span>
              <span className="booking-row-room">{booking.room}</span>
              <span className="booking-row-date">{booking.date}</span>
              <span className="booking-row-time">
                {formatTime(booking.start)}-{formatTime(booking.end)}
              </span>
              <button
                type="button"
                aria-label={`Edit ${booking.title}`}
                onClick={() => handleEdit(booking.id)}
              >
                Edit
              </button>
              <button
                type="button"
                aria-label={`Cancel ${booking.title}`}
                onClick={() => handleCancel(booking.id)}
              >
                Cancel
              </button>
              {seriesId !== undefined && (
                <button
                  type="button"
                  aria-label="Cancel series"
                  onClick={() => handleCancelSeries(seriesId)}
                >
                  Cancel series
                </button>
              )}
            </div>
          );
        })}
      </div>

      {draft !== undefined && (
        <EditForm key={draft.id} draft={draft} onSuccess={handleEditSuccess} onFailure={handleEditFailure} />
      )}
    </main>
  );
}

