  const type = (field: keyof FormText) => (value: string) => typed.run({ input: { field, value } });
  return (
    <section>
      <Field label="Edit item" value={text.item} onType={type("item")} />
      <Field label="Edit from" value={text.from} onType={type("from")} />
      <Field label="Edit to" value={text.to} onType={type("to")} />
      <Field label="Edit quantity" value={text.quantity} onType={type("quantity")} />
