function PlanScreen() {
  const rootId = useId();
  const list = useData(courses);
  const title = useData(draftTitle);
  const courseChoice = useData(selectedCourseId);
  const prerequisiteChoice = useData(selectedPrerequisiteId);
  const activeFilter = useData(filter);
  const errorKind = useData(notice);

  const addCourse = useRun(createCourse);
  const addLink = useRun(addPrerequisite);
  const removeLink = useRun(removePrerequisite);
  const complete = useRun(completeCourse);
  const reopen = useRun(reopenCourse);
  const undo = useRun(undoPlan);
  const editTitle = useRun(typeTitle);
  const chooseCourseAction = useRun(chooseCourse);
  const choosePrerequisiteAction = useRun(choosePrerequisite);
  const chooseFilterAction = useRun(chooseFilter);

  const rows = list.filter((course) => {
    if (activeFilter === "All") {
      return true;
    }
    if (activeFilter === "Done") {
      return course.done;
    }
    return statusOf(list, course) === "Ready";
  });

  const titleId = `${rootId}-title`;
  const courseSelectId = `${rootId}-course`;
  const prerequisiteSelectId = `${rootId}-prerequisite`;

  return (
    <section>
      <form
        onSubmit={(event) => {
          event.preventDefault();
          addCourse.run({ input: { title } });
        }}
      >
        <label htmlFor={titleId}>Title</label>
        <input
          id={titleId}
          value={title}
          onChange={(event) => {
            editTitle.run({ input: { title: event.target.value } });
          }}
        />
        <button type="submit">Add course</button>
      </form>

      <div>
        {filters.map((name) => (
          <button
            key={name}
            type="button"
            aria-pressed={activeFilter === name}
            onClick={() => {
              chooseFilterAction.run({ input: { filter: name } });
            }}
          >
            {name}
          </button>
        ))}
        <button type="button" onClick={() => undo.run({})}>
          Undo
        </button>
      </div>

      <p role="alert">{errorKind ?? ""}</p>

      <table aria-label="Courses">
        <thead>
          <tr>
            <th>Title</th>
            <th>Status</th>
            <th>Requires</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {rows.map((course) => (
            <tr key={course.id}>
              <td>{course.title}</td>
              <td>{statusOf(list, course)}</td>
              <td>{requiresText(list, course)}</td>
              <td>
                {course.done ? (
                  <button
                    type="button"
                    onClick={() => {
                      reopen.run({ input: { id: course.id } });
                    }}
                  >
                    Reopen {course.title}
                  </button>
                ) : (
                  <button
                    type="button"
                    onClick={() => {
                      complete.run({ input: { id: course.id } });
                    }}
                  >
                    Complete {course.title}
                  </button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      <form
        onSubmit={(event) => {
          event.preventDefault();
          addLink.run({
            input: {
              courseId: courseChoice,
              prerequisiteId: prerequisiteChoice,
            },
          });
        }}
      >
        <label htmlFor={courseSelectId}>Course</label>
        <select
          id={courseSelectId}
          value={courseChoice}
          onChange={(event) => {
            chooseCourseAction.run({ input: { id: event.target.value } });
          }}
        >
          {linkOptions(list, courseChoice)}
        </select>

        <label htmlFor={prerequisiteSelectId}>Prerequisite</label>
        <select
          id={prerequisiteSelectId}
          value={prerequisiteChoice}
          onChange={(event) => {
            choosePrerequisiteAction.run({ input: { id: event.target.value } });
          }}
        >
          {linkOptions(list, prerequisiteChoice)}
        </select>

        <button type="submit">Add requirement</button>
        <button
          type="button"
          onClick={() => {
            removeLink.run({
              input: {
                courseId: courseChoice,
                prerequisiteId: prerequisiteChoice,
              },
            });
          }}
        >
          Remove requirement
        </button>
      </form>
    </section>
  );
}

