function BookingScreen(): ReactElement {
  const scope = useScope();
  const formId = useId();
  const list = useData(bookings);
  const draft = useData(editDraft);
  const [filter, setFilter] = useState<Filter>("All");
  const [error, setError] = useState<string | undefined>(undefined);
  const [title, setTitle] = useState("");
  const [room, setRoom] = useState("");
  const [date, setDate] = useState(defaultDate);
  const [start, setStart] = useState("");
  const [end, setEnd] = useState("");
  const [weeks, setWeeks] = useState("1");

  const run = (action: () => void): void => {
    try {
      action();
      setError(undefined);
    } catch (caught) {
      setError(shownKind(caught));
    }
  };

  const bookOne = (): void =>
    run(() => {
      scope.run(bookBooking, {
        input: {
          title,
          room,
          date: parseDate(date),
          start: parseTime(start),
          end: parseTime(end),
        },
      });
      setTitle("");
    });

  const bookMany = (): void =>
    run(() => {
      scope.run(bookSeries, {
        input: {
          title,
          room,
          date: parseDate(date) ?? defaultDate,
          start: parseTime(start),
          end: parseTime(end),
          weeks: parseWeeks(weeks),
        },
      });
      setTitle("");
    });

  return (
    <div>
      <form
        onSubmit={(event) => {
          event.preventDefault();
          bookOne();
        }}
      >
        <label htmlFor={`${formId}-title`}>Title</label>
        <input
          id={`${formId}-title`}
          name="Title"
          type="text"
          value={title}
          onChange={(event) => setTitle(event.target.value)}
        />
        <label htmlFor={`${formId}-room`}>Room</label>
        <input
          id={`${formId}-room`}
          name="Room"
          type="text"
          value={room}
          onChange={(event) => setRoom(event.target.value)}
        />
        <label htmlFor={`${formId}-date`}>Date</label>
        <input
          id={`${formId}-date`}
          name="Date"
          type="text"
          value={date}
          onChange={(event) => setDate(event.target.value)}
        />
        <label htmlFor={`${formId}-start`}>Start time</label>
        <input
          id={`${formId}-start`}
          name="Start time"
          type="text"
          value={start}
          onChange={(event) => setStart(event.target.value)}
        />
        <label htmlFor={`${formId}-end`}>End time</label>
        <input
          id={`${formId}-end`}
          name="End time"
          type="text"
          value={end}
          onChange={(event) => setEnd(event.target.value)}
        />
        <label htmlFor={`${formId}-weeks`}>Weeks</label>
        <input
          id={`${formId}-weeks`}
          name="Weeks"
          type="text"
          value={weeks}
          onChange={(event) => setWeeks(event.target.value)}
        />
        <button type="submit">Book</button>
        <button type="button" onClick={bookMany}>
          Book series
        </button>
      </form>
      <div role="alert">{error ?? ""}</div>
      <div>
        <button
          type="button"
          onClick={() =>
            run(() => {
              scope.run(undoChange, {});
            })
          }
        >
          Undo
        </button>
      </div>
      <div>
        <button type="button" onClick={() => setFilter("All")}>
          All
        </button>
        <button type="button" onClick={() => setFilter("Cedar")}>
          Cedar
        </button>
        <button type="button" onClick={() => setFilter("Maple")}>
          Maple
        </button>
      </div>
      {draft ? (
        <EditForm
          key={draft.id}
          draft={draft}
          onSave={(fields) =>
            run(() => {
              scope.run(saveEdit, { input: { id: draft.id, ...fields } });
            })
          }
          onDiscard={() =>
            run(() => {
              scope.run(discardEdit, { input: { id: draft.id } });
            })
          }
        />
      ) : null}
      <table>
        <tbody>
          {list.map((booking) => (
            <tr
              key={booking.id}
              hidden={filter !== "All" && filter !== booking.room}
            >
              <td>{booking.title}</td>
              <td>{booking.room}</td>
              <td>{booking.date}</td>
              <td>
