                <button
                  type="button"
                  aria-label={`Edit ${booking.title}`}
                  onClick={() =>
                    run(() => {
                      scope.run(openEdit, { input: { id: booking.id } });
                    })
                  }
                >
                  Edit
                </button>
                <button
                  type="button"
                  aria-label={`Cancel ${booking.title}`}
                  onClick={() =>
                    run(() => {
                      scope.run(cancelBooking, { input: { id: booking.id } });
                    })
                  }
                >
                  Cancel
