                {booking.seriesId === undefined ? null : (
                  <button
                    type="button"
                    onClick={() =>
                      run(() => {
                        if (booking.seriesId !== undefined) {
                          scope.run(cancelSeries, {
                            input: { seriesId: booking.seriesId },
