function BookingScreen(): ReactElement {
  const list = useData(bookings);
  const draft = useData(editDraft);
  const [filter, setFilter] = useState<Filter>("All");
  const [title, setTitle] = useState("");
  const [room, setRoom] = useState("Cedar");
  const [date, setDate] = useState(defaultDate);
  const [start, setStart] = useState("09:00");
  const [end, setEnd] = useState("10:00");
  const [weeks, setWeeks] = useState("1");
  const [kind, setKind] = useState<string | undefined>(undefined);

  const book = useRun(bookBooking, {
    onSuccess: () => {
      setTitle("");
      setKind(undefined);
    },
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const series = useRun(bookSeries, {
    onSuccess: () => {
      setTitle("");
      setKind(undefined);
    },
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const cancel = useRun(cancelBooking, {
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const cancelWholeSeries = useRun(cancelSeries, {
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const open = useRun(openEdit, {
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const save = useRun(saveEdit, {
    onSuccess: () => {
      setKind(undefined);
    },
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const undo = useRun(undoChange, {
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const discard = useRun(discardEdit, {
    onError: (error) => {
      setKind(kindOf(error));
    },
  });

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const startMinute = toMinute(start);
    const endMinute = toMinute(end);
    if (startMinute === undefined || endMinute === undefined) {
      setKind("BadTime");
      return;
    }
    book.run({ input: { title, room, date, start: startMinute, end: endMinute } });
  };

  const submitSeries = () => {
    const startMinute = toMinute(start);
    const endMinute = toMinute(end);
    if (startMinute === undefined || endMinute === undefined) {
      setKind("BadTime");
      return;
    }
    series.run({ input: { title, room, date, start: startMinute, end: endMinute, weeks: Number(weeks) } });
  };

  const saveDraft = (input: {
    readonly id: string;
    readonly title: string;
    readonly room: string;
    readonly date: string;
    readonly start: number;
    readonly end: number;
  }) => {
    if (input.start < 0 || input.end < 0) {
      setKind("BadTime");
      return;
    }
    save.run({ input });
  };

  return (
    <main>
      <form onSubmit={submit}>
        <label>
          Title
          <input name="Title" value={title} onChange={(event) => setTitle(event.target.value)} />
        </label>
        <label>
          Room
          <input name="Room" value={room} onChange={(event) => setRoom(event.target.value)} />
        </label>
        <label>
          Date
          <input name="Date" value={date} onChange={(event) => setDate(event.target.value)} />
        </label>
        <label>
          Start time
          <input
            name="Start time"
            placeholder="09:00"
            value={start}
            onChange={(event) => setStart(event.target.value)}
          />
        </label>
        <label>
          End time
          <input
            name="End time"
            placeholder="10:00"
            value={end}
            onChange={(event) => setEnd(event.target.value)}
          />
        </label>
        <label>
          Weeks
          <input name="Weeks" value={weeks} onChange={(event) => setWeeks(event.target.value)} />
        </label>
        <button type="submit">Book</button>
        <button type="button" onClick={() => submitSeries()}>
          Book series
        </button>
        <button type="button" onClick={() => undo.run()}>
          Undo
        </button>
        {kind !== undefined ? <div role="alert">{kind}</div> : undefined}
      </form>
      {draft !== undefined ? (
        <DraftEditor draft={draft} onSave={saveDraft} onDiscard={(id) => discard.run({ input: { id } })} />
      ) : undefined}
      <div>
        {filters.map((each) => (
          <button key={each} type="button" aria-pressed={filter === each} onClick={() => setFilter(each)}>
            {each}
          </button>
        ))}
      </div>
      <ul>
        {visible(list, filter).map((booked) => (
          <Row
            key={booked.id}
            booked={booked}
            onCancel={(id) => cancel.run({ input: { id } })}
            onEdit={(id) => open.run({ input: { id } })}
            onCancelSeries={(seriesId) => cancelWholeSeries.run({ input: { seriesId } })}
          />
        ))}
      </ul>
    </main>
  );
}

