        {noticeKind !== undefined ? <div role="alert">{noticeKind}</div> : undefined}
      </form>
      {edit !== undefined ? <DraftEditor draft={edit} /> : undefined}
      {seriesEditor !== undefined ? <SeriesTitleEditor editor={seriesEditor} /> : undefined}
      <div>
        {filters.map((each) => (
          <button
            key={each}
            type="button"
            aria-pressed={filter === each}
            onClick={() => choose.run({ input: each })}
          >
            {each}
          </button>
        ))}
      </div>
      <ul>
        {visible(list, filter).map((booked) => (
          <Row
            key={booked.id}
            booked={booked}
            onCancel={(id) => cancel.run({ input: { id } })}
            onEdit={(id) => open.run({ input: { id } })}
            onCancelSeries={(seriesId) => cancelWholeSeries.run({ input: { seriesId } })}
            onRenameSeries={(id) => renameSeries.run({ input: { id } })}
          />
        ))}
      </ul>
    </main>
  );
}

