function BookingScreen(): ReactElement {
  const scope = useScope();
  const list = useData(bookings);
  const draft = useData(editDraft);
  const [filter, setFilter] = useState<Filter>("All");
  const [title, setTitle] = useState("");
  const [room, setRoom] = useState("");
  const [date, setDate] = useState(DEFAULT_DATE);
  const [startText, setStartText] = useState("");
  const [endText, setEndText] = useState("");
  const [weeks, setWeeks] = useState("1");
  const [alert, setAlert] = useState<string | undefined>(undefined);

  const shown = filter === "All" ? list : list.filter((b) => b.room === filter);

  function handleBook(): void {
    const start = parseTime(startText);
    const end = parseTime(endText);
    if (start === undefined || end === undefined) {
      setAlert("BadTime");
      return;
    }
    try {
      scope.run(bookBooking, { input: { title, room, date, start, end } });
      setTitle("");
      setAlert(undefined);
    } catch (error) {
      setAlert(errorKind(error));
    }
  }

  function handleBookSeries(): void {
    const start = parseTime(startText);
    const end = parseTime(endText);
    if (start === undefined || end === undefined) {
      setAlert("BadTime");
      return;
    }
    try {
      scope.run(bookSeries, {
        input: { title, room, date, start, end, weeks: Number(weeks) },
      });
      setTitle("");
      setAlert(undefined);
    } catch (error) {
      setAlert(errorKind(error));
    }
  }

  function handleEdit(id: string): void {
    try {
      scope.run(openEdit, { input: { id } });
      setAlert(undefined);
    } catch (error) {
      setAlert(errorKind(error));
    }
  }

  function handleCancel(id: string): void {
    try {
      scope.run(cancelBooking, { input: { id } });
      setAlert(undefined);
    } catch (error) {
      setAlert(errorKind(error));
    }
  }

  function handleUndo(): void {
    try {
      scope.run(undoChange, {});
      setAlert(undefined);
    } catch (error) {
      setAlert(errorKind(error));
    }
  }

  function handleCancelSeries(seriesId: string): void {
    try {
      scope.run(cancelSeries, { input: { seriesId } });
      setAlert(undefined);
    } catch (error) {
      setAlert(errorKind(error));
    }
  }

  return (
    <div>
      <div>
        <label htmlFor="title">Title</label>
        <input
          id="title"
          value={title}
          onChange={(event: ChangeEvent<HTMLInputElement>) =>
            setTitle(event.target.value)
          }
        />
        <label htmlFor="room">Room</label>
        <input
          id="room"
          value={room}
          onChange={(event: ChangeEvent<HTMLInputElement>) =>
            setRoom(event.target.value)
          }
        />
        <label htmlFor="date">Date</label>
        <input
          id="date"
          value={date}
          onChange={(event: ChangeEvent<HTMLInputElement>) =>
            setDate(event.target.value)
          }
        />
        <label htmlFor="start">Start time</label>
        <input
          id="start"
          value={startText}
          onChange={(event: ChangeEvent<HTMLInputElement>) =>
            setStartText(event.target.value)
          }
        />
        <label htmlFor="end">End time</label>
        <input
          id="end"
          value={endText}
          onChange={(event: ChangeEvent<HTMLInputElement>) =>
            setEndText(event.target.value)
          }
        />
        <label htmlFor="weeks">Weeks</label>
        <input
          id="weeks"
          value={weeks}
          onChange={(event: ChangeEvent<HTMLInputElement>) =>
            setWeeks(event.target.value)
          }
        />
        <button type="button" onClick={handleBook}>
          Book
        </button>
        <button type="button" onClick={handleBookSeries}>
          Book series
        </button>
        <button type="button" onClick={handleUndo}>
          Undo
        </button>
      </div>

      {alert === undefined ? null : <div role="alert">{alert}</div>}

      {draft === undefined ? null : (
        <EditForm
          key={draft.id}
          draft={draft}
          scope={scope}
          onError={setAlert}
        />
      )}

      <FilterBar active={filter} onSelect={setFilter} />

      <table>
        <thead>
          <tr>
            <th>Title</th>
            <th>Room</th>
            <th>Date</th>
            <th>Time</th>
            <th>Edit</th>
            <th>Cancel</th>
            <th>Series</th>
          </tr>
        </thead>
        <tbody>
          {shown.map((booking) => (
            <BookingRow
              key={booking.id}
              booking={booking}
              onEdit={handleEdit}
              onCancel={handleCancel}
              onCancelSeries={handleCancelSeries}
            />
          ))}
        </tbody>
      </table>
    </div>
  );
}

