function DraftEditor(props: {
  readonly draft: Booking;
  readonly onSave: (input: {
    readonly id: string;
    readonly title: string;
    readonly room: string;
    readonly date: string;
    readonly start: number;
    readonly end: number;
  }) => void;
  readonly onDiscard: (id: string) => void;
}): ReactElement {
  const { draft, onSave, onDiscard } = props;
  const [title, setTitle] = useState(draft.title);
  const [room, setRoom] = useState<string>(draft.room);
  const [date, setDate] = useState(draft.date);
  const [start, setStart] = useState(timeLabel(draft.start));
  const [end, setEnd] = useState(timeLabel(draft.end));

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const startMinute = toMinute(start);
    const endMinute = toMinute(end);
    if (startMinute === undefined || endMinute === undefined) {
      onSave({ id: draft.id, title, room, date, start: -1, end: -1 });
      return;
    }
    onSave({ id: draft.id, title, room, date, start: startMinute, end: endMinute });
  };

  return (
    <form onSubmit={submit}>
      <label>
        Edit title
        <input name="Edit title" value={title} onChange={(event) => setTitle(event.target.value)} />
      </label>
      <label>
        Edit room
        <input name="Edit room" value={room} onChange={(event) => setRoom(event.target.value)} />
      </label>
      <label>
        Edit date
        <input name="Edit date" value={date} onChange={(event) => setDate(event.target.value)} />
      </label>
      <label>
        Edit start time
        <input
          name="Edit start time"
          placeholder="09:00"
          value={start}
          onChange={(event) => setStart(event.target.value)}
        />
      </label>
      <label>
        Edit end time
        <input
          name="Edit end time"
          placeholder="10:00"
          value={end}
          onChange={(event) => setEnd(event.target.value)}
        />
      </label>
      <button type="submit">Save</button>
      <button type="button" onClick={() => onDiscard(draft.id)}>
        Discard
      </button>
    </form>
  );
}

function BookingScreen(): ReactElement {
  const scope = useScope();
  const list = useData(bookings);
  const draft = useData(editDraft);

  const [title, setTitle] = useState("");
  const [room, setRoom] = useState("");
  const [date, setDate] = useState("2026-10-01");
  const [start, setStart] = useState("");
  const [end, setEnd] = useState("");
  const [weeks, setWeeks] = useState("1");
  const [filter, setFilter] = useState<Room | "All">("All");
  const [failure, setFailure] = useState<string | null>(null);

  function handleBook(event: FormEvent): void {
    event.preventDefault();
    setFailure(null);
    try {
      scope.run(bookBooking, {
        input: { title, room, date, start: toMinutes(start), end: toMinutes(end) },
      });
      setTitle("");
    } catch (thrown) {
      setFailure(errorKind(thrown));
    }
  }

  function handleBookSeries(): void {
    setFailure(null);
    try {
      scope.run(bookSeries, {
        input: { title, room, date, start: toMinutes(start), end: toMinutes(end), weeks: Number(weeks) },
      });
      setTitle("");
    } catch (thrown) {
      setFailure(errorKind(thrown));
    }
  }

  function handleCancel(id: string): void {
    setFailure(null);
    try {
      scope.run(cancelBooking, { input: { id } });
    } catch (thrown) {
      setFailure(errorKind(thrown));
    }
  }

  function handleCancelSeries(seriesId: string): void {
    setFailure(null);
    try {
      scope.run(cancelSeries, { input: { seriesId } });
    } catch (thrown) {
      setFailure(errorKind(thrown));
    }
  }

  function handleEdit(id: string): void {
    setFailure(null);
    try {
      scope.run(openEdit, { input: { id } });
    } catch (thrown) {
      setFailure(errorKind(thrown));
    }
  }

  function handleUndo(): void {
    setFailure(null);
    try {
      scope.run(undoChange, {});
    } catch (thrown) {
      setFailure(errorKind(thrown));
    }
  }

  function handleEditFailure(thrown: unknown): void {
    setFailure(errorKind(thrown));
  }

  function handleEditSuccess(): void {
    setFailure(null);
  }

  return (
    <main>
      <form className="booking-form" onSubmit={handleBook}>
        <label htmlFor="book-title">Title</label>
        <input
          id="book-title"
          name="Title"
          value={title}
          onChange={(event) => setTitle(event.target.value)}
        />
        <label htmlFor="book-room">Room</label>
        <input
          id="book-room"
          name="Room"
          value={room}
          onChange={(event) => setRoom(event.target.value)}
        />
        <label htmlFor="book-date">Date</label>
        <input
          id="book-date"
          name="Date"
          value={date}
          onChange={(event) => setDate(event.target.value)}
        />
        <label htmlFor="book-start">Start time</label>
        <input
          id="book-start"
          name="Start time"
          value={start}
          onChange={(event) => setStart(event.target.value)}
        />
        <label htmlFor="book-end">End time</label>
        <input
          id="book-end"
          name="End time"
          value={end}
          onChange={(event) => setEnd(event.target.value)}
        />
        <label htmlFor="book-weeks">Weeks</label>
        <input
          id="book-weeks"
          name="Weeks"
          value={weeks}
          onChange={(event) => setWeeks(event.target.value)}
        />
        <button type="submit">Book</button>
        <button type="button" onClick={handleBookSeries}>
          Book series
        </button>
      </form>
      {failure !== null && <div role="alert">{failure}</div>}

      <div className="history">
        <button type="button" onClick={handleUndo}>
          Undo
        </button>
      </div>

      <div className="filters">
        <button type="button" aria-pressed={filter === "All"} onClick={() => setFilter("All")}>
          All
        </button>
        {rooms.map((roomName) => (
          <button
            key={roomName}
            type="button"
            aria-pressed={filter === roomName}
            onClick={() => setFilter(roomName)}
          >
            {roomName}
          </button>
        ))}
      </div>

      <div className="booking-list">
        {list.map((booking) => {
          const seriesId = booking.seriesId;
          return (
            <div
              key={booking.id}
              className="booking-row"
              style={filter === "All" || booking.room === filter ? undefined : { display: "none" }}
            >
              <span className="booking-row-title">{booking.title}</span>
              <span className="booking-row-room">{booking.room}</span>
              <span className="booking-row-date">{booking.date}</span>
              <span className="booking-row-time">
                {formatTime(booking.start)}-{formatTime(booking.end)}
              </span>
              <button
                type="button"
                aria-label={`Edit ${booking.title}`}
                onClick={() => handleEdit(booking.id)}
              >
                Edit
              </button>
              <button
                type="button"
                aria-label={`Cancel ${booking.title}`}
                onClick={() => handleCancel(booking.id)}
              >
                Cancel
              </button>
              {seriesId !== undefined && (
                <button
                  type="button"
                  aria-label="Cancel series"
                  onClick={() => handleCancelSeries(seriesId)}
                >
                  Cancel series
                </button>
              )}
            </div>
          );
        })}
      </div>

      {draft !== undefined && (
        <EditForm key={draft.id} draft={draft} onSuccess={handleEditSuccess} onFailure={handleEditFailure} />
      )}
    </main>
  );
}

