          key={draft.id}
          draft={draft}
          onSave={(fields) =>
            run(() => {
              scope.run(saveEdit, { input: { id: draft.id, ...fields } });
            })
          }
          onDiscard={() =>
            run(() => {
              scope.run(discardEdit, { input: { id: draft.id } });
            })
          }
        />
      ) : null}
      <table>
        <tbody>
          {list.map((booking) => (
            <tr
              key={booking.id}
              hidden={filter !== "All" && filter !== booking.room}
            >
              <td>{booking.title}</td>
              <td>{booking.room}</td>
              <td>{booking.date}</td>
              <td>
                {formatTime(booking.start)} - {formatTime(booking.end)}
              </td>
