                  type="button"
                  aria-label={`Edit ${booking.title}`}
                  onClick={() =>
                    run(() => {
                      scope.run(openEdit, { input: { id: booking.id } });
                    })
                  }
                >
                  Edit
                </button>
                <button
                  type="button"
                  aria-label={`Cancel ${booking.title}`}
                  onClick={() =>
                    run(() => {
                      scope.run(cancelBooking, { input: { id: booking.id } });
                    })
                  }
                >
                  Cancel
                </button>
                {booking.seriesId === undefined ? null : (
                  <button
                    type="button"
                    onClick={() =>
                      run(() => {
                        if (booking.seriesId !== undefined) {
                          scope.run(cancelSeries, {
                            input: { seriesId: booking.seriesId },
                          });
                        }
                      })
                    }
                  >
                    Cancel series
                  </button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
