function EditForm({
  draft,
  scope,
  onError,
}: {
  readonly draft: Booking;
  readonly scope: Scope.Handle;
  readonly onError: (kind: string | undefined) => void;
}): ReactElement {
  const [title, setTitle] = useState(draft.title);
  const [room, setRoom] = useState<string>(draft.room);
  const [date, setDate] = useState(draft.date);
  const [startText, setStartText] = useState(formatTime(draft.start));
  const [endText, setEndText] = useState(formatTime(draft.end));

  function handleSave(): void {
    const start = parseTime(startText);
    const end = parseTime(endText);
    if (start === undefined || end === undefined) {
      onError("BadTime");
      return;
    }
    try {
      scope.run(saveEdit, {
        input: { id: draft.id, title, room, date, start, end },
      });
      onError(undefined);
    } catch (error) {
      onError(errorKind(error));
    }
  }

  function handleDiscard(): void {
    try {
      scope.run(discardEdit, { input: { id: draft.id } });
      onError(undefined);
    } catch (error) {
      onError(errorKind(error));
    }
  }

  return (
    <div>
      <label htmlFor="edit-title">Edit title</label>
      <input
        id="edit-title"
        value={title}
        onChange={(event: ChangeEvent<HTMLInputElement>) =>
          setTitle(event.target.value)
        }
      />
      <label htmlFor="edit-room">Edit room</label>
      <input
        id="edit-room"
        value={room}
        onChange={(event: ChangeEvent<HTMLInputElement>) =>
          setRoom(event.target.value)
        }
      />
      <label htmlFor="edit-date">Edit date</label>
      <input
        id="edit-date"
        value={date}
        onChange={(event: ChangeEvent<HTMLInputElement>) =>
          setDate(event.target.value)
        }
      />
      <label htmlFor="edit-start">Edit start time</label>
      <input
        id="edit-start"
        value={startText}
        onChange={(event: ChangeEvent<HTMLInputElement>) =>
          setStartText(event.target.value)
        }
      />
      <label htmlFor="edit-end">Edit end time</label>
      <input
        id="edit-end"
        value={endText}
        onChange={(event: ChangeEvent<HTMLInputElement>) =>
          setEndText(event.target.value)
        }
      />
      <button type="button" onClick={handleSave}>
        Save
      </button>
      <button type="button" onClick={handleDiscard}>
        Discard
      </button>
    </div>
  );
}

