addPrerequisite: Operation.Handle<
  Course,
  { courseId: string; prerequisiteId: string }
> = operation({
  label: "addPrerequisite",
  depends: {
    courses: courses.controller,
    history: history.controller,
    notice: notice.controller,
  },
  run: (deps, ctx) =>
    attempt(deps.notice, () => {
      const list = deps.courses.get();
      const { courseId, prerequisiteId } = ctx.input;
      const course = linkEnds(list, courseId, prerequisiteId);
      if (course.done) {
        return fail("CourseDone", { id: courseId });
      }
      if (course.prerequisiteIds.includes(prerequisiteId)) {
        return course;
      }
      if (requires(list, prerequisiteId, courseId)) {
        return fail("Cycle", { courseId, prerequisiteId });
      }
      const changed: Course = {
        ...course,
        prerequisiteIds: [...course.prerequisiteIds, prerequisiteId],
      };
      commit({ courses: deps.courses, history: deps.history }, replaceCourse(list, courseId, changed));
      return changed;
    }),
})

completeCourse = operation({
  label: "completeCourse",
  depends: planDeps,
  run: (deps, ctx: Operation.Ctx<CourseId>): Course => {
    const { id } = ctx.input;
    const list = deps.list.get();
    const course = findCourse(list, id);
    if (course === undefined) return fail(deps.notice, "NotFound", { id });
    const open = course.prerequisiteIds.filter((requiredId) => {
      const required = findCourse(list, requiredId);
      return required === undefined || !required.done;
    });
    if (open.length > 0) {
      return fail(deps.notice, "PrerequisitesOpen", { id, prerequisiteIds: open });
    }
    if (course.done) {
      deps.notice.set(null);
      return course;
    }
    const changed: Course = { ...course, done: true };
    deps.notice.set(null);
    deps.undo.set([...deps.undo.get(), list]);
    deps.list.set(replaceCourse(list, changed));
    return changed;
  },
})

reopenCourse: Operation.Handle<Course, { id: string }> =
  operation({
    label: "reopenCourse",
    depends: {
      courses: courses.controller,
      history: history.controller,
      notice: notice.controller,
    },
    run: (deps, ctx) =>
      attempt(deps.notice, () => {
        const list = deps.courses.get();
        const course = findCourse(list, ctx.input.id);
        if (course === undefined) {
          return fail("NotFound", { id: ctx.input.id });
        }
        const dependents = doneDependents(list, course.id);
        if (dependents.length > 0) {
          return fail("DependentsDone", { id: course.id, dependentIds: dependents });
        }
        if (!course.done) {
          return course;
        }
        const changed: Course = { ...course, done: false };
        commit({ courses: deps.courses, history: deps.history }, replaceCourse(list, course.id, changed));
        return changed;
      }),
  })

