function addDays(date: string, days: number): string {
  const parts = date.split("-").map(Number);
  const time = new Date(0);
  time.setUTCFullYear(parts[0], parts[1] - 1, parts[2] + days);
  time.setUTCHours(0, 0, 0, 0);
  const year = time.getUTCFullYear().toString().padStart(4, "0");
  const month = (time.getUTCMonth() + 1).toString().padStart(2, "0");
  const day = time.getUTCDate().toString().padStart(2, "0");
  return `${year}-${month}-${day}`;
}

export function shapeBooking(raw: unknown): BookInput {
  const date = field(raw, "date");
  return {
    title: text(field(raw, "title")),
    room: text(field(raw, "room")),
    date: typeof date === "string" ? date : undefined,
    start: minute(field(raw, "start")),
    end: minute(field(raw, "end")),
  };
}

function isRealDay(raw: string): boolean {
  const year = Number(raw.slice(0, 4));
  const month = Number(raw.slice(5, 7));
  const day = Number(raw.slice(8, 10));
  const check = new Date(Date.UTC(year, month - 1, day));
  return (
    check.getUTCFullYear() === year &&
    check.getUTCMonth() === month - 1 &&
    check.getUTCDate() === day
  );
}

function shiftStock(
  rows: readonly Stock[],
  item: Item,
  from: Place,
  to: Place,
  quantity: number,
): readonly Stock[] {
  return rows.map((row) => {
    if (row.item !== item) return row;
    if (row.place === from) return { ...row, quantity: row.quantity - quantity };
    if (row.place === to) return { ...row, quantity: row.quantity + quantity };
    return row;
  });
}

function requireMinute(value: unknown): number {
  if (
    typeof value !== "number" ||
    !Number.isInteger(value) ||
    value < 0 ||
    value > 1439
  ) {
    throw appError("BadTime", { value });
  }
  return value;
}

function applyChange(deps: ChangeDeps, next: readonly Booking[]): void {
  deps.history.set([...deps.history.get(), deps.list.get()]);
  deps.list.set(next);
}

function findRoom(value: string): Room | undefined {
  return ROOM_LIST.find((room) => room === value);
}

export function addDays(date: string, days: number): string {
  const match = DATE_PATTERN.exec(date);
  if (match === null) {
    throw badDate(date);
  }
  let year = Number(match[1]);
  let month = Number(match[2]);
  let day = Number(match[3]) + days;
  let limit = daysInMonth(year, month);
  while (day > limit) {
    day -= limit;
    month += 1;
    if (month > MONTHS_PER_YEAR) {
      month = 1;
      year += 1;
    }
    limit = daysInMonth(year, month);
  }
  const textYear = String(year).padStart(4, "0");
  const textMonth = String(month).padStart(2, "0");
  const textDay = String(day).padStart(2, "0");
  return `${textYear}-${textMonth}-${textDay}`;
}

function addDays(date: string, days: number): string {
  const start = Date.UTC(
    Number(date.slice(0, 4)),
    Number(date.slice(5, 7)) - 1,
    Number(date.slice(8, 10)),
  );
  return new Date(start + days * DAY_MS).toISOString().slice(0, 10);
}

export function requireWeeks(value: unknown): number {
  if (
    typeof value !== "number" ||
    !Number.isInteger(value) ||
    value < 1 ||
    value > 12
  ) {
    throw appError("BadCount", { weeks: value });
  }
  return value;
}

function civilFromDays(days: number): { readonly year: number; readonly month: number; readonly day: number } {
  const shifted = days + 719468;
  const era = Math.floor(shifted / 146097);
  const dayOfEra = shifted - era * 146097;
  const yearOfEra = Math.floor(
    (dayOfEra - Math.floor(dayOfEra / 1460) + Math.floor(dayOfEra / 36524) - Math.floor(dayOfEra / 146096)) / 365,
  );
  const year = yearOfEra + era * 400;
  const dayOfYear =
    dayOfEra - (365 * yearOfEra + Math.floor(yearOfEra / 4) - Math.floor(yearOfEra / 100));
  const monthPattern = Math.floor((5 * dayOfYear + 2) / 153);
  const day = dayOfYear - Math.floor((153 * monthPattern + 2) / 5) + 1;
  const month = monthPattern < 10 ? monthPattern + 3 : monthPattern - 9;
  return { year: month <= 2 ? year + 1 : year, month, day };
}

function idField(value: unknown, key: 'toolId' | 'loanId'): string {
  const id = field(value, key);
  return typeof id === 'string' ? id : String(id);
}

