cancelTicket: Operation.Handle<void, TicketInput> = operation<
  typeof ticketDeps,
  void,
  TicketInput
>({
  label: "cancelTicket",
  depends: ticketDeps,
  run(deps, ctx) {
    try {
      const ticket = requireTicket(deps.tickets.get(), readTicketId(ctx.rawInput));
      if (ticket.state !== "waiting") {
        throw fail("CannotCancel", { id: ticket.id });
      }
      const list = deps.tickets.get();
      deps.undo.update((prev) => [
        ...prev,
        { tickets: list, stove: deps.stove.get() },
      ]);
      deps.tickets.set(list.filter((t) => t.id !== ticket.id));
      deps.notice.set(null);
    } catch (error) {
      throw noted(deps.notice, error);
    }
  },
})

function withDefaultDate(raw: unknown): unknown {
  if (fieldPresent(raw, "date")) return raw;
  if (typeof raw !== "object" || raw === null) return { date: DEFAULT_DATE };
  return { ...raw, date: DEFAULT_DATE };
}

bookBooking: Operation.Handle<Booking, BookInput> = operation<
  ListDep & CreatedDep & HistoryDep,
  Booking,
  BookInput
>({
  label: "bookBooking",
  depends: {
    bookings: bookings.controller,
    created: created.controller,
    history: history.controller,
  },
  run: (deps, ctx) => {
    const raw = ctx.rawInput;
    const title = readTitle(fieldOffered(raw, "title"));
    const room = readRoom(fieldOffered(raw, "room"));
    const date = fieldPresent(raw, "date")
      ? readDate(fieldOffered(raw, "date"))
      : DEFAULT_DATE;
    const startOffered = fieldOffered(raw, "start");
    const endOffered = fieldOffered(raw, "end");
    const start = readMinutes(startOffered);
    const end = readMinutes(endOffered);
    if (end <= start) raise("BadTime", { value: endOffered });
    const saved = deps.bookings.get();
    if (saved.some((booking) => overlaps(room, date, start, end, booking))) {
      raise("Clash", { room, start, end });
    }
    const booking: Booking = { id: ctx.random.uuid(), title, room, date, start, end };
    const ids = [...deps.created.get(), booking.id];
    deps.history.set([...deps.history.get(), { bookings: saved, created: deps.created.get() }]);
    deps.created.set(ids);
    deps.bookings.set(inListOrder([...saved, booking], ids));
    return booking;
  },
})

saveEdit: Operation.Handle<Booking, EditInput> = operation<
  ListDep & CreatedDep & DraftDep & HistoryDep,
  Booking,
  EditInput
>({
  label: "saveEdit",
  depends: {
    bookings: bookings.controller,
    created: created.controller,
    draft: editDraft.controller,
    history: history.controller,
  },
  run: (deps, ctx) => {
    const raw = ctx.rawInput;
    const id = readId(fieldOffered(raw, "id"));
    const draft = deps.draft.get();
    if (draft === undefined || draft.id !== id) raise("NotFound", { id });
    const title = readTitle(fieldOffered(raw, "title"));
    const room = readRoom(fieldOffered(raw, "room"));
    const date = fieldPresent(raw, "date")
      ? readDate(fieldOffered(raw, "date"))
      : DEFAULT_DATE;
    const startOffered = fieldOffered(raw, "start");
    const endOffered = fieldOffered(raw, "end");
    const start = readMinutes(startOffered);
    const end = readMinutes(endOffered);
    if (end <= start) raise("BadTime", { value: endOffered });
    const saved = deps.bookings.get();
    if (!saved.some((booking) => booking.id === id)) raise("NotFound", { id });
    if (saved.some((booking) => booking.id !== id && overlaps(room, date, start, end, booking))) {
      raise("Clash", { room, start, end });
    }
    const edited: Booking = draft.seriesId === undefined
      ? { id, title, room, date, start, end }
      : { id, title, room, date, start, end, seriesId: draft.seriesId };
    deps.history.set([...deps.history.get(), { bookings: saved, created: deps.created.get() }]);
    deps.bookings.set(
      inListOrder(saved.map((booking) => (booking.id === id ? edited : booking)), deps.created.get()),
    );
    deps.draft.set(undefined);
    return edited;
  },
})

function foldChunk(
  chunk: Tinkerer.Chunk,
  deps: Pick<TurnCells, "text" | "usage">,
  parts: Map<number, { id: string; name: string; args: string }>,
  finish: string | undefined,
): string | undefined {
  const head = chunk.choices?.[0];
  if (head?.delta !== undefined) foldDelta(head.delta, deps.text, parts);
  recordUsage(deps.usage, chunk.usage);
  const reason = head?.finish_reason;
  return typeof reason === "string" ? reason : finish;
}

function startClaude(
  sdk: ClaudeCode.Sdk,
  options: Options,
  hooks: Harness.Hooks,
): Harness.Thread<ClaudeCode.Turn, ClaudeCode.Result, ClaudeCode.Calls> {
  const aborter = new AbortController();
  if (hooks.signal.aborted) aborter.abort(hooks.signal.reason);
  else
    hooks.signal.addEventListener("abort", () => aborter.abort(hooks.signal.reason), {
      once: true,
    });
  const state: ThreadState = { lastId: undefined, server: undefined };
  return {
    run: async (turn, calls) => {
      const opened = readTurnOptions(sdk, options, state, aborter, calls, hooks);
      for await (const message of sdk.query({ prompt: turn.prompt, options: opened })) {
        const result = mapClaudeMessage(message, hooks);
        if (result !== undefined) {
          state.lastId = result.session_id;
          return result;
        }
      }
      if (hooks.signal.aborted) throw hooks.signal.reason;
      raise("TurnEnded", { harness: "claudeCode" });
    },
    close: () => {
      aborter.abort();
    },
  };
}

