function readTurnOptions(
  sdk: ClaudeCode.Sdk,
  options: Options,
  state: ThreadState,
  aborter: AbortController,
  calls: Harness.TurnCalls<ClaudeCode.Calls>,
  hooks: Harness.Hooks,
): Options {
  const opened: Options =
    state.lastId === undefined
      ? { ...options, abortController: aborter }
      : { ...options, resume: state.lastId, abortController: aborter };
  if (calls.approve !== undefined) opened.canUseTool = readCanUseTool(calls.approve, hooks);
  if (calls.tools !== undefined) {
    state.server ??= readServer(sdk, hooks.label, calls.tools);
    opened.mcpServers = { ...options.mcpServers, [hooks.label]: state.server };
  }
  return opened;
}

function readServer(
  sdk: ClaudeCode.Sdk,
  label: string,
  tools: readonly Harness.ToolCall<ClaudeCode.Calls>[],
): McpServerConfig {
  return sdk.createSdkMcpServer({
    name: label,
    tools: tools.map(({ op, meta, run }) =>
      sdk.tool(meta.name ?? op.label, meta.description, meta.schema, async (args) => {
        const result = await Promise.resolve(run.settle({ rawInput: args }));
        if (result.status === "success") return answerTool(meta, result.value);
        throw result.status === "failed" ? result.error : result.reason;
      }),
    ),
  });
}

export async function execute(
  entry: Process.Entry,
  rest: readonly string[],
  out: Process.Io,
  opts?: { readonly signal?: AbortSignal; readonly usage?: string },
): Promise<number> {
  const signal = opts?.signal;
  /** Read through a call, never a narrowed constant: the signal may abort mid-run. */
  const cancelled = (): boolean => signal?.aborted === true;
  if (cancelled()) return 130;
  const scope = rootFor(entry, rest, out);
  const stop = (): void => void scope.close();
  signal?.addEventListener("abort", stop, { once: true });
  try {
    await scope.ready;
    return readResult(await scope.settle(entry.op), out, cancelled(), opts?.usage);
  } catch (error: unknown) {
    /** Only a failed start or a closed root lands here: `settle` itself never throws. */
    return readFailure(error, out, cancelled(), opts?.usage);
  } finally {
    signal?.removeEventListener("abort", stop);
    await scope.close({ graceful: !cancelled() });
  }
}

function readServer(
  sdk: ClaudeCode.Sdk,
  label: string,
  tools: readonly Harness.ToolCall<ClaudeCode.Calls>[],
